  ["# 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n# ___ halvings: math.log2(1024)\n"] = "# 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n# ___ půlení: math.log2(1024)\n",
  ["# 400 URLs, threads are fine here:\n# the GIL is ___ while the socket waits\nrequests.get(url)\n"] = "# 400 URL, tady vlákna stačí:\n# GIL se ___, dokud socket čeká\nrequests.get(url)\n",
  ["# 400 supplier calls  -> ThreadPoolExecutor\n# 400 image resizes   -> ___PoolExecutor\n"] = "# 400 volání na dodavatele -> ThreadPoolExecutor\n# 400 obrázků ke zmenšení  -> ___PoolExecutor\n",
  ["# 8 threads, 8 cores, one core busy\n# the reason has three letters: the ___\nimport threading\n"] = "# 8 vláken, 8 jader, vytížené jedno\n# důvod má tři písmena: ___\nimport threading\n",
  ["# One thread runs Python bytecode at a time: the ___.\n# Threads overlap I/O and sleep, not CPU work.\n# For CPU-bound work use multiprocessing.\n"] = "# Bytecode Pythonu běží v jednom vlákně naráz: ___.\n# Vlákna překrývají I/O a sleep, ne práci CPU.\n# Na práci náročnou na CPU použij multiprocessing.\n",
  ["# bisect on an unsorted list returns nonsense.\n# Precondition: a is ___ ascending.\na.sort()\ni = bisect.bisect_left(a, 38)\n"] = "# bisect na neseřazeném seznamu vrací nesmysly.\n# Předpoklad: a je ___ vzestupně.\na.sort()\ni = bisect.bisect_left(a, 38)\n",
  ["# level 1: merge 2 halves      -> n items moved\n# level 2: merge 4 quarters    -> n items moved\n# each level: ___ ; levels: log n ; total: n log n\n"] = "# úroveň 1: sluč 2 půlky        -> n položek přesunuto\n# úroveň 2: sluč 4 čtvrtiny     -> n položek přesunuto\n# každá úroveň: ___ ; úrovní: log n ; celkem: n log n\n",
  ["# n = 100\n# pairs = 100 * 99 // 2 = ___\n# still O(n^2): the /2 is a constant\n"] = "# n = 100\n# dvojic = 100 * 99 // 2 = ___\n# stále O(n^2): /2 je konstanta\n",
  ["# n = 1000 -> items[3] : 1 step\n# n = 2000 -> items[3] : 1 step\n# the cost stays the ___\n"] = "# n = 1000 -> items[3] : 1 krok\n# n = 2000 -> items[3] : 1 krok\n# cena zůstává the ___\n",
  ["# process 1: python3 -> its own GIL\n# process 2: python3 -> its own ___\n# two cores at 100%\n"] = "# proces 1: python3 -> vlastní GIL\n# proces 2: python3 -> vlastní ___\n# dvě jádra na 100 %\n",
  ["# quicksort halves the range each level on average\n# depth ~ log2(n) frames on the stack: O(___) space\n# (naive fib without cache: depth n, RecursionError near 1000)\n"] = "# quicksort v průměru půlí rozsah na každé úrovni\n# hloubka ~ log2(n) rámců na zásobníku: O(___) prostoru\n# (naivní fib bez cache: hloubka n, RecursionError kolem 1000)\n",
  ["# starts a comment. There is no block comment; a triple-quoted string at the top of a def is a docstring."] = "# začíná komentář. Blokový komentář neexistuje; řetězec v trojitých uvozovkách na začátku def je docstring.",
  ["# without cache: 2^n calls\n# with cache: fib(0) .. fib(n), each once -> O(___)\n"] = "# bez cache: 2^n volání\n# s cache: fib(0) .. fib(n), každé jednou -> O(___)\n",
  ['#[___(Debug)]\nstruct Order { qty: u32 }\n\nlet o = Order { qty: 2 };\nprintln!("{:?}", o);        // Order { qty: 2 }\n'] = '#[___(Debug)]\nstruct Order { qty: u32 }\n\nlet o = Order { qty: 2 };\nprintln!("{:?}", o);        // Order { qty: 2 }\n',
  ["#[derive(Clone, Debug)] generates the impls. Also common: PartialEq, Default, Copy for small types."] = "#[derive(Clone, Debug)] generuje implementace. Běžné také: PartialEq, Default, Copy pro malé typy.",
  ["#[derive(Debug, Clone, PartialEq)] generates common traits. {:?} needs Debug. The till prints the order and the afternoon set is sold."] = "#[derive(Debug, Clone, PartialEq)] generuje běžné traity. {:?} potřebuje Debug. Pokladna vytiskne objednávku a odpolední menu je prodáno.",
  ['#[derive(Default, Debug)]\nstruct Tray { buns: u32, teas: u32 }\n// An empty tray, all zeros, without typing them.\nlet empty = Tray::___();\nprintln!("{empty:?}");\n'] = '#[derive(Default, Debug)]\nstruct Tray { buns: u32, teas: u32 }\n// Prázdný tác, všude nuly, bez vypisování.\nlet empty = Tray::___();\nprintln!("{empty:?}");\n',
  ['#[derive(Serialize, Deserialize)]\nstruct Order {\n    #[serde(___ = "dish")]\n    name: String,\n    qty: u32,\n}\n// {"dish":"toast","qty":2} now fills name\n'] = '#[derive(Serialize, Deserialize)]\nstruct Order {\n    #[serde(___ = "dish")]\n    name: String,\n    qty: u32,\n}\n// {"dish":"toast","qty":2} teď naplní name\n',
  ['#[derive(Serialize, Deserialize)]\nstruct Order {\n    name: String,\n    #[serde(___ = "Option::is_none")]\n    note: Option<String>,\n}\n// None -> {"name":"toast"}   Some -> {"name":..,"note":..}\n'] = '#[derive(Serialize, Deserialize)]\nstruct Order {\n    name: String,\n    #[serde(___ = "Option::is_none")]\n    note: Option<String>,\n}\n// None -> {"name":"toast"}   Some -> {"name":..,"note":..}\n',
  ['#[serde(rename = "dish")] is the Go json tag. rename_all = "camelCase" on the struct is common.'] = '#[serde(rename = "dish")] je json tag z Go. rename_all = "camelCase" na structu je běžné.',
  ["#[tokio::main] builds the runtime and block_on(main()). Use #[tokio::test] in tests."] = "#[tokio::main] postaví runtime a block_on(main()). V testech použij #[tokio::test].",
  ['$ ___ shop.py\nshop.py:12: error: Incompatible return value type\n    (got "None", expected "str")\nFound 1 error in 1 file\n'] = '$ ___ shop.py\nshop.py:12: error: Incompatible return value type\n    (got "None", expected "str")\nFound 1 error in 1 file\n',
  ["$ cargo ___\n   Compiling delivery v0.1.0\nrunning 2 checks\nqty_parses ....... ok\neta_is_positive .. ok\nresult: ok. 2 passed; 0 failed\n"] = "$ cargo ___\n   Compiling delivery v0.1.0\nrunning 2 checks\nqty_parses ....... ok\neta_is_positive .. ok\nresult: ok. 2 passed; 0 failed\n",
  ['$ cargo ___\n$ git diff --stat\n src/main.rs | 14 ++++++-------\n$ cargo ___ --check && echo "clean"\n'] = '$ cargo ___\n$ git diff --stat\n src/main.rs | 14 ++++++-------\n$ cargo ___ --check && echo "clean"\n',
  ["$ cargo ___\nwarning: this `.into_iter()` call is equivalent to `.iter()`\n  --> src/main.rs:12:24\n   = help: consider using `.iter()`\n"] = "$ cargo ___\nwarning: this `.into_iter()` call is equivalent to `.iter()`\n  --> src/main.rs:12:24\n   = help: consider using `.iter()`\n",
  ["$ cargo ___ delivery\n     Created binary (application) `delivery` package\n$ ls delivery\nCargo.toml  src/main.rs\n"] = "$ cargo ___ delivery\n     Created binary (application) `delivery` package\n$ ls delivery\nCargo.toml  src/main.rs\n",
  ["$ cargo ___ reqwest --features json\n    Updating crates.io index\n      Adding reqwest v0.12 to dependencies\n"] = "$ cargo ___ reqwest --features json\n    Updating crates.io index\n      Adding reqwest v0.12 to dependencies\n",
  ["$ cargo build --___\n   Compiling delivery v0.1.0\n    Finished [optimized] target(s) in 41.2s\n"] = "$ cargo build --___\n   Compiling delivery v0.1.0\n    Finished [optimized] target(s) in 41.2s\n",
  ["$ cat go.___\ngithub.com/alex/luckymac v1.2.0 h1:9fK2...Qw=\ngithub.com/alex/luckymac v1.2.0/go.mod h1:Lm0...c8=\n"] = "$ cat go.___\ngithub.com/alex/luckymac v1.2.0 h1:9fK2...Qw=\ngithub.com/alex/luckymac v1.2.0/go.mod h1:Lm0...c8=\n",
  ["$ cd luckymac/menu\n$ go env ___\n/Users/alex/luckymac/go.mod\n"] = "$ cd luckymac/menu\n$ go env ___\n/Users/alex/luckymac/go.mod\n",
  ["$ git ___ v1.0.0\n$ git push origin v1.0.0\n"] = "$ git ___ v1.0.0\n$ git push origin v1.0.0\n",
  ['$ git config --global \\\n    url."git@github.com:".___ "https://github.com/"\n'] = '$ git config --global \\\n    url."git@github.com:".___ "https://github.com/"\n',
  ["$ git remote -v\norigin  git@github.com:alex/luckymac.git (push)\n$ go mod init ___\ngo: creating new go.mod\n"] = "$ git remote -v\norigin  git@github.com:alex/luckymac.git (push)\n$ go mod init ___\ngo: creating new go.mod\n",
  ["$ go ___ -m all\ngithub.com/siuming/cousinshop\ngithub.com/alex/luckymac v1.0.0\ngithub.com/goccy/go-json v0.10.3\n"] = "$ go ___ -m all\ngithub.com/siuming/cousinshop\ngithub.com/alex/luckymac v1.0.0\ngithub.com/goccy/go-json v0.10.3\n",
  ["$ go ___ -o delivery .    # one static file\n$ ./delivery\n"] = "$ go ___ -o delivery .    # one static file\n$ ./delivery\n",
  ["$ go ___ ./...    # static checks, no run\n$ go fmt ./...    # and gofmt every file\n"] = "$ go ___ ./...    # static checks, no run\n$ go fmt ./...    # and gofmt every file\n",
  ["$ go ___ github.com/alex/luckymac@v1.2.0\ngo: downloading github.com/alex/luckymac v1.2.0\ngo: added github.com/alex/luckymac v1.2.0\n"] = "$ go ___ github.com/alex/luckymac@v1.2.0\ngo: downloading github.com/alex/luckymac v1.2.0\ngo: added github.com/alex/luckymac v1.2.0\n",
  ["$ go ___ init luckymac/delivery\ngo: creating new go.mod: module luckymac/delivery\n"] = "$ go ___ init luckymac/delivery\ngo: creating new go.mod: module luckymac/delivery\n",
  ["$ go build ./...\nmain.go:6:2: no required module provides package\n    github.com/alex/luckymac/menu; to add it:\n    go mod ___\n"] = "$ go build ./...\nmain.go:6:2: no required module provides package\n    github.com/alex/luckymac/menu; to add it:\n    go mod ___\n",
  ["$ go clean -___\n$ go build ./...     # everything downloads again, once\n"] = "$ go clean -___\n$ go build ./...     # všechno se stáhne znovu, jednou\n",
  ["$ go env -w ___=github.com/luckymac-hk/*\n$ go get github.com/luckymac-hk/kitchen@latest\n"] = "$ go env -w ___=github.com/luckymac-hk/*\n$ go get github.com/luckymac-hk/kitchen@latest\n",
  ["$ go env GO111MODULE\n___\n# modules everywhere, go.mod or not\n"] = "$ go env GO111MODULE\n___\n# moduly všude, s go.mod i bez něj\n",
  ["$ go env GOPROXY\nhttps://proxy.golang.org,___\n"] = "$ go env GOPROXY\nhttps://proxy.golang.org,___\n",
  ["$ go env GOSUMDB\n___.golang.org\n"] = "$ go env GOSUMDB\n___.golang.org\n",
  ["$ go get github.com/alex/luckymac@___\ngo: upgraded github.com/alex/luckymac v0.3.0 => v1.0.0\n"] = "$ go get github.com/alex/luckymac@___\ngo: upgraded github.com/alex/luckymac v0.3.0 => v1.0.0\n",
  ["$ go mod ___\n$ ls\ngo.mod  go.sum  main.go  menu/  ___/\n$ go build ./...      # reads ___/ automatically\n"] = "$ go mod ___\n$ ls\ngo.mod  go.sum  main.go  menu/  ___/\n$ go build ./...      # čte ___/ automaticky\n",
  ["$ go mod ___    # sync go.mod with the imports\n"] = "$ go mod ___    # sync go.mod with the imports\n",
  ["$ go test -___ ./kitchen\nWARNING: DATA RACE\nWrite at 0x00c0000b4010 by goroutine 8\nPrevious read by goroutine 7\n"] = "$ go test -___ ./kitchen\nWARNING: DATA RACE\nWrite at 0x00c0000b4010 by goroutine 8\nPrevious read by goroutine 7\n",
  ["$ go test ___ ./...\nWARNING: DATA RACE\nWrite at 0x00c0000 by goroutine 7\n"] = "$ go test ___ ./...\nWARNING: DATA RACE\nWrite at 0x00c0000 by goroutine 7\n",
  ["$ ls\ncousinshop/  luckymac/\n$ go ___ init ./cousinshop ./luckymac\n"] = "$ ls\ncousinshop/  luckymac/\n$ go ___ init ./cousinshop ./luckymac\n",
  ["$ ls $(go env GOMODCACHE)\ncache/  github.com/\n$ go env GOMODCACHE\n/Users/siuming/go/pkg/___\n"] = "$ ls $(go env GOMODCACHE)\ncache/  github.com/\n$ go env GOMODCACHE\n/Users/siuming/go/pkg/___\n",
  ['$ python3.13t -c "import sys; print(sys._is_gil_enabled())"\nFalse\n# this is the ___-threaded build (PEP 703)\n'] = '$ python3.13t -c "import sys; print(sys._is_gil_enabled())"\nFalse\n# tohle je sestavení ___-threaded (PEP 703)\n',
  ["%d / %d clear"] = "%d / %d hotovo",
  ["%s  MAP %d/%d  %s"] = "%s  MAPA %d/%d  %s",
  ["%s TRACK"] = "TRASA %s",
  ["%v value, %+v with names, %#v as Go syntax, %T the type."] = "%v hodnota, %+v s názvy, %#v jako syntaxe Go, %T typ.",
  ["%v with a plus. %#v adds the type name too; %T prints only the type."] = "%v s plusem. %#v přidá i název typu; %T vypíše jen typ.",
  ["%w builds a chain. %v would flatten it to text and lose the cause."] = "%w staví řetěz. %v by ho zploštil na text a ztratil příčinu.",
  ["&'a str: the output lives at least as long as the shorter of a and b. Lifetimes describe; they never extend anything."] = "&'a str: výstup žije nejméně tak dlouho jako kratší z a a b. Lifetimy popisují; nikdy nic neprodlužují.",
  ["&'static str lives for the whole program. String literals are 'static; a returned reference with no input to borrow from must be too."] = "&'static str žije po celý program. Řetězcové literály jsou 'static; vrácená reference bez vstupu, ze kterého by si půjčila, musí být také.",
  ["&String is a shared borrow: read only, any number at once, the owner keeps the value."] = "&String je sdílená výpůjčka: jen pro čtení, libovolný počet najednou, vlastník si hodnotu nechává.",
  ["&T{} is the usual way to make a pointer to a struct. p.Field works without (*p)."] = "&T{} je obvyklý způsob, jak vytvořit ukazatel na struct. p.Field funguje bez (*p).",
  ["&dyn Cook is a trait object: a pointer plus a vtable. Go interfaces work the same way underneath."] = "&dyn Cook je trait object: ukazatel plus vtable. Rozhraní v Go fungují pod kapotou stejně.",
  ["&mut a. While r lives, no other borrow of a may exist: exactly 1 &mut, or many &, never both."] = "&mut a. Dokud r žije, nesmí existovat žádná jiná výpůjčka a: přesně 1 &mut, nebo mnoho &, nikdy obojí.",
  ["&prices[1..3] is a slice of type &[i32]: a borrowed window, no copy. [1..] and [..2] also work."] = "&prices[1..3] je slice typu &[i32]: vypůjčené okno, žádná kopie. [1..] a [..2] fungují také.",
  ["&str is a view into text; String owns it. Take &str in parameters, return String when you build new text. The receipt prints once."] = "&str je pohled do textu; String ho vlastní. V parametrech ber &str, String vracej, když stavíš nový text. Účtenka se vytiskne jednou.",
  ["(hi - lo) / 2. Each pass throws away half the range. usize overflow panics in debug builds, so the subtraction form matters."] = "(hi - lo) / 2. Každý průchod zahodí polovinu rozsahu. Přetečení usize v debug sestavení způsobí panic, takže na tvaru s odčítáním záleží.",
  ["(lo + hi) / 2, or lo + (hi-lo)/2 to dodge overflow. Each pass throws away half the range."] = "(lo + hi) / 2, nebo lo + (hi-lo)/2, aby se vyhnulo přetečení. Každý průchod zahodí polovinu rozsahu.",
  ["(lo + hi) // 2. Python ints never overflow, so the plain form is safe. Each pass throws away half the range."] = "(lo + hi) // 2. Inty v Pythonu nikdy nepřetečou, takže prostý tvar je bezpečný. Každý průchod zahodí polovinu rozsahu.",
  ["(ok, err). Check err before using ok. The gate opens."] = "(ok, err). Zkontroluj err, než použiješ ok. Turniket se otevře.",
  ["**opts packs keyword arguments into a dict. The usual names are *args and **kwargs; any name works."] = "**opts sbalí pojmenované argumenty do dictu. Obvyklá jména jsou *args a **kwargs; funguje jakékoli jméno.",
  ["*Order is a pointer. Methods that change the struct use a *T receiver."] = "*Order je ukazatel. Metody, které mění struct, používají receiver *T.",
  ["*http.Request is everything the client sent. Query().Get reads ?item=."] = "*http.Request je vše, co klient poslal. Query().Get čte ?item=.",
  ["*items packs extra positional arguments into a tuple. Go's ...int. Calling total(*prices) unpacks a list the other way."] = "*items sbalí přebývající poziční argumenty do tuple. ...int z Go. Volání total(*prices) naopak rozbalí seznam.",
  ["+%d XP"] = "+%d XP",
  ["--release turns on opt-level 3 and drops debug checks. Plain cargo build is for development."] = "--release zapne opt-level 3 a vyhodí debug kontroly. Holé cargo build je pro vývoj.",
  ["-> None says: no useful result. mypy then complains if you assign the call. Forty bowls saved."] = "-> None říká: žádný užitečný výsledek. mypy si pak stěžuje, když volání přiřadíš. Čtyřicet misek zachráněno.",
  ["-gcflags=-m says o escapes. Where does a shared reference have to live?"] = "-gcflags=-m hlásí, že o uniká. Kde musí sdílená reference bydlet?",
  ["...int is variadic. Call it with sum(a, b, c) or spread a slice: sum(fares...)."] = "...int je variadický. Volej sum(a, b, c) nebo rozbal slice: sum(fares...).",
  [".await yields to the runtime until the Future is ready. Forget it and nothing runs."] = ".await předá řízení runtimu, dokud Future není hotový. Zapomeň na něj a nic neběží.",
  ['// "abc" is not a number: fall back to zero coins.\nlet coins: u32 = "abc".parse().___(0);\n'] = '// "abc" není číslo: vrať se k nule mincí.\nlet coins: u32 = "abc".parse().___(0);\n',
  ["// &Option<T> to Option<&T>: a borrow, not a move.\nfn root_val(tree: &Link) -> Option<i32> {\n    tree.___().map(|n| n.val)\n}\n"] = "// &Option<T> na Option<&T>: výpůjčka, ne přesun.\nfn root_val(tree: &Link) -> Option<i32> {\n    tree.___().map(|n| n.val)\n}\n",
  ["// 1 topping: 2 combos   2 toppings: 4   3 toppings: 8\n// n toppings: ___ combos, and listing them all cannot be faster\n"] = "// 1 příloha: 2 kombinace   2 přílohy: 4   3 přílohy: 8\n// n příloh: ___ kombinací, a vypsat všechny nemůže být rychlejší\n",
  ["// 1 topping: 2 combos   2 toppings: 4   3 toppings: 8\n// n toppings: ___ combos; 1u64 << n computes it\n"] = "// 1 příloha: 2 kombinace   2 přílohy: 4   3 přílohy: 8\n// n příloh: ___ kombinací; 1u64 << n to spočítá\n",
  ["// 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n// ___ halvings: 1024_u32.ilog2()\n"] = "// 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n// ___ půlení: 1024_u32.ilog2()\n",
  ["// 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n// ___ halvings: log2(1024)\n"] = "// 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n// ___ půlení: log2(1024)\n",
  ['// Any cook must give a name; greet comes for free.\n___ Cook {\n    fn name(&self) -> String;\n    fn greet(&self) -> String {\n        format!("{} at the pass", self.name())\n    }\n}\n'] = '// Každý kuchař musí dát jméno; greet je zdarma.\n___ Cook {\n    fn name(&self) -> String;\n    fn greet(&self) -> String {\n        format!("{} at the pass", self.name())\n    }\n}\n',
  ["// Ask the compiler to write .clone() for Order.\n#[___(Clone, Debug)]\nstruct Order {\n    bun: String,\n    qty: u32,\n}\n"] = "// Požádej kompilátor, aby napsal .clone() pro Order.\n#[___(Clone, Debug)]\nstruct Order {\n    bun: String,\n    qty: u32,\n}\n",
  ["// BinarySearch on an unsorted slice returns nonsense.\n// Precondition: a is ___ ascending.\nsort.Ints(a)\ni, found := slices.BinarySearch(a, 38)\n"] = "// BinarySearch na neseřazeném slice vrací nesmysly.\n// Předpoklad: a je ___ vzestupně.\nsort.Ints(a)\ni, found := slices.BinarySearch(a, 38)\n",
  ['// Cargo.toml: [dependencies] has this crate at version 1\nuse ___::Error;\n#[derive(Debug, Error)]\nenum OrderError {\n    #[error("order is empty")]\n    Empty,\n}\n'] = '// Cargo.toml: [dependencies] má tento crate ve verzi 1\nuse ___::Error;\n#[derive(Debug, Error)]\nenum OrderError {\n    #[error("order is empty")]\n    Empty,\n}\n',
  ['// Cargo.toml: tokio = {version="1", features=["full"]}\n#[___]\nasync fn main() {\n    let eta = fetch_eta(7).await;\n    println!("{eta} min");\n}\n'] = '// Cargo.toml: tokio = {version="1", features=["full"]}\n#[___]\nasync fn main() {\n    let eta = fetch_eta(7).await;\n    println!("{eta} min");\n}\n',
  ["// Debug + Display are done, so the body can stay empty\nimpl ___ for OrderError {}\n"] = "// Debug + Display jsou hotové, tělo může zůstat prázdné\nimpl ___ for OrderError {}\n",
  ["// Do not communicate by sharing memory;\n// share memory by ___.\norders <- Order{id: 7}\n"] = "// Nekomunikuj sdílením paměti;\n// sdílej paměť ___.\norders <- Order{id: 7}\n",
  ['// Grill and Wok in one Vec: each boxed as a trait object.\nlet crew: Vec<___> = vec![Box::new(Grill), Box::new(Wok)];\nfor c in &crew { println!("{}", c.greet()); }\n'] = '// Grill a Wok v jednom Vec: každý v Boxu jako trait object.\nlet crew: Vec<___> = vec![Box::new(Grill), Box::new(Wok)];\nfor c in &crew { println!("{}", c.greet()); }\n',
  ['// In the terminal, inside the project folder:\n//   $ cargo ___\n// Compiles target/debug/express and starts it.\nfn main() {\n    println!("Lucky Mac Express");\n}\n'] = '// V terminálu, ve složce projektu:\n//   $ cargo ___\n// Zkompiluje target/debug/express a spustí ho.\nfn main() {\n    println!("Lucky Mac Express");\n}\n',
  ['// Keep every handle so the pass can wait for every cook.\nlet mut hs: Vec<___<()>> = Vec::new();\nfor id in 0..3 {\n    hs.push(thread::spawn(move || println!("cook {id}")));\n}\nfor h in hs { h.join().unwrap(); }\n'] = '// Uchovej každý handle, aby výdej mohl počkat na každého kuchaře.\nlet mut hs: Vec<___<()>> = Vec::new();\nfor id in 0..3 {\n    hs.push(thread::spawn(move || println!("cook {id}")));\n}\nfor h in hs { h.join().unwrap(); }\n',
  ["// Not every table has an order yet.\nfn find(orders: &[(u32, &str)], t: u32) -> ___<String> {\n    for (n, item) in orders {\n        if *n == t { return Some(item.to_string()); }\n    }\n    None\n}\n"] = "// Ne každý stůl už má objednávku.\nfn find(orders: &[(u32, &str)], t: u32) -> ___<String> {\n    for (n, item) in orders {\n        if *n == t { return Some(item.to_string()); }\n    }\n    None\n}\n",
  ['// Nothing here tells parse which number type to build.\nlet qty = "12".parse___().unwrap();\nlet total = qty * 18;\n'] = '// Nic tady parse neříká, který číselný typ má postavit.\nlet qty = "12".parse___().unwrap();\nlet total = qty * 18;\n',
  ["// One counter, many cooks: one writer at a time.\nlet sold = Arc::new(___::new(0u32));\n"] = "// Jeden čítač, mnoho kuchařů: jeden zapisovatel najednou.\nlet sold = Arc::new(___::new(0u32));\n",
  ["// Only types with this marker may move to another thread.\nfn ship<T: ___ + 'static>(t: T) {\n    thread::spawn(move || drop(t));\n}\nship(Arc::new(5));    // ok: Arc is thread-safe\n// ship(Rc::new(5));  // error: Rc is not\n"] = "// Jen typy s touto značkou se smí přesunout do jiného vlákna.\nfn ship<T: ___ + 'static>(t: T) {\n    thread::spawn(move || drop(t));\n}\nship(Arc::new(5));    // ok: Arc je thread-safe\n// ship(Rc::new(5));  // chyba: Rc není\n",
  ['// Peek without waiting: the till must keep beeping.\nmatch rx.___() {\n    Ok(order) => println!("got {order}"),\n    Err(_) => println!("nothing yet"),\n}\n'] = '// Nakoukni bez čekání: pokladna musí dál pípat.\nmatch rx.___() {\n    Ok(order) => println!("got {order}"),\n    Err(_) => println!("nothing yet"),\n}\n',
  ['// Rc counts on one thread only; this one crosses threads.\nlet menu = ___::new(vec!["bun", "egg tart"]);\nlet m2 = menu.clone();\nthread::spawn(move || println!("{}", m2[0]));\n'] = '// Rc počítá jen na jednom vlákně; tenhle přechází mezi vlákny.\nlet menu = ___::new(vec!["bun", "egg tart"]);\nlet m2 = menu.clone();\nthread::spawn(move || println!("{}", m2[0]));\n',
  ['// Same bound, written under the signature for long lists.\nfn show_all<T>(items: &[T])\n___\n    T: std::fmt::Display,\n{\n    for it in items { println!("{it}"); }\n}\n'] = '// Stejné omezení, napsané pod signaturou pro dlouhé seznamy.\nfn show_all<T>(items: &[T])\n___\n    T: std::fmt::Display,\n{\n    for it in items { println!("{it}"); }\n}\n',
  ["// Take any Cook at all; the caller picks the concrete type.\nfn fire(c: ___ Cook) -> String {\n    c.greet()\n}\n"] = "// Vezmi jakéhokoli Cook; konkrétní typ vybere volající.\nfn fire(c: ___ Cook) -> String {\n    c.greet()\n}\n",
  ['// The banner is baked into the binary for the whole run.\nfn banner() -> &___ str {\n    "Lucky Mac Express"\n}\n'] = '// Banner je zapečený v binárce po celý běh.\nfn banner() -> &___ str {\n    "Lucky Mac Express"\n}\n',
  ["// The child lives on the heap, behind a pointer.\ntype Link = Option<___<Node>>;\nstruct Node {\n    val: i32,\n    left: Link,\n    right: Link,\n}\n"] = "// Potomek žije na haldě, za ukazatelem.\ntype Link = Option<___<Node>>;\nstruct Node {\n    val: i32,\n    left: Link,\n    right: Link,\n}\n",
  ['// The entry point of a binary crate.\nfn ___() {\n    println!("Lucky Mac Express");\n}\n'] = '// Vstupní bod binárního crate.\nfn ___() {\n    println!("Lucky Mac Express");\n}\n',
  ["// The first line of a Go file.\npackage ___\nfunc hello() {}\n"] = "// První řádek souboru v Go.\npackage ___\nfunc hello() {}\n",
  ['// The pass holds three trays: send blocks when full.\nlet (tx, rx) = mpsc::___(3);\ntx.send("tray").unwrap();\n'] = '// Výdej pojme tři tácy: send blokuje, když je plno.\nlet (tx, rx) = mpsc::___(3);\ntx.send("tray").unwrap();\n',
  ["// The receipt only borrows the name: say so on the struct.\nstruct Receipt___ {\n    name: &'a str,\n    total: u32,\n}\n"] = "// Účtenka si jméno jen půjčuje: řekni to na structu.\nstruct Receipt___ {\n    name: &'a str,\n    total: u32,\n}\n",
  ["// The tea thread hands back a number when it is done.\nlet tea = thread::spawn(|| 3 * 60);\n// Wait for it and take the result out of the handle.\nlet secs: u32 = tea.___().unwrap();\n"] = "// Vlákno s čajem vrátí číslo, když skončí.\nlet tea = thread::spawn(|| 3 * 60);\n// Počkej na něj a vyndej výsledek z handle.\nlet secs: u32 = tea.___().unwrap();\n",
  ['// The till gives change back, or a message.\nfn pay(cash: u32, price: u32) -> ___<u32, String> {\n    if cash < price {\n        return Err("not enough cash".to_string());\n    }\n    Ok(cash - price)\n}\n'] = '// Pokladna vrátí drobné, nebo zprávu.\nfn pay(cash: u32, price: u32) -> ___<u32, String> {\n    if cash < price {\n        return Err("not enough cash".to_string());\n    }\n    Ok(cash - price)\n}\n',
  ["// Two buns from one tray: the winner lives as long as both.\nfn longest<'a>(a: &'a str, b: &'a str) -> &___ str {\n    if a.len() >= b.len() { a } else { b }\n}\n"] = "// Dvě housky z jednoho tácu: vítěz žije tak dlouho jako obě.\nfn longest<'a>(a: &'a str, b: &'a str) -> &___ str {\n    if a.len() >= b.len() { a } else { b }\n}\n",
  ["// ___ menu prices the morning set and the tea set.\npackage menu\n"] = "// ___ menu prices the morning set and the tea set.\npackage menu\n",
  ['// a literal is a &str; the kiosk needs its own copy\nlet shop = String::___("Lucky Mac Express");\nlet label: &str = &shop;\n'] = '// literál je &str; kiosek potřebuje vlastní kopii\nlet shop = String::___("Lucky Mac Express");\nlet label: &str = &shop;\n',
  ['// a max-heap of (count, word), built straight from the map\nlet mut heap: BinaryHeap<(usize, &str)> =\n    cnt.into_iter().map(|(w, c)| (c, w)).___();\n// k pops: most frequent first, tuples compare by count\nfor _ in 0..k {\n    if let Some((c, w)) = heap.pop() { print!("{w} "); }\n}\n'] = '// max-halda (count, word), postavená rovnou z mapy\nlet mut heap: BinaryHeap<(usize, &str)> =\n    cnt.into_iter().map(|(w, c)| (c, w)).___();\n// k popů: nejčastější první, n-tice se řadí podle count\nfor _ in 0..k {\n    if let Some((c, w)) = heap.pop() { print!("{w} "); }\n}\n',
  ["// a second stack: the smallest so far, at every depth\nfn push(&mut self, x: i32) {\n    let m = *self.low.last().unwrap_or(&x);\n    self.st.push(x);\n    self.low.push(x.___(m));\n}\n// the smallest: *self.low.last().unwrap()   O(1)\n"] = "// druhý zásobník: dosavadní minimum v každé hloubce\nfn push(&mut self, x: i32) {\n    let m = *self.low.last().unwrap_or(&x);\n    self.st.push(x);\n    self.low.push(x.___(m));\n}\n// nejmenší: *self.low.last().unwrap()   O(1)\n",
  ["// b'a' is the byte 97. Subtracting it maps a..z onto 0..26.\n// An array index must be the pointer-sized unsigned type.\nlet mut count = [0i32; 26];\nfor c in \"muffin\".bytes() {\n    count[(c - b'a') as ___] += 1;\n}\n"] = "// b'a' je bajt 97. Odečtením se a..z zobrazí na 0..26.\n// Index pole musí být unsigned typ velikosti ukazatele.\nlet mut count = [0i32; 26];\nfor c in \"muffin\".bytes() {\n    count[(c - b'a') as ___] += 1;\n}\n",
  ["// biggest run of days: extend the run, or start over at x\nlet (mut cur, mut best) = (a[0], a[0]);\nfor &x in &a[1..] {\n    cur = x.___(cur + x);\n    if cur > best { best = cur; }\n}\n"] = "// nejlepší řada dnů: prodluž ji, nebo začni znovu od x\nlet (mut cur, mut best) = (a[0], a[0]);\nfor &x in &a[1..] {\n    cur = x.___(cur + x);\n    if cur > best { best = cur; }\n}\n",
  ["// binary_search on an unsorted slice returns nonsense.\n// Precondition: a is ___ ascending.\na.sort();\nlet i = a.binary_search(&38);\n"] = "// binary_search na neseřazeném slice vrací nesmysly.\n// Předpoklad: a je ___ vzestupně.\na.sort();\nlet i = a.binary_search(&38);\n",
  ['// both futures make progress on this task at once\nlet (a, b) = tokio::___!(fetch_eta(1), fetch_eta(2));\nprintln!("rider A {a} min, rider B {b} min");\n'] = '// oba futures postupují na tomto tasku zároveň\nlet (a, b) = tokio::___!(fetch_eta(1), fetch_eta(2));\nprintln!("rider A {a} min, rider B {b} min");\n',
  ["// calling this does nothing yet; it hands back a Future\n___ fn fetch_eta(order_id: u32) -> u32 {\n    tokio::time::sleep(Duration::from_millis(200)).await;\n    order_id % 10 + 5\n}\n"] = "// zavolání zatím nic nedělá; vrátí Future\n___ fn fetch_eta(order_id: u32) -> u32 {\n    tokio::time::sleep(Duration::from_millis(200)).await;\n    order_id % 10 + 5\n}\n",
  ["// cmd/kiosk/main.go\npackage ___\n\nfunc main() { kiosk.Run() }\n"] = "// cmd/kiosk/main.go\npackage ___\n\nfunc main() { kiosk.Run() }\n",
  ["// count every dish name once per receipt\nlet mut cnt: HashMap<&str, usize> = HashMap::new();\nfor w in words {\n    *cnt.___(w).or_insert(0) += 1;\n}\n"] = "// každé jméno jídla počítej jednou za účtenku\nlet mut cnt: HashMap<&str, usize> = HashMap::new();\nfor w in words {\n    *cnt.___(w).or_insert(0) += 1;\n}\n",
  ["// dp[a] = fewest coins that make amount a\nfor a := range dp {\n    dp[a] = ___             // 'impossible' until proven\n}\ndp[0] = 0\n"] = "// dp[a] = nejméně mincí na částku a\nfor a := range dp {\n    dp[a] = ___             // „nejde“, než se ukáže jinak\n}\ndp[0] = 0\n",
  ["// first parameter, never a struct field\nfunc Cook(___ context.Context, o Order) error {\n    return nil\n}\n"] = "// vždy první parametr, nikdy položka struktury\nfunc Cook(___ context.Context, o Order) error {\n    return nil\n}\n",
  ["// go f() starts a ___\n// thousands of them are cheap\n"] = "// go f() spustí ___\n// tisíce z nich jsou levné\n",
  ["// k items left; the top is the smallest of the k biggest\nlet Reverse(kth) = *heap.___().unwrap();\nkth\n// kth_largest(&[3, 2, 1, 5, 6, 4], 2) == 5\n"] = "// zbývá k prvků; vrchol je nejmenší z k největších\nlet Reverse(kth) = *heap.___().unwrap();\nkth\n// kth_largest(&[3, 2, 1, 5, 6, 4], 2) == 5\n",
  ["// kth largest: a heap of the k biggest, smallest on top.\n// BinaryHeap is a max-heap; a std::cmp wrapper flips it.\nlet mut heap = BinaryHeap::new();\nfor &x in nums {\n    heap.push(___(x));\n    if heap.len() > k { heap.pop(); }\n}\n"] = "// k-tý největší: halda k největších, nejmenší nahoře.\n// BinaryHeap je max-halda; obal ze std::cmp ji obrátí.\nlet mut heap = BinaryHeap::new();\nfor &x in nums {\n    heap.push(___(x));\n    if heap.len() > k { heap.pop(); }\n}\n",
  ["// level 1: merge 2 halves      -> n items moved\n// level 2: merge 4 quarters    -> n items moved\n// each level: ___ ; levels: log n ; total: n log n\n"] = "// úroveň 1: sluč 2 půlky        -> n položek přesunuto\n// úroveň 2: sluč 4 čtvrtiny     -> n položek přesunuto\n// každá úroveň: ___ ; úrovní: log n ; celkem: n log n\n",
  ['// main.go, module github.com/alex/luckymac\nimport "___"\n\nfmt.Println(menu.Price("set"))\n'] = '// main.go, module github.com/alex/luckymac\nimport "___"\n\nfmt.Println(menu.Price("set"))\n',
  ["// menu/price.go\npackage ___\n\nfunc price(item string) int { return 42 }\n"] = "// menu/price.go\npackage ___\n\nfunc price(item string) int { return 42 }\n",
  ["// menu/price.go\npackage menu\n\nfunc ___(item string) int { return 42 }\n"] = "// menu/price.go\npackage menu\n\nfunc ___(item string) int { return 42 }\n",
  ['// menu/price_test.go\npackage menu___\n\nimport "github.com/alex/luckymac/menu"\n'] = '// menu/price_test.go\npackage menu___\n\nimport "github.com/alex/luckymac/menu"\n',
  ["// merge(l, r): both slices are already sorted\nlet (mut i, mut j, mut out) = (0, 0, Vec::new());\nwhile i < l.len() && j < r.len() {\n    if l[i] ___ r[j] { out.push(l[i]); i += 1; }\n    else { out.push(r[j]); j += 1; }\n}\nout.extend(&l[i..]); out.extend(&r[j..]);\n"] = "// merge(l, r): oba slice už jsou seřazené\nlet (mut i, mut j, mut out) = (0, 0, Vec::new());\nwhile i < l.len() && j < r.len() {\n    if l[i] ___ r[j] { out.push(l[i]); i += 1; }\n    else { out.push(r[j]); j += 1; }\n}\nout.extend(&l[i..]); out.extend(&r[j..]);\n",
  ["// n = 100\n// pairs = 100 * 99 / 2 = ___\n// still O(n^2): the /2 is a constant\n"] = "// n = 100\n// dvojic = 100 * 99 / 2 = ___\n// stále O(n^2): /2 je konstanta\n",
  ["// n = 1000 -> items[3] : 1 step\n// n = 2000 -> items[3] : 1 step\n// the cost stays the ___\n"] = "// n = 1000 -> items[3] : 1 krok\n// n = 2000 -> items[3] : 1 krok\n// cena zůstává the ___\n",
  ['// position gives an Option; the till wants a Result.\nfn find(menu: &[&str], w: &str) -> Result<usize, String> {\n    menu.iter()\n        .position(|m| *m == w)\n        .___("not on the menu".to_string())\n}\n'] = '// position dává Option; pokladna chce Result.\nfn find(menu: &[&str], w: &str) -> Result<usize, String> {\n    menu.iter()\n        .position(|m| *m == w)\n        .___("not on the menu".to_string())\n}\n',
  ["// quicksort halves the range each level on average\n// depth ~ log2(n) frames on the stack: O(___) space\n// (naive fib without memo: depth n)\n"] = "// quicksort v průměru půlí rozsah na každé úrovni\n// hloubka ~ log2(n) rámců na zásobníku: O(___) prostoru\n// (naivní fib bez mema: hloubka n)\n",
  ["// returns a JoinHandle; the task runs on the pool now\nlet handle = tokio::___(async { fetch_eta(3).await });\nprint_menu().await;\nlet eta = handle.await?;\n"] = "// vrací JoinHandle; task teď běží na poolu\nlet handle = tokio::___(async { fetch_eta(3).await });\nprint_menu().await;\nlet eta = handle.await?;\n",
  ["// starts a line comment. /// is a doc comment that cargo doc turns into pages."] = "// začíná řádkový komentář. /// je dokumentační komentář, ze kterého cargo doc udělá stránky.",
  ["// the caller only learns: it is some Iterator of &str\nfn free_riders() -> ___ Iterator<Item = &'static str> {\n    [\"Wing\", \"Fai\"].into_iter().filter(|r| *r != \"Fai\")\n}\n"] = "// volající se dozví jen: je to nějaký Iterator přes &str\nfn free_riders() -> ___ Iterator<Item = &'static str> {\n    [\"Wing\", \"Fai\"].into_iter().filter(|r| *r != \"Fai\")\n}\n",
  ['// the mall has five floors of pickup lockers\nfor floor in 1___5 {\n    println!("checking locker on floor {floor}");\n}\n// prints 1, 2, 3, 4, 5\n'] = '// obchoďák má pět pater se skříňkami na vyzvednutí\nfor floor in 1___5 {\n    println!("checking locker on floor {floor}");\n}\n// vypíše 1, 2, 3, 4, 5\n',
  ["// the sum of every window of k, without re-adding k items\nlet mut sum: i32 = a[..k].iter().sum();\nlet mut best = sum;\nfor i in k..a.len() {\n    sum += a[i] - a[___];       // one in, one out\n    if sum > best { best = sum; }\n}\n"] = "// součet každého okna k, bez sčítání k prvků znovu\nlet mut sum: i32 = a[..k].iter().sum();\nlet mut best = sum;\nfor i in k..a.len() {\n    sum += a[i] - a[___];       // jeden dovnitř, jeden ven\n    if sum > best { best = sum; }\n}\n",
  ['// three characters, three bytes each in UTF-8\nlet district = "銅鑼灣";\nlet n = district.___();\nassert_eq!(n, 9);\n'] = '// tři znaky, každý tři bajty v UTF-8\nlet district = "銅鑼灣";\nlet n = district.___();\nassert_eq!(n, 9);\n',
  ["// two_sum: value -> index in a HashMap, one pass, O(n)\nlet mut seen = HashMap::new();\nfor (i, &x) in nums.iter().enumerate() {\n    let want = target - x;\n    if seen.___(&want) { return Some((seen[&want], i)); }\n    seen.insert(x, i);\n}\n"] = "// two_sum: hodnota -> index v HashMap, jeden průchod, O(n)\nlet mut seen = HashMap::new();\nfor (i, &x) in nums.iter().enumerate() {\n    let want = target - x;\n    if seen.___(&want) { return Some((seen[&want], i)); }\n    seen.insert(x, i);\n}\n",
  ["// without memo: 2^n calls\n// with memo: fib(0) .. fib(n), each once -> O(___)\n"] = "// bez mema: 2^n volání\n// s memem: fib(0) .. fib(n), každé jednou -> O(___)\n",
  ["// worker(id, rx): the let drops the lock guard at the\n// semicolon, so the job runs with the rail unlocked.\nloop {\n    let msg = rx.lock().unwrap().___();\n    let Ok(job) = msg else { break };  // Err: senders gone\n    job();\n}\n"] = "// worker(id, rx): let zahodí guard zámku už na\n// středníku, takže job běží s odemčenou lištou.\nloop {\n    let msg = rx.lock().unwrap().___();\n    let Ok(job) = msg else { break };  // Err: konec odesílatelů\n    job();\n}\n",
  ["//go:embed puts files in the binary: string, []byte or embed.FS."] = "//go:embed vloží soubory do binárky: string, []byte nebo embed.FS.",
  ["0  PNG DISK"] = "0  PNG DISK",
  ["0 is clean, a positive number is sys.exit(n), and a negative one is the signal that killed it: -9 is the out-of-memory killer."] = "0 je čisté, kladné číslo je sys.exit(n) a záporné je signál, který ho zabil: -9 je zabiják při nedostatku paměti.",
  ["0..3 stops before 3. Which range operator includes the last number?"] = "0..3 se zastaví před 3. Který operátor rozsahu zahrne i poslední číslo?",
  ["00:00. CODE RUSH, the live coding show on the Times Square screen, midnight edition: Python. The night market crowd, a buzzer, seven rounds, Chef Bo at the keyboard. No misses keeps the combo. Round one: recursion, and why fib needs a memo."] = "00:00. CODE RUSH, živá programátorská show na obrazovce Times Square, půlnoční vydání: Python. Dav nočního trhu, bzučák, sedm kol, šéfkuchař Bo u klávesnice. Bez chyb kombo pokračuje. První kolo: rekurze a proč fib potřebuje memo.",
  ["01:00. The night market is packing up and the startup's back office is still lit. Siu Ming, host by night, interviewer by later night, hands Chef Bo a marker. The Times Square screen said HIRED; the whiteboard decides the offer. Round one: a receipt full of brackets. Are they balanced?"] = "01:00. Noční trh balí a zadní kancelář startupu ještě svítí. Siu Ming, v noci moderátor, v pozdější noci tazatel, podává šéfkuchaři Bo fix. Obrazovka na Times Square řekla HIRED; tabule rozhodne o nabídce. První kolo: účtenka plná závorek. Jsou vyvážené?",
  ["02:00. The shutters are down and the night batch has forty thousand photos to resize before the morning delivery. Chef Bo threw threads at it and the laptop got hot and no faster. One lock in the interpreter is why, and there is exactly one way around it."] = "02:00. Mříže jsou dole a noční dávka má do ranního rozvozu zmenšit čtyřicet tisíc fotek. Šéf Bo na to hodil vlákna, notebook se zahřál a rychleji to nebylo. Důvodem je jeden zámek uvnitř interpretu a existuje právě jedna cesta okolo.",
  ["02:15. The fix looks like one word: Thread becomes Process. Then the terminal fills with the same log line a hundred times over, because a spawned child imports the script it came from and runs everything that is not tucked behind the main guard."] = "02:15. Náprava vypadá na jedno slovo: Thread se změní na Process. Načež se terminál zaplní stejným řádkem logu stokrát za sebou, protože potomek spuštěný přes spawn naimportuje skript, ze kterého vzešel, a spustí všechno, co není schované za stráží main.",
  ["02:30. Forty thousand photos, eight cores, and one lesson: pay for the interpreters once. A Pool is eight cooks reading the same order book, and the only real decision left is how many photos each of them carries across the kitchen at a time."] = "02:30. Čtyřicet tisíc fotek, osm jader a jedno ponaučení: za interprety se platí jen jednou. Pool je osm kuchařů čtoucích stejnou objednávkovou knihu a jediné skutečné rozhodnutí je, kolik fotek každý naráz přenese přes kuchyni.",
  ["02:45. The receipts worker fills a list and the parent prints nothing, over and over. There is no bug: the child got a copy of the list at start-up and has been filling that. Between processes there is only the dumbwaiter, and everything on it is pickled."] = "02:45. Worker na účtenky plní seznam a rodič nevypíše nic, znovu a znovu. Není to chyba: potomek dostal při startu kopii seznamu a plní ji. Mezi procesy je jen jídelní výtah a všechno, co na něm jede, prošlo picklem.",
  ["03:00. Eight workers, one label printer, and a sticker with two orders printed on top of each other. Separate memory did not make the printer separate. What crosses process lines now is not data but permission: who may write, and when."] = "03:00. Osm workerů, jedna tiskárna štítků a nálepka se dvěma objednávkami vytištěnými přes sebe. Oddělená paměť tiskárnu neoddělila. Hranici procesů teď nepřekračují data, ale povolení: kdo smí psát a kdy.",
  ["03:20. The month's receipts are two gigabytes and every worker got its own pickled copy of them: eight copies, eight seconds of pickling, one machine on its knees. The cold room is the answer. One block of bytes, everybody walks in, nobody carries it."] = "03:20. Účtenky za měsíc mají dva gigabajty a každý worker dostal vlastní kopii přes pickle: osm kopií, osm sekund picklování, jeden stroj na kolenou. Odpovědí je chladicí box. Jeden blok bajtů, všichni do něj vejdou a nikdo ho nenosí.",
  ["03:50. The van comes at five. What is left is four hundred HTTP calls to the supplier and four hundred images to resize, and Chef Bo wants one way to write both. concurrent.futures is that way: the same six lines, and one word that decides whether it waits or computes."] = "03:50. Dodávka přijede v pět. Zbývá čtyři sta HTTP volání na dodavatele a čtyři sta obrázků ke zmenšení a šéf Bo chce jeden způsob, jak napsat obojí. concurrent.futures je ten způsob: stejných šest řádků a jedno slovo, které rozhodne, jestli se čeká, nebo počítá.",
  ["06:40. Causeway Bay. Alex wants a muffin, a hash brown and coffee. The flat's door kiosk will not unlock until the Go file compiles."] = "06:40. Causeway Bay. Alex chce muffin, hash brown a kávu. Kiosek na dveřích bytu se neodemkne, dokud se soubor v Go nezkompiluje.",
  ["08:10. Breakfast done. The owner wants a delivery app before the lunch rush. First ticket: the signboard shows 銅鑼灣 wrong, because a Go string is bytes, not characters."] = "08:10. Po snídani. Majitel chce rozvozovou appku před obědovým náporem. První ticket: cedule ukazuje 銅鑼灣 špatně, protože string v Go jsou bajty, ne znaky.",
  ["1  QUESTION"] = "1  OTÁZKA",
  ["1 + max(hl, hr). A balanced tree of n nodes is about log2(n) tall; a sorted insert order makes a list, height n."] = "1 + max(hl, hr). Vyvážený strom s n uzly je vysoký asi log2(n); seřazené pořadí vkládání udělá seznam, výška n.",
  ["1-4 copy    5-0 export    A all    S scope    ESC close"] = "1-4 kopírovat    5-0 exportovat    A vše    S rozsah    ESC zavřít",
  ["1-7 jump straight in.   Q quest.   TAB Go/Rust.   F3 language.   F4 sound.   ESC quit."] = "1-7 skok rovnou dovnitř.   Q mise.   TAB Go/Rust.   F3 jazyk.   F4 zvuk.   ESC konec.",
  ["1-7 jump straight in.   Q quest.   TAB Go/Rust/Python.   F3 language.   F4 sound.   ESC quit."] = "1-7 skok rovnou dovnitř.   Q úkol.   TAB Go/Rust/Python.   F3 jazyk.   F4 zvuk.   ESC konec.",
  ["1..=3 is 1, 2, 3. for in Rust walks anything iterable: ranges, Vec, iterators."] = "1..=3 je 1, 2, 3. for v Rustu projde cokoli iterovatelného: rozsahy, Vec, iterátory.",
  ['1..=5 is RangeInclusive; 1..5 stops at 4. Also in patterns: 1..=5 => "low".'] = '1..=5 je RangeInclusive; 1..5 skončí u 4. Funguje i ve vzorech: 1..=5 => "low".',
  ["10. A million items take 20, a billion 30. That is how slowly log n grows."] = "10. Milion položek zabere 20, miliarda 30. Tak pomalu log n roste.",
  ["10. A million items take 20, a billion 30. That is how slowly log n grows: the line almost lies down."] = "10. Milion položek zabere 20, miliarda 30. Tak pomalu log n roste: čára si téměř lehne.",
  ["100 RIGHT"] = "100 SPRÁVNĚ",
  ["1024 sorted items. Halving each time, at most how many steps until one is left?"] = "1024 seřazených položek. Půlením pokaždé, nejvýše kolik kroků, než zbude jedna?",
  ["12:00. Both tills are open, the queue is out to Percival Street, and the counter on the wall is wrong by six. Nobody stole anything: sold++ is a read, an add and a write, and two goroutines read the same number before either wrote it back."] = "12:00. Obě kasy jsou otevřené, fronta sahá až na Percival Street a čítač na zdi se plete o šest. Nikdo nic neukradl: sold++ je čtení, přičtení a zápis, a dvě goroutiny přečetly stejné číslo dřív, než ho jedna z nich stihla zapsat zpět.",
  ["12:20. The door sensor, the till and the delivery app all raise one counter. A mutex would work and would also be the slowest thing in the building. The hardware can add without a lock; the sync/atomic package is how Go asks it to."] = "12:20. Čidlo u dveří, kasa i doručovací aplikace zvedají jeden čítač. Mutex by fungoval a zároveň by byl tou nejpomalejší věcí v budově. Hardware umí přičítat bez zámku; balík sync/atomic je způsob, jak ho o to Go požádá.",
  ["12:35. The kitchen board is a map[string]int the six wok goroutines all write to, and Go kills the process for it on purpose: a torn map is worse than a stopped one. Alex has three ways out, and only one of them is a lock."] = "12:35. Kuchyňská tabule je map[string]int, do které zapisuje všech šest goroutin od woků, a Go kvůli tomu schválně zabije proces: roztržená mapa je horší než zastavený program. Alex má tři východiska a jen jedno z nich je zámek.",
  ["12:50. Forty riders, eight bikes, one printer. Goroutines are cheap enough that Alex made one per order and the queue turned to noise. A pool is the fix: a fixed number of workers, all reading the same channel, all finishing before the shift ends."] = "12:50. Čtyřicet kurýrů, osm kol, jedna tiskárna. Goroutiny jsou tak levné, že jich Alex udělal jednu na objednávku a fronta se změnila v šum. Náprava je fond: pevný počet workerů, všichni čtou stejný kanál a všichni skončí před koncem směny.",
  ["13:00. CODE RUSH, the live coding show on the Times Square screen. A crowd, a buzzer, seven rounds. Answer without a miss to keep the combo. Round one: recursion, and why fib needs a memo."] = "13:00. CODE RUSH, živá programátorská show na obrazovce na Times Square. Dav, bzučák, sedm kol. Odpovídej bez chyby, ať udržíš combo. Kolo jedna: rekurze a proč fib potřebuje memo.",
  ["13:05. The kitchen stopped sending but the counter kept receiving, and every receive came back instantly with an empty Order. A closed channel is not an error: it is a promise that nothing more is coming, and the second value of the receive is where it says so."] = "13:05. Kuchyně přestala posílat, ale pult dál přijímal a každý příjem se okamžitě vracel s prázdnou objednávkou. Zavřený kanál není chyba: je to slib, že už nic nepřijde, a druhá hodnota příjmu je místo, kde to říká.",
  ["13:20. A rider cancels, the customer closes the app, and three goroutines carry on fetching an ETA nobody will read. Go cannot kill a goroutine from outside: cancellation is a value you pass in and a channel the work agrees to watch."] = "13:20. Kurýr ruší, zákazník zavřel aplikaci a tři goroutiny dál shánějí ETA, které nikdo nepřečte. Go neumí zabít goroutinu zvenčí: zrušení je hodnota, kterou předáš, a kanál, který se práce zavázala sledovat.",
  ["13:40. Alex asks the question every newcomer asks: where is async, where is await? Mei draws two lines on the whiteboard. Start it with go. Wait for it with an arrow. Everything async/await gives you, Go gives you without splitting functions into two kinds."] = "13:40. Alex položí otázku, kterou pokládá každý nováček: kde je async, kde je await? Mei nakreslí na tabuli dva řádky. Spusť to přes go. Počkej na to šipkou. Všechno, co dává async/await, dává Go taky, a navíc bez rozdělení funkcí na dva druhy.",
  ["14:30. The screen at Times Square still says HIRED, but the startup wants a second round in the back office: a whiteboard, a marker, Siu Ming with a list. Round one is the question every callback starts with: does every bracket close in the right order?"] = "14:30. Obrazovka na Times Square pořád říká PŘIJAT, ale startup chce druhé kolo v zadní kanceláři: tabule, fix, Siu Ming se seznamem. Kolo jedna je otázka, kterou začíná každý callback: zavírá se každá závorka ve správném pořadí?",
  ["15:00. Lunch is done at Lucky Mac. Mei's laptop shows the Times Square branch: every kiosk of Lucky Mac Express is frozen on a Rust file with no main. Alex knows Go. Mei knows Rust. They start walking."] = "15:00. Oběd v Lucky Mac skončil. Na Meiině notebooku je pobočka na Times Square: každý kiosek Lucky Mac Express zamrzl na souboru v Rustu bez main. Alex zná Go. Mei zná Rust. Vyrážejí pěšky.",
  ["15:08. The tram stop on Percival Street. The next-tram sign runs a tiny Rust program and it will not compile: someone tried to change a value that was never marked mut. Mei fixes it while Alex reads the error messages out loud."] = "15:08. Tramvajová zastávka na Percival Street. Tabule s další tramvají běží na malém programu v Rustu a ten se nezkompiluje: někdo zkusil změnit hodnotu, která nikdy nebyla označená mut. Mei to opravuje, zatímco Alex čte chybové hlášky nahlas.",
  ["15:15. The underpass at Causeway Bay MTR exit A. The Lucky Mac Express ad gate should show muffin, coffee or set as people walk past, but its match has a hole and the loop never ends. Mei counts the cases on her fingers."] = "15:15. Podchod u výstupu A z MTR Causeway Bay. Reklamní brána Lucky Mac Express má kolemjdoucím ukazovat muffin, coffee nebo set, ale její match má díru a cyklus nikdy nekončí. Mei počítá případy na prstech.",
  ["15:20. The footbridge over Canal Road, Times Square's clock ahead. The Express delivery board on the bridge shows the price of every set, but the pricing function returns nothing and the seat finder crashes on an empty table. Alex tries the Rust himself for the first time."] = "15:20. Lávka přes Canal Road, před nimi hodiny Times Square. Rozvozová tabule Express na mostě ukazuje cenu každého menu, ale cenová funkce nic nevrací a hledač míst padá na prázdném stole. Alex si Rust poprvé zkouší sám.",
  ["15:25. The atrium of Times Square, the crab sticker on the Express order kiosk. The kiosk prints a receipt, then tries to read the same String again and the compiler says: value used after move. Mei explains who owns the tray."] = "15:25. Atrium Times Square, nálepka s krabem na objednávkovém kiosku Express. Kiosek vytiskne účtenku, pak zkusí znovu přečíst tentýž String a kompilátor říká: value used after move. Mei vysvětluje, kdo vlastní tác.",
  ["15:30. The delivery app is one file and the Times Square shop wants to import the menu code from GitHub. Before there is a package to import there has to be a module to hold it, and the module's name is not a label: it is the first half of every import path."] = "15:30. Rozvozová aplikace je jeden soubor a obchod na Times Square chce importovat kód menu z GitHubu. Než bude co importovat, musí existovat modul, který balíček drží, a jméno modulu není nálepka: je to první polovina každé importní cesty.",
  ["15:30. The queue outside Lucky Mac Express, twelve people and a crab sticker on the board. The board should list every order's price and count the muffins per table, but the Vec is never pushed to and the HashMap panics on a missing key. Siu Ming waves them to the front."] = "15:30. Fronta před Lucky Mac Express, dvanáct lidí a nálepka s krabem na tabuli. Tabule má vypisovat cenu každé objednávky a počítat muffiny na stůl, ale do Vec se nikdy nic nepushne a HashMap panikaří na chybějícím klíči. Siu Ming je mává dopředu.",
  ["15:35. The counter of Lucky Mac Express at last, the crab sticker smiling on the till. The till keeps orders as loose tuples and cannot print them, and a size of Medium sneaks in that the kitchen does not know. Siu Ming needs an Order type before the afternoon set can be sold."] = "15:35. Konečně pult Lucky Mac Express, nálepka s krabem se usmívá na pokladně. Pokladna drží objednávky jako volné n-tice a neumí je vytisknout, a vloudila se velikost Medium, kterou kuchyně nezná. Siu Ming potřebuje typ Order, než se odpolední menu bude moct prodat.",
  ["15:45. The menu code moves into its own folder and immediately breaks in three ways: the package is named after nothing, main cannot see the price function, and the import written as ./menu will not build. All three are the same lesson about what a path means."] = "15:45. Kód menu se stěhuje do vlastní složky a hned se rozbije třemi způsoby: balíček se nejmenuje podle ničeho, main nevidí funkci price a import zapsaný jako ./menu se nepřeloží. Všechny tři jsou stejná lekce o tom, co cesta znamená.",
  ["16:00. Lucky Mac Express, Times Square. The till took a coin it could not parse and froze on a red Err. Siu Ming has a queue; Alex has to learn how Rust hands errors back."] = "16:00. Lucky Mac Express, Times Square. Pokladna vzala minci, kterou neuměla naparsovat, a zamrzla na červeném Err. Siu Ming má frontu; Alex se musí naučit, jak Rust vrací chyby.",
  ["16:00. The cousin's shop imports github.com/alex/luckymac/menu and the go tool fetches it from GitHub without being told where GitHub is: the host is in the path. What it writes down afterwards, in go.mod and go.sum, is what makes next month's build the same build."] = "16:00. Bratrancův obchod importuje github.com/alex/luckymac/menu a nástroj go ho stáhne z GitHubu, aniž by mu kdo řekl, kde GitHub je: host je v cestě. To, co si potom zapíše do go.mod a go.sum, dělá z buildu za měsíc tentýž build.",
  ["16:10. The Express kitchen. Chef Bo's pass runs every station through one Rust program, but the grill and the wok speak different types and the order board shows nothing. A trait gives them one shared voice."] = "16:10. Kuchyně Express. Výdej šéfkuchaře Bo řídí každou stanici jedním programem v Rustu, ale gril a wok mluví různými typy a tabule objednávek nic neukazuje. Trait jim dá jeden společný hlas.",
  ["16:15. Exporting a name is a promise, and the cousin's shop just took Alex up on one he never meant to make. The fix is not a comment asking people to be nice: it is a directory name the compiler enforces, and a layout that says which packages are the API."] = "16:15. Exportovat jméno je slib a bratrancův obchod právě vzal Alexe za slovo u slibu, který nikdy nemínil dát. Náprava není komentář prosící o slušnost: je to jméno adresáře, které vynucuje překladač, a rozvržení, které říká, které balíčky jsou API.",
  ["16:20. The kiosk in the mall corridor has one price list in u32 and one weight list in f64, and two copies of every function. The crab on the screen sulks. Generics fold them into one."] = "16:20. Kiosek v chodbě obchoďáku má jeden ceník v u32 a jeden seznam vah ve f64, a od každé funkce dvě kopie. Krab na obrazovce trucuje. Generika je složí do jedné.",
  ["16:30. The path problem in the flesh: the library on disk is newer than the library in the cache, and the import path points at the cache. Two lines of go.mod, or one go.work file, redirect a path to a folder while you work, and tidy puts go.mod back in step."] = "16:30. Problém s cestou v celé kráse: knihovna na disku je novější než knihovna v cache a importní cesta ukazuje do cache. Dva řádky go.mod, nebo jeden soubor go.work, přesměrují cestu na složku, dokud pracuješ, a tidy vrátí go.mod do souladu.",
  ["16:30. The set table by the window. The receipt printer holds a reference to a name that was freed one line earlier and Rust refuses to build. Alex learns to say how long a borrow lives."] = "16:30. Stůl s menu u okna. Tiskárna účtenek drží referenci na jméno, které bylo uvolněno o řádek dřív, a Rust odmítá sestavit. Alex se učí říct, jak dlouho výpůjčka žije.",
  ["16:40. Three orders, one cook, one thread: the pineapple buns wait while the kettle boils. Chef Bo wants the grill, the kettle and the pass to run at the same time. Rust threads are real OS threads; no go keyword here."] = "16:40. Tři objednávky, jeden kuchař, jedno vlákno: ananasové housky čekají, dokud se vaří konvice. Šéfkuchař Bo chce, aby gril, konvice a výdej běžely zároveň. Vlákna v Rustu jsou skutečná vlákna OS; žádné klíčové slovo go tady není.",
  ["16:45. There is no publish button. A Go module is released by pushing a git tag, and the number on the tag is a contract: patch and minor never break a caller, and a major that does gets a new import path so old and new can live side by side."] = "16:45. Žádné tlačítko publikovat neexistuje. Go modul se vydává pushnutím git tagu a číslo na tagu je smlouva: patch a minor nikdy nerozbijí volajícího, a major, který rozbije, dostane novou importní cestu, aby staré a nové mohly žít vedle sebe.",
  ["16:50. Two tills at Lucky Mac Express and one kitchen. Orders sit in a shared Vec that both tills scribble on and the kitchen never sees. Mei replaces the Vec with a channel: many senders, one receiver."] = "16:50. Dvě pokladny v Lucky Mac Express a jedna kuchyně. Objednávky leží ve sdíleném Vec, do kterého obě pokladny čmárají a kuchyně ho nikdy nevidí. Mei nahradí Vec kanálem: mnoho odesílatelů, jeden příjemce.",
  ["17:00. Last hour before the tea set. Both tills bump one sold counter from two threads and the total drifts. Rc will not even compile across threads; Mei reaches for Arc, Mutex and one atomic. Get it right and the afternoon tea set is yours."] = "17:00. Poslední hodina před svačinou. Obě pokladny zvyšují jeden čítač prodejů ze dvou vláken a součet ujíždí. Rc se napříč vlákny ani nezkompiluje; Mei sahá po Arc, Mutex a jednom atomiku. Udělej to správně a odpolední svačina je tvoje.",
  ["17:00. Lucky Mac Express, Times Square. The receipt printer writes the shop name as 銅鑼 and a broken square. Someone sliced a String by byte count. Mei opens ticket one."] = "17:00. Lucky Mac Express, Times Square. Tiskárna účtenek píše název obchodu jako 銅鑼 a rozbitý čtvereček. Někdo rozřezal String podle počtu bajtů. Mei otvírá ticket jedna.",
  ["17:00. The last path problem is not on disk: it is between the go tool, a public proxy that mirrors the whole ecosystem, and a repo that only Alex's ssh key can open. Two environment variables and one git setting route the private path around the proxy."] = "17:00. Poslední problém s cestou není na disku: je mezi nástrojem go, veřejnou proxy, která zrcadlí celý ekosystém, a repozitářem, který otevře jen Alexův ssh klíč. Dvě proměnné prostředí a jedno nastavení gitu vedou soukromou cestu kolem proxy.",
  ["17:10. The till at Lucky Mac Express unwraps every parse. One bad keypad entry and the drawer prints a stack trace instead of a receipt. Siu Ming wants a real error type."] = "17:10. Kasa v Lucky Mac Express unwrapuje každý parse. Jeden špatný úhoz na klávesnici a pokladna vytiskne stack trace místo účtenky. Siu Ming chce pořádný typ chyby.",
  ["17:20. The kitchen printer at Lucky Mac Express runs a hand-written index loop. It skips the first dish and prints the last one twice. Chef Bo hands Alex ticket three: iterators."] = "17:20. Kuchyňská tiskárna v Lucky Mac Express jede na ručně psaném cyklu s indexem. Přeskočí první jídlo a poslední vytiskne dvakrát. Šéfkuchař Bo podává Alexovi ticket tři: iterátory.",
  ['17:30. Under the mall atrium screens, the rider app and the kitchen disagree on field names, and every order arrives as "name": null. Ticket four: teach the structs to speak JSON with serde.'] = '17:30. Pod obrazovkami v atriu obchoďáku se appka kurýrů a kuchyň neshodnou na názvech polí a každá objednávka dorazí jako "name": null. Ticket čtyři: nauč structy mluvit JSONem přes serde.',
  ["17:40. Russell Street. Riders idle by the tram stop while the delivery backend fetches ETAs one by one, blocking on each. Ticket five: make the calls async and run them together on tokio."] = "17:40. Russell Street. Kurýři se flákají u zastávky tramvaje, zatímco rozvozový backend stahuje ETA jedno po druhém a na každém blokuje. Ticket pět: udělej volání async a pusť je společně na tokiu.",
  ["17:50. The pickup queue at Lucky Mac Express is out the door and the new backend is still a folder of .rs files. Alex has go build in his fingers. Mei: in Rust it is all cargo."] = "17:50. Fronta na vyzvednutí v Lucky Mac Express sahá až ze dveří a nový backend je pořád jen složka souborů .rs. Alex má v prstech go build. Mei: v Rustu je všechno cargo.",
  ["17:55. Lucky Mac Express, the set counter. The backend compiles, but Mei's review has six comments: this is 2015 Rust. Alex rewrites each one the modern way. Then it ships. SHIPPED."] = "17:55. Lucky Mac Express, pult s menu. Backend se kompiluje, ale Mei má v review šest komentářů: tohle je Rust z roku 2015. Alex každý přepíše moderně. Pak to jde ven. NASAZENO.",
  ["19:00. CODE RUSH, the live coding show on the Times Square screen, evening edition: Rust. A crowd, a buzzer, seven rounds, Mei at the keyboard. No misses keeps the combo. Round one: recursion, and why fib needs a memo."] = "19:00. CODE RUSH, živá coding show na obrazovce na Times Square, večerní vydání: Rust. Dav, bzučák, sedm kol, Mei za klávesnicí. Bez chyby drží kombo. První kolo: rekurze a proč fib potřebuje memo.",
  ["19:08. Round two, and the screen shows a tree of order numbers. Insert, walk in order, measure the height. In Rust a tree is a struct with two Option<Box<Node>> fields, and the compiler wants to know its size."] = "19:08. Druhé kolo a na obrazovce je strom čísel objednávek. Vlož, projdi v pořadí, změř výšku. V Rustu je strom struct se dvěma poli Option<Box<Node>> a kompilátor chce znát jeho velikost.",
  ["19:17. Round three puts the MTR map on the big screen: stations are nodes, lines are edges. Mei has to reach every station once. Wide first with a queue, then deep with a stack, and a HashSet so nobody loops forever."] = "19:17. Třetí kolo dá na velkou obrazovku mapu MTR: stanice jsou uzly, linky jsou hrany. Mei musí navštívit každou stanici jednou. Nejdřív do šířky s frontou, pak do hloubky se zásobníkem, a HashSet, aby se nikdo nezacyklil.",
  ["19:26. Round four is the chain: a linked list of order tickets, out on the street where the delivery riders queue. Each node owns the next one. Reverse it, walk it, find the middle, and never touch a raw pointer."] = "19:26. Čtvrté kolo je řetěz: spojový seznam lístků objednávek, venku na ulici, kde stojí fronta kurýrů. Každý uzel vlastní ten další. Otoč ho, projdi ho, najdi střed, a nikdy nesahej na syrový ukazatel.",
  ["19:35. Round five, the shuffle. The screen dumps a hundred order prices in random order. Mei writes merge sort from memory, then the host wants the std spelling: stable, unstable, and a binary search on the result."] = "19:35. Páté kolo, zamíchání. Obrazovka vysype sto cen objednávek v náhodném pořadí. Mei píše merge sort zpaměti, pak moderátor chce zápis ze std: stabilní, nestabilní a binární vyhledání ve výsledku.",
  ["19:44. Round six, the classics, back on the mall floor with the crowd pressing in. Two-sum, a palindrome, an anagram, a word count. Every one of them is a hash map or an array of 26, and every one is O(n)."] = "19:44. Šesté kolo, klasika, zpátky v pasáži obchoďáku a dav se tlačí. Two-sum, palindrom, přesmyčka, počítání slov. Každé z nich je hash mapa nebo pole o 26 prvcích a každé je O(n).",
  ["19:55. The final, the one they always ask: N worker threads pull jobs from one channel. The Times Square screen shows the Lucky Mac Express kitchen as the diagram. Get the lock, the drop and the join right and the prize is HIRED."] = "19:55. Finále, ta otázka, co padne vždycky: N pracovních vláken tahá joby z jednoho kanálu. Obrazovka na Times Square ukazuje jako diagram kuchyni Lucky Mac Express. Trefit zámek, drop i join a cena je PŘIJATA.",
  ["2  HINT"] = "2  NÁPOVĚDA",
  ["2 ** 10 is 1024. 2 ** 0.5 is a square root. Ints never overflow in Python; they just grow."] = "2 ** 10 je 1024. 2 ** 0.5 je druhá odmocnina. Inty v Pythonu nikdy nepřetečou; jen rostou.",
  ["20:30. The Times Square screen is dark; the startup's back office is not. A whiteboard, a marker, Siu Ming with a clipboard. The callback round: the problems the live show never had time for. First, brackets. Every ( wants its ), in order, and a Vec is the stack."] = "20:30. Obrazovka na Times Square je tmavá; zadní kancelář startupu ne. Tabule, fix, Siu Ming s deskami na psaní. Kolo CALLBACK: úlohy, na které živá show nikdy neměla čas. Nejdřív závorky. Každá ( chce svou ), ve správném pořadí, a Vec je zásobník.",
  ["20:38. Siu Ming draws a staircase. One step or two at a time: how many ways to the top? Mei sees fib, but this time there is no memo: a Vec filled from the bottom. Then the till: the fewest coins for 27 dollars, from 1, 5 and 10. Same table, a min instead of a sum."] = "20:38. Siu Ming kreslí schodiště. Po jednom nebo po dvou schodech: kolika způsoby nahoru? Mei vidí fib, ale tentokrát bez mema: Vec plněný odspoda. Pak pokladna: nejméně mincí na 27 dolarů z 1, 5 a 10. Stejná tabulka, min místo součtu.",
  ["20:45. A week of Lucky Mac Express sales on the whiteboard, some days negative. Which run of days made the most? Mei writes Kadane in four lines. Then windows of k hours, then the longest stretch of dishes with no repeat. Every one of them is one pass and two indices."] = "20:45. Týden tržeb Lucky Mac Express na tabuli, některé dny záporné. Která řada dnů vydělala nejvíc? Mei píše Kadaneho na čtyři řádky. Pak okna k hodin, pak nejdelší úsek jídel bez opakování. Každé z toho je jeden průchod a dva indexy.",
  ["20:52. Siu Ming dumps a box of receipts on the table: ten thousand of them. The third largest, please, and the five most ordered dishes. Sorting is O(n log n) and the crowd knows it. Mei draws a heap of size k on the board and the room goes quiet."] = "20:52. Siu Ming vysype na stůl krabici účtenek: deset tisíc. Třetí největší, prosím, a pět nejobjednávanějších jídel. Řazení je O(n log n) a dav to ví. Mei kreslí na tabuli haldu velikosti k a v místnosti se rozhostí ticho.",
  ["21:00. The cook's shift sheet goes up on the board: a dozen (start, end) pairs, out of order, overlapping. When is the kitchen covered, and where are the gaps? Sort by start, keep the last merged shift in view, and each new one either stretches it or starts a fresh block."] = "21:00. Na tabuli jde rozpis směn kuchařů: tucet dvojic (start, end), na přeskáčku, překrývajících se. Kdy je kuchyně pokrytá a kde jsou díry? Seřaď podle začátku, drž na očích poslední sloučenou směnu, a každá nová ji buď natáhne, nebo začne nový blok.",
  ["21:00. The morning set is long gone and the Rust afternoon is over. Lucky Mac's night shift runs on Python scripts Chef Bo wrote years ago. Tonight the pass screen is blank. Bo hands Alex the laptop; a blue and yellow snake sticker on the lid seems to grin."] = "21:00. Snídaňové menu je dávno pryč a rustové odpoledne skončilo. Noční směna v Lucky Macu běží na pythonových skriptech, které šéfkuchař Bo napsal před lety. Dnes v noci je obrazovka u výdeje černá. Bo podává Alexovi notebook; modrožlutá samolepka hada na víku jako by se usmívala.",
  ["21:08. The one every backend interview ends with: a cache with a capacity, where the least recently used entry makes room for the new one. Mei keeps it honest: a HashMap for the values, a VecDeque for the order, and a note on the board that the linked-list version makes every step O(1)."] = "21:08. Ta, kterou končí každý backendový pohovor: cache s kapacitou, kde nejdéle nepoužitá položka uvolní místo nové. Mei to drží poctivé: HashMap na hodnoty, VecDeque na pořadí a poznámka na tabuli, že verze se spojovým seznamem má každý krok v O(1).",
  ["21:15. The last board: Victoria Harbour as a grid of ones and zeros. How many islands? Mei writes sink: stop at the edge, stop at water, turn this cell to water, flood the four neighbours. Count one per unsunk land cell. Siu Ming caps the marker. The screen outside lights up: OFFER."] = "21:15. Poslední tabule: Victoria Harbour jako mřížka jedniček a nul. Kolik ostrovů? Mei píše sink: zastav na okraji, zastav na vodě, změň tuhle buňku na vodu, zaplav čtyři sousedy. Počítej jedna za každou nepotopenou pevninskou buňku. Siu Ming zavírá fix. Obrazovka venku se rozsvítí: OFFER.",
  ["22:00. The back office behind the kitchen: a humming rack, two laptops, a whiteboard with a tree on it. The refund script crashes on the first bad receipt because nobody catches anything. Alex reaches for if err != nil; Bo shakes his head."] = "22:00. Zadní kancelář za kuchyní: hučící rack, dva notebooky, tabule se stromem. Skript vratek padá na první špatné účtence, protože nikdo nic nezachytává. Alex sahá po if err != nil; Bo vrtí hlavou.",
  ["22:15. The shutter is half down and a small queue waits outside. Chef Bo's queue script counts bowls and people. It is missing every keyword that makes a decision. Mei reads Python like a recipe: colon, then indent."] = "22:15. Roleta je napůl dole a venku čeká malá fronta. Boův skript fronty počítá misky a lidi. Chybí mu všechna klíčová slova, která rozhodují. Mei čte Python jako recept: dvojtečka, pak odsazení.",
  ["23:00. The last order robot at the market stall runs on a class called Order. Its constructor is gone, its methods lost their first parameter, and the receipt prints <__main__.Order object at 0x7f...>. Bo fixes it with Alex; Monty the sticker watches from the lid."] = "23:00. Poslední objednávkový robot na tržním stánku běží na třídě jménem Order. Konstruktor je pryč, metody ztratily první parametr a účtenka tiskne <__main__.Order object at 0x7f...>. Bo to s Alexem opravuje; Monty ze samolepky sleduje z víka.",
  ["23:00. The last orders of the night hit three woks. The cook script runs them one after another. Threads will overlap the waiting; the GIL means they will not overlap the arithmetic. For frying, waiting is all that matters."] = "23:00. Poslední objednávky noci dopadají na tři woky. Kuchařský skript je zpracovává jednu po druhé. Vlákna překryjí čekání; GIL znamená, že nepřekryjí aritmetiku. Při smažení je čekání všechno, na čem záleží.",
  ["25 // 6 is 4, 25 / 6 is 4.1666. In Python 3 a single slash always makes a float."] = "25 // 6 je 4, 25 / 6 je 4.1666. V Pythonu 3 jedno lomítko vždy vytvoří float.",
  ["25 eggs, 6 per tray: how many whole trays? Which operator divides and rounds down?"] = "25 vajec, 6 na tác: kolik celých táců? Který operátor dělí a zaokrouhluje dolů?",
  ["2^n subsets. When the output itself is exponential no algorithm can be faster; when only the answer is needed, look for a memo."] = "2^n podmnožin. Když je exponenciální samotný výstup, žádný algoritmus nemůže být rychlejší; když je potřeba jen odpověď, hledej memo.",
  ["2^n subsets. When the output itself is exponential no algorithm can be faster; when only the answer is needed, look for a memo. The board is full."] = "2^n podmnožin. Když je exponenciální samotný výstup, žádný algoritmus nemůže být rychlejší; když je potřeba jen odpověď, hledej memo. Tabule je plná.",
  ["2^n subsets. itertools.combinations lists them; when the output itself is exponential no algorithm can be faster."] = "2^n podmnožin. itertools.combinations je vypíše; když je exponenciální samotný výstup, žádný algoritmus nemůže být rychlejší.",
  ["3  ANSWER"] = "3  ODPOVĚĎ",
  ["4  ALL"] = "4  VŠE",
  ["4950. For 10,000 guests it is about fifty million. Big O ignores the /2, and rightly: the curve is the same."] = "4950. Pro 10 000 hostů je to asi padesát milionů. Big O ignoruje /2, a právem: křivka je stejná.",
  ["4950. For 10,000 guests it is about fifty million. Big O ignores the /2: the curve is the same."] = "4950. Pro 10 000 hostů je to asi padesát milionů. Big O ignoruje /2: křivka je stejná.",
  ["5  MARKDOWN"] = "5  MARKDOWN",
  ["6  CSV"] = "6  CSV",
  ["7  JSONL"] = "7  JSONL",
  ["7 streets. One language. Type the answers."] = "7 ulic. Jeden jazyk. Piš odpovědi.",
  ["8  TXT"] = "8  TXT",
  ["9  SQLITE"] = "9  SQLITE",
  [":= declares and assigns. Type comes from the right-hand side."] = ":= deklaruje a přiřazuje. Typ se bere z pravé strany.",
  [":= infers the type. var names it. const never changes. int starts at 0."] = ":= odvodí typ. var ho pojmenuje. const se nikdy nemění. int začíná na 0.",
  ["< PREV"] = "< ZPĚT",
  ["<-chan T and chan<- T let the compiler stop the wrong side from sending or closing."] = "<-chan T a chan<- T nechají kompilátor zabránit špatné straně odesílat nebo zavírat.",
  ["<= merges [1,3] and [3,5] into [1,5]. Use < if touching intervals should stay apart."] = "<= sloučí [1,3] a [3,5] do [1,5]. Použij <, pokud mají dotýkající se intervaly zůstat zvlášť.",
  ["<= takes the left item on ties, so equal receipts keep their order. Merge is O(n); the whole sort O(n log n)."] = "<= bere při shodě levou položku, takže stejné účtenky si drží pořadí. Sloučení je O(n); celé třídění O(n log n).",
  ["? calls From::from on the error. Without the impl, use .map_err(OrderError::BadQty) by hand."] = "? zavolá na chybu From::from. Bez toho impl použij ručně .map_err(OrderError::BadQty).",
  ["? on Option returns None when it sees None. The function type must be Option as well."] = "? na Option vrátí None, když uvidí None. Návratový typ funkce musí být taky Option.",
  ["? unwraps Ok, or returns Err early from the function. Only works where the return type is Result or Option."] = "? rozbalí Ok, nebo z funkce předčasně vrátí Err. Funguje jen tam, kde je návratový typ Result nebo Option.",
  ["@classmethod gets cls; return cls(...) builds the right subclass too. The stamp desk closes."] = "@classmethod dostane cls; return cls(...) postaví i správnou podtřídu. Razítkovací přepážka zavírá.",
  ['@contextlib.___\ndef safe():\n    f = open("stock.csv")\n    try:\n        yield f\n    finally:\n        f.close()\n'] = '@contextlib.___\ndef safe():\n    f = open("stock.csv")\n    try:\n        yield f\n    finally:\n        f.close()\n',
  ["@contextlib.contextmanager: everything before yield is __enter__, everything after is __exit__. Ten lines become five."] = "@contextlib.contextmanager: všechno před yield je __enter__, všechno po něm je __exit__. Z deseti řádků pět.",
  ["@dataclass reads the annotated fields and writes the boilerplate. Order('tea', 2) just works. The shutter comes down; the night shift is closed."] = "@dataclass přečte anotovaná pole a napíše šablonový kód. Order('tea', 2) prostě funguje. Roleta jde dolů; noční směna je uzavřená.",
  ["@functools.___\ndef fib(n):\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)    # now O(n)\n"] = "@functools.___\ndef fib(n):\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)    # teď O(n)\n",
  ["@functools.cache (3.9) memoizes by arguments; @lru_cache(maxsize=128) bounds it. fib(40) becomes 40 calls."] = "@functools.cache (3.9) memoizuje podle argumentů; @lru_cache(maxsize=128) to omezí. Z fib(40) je 40 volání.",
  ["@functools.cache: a dict keyed by the arguments, O(1) per hit. Go spells this a comma-ok test; Rust memo.get(&n)."] = "@functools.cache: dict s argumenty jako klíči, O(1) na zásah. Go to píše testem comma-ok; Rust memo.get(&n).",
  ["@functools.wraps(fn) copies __name__, __doc__ and more onto the wrapper. Every decorator you write should use it."] = "@functools.wraps(fn) zkopíruje __name__, __doc__ a další na obal. Každý dekorátor, který napíšeš, by ho měl používat.",
  ["@property makes a getter; @total.setter adds assignment. Go would write a Total() method; Python hides the call."] = "@property vytvoří getter; @total.setter přidá přiřazení. Go by napsalo metodu Total(); Python volání schová.",
  ["@staticmethod: no implicit first argument. It is a namespaced plain function. Often a module-level def is clearer."] = "@staticmethod: žádný implicitní první argument. Je to obyčejná funkce v namespace. Často je def na úrovni modulu jasnější.",
  ["@timer above def fry is exactly fry = timer(fry). Sugar, nothing more. Decorators stack, top one runs last."] = "@timer nad def fry je přesně fry = timer(fry). Cukr, nic víc. Dekorátory se vrství, horní se aplikuje jako poslední.",
  ["A  ALL FORMATS"] = "A  VŠECHNY FORMÁTY",
  ["A DP table starts from the cases you can answer by hand. Everything else is built on them."] = "DP tabulka začíná případy, které umíš zodpovědět z hlavy. Všechno ostatní stojí na nich.",
  ["A Go release is a git tag: v1.0.0, pushed. go get pkg@latest picks the highest tag; no tag means a pseudo-version built from the commit. A breaking change is a new major, and a new major is a new import path: module github.com/you/x/v2. retract in go.mod tells everyone a tag was a mistake."] = "Vydání v Go je git tag: v1.0.0, pushnutý. go get pkg@latest vybere nejvyšší tag; bez tagu dostaneš pseudoverzi sestavenou z commitu. Nekompatibilní změna je nová major verze a nová major verze je nová importní cesta: module github.com/you/x/v2. retract v go.mod řekne všem, že tag byl omyl.",
  ["A Greek letter. Rust writes |o| o.1 for the same thing."] = "Řecké písmeno. Rust pro totéž píše |o| o.1.",
  ["A ListNode holds val and next. Reverse with three names: prev, cur, nxt. Two runners find the middle; if the fast one meets the slow one, there is a cycle."] = "ListNode drží val a next. Obrať pomocí tří jmen: prev, cur, nxt. Dva běžci najdou střed; když rychlý dohoní pomalého, je tam cyklus.",
  ["A Manager is convenience, not speed: every read and write is a round trip to another process. Fine for results, wrong for a hot loop."] = "Manager je pohodlí, ne rychlost: každé čtení i zápis je cesta tam a zpět do jiného procesu. Na výsledky dobré, do horké smyčky špatné.",
  ["A Node holds val, left, right; children start as None. Insert goes left when smaller. In-order walk prints sorted. Height is 1 + max of the children. BFS uses a deque and popleft."] = "Node drží val, left, right; děti začínají jako None. Vkládání jde vlevo, když je menší. Průchod in-order tiskne seřazeně. Výška je 1 + max z dětí. BFS používá deque a popleft.",
  ["A Pool starts N interpreters once and feeds them work. pool.map keeps the order and waits for everything; imap yields results as they land; starmap unpacks tuples into several arguments; apply_async returns a handle whose get() blocks. chunksize decides how many items travel per trip, and for tiny tasks it is the whole game."] = "Pool spustí N interpretů jednou a pak jim přihrává práci. pool.map zachová pořadí a počká na všechno; imap vydává výsledky, jak přicházejí; starmap rozbalí n-tice do několika argumentů; apply_async vrátí úchyt, jehož get() blokuje. chunksize rozhoduje, kolik položek pocestuje najednou, a u drobných úloh je v něm celá hra.",
  ["A Python list is your Go slice, minus the type. It just grows."] = "Pythonový seznam je tvůj slice z Go, bez typu. Prostě roste.",
  ["A Queue has no close(). What do you put on it to tell the workers to stop?"] = "Queue nemá close(). Co na ni položíš, abys workerům řekl, ať skončí?",
  ["A Semaphore is a lock that lets n holders through. mp also has Event, Condition and Barrier, all with the threading names."] = "Semaphore je zámek, který pustí n držitelů. mp má i Event, Condition a Barrier, všechny se jmény z threading.",
  ["A String has one owner. Assigning moves it. & borrows, &mut borrows exclusively. Values drop at the end of their scope."] = "String má jednoho vlastníka. Přiřazení ho přesune. & půjčuje, &mut půjčuje výhradně. Hodnoty se uvolní na konci svého bloku.",
  ["A Vec is a stack for free: the end is the top, and both ends of work are O(1)."] = "Vec je zásobník zdarma: konec je vrchol a práce na obou koncích je O(1).",
  ["A Vec is your Go slice. An array knows its length at compile time."] = "Vec je tvůj slice z Go. Pole zná svou délku při kompilaci.",
  ["A Vec<char> is the stack: push every opener, pop on every closer and compare. Valid when the stack ends empty. A second Vec of the smallest-so-far gives the minimum in O(1)."] = "Vec<char> je zásobník: pushni každou otevírací, při každé zavírací popni a porovnej. Platné, když zásobník skončí prázdný. Druhý Vec s dosavadními minimy dá minimum v O(1).",
  ["A VecDeque grows at both ends in O(1). The stale end is the front, so eviction is a pop from there."] = "VecDeque roste na obou koncích v O(1). Starý konec je předek, takže vyhození je pop odtamtud.",
  ["A WaitGroup that carries an error, from golang.org/x/sync. Two words joined: err and group."] = "WaitGroup, který nese chybu, z golang.org/x/sync. Dvě slova spojená v jedno: err a group.",
  ["A bang. vec! and format! end the same way."] = "Vykřičník. vec! a format! končí stejně.",
  ["A bool method on every collection, two words joined by an underscore. Not len() == 0, though that works too."] = "Metoda vracející bool na každé kolekci, dvě slova spojená podtržítkem. Ne len() == 0, i když to funguje taky.",
  ["A buffered channel blocks only when full. Unbuffered blocks on every send until someone receives."] = "Kanál s bufferem blokuje, jen když je plný. Bez bufferu blokuje každé odeslání, dokud někdo nepřijme.",
  ["A buffered channel is a counting semaphore. golang.org/x/sync/semaphore is the weighted version."] = "Bufferovaný channel je počítající semafor. golang.org/x/sync/semaphore je vážená verze.",
  ["A buffered channel of capacity 4 is a counting semaphore: the fifth send blocks until a trip finishes."] = "Kanál s kapacitou 4 je počítající semafor: páté odeslání se zablokuje, dokud jedna jízda neskončí.",
  ["A call that can fail returns Result. Handle Err, or pass it up with ?."] = "Volání, které může selhat, vrací Result. Ošetři Err, nebo ho pošli výš přes ?.",
  ["A channel that holds 3 muffins before a send blocks. Fill: make(chan string, ___)"] = "Kanál, který pojme 3 muffiny, než odeslání zablokuje. Doplň: make(chan string, ___)",
  ["A closed channel never blocks again, so a for-range over it ends and a bare receive returns instantly, for ever."] = "Zavřený kanál už nikdy neblokuje, takže for-range nad ním skončí a holý příjem se navždy vrací okamžitě.",
  ["A closer must match the most recent opener. Which method removes and returns the top?"] = "Zavírací závorka musí odpovídat poslední otvírací. Která metoda odebere a vrátí vršek?",
  ["A closer must match the most recent opener. Which method takes the top off and returns Option<char>?"] = "Zavírací závorka musí odpovídat poslední otevírací. Která metoda sundá vrchol a vrátí Option<char>?",
  ["A closer must match the top of the stack. Which map gives the opener it needs?"] = "Zavírací závorka musí sedět na vrchol zásobníku. Která mapa dá otevírací, kterou potřebuje?",
  ["A closer names the opener it needs. Finish the match: '}' wants which char?"] = "Zavírací závorka říká, kterou otevírací potřebuje. Dokonči match: '}' chce který znak?",
  ["A closure captures n. Each call to add(2) has its own n."] = "Closure zachytí n. Každé volání add(2) má vlastní n.",
  ["A cold coffee came back. The app says 'error' and nothing else."] = "Vrátila se studená káva. Appka říká 'error' a nic víc.",
  ["A compile-time value with an UPPER_CASE name and a required type. Which keyword?"] = "Hodnota známá při kompilaci, jméno VELKÝMI_PÍSMENY a povinný typ. Které klíčové slovo?",
  ["A constraint that allows int and every type built on int. Fill: ___int | ___float64"] = "Omezení, které povolí int a každý typ postavený na int. Doplň: ___int | ___float64",
  ["A context is the cancel signal of a request. It travels as the first parameter, named ctx, never inside a struct. WithCancel and WithTimeout wrap a parent and hand back a cancel function you always defer. Work watches ctx.Done() and reports ctx.Err(), which is Canceled or DeadlineExceeded."] = "Context je signál zrušení jednoho požadavku. Cestuje jako první parametr jménem ctx, nikdy uvnitř struktury. WithCancel a WithTimeout obalí rodiče a vrátí funkci cancel, kterou vždycky odložíš přes defer. Práce sleduje ctx.Done() a hlásí ctx.Err(), což je Canceled nebo DeadlineExceeded.",
  ["A cook locks the rail, pulls one ticket, releases. Which Receiver method blocks until a job arrives?"] = "Kuchař zamkne lištu, vytáhne jeden lístek, pustí ji. Která metoda Receiveru blokuje, dokud nepřijde job?",
  ["A cook takes the next order, waiting if the queue is empty. Which method?"] = "Kuchař vezme další objednávku, čeká, když je fronta prázdná. Která metoda?",
  ["A copied mutex protects nothing. Anything holding a sync type gets pointer receivers, and never travels by value."] = "Zkopírovaný mutex nechrání nic. Cokoli, co drží typ ze sync, má ukazatelové příjemce a nikdy necestuje hodnotou.",
  ["A counter every process can see. Which attribute reads and writes the shared number?"] = "Čítač, který vidí každý proces. Který atribut čte a zapisuje sdílené číslo?",
  ["A counter no mutex guards. Which sync/atomic type holds a 64-bit int?"] = "Čítač, který nehlídá žádný mutex. Který typ ze sync/atomic drží 64bitový int?",
  ["A crash you can catch in the same goroutine. Which pair: panic and ___?"] = "Pád, který lze chytit ve stejné goroutine. Která dvojice: panic a ___?",
  ['A crate writes Display and Error for you from #[error("..")]. Its name?'] = 'Crate ti napíše Display a Error z #[error("..")]. Jak se jmenuje?',
  ["A customer typed 1x8 sets and the till printed a page of panic. Ticket two."] = "Zákazník napsal 1x8 menu a kasa vytiskla stránku paniky. Ticket dva.",
  ["A daemon child is terminated when the parent exits, and it may not have children of its own. Use it for watchers, never for work you need finished."] = "Potomek s daemon se ukončí, když skončí rodič, a nesmí mít vlastní potomky. Používej ho na hlídače, nikdy na práci, kterou potřebuješ dokončit.",
  ["A decorator is a function that takes a function and returns a new one; @name applies it. functools.wraps keeps the name. @property, @staticmethod and @classmethod are built-in decorators."] = "Dekorátor je funkce, která vezme funkci a vrátí novou; @name ji aplikuje. functools.wraps zachová jméno. @property, @staticmethod a @classmethod jsou vestavěné dekorátory.",
  ["A def with no return evaluates to None. Printing that is a classic beginner surprise. The pass window is done."] = "def bez return se vyhodnotí na None. Vytisknout to je klasické překvapení začátečníka. Výdejní okno je hotové.",
  ["A dict from closer to opener. Looking up a closer is O(1); no chain of ifs."] = "Dict ze zavírací na otvírací. Vyhledání zavírací je O(1); žádný řetěz ifů.",
  ["A dict maps keys to values: {} makes one, d[k] reads, d.get(k, default) reads safely, .items() walks pairs, del removes. set() keeps unique items."] = "Dict mapuje klíče na hodnoty: {} ho vytvoří, d[k] čte, d.get(k, default) čte bezpečně, .items() prochází dvojice, del maže. set() drží jen unikátní položky.",
  ["A dict that also remembers which key is oldest. Which class from collections?"] = "Dict, který si také pamatuje, který klíč je nejstarší. Která třída z collections?",
  ["A directory that builds into a program declares which package?"] = "Adresář, který se překládá na program, deklaruje který balíček?",
  ["A done signal that carries no data. Fill the element type: make(chan ___)"] = "Signál hotovo, který nenese žádná data. Doplň typ prvku: make(chan ___)",
  ["A dot, then the word for waiting. Only allowed inside an async block or fn."] = "Tečka, pak slovo pro čekání. Povoleno jen uvnitř async bloku nebo fn.",
  ["A field with no name, only the type. That is embedding."] = "Pole bez jména, jen typ. To je embedding.",
  ["A fixed [26]int beats a map for lowercase ASCII. Then check every count == 0."] = "Pevné [26]int překoná mapu pro malé ASCII. Pak zkontroluj, že každý count == 0.",
  ["A fixed array of exactly 3 frames, size in the type. Fill: var frames ___"] = "Pevné pole přesně 3 snímků, velikost v typu. Doplň: var frames ___",
  ["A fixed tray of three prices. The array type spells out its length. Which number?"] = "Pevný tác tří cen. Typ pole vypisuje svou délku. Které číslo?",
  ["A fixed window is O(n), not O(n*k): every element enters once and leaves once."] = "Pevné okno je O(n), ne O(n*k): každý prvek jednou vstoupí a jednou odejde.",
  ["A flag: dash then four letters. Works with run and build too."] = "Přepínač: pomlčka a čtyři písmena. Funguje i s run a build.",
  ["A folder is a package"] = "Složka je balíček",
  ["A fresh node has no children yet. What are left and right set to?"] = "Nový uzel zatím nemá děti. Na co se nastaví left a right?",
  ["A function that can fail returns a value and an ___."] = "Funkce, která může selhat, vrací hodnotu a ___.",
  ["A function that can fail returns which type?"] = "Funkce, která může selhat, vrací který typ?",
  ["A function that remembers n after ident returns. What is that function called?"] = "Funkce, která si pamatuje n i poté, co ident vrátí. Jak se taková funkce jmenuje?",
  ["A function that runs once before main, and nobody calls it. Its name?"] = "Funkce, která běží jednou před main a nikdo ji nevolá. Jak se jmenuje?",
  ["A function, past tense, returning a new list. names.sort(key=len) would do it in place."] = "Funkce, v minulém čase, vracející nový seznam. names.sort(key=len) by to udělalo na místě.",
  ["A function, past tense. The method prices.sort() would change the list in place and return None."] = "Funkce, v minulém čase. Metoda prices.sort() by seznam změnila na místě a vrátila None.",
  ["A gap: this shift starts after the last block ended. Start a new block. Which list method?"] = "Mezera: tahle směna začíná až po konci posledního bloku. Začni nový blok. Která metoda seznamu?",
  ["A generator is a Rust iterator that writes itself. yield instead of impl Iterator."] = "Generátor je rustový iterátor, který se napíše sám. yield místo impl Iterator.",
  ["A go.work is a list of use directories and optional replaces. It never lists versions: those still come from each module's own go.mod."] = "go.work je seznam adresářů use a volitelných replace. Nikdy nevypisuje verze: ty pořád pocházejí z vlastního go.mod každého modulu.",
  ["A goroutine is cheap. Don't confuse it with a thread you create by hand."] = "Goroutine je levná. Nepleť si ji s vláknem, které vytvoříš ručně.",
  ["A goroutine is not an OS thread: the runtime multiplexes many of them onto GOMAXPROCS threads, so a pool sized by runtime.NumCPU() is the usual answer for CPU work. WaitGroup counts the workers, a buffered channel works as a semaphore, and sync.Pool recycles the buffers they allocate."] = "Goroutina není vlákno operačního systému: runtime jich multiplexuje spoustu na GOMAXPROCS vláken, takže fond o velikosti runtime.NumCPU() je obvyklá odpověď pro práci s procesorem. WaitGroup počítá workery, kanál s bufferem funguje jako semafor a sync.Pool recykluje buffery, které si alokují.",
  ["A goroutine that nobody waits for and nothing cancels is a leak: it holds its stack and whatever it captured until the process ends."] = "Goroutina, na kterou nikdo nečeká a kterou nic neruší, je únik: drží si zásobník i všechno zachycené, dokud proces neskončí.",
  ["A graph is a dict of lists: defaultdict(list). BFS uses a deque and a visited set; DFS recurses. Mark a node visited when you enqueue it, not when you pop it."] = "Graf je dict seznamů: defaultdict(list). BFS používá deque a množinu navštívených; DFS rekurzi. Uzel označ jako navštívený při zařazení do fronty, ne při vyjmutí.",
  ["A grid is a graph without an adjacency list. Count islands: for every land cell, count one and sink the whole island with a recursive flood that stops at the edges and at water. usize needs wrapping_sub for 'row minus one'."] = "Mřížka je graf bez seznamu sousedů. Počítání ostrovů: za každou pevninskou buňku počítej jedna a potop celý ostrov rekurzivní záplavou, která se zastaví na okrajích a na vodě. usize potřebuje wrapping_sub na „řádek minus jedna“.",
  ["A grid is a graph: each cell has four neighbours. Flood fill: stop off the map or on water, sink the cell, recurse four ways. Count one island per unsunk land cell in the double loop."] = "Mřížka je graf: každá buňka má čtyři sousedy. Flood fill: zastav mimo mapu nebo na vodě, potop buňku, rekurzivně na čtyři strany. Ve dvojitém cyklu počítej jeden ostrov za každou nepotopenou buňku pevniny.",
  ["A handful of index variables, however long the Vec. Constant."] = "Hrstka indexových proměnných, ať je Vec jakkoli dlouhý. Konstantní.",
  ["A handful of index variables, however long the list. Constant."] = "Hrstka indexových proměnných, ať je seznam jakkoli dlouhý. Konstantní.",
  ["A handful of index variables, however long the slice. Constant."] = "Hrstka indexových proměnných, ať je slice jakkoli dlouhý. Konstantní.",
  ["A heap is a list whose front is its root. The front index."] = "Halda je seznam, jehož začátek je kořen. Index začátku.",
  ["A heap of size k, Mei. Rust's is a max-heap, so you'll need the little wrapper that flips it."] = "Halda velikosti k, Mei. Ta v Rustu je max-halda, takže budeš potřebovat ten malý obal, co ji obrátí.",
  ["A heap pointer to a dyn trait: Box, angle brackets, dyn, the trait."] = "Ukazatel na haldu na dyn trait: Box, lomené závorky, dyn, trait.",
  ["A helper inside the class that needs neither self nor the class. Which decorator?"] = "Pomocník uvnitř třídy, který nepotřebuje ani self, ani třídu. Který dekorátor?",
  ["A hit: the key was just used, so it becomes the newest. Which OrderedDict method?"] = "Zásah: klíč byl právě použit, takže se stává nejnovějším. Která metoda OrderedDict?",
  ["A linear scan. Found early is lucky; Big O counts the worst case, n. A HashSet<String> makes it O(1)."] = "Lineární průchod. Najít brzy je štěstí; Big O počítá nejhorší případ, n. HashSet<String> z toho udělá O(1).",
  ["A linear scan. Found early is lucky; Big O counts the worst case, n. A map[string]bool makes it O(1)."] = "Lineární průchod. Najít brzy je štěstí; Big O počítá nejhorší případ, n. map[string]bool z toho udělá O(1).",
  ["A list grows with append and shrinks with pop. len counts. a[1:3] slices, a[-1] is the last item. [f(x) for x in a] builds a new list. sorted returns a new list."] = "Seznam roste pomocí append a zmenšuje se pomocí pop. len počítá. a[1:3] řeže, a[-1] je poslední položka. [f(x) for x in a] staví nový seznam. sorted vrací nový seznam.",
  ["A list is Option<Box<ListNode>>. take() moves a node out and leaves None. Reverse with prev and cur; slow and fast runners find the middle."] = "Seznam je Option<Box<ListNode>>. take() vytáhne uzel ven a nechá tam None. Otoč ho pomocí prev a cur; běžci slow a fast najdou střed.",
  ["A list is a stack: append pushes, pop takes the top, st[-1] peeks. Openers go on, closers must match the top. A second list of running minimums makes a min stack."] = "Seznam je zásobník: append vkládá, pop bere vršek, st[-1] nakoukne. Otvírací závorky jdou dovnitř, zavírací musí odpovídat vršku. Druhý seznam průběžných minim dělá min stack.",
  ["A list is not an iterator; get one from it. Which built-in?"] = "Seznam není iterátor; získej z něj jeden. Která vestavěná funkce?",
  ["A list of order names. Which built-in generic, lowercase since 3.9?"] = "Seznam jmen objednávek. Který vestavěný generický typ, od 3.9 malými písmeny?",
  ["A list of the dishes on the board, just the names. Which method?"] = "Seznam jídel na lístku, jen jména. Která metoda?",
  ["A loop over n guests inside a loop over m tables. The two sizes differ. Cost?"] = "Cyklus přes n hostů uvnitř cyklu přes m stolů. Obě velikosti se liší. Cena?",
  ["A loop over n guests inside a loop over the same n guests. Cost, in Big O?"] = "Cyklus přes n hostů uvnitř cyklu přes stejných n hostů. Cena, v Big O?",
  ["A loop that returns a value? Go cannot do that."] = "Cyklus, který vrací hodnotu? To Go neumí.",
  ["A major.minor like 1.23. Since Go 1.21 it is a real floor: an older toolchain will fetch a newer one."] = "major.minor jako 1.23. Od Go 1.21 je to skutečná spodní hranice: starší toolchain si stáhne novější.",
  ["A map built on hashing, CapWords. A Vec of pairs would need a scan, O(n)."] = "Mapa postavená na hashování, CapWords. Vec dvojic by potřeboval průchod, O(n).",
  ["A map entry pointing at a removed node is a bug waiting: the map and the list must always agree."] = "Položka mapy ukazující na odstraněný uzel je bug, který čeká: mapa a seznam se musí vždycky shodovat.",
  ["A map finds it, a list remembers the order. Two structures that agree."] = "Mapa to najde, seznam si pamatuje pořadí. Dvě struktury, které se shodují.",
  ['A map from string to int. Fill the type: prices := ___{"muffin": 18}'] = 'Mapa ze string na int. Doplň typ: prices := ___{"muffin": 18}',
  ["A map is a hash table. comma-ok tells you if the key was there. delete removes it."] = "Mapa je hashovací tabulka. comma-ok ti řekne, jestli tam klíč byl. delete ho odstraní.",
  ["A map of last positions lets the left edge jump instead of creeping one step at a time."] = "Mapa posledních pozic nechá levý okraj skočit, místo aby se plížil po jednom kroku.",
  ["A map turns 'does this closer match?' into one lookup. Openers are the values, closers the keys."] = "Mapa promění „sedí tahle zavírací závorka?“ v jedno vyhledání. Otevírací jsou hodnoty, zavírací klíče.",
  ["A map turns O(n^2) two-sum into O(n). Two pointers check a palindrome. A [26]int counts letters."] = "Mapa promění two-sum z O(n^2) na O(n). Dva ukazatele ověří palindrom. [26]int počítá písmena.",
  ["A match guard does the test. With < instead, (1,3) and (3,5) would stay apart; ask the interviewer which they want."] = "Test dělá match guard. S < místo toho by (1,3) a (3,5) zůstaly zvlášť; zeptej se tazatele, co chce.",
  ["A method on context.Context. Its channel closes on cancel."] = "Metoda na context.Context. Její kanál se zavře při zrušení.",
  ["A method that changes the order needs a pointer receiver. Fill: func (o ___) Add(p int)"] = "Metoda, která mění objednávku, potřebuje ukazatelový receiver. Doplň: func (o ___) Add(p int)",
  ["A min stack answers the minimum in O(1). Each push also records the smaller of x and the old low. Which built-in?"] = "Min stack odpoví minimum v O(1). Každý push také zaznamená menší z x a starého minima. Která vestavěná funkce?",
  ["A min stack answers the minimum in O(1): a second slice keeps the running minimum. What is pushed onto low?"] = "Min stack odpoví na minimum v O(1): druhý slice drží průběžné minimum. Co se pushuje do low?",
  ["A miss: compute it from the two smaller ones. Fill the second call: fib(___, memo)"] = "Minula: spočítej to ze dvou menších. Doplň druhé volání: fib(___, memo)",
  ["A module is a tree of packages with one go.mod at its root. go mod init names it, and that name is the prefix of every import path inside it, so name it after the repo: github.com/you/project. The go directive is the minimum toolchain. Modules have been the only mode since Go 1.16; GOPATH is history."] = "Modul je strom balíčků s jedním go.mod v kořeni. go mod init mu dá jméno a to jméno je předponou každé importní cesty uvnitř, takže ho pojmenuj podle repozitáře: github.com/you/project. Direktiva go je minimální toolchain. Moduly jsou jediný režim od Go 1.16; GOPATH je minulost.",
  ["A move. Integers are Copy and stay valid; a String is moved and the old name dies. No double free, ever."] = "Přesun (move). Celá čísla jsou Copy a zůstávají platná; String se přesune a staré jméno umírá. Nikdy žádné double free.",
  ["A mutex for a single int is a lot of ceremony for one number."] = "Mutex kvůli jedinému int je na jedno číslo hodně obřadu.",
  ["A name that cannot be assigned later. Which keyword?"] = "Jméno, do kterého už nejde později přiřadit. Které klíčové slovo?",
  ["A new neighbour: mark it seen when you enqueue it. Which set method?"] = "Nový soused: označ ho jako viděného při zařazení do fronty. Která metoda setu?",
  ["A nil *Order stored in an interface. Is the interface == nil? It prints ___"] = "nil *Order uložený v rozhraní. Je rozhraní == nil? Vytiskne ___",
  ["A nil map panics when you write to it. Allocate one: floors = ___(map[string]int)"] = "nil mapa při zápisu zpanikaří. Alokuj ji: floors = ___(map[string]int)",
  ["A node points at two children of its own type. Fill the field type: Left, Right ___"] = "Uzel ukazuje na dva potomky svého vlastního typu. Doplň typ pole: Left, Right ___",
  ["A phone book: open the middle, decide left or right, throw half away. Again."] = "Telefonní seznam: otevři uprostřed, rozhodni vlevo nebo vpravo, zahoď polovinu. Znovu.",
  ["A pipe that carries string. Fill: ch := make(___)"] = "Roura přenášející string. Doplň: ch := make(___)",
  ["A pointer receiver: a star before the type name."] = "Ukazatelový receiver: hvězdička před jménem typu.",
  ["A pointer to Order. Fill the type of p: var p ___Order"] = "Ukazatel na Order. Doplň typ p: var p ___Order",
  ["A pointer to the node type of container/list."] = "Ukazatel na typ uzlu z container/list.",
  ["A pointer, or the struct would contain itself forever. Star then the type."] = "Ukazatel, jinak by struct obsahoval sám sebe donekonečna. Hvězdička a pak typ.",
  ["A range with two dots, like Go's [1:3]."] = "Rozsah se dvěma tečkami, jako [1:3] v Go.",
  ["A receive-only parameter makes the compiler enforce the direction: a worker that tries to send on jobs will not build."] = "Parametr jen pro příjem donutí překladač hlídat směr: worker, který by chtěl do jobs posílat, se nepřeloží.",
  ["A recursive def needs a base case and a smaller call. A dict memo or @functools.cache turns fib from 2^n into n."] = "Rekurzivní def potřebuje základní případ a menší volání. Memo v dictu nebo @functools.cache změní fib z 2^n na n.",
  ["A recursive fn needs a base case and a smaller call. A HashMap memo turns fib from 2^n into n."] = "Rekurzivní fn potřebuje bázový případ a menší volání. Memo v HashMap změní fib z 2^n na n.",
  ["A recursive func needs a base case and a smaller call. A memo map turns fib from 2^n into n."] = "Rekurzivní func potřebuje základní případ a menší volání. Mapa memo promění fib z 2^n na n.",
  ["A reference must not outlive what it points at. 'a names how long; 'static means the whole program."] = "Reference nesmí přežít to, na co ukazuje. 'a pojmenovává jak dlouho; 'static znamená celý program.",
  ["A repo grows a shape: cmd/<name>/main.go per binary, internal/ for packages the compiler refuses to let outsiders import, a doc comment on every package, and menu_test.go in package menu_test so the tests use the package the way a caller would."] = "Repozitář dostane tvar: cmd/<name>/main.go pro každý binární program, internal/ pro balíčky, které překladač nedovolí importovat cizím, dokumentační komentář u každého balíčku a menu_test.go v package menu_test, aby testy používaly balíček tak jako volající.",
  ["A room frees up when this start is not before the earliest end."] = "Místnost se uvolní, když tenhle začátek není před nejdřívějším koncem.",
  ["A seat number that may not exist. Which type wraps a value that can be missing?"] = "Číslo místa, které možná neexistuje. Který typ obaluje hodnotu, která může chybět?",
  ["A second test after an if. Which keyword is Python's 'else if'?"] = 'Druhý test po if. Které klíčové slovo je pythonové „else if"?',
  ["A sentinel error value the whole package can compare against. Fill: errors.___"] = "Sentinelová chybová hodnota, se kterou může celý balíček porovnávat. Doplň: errors.___",
  ["A sentinel infinity. math.MaxInt would overflow the moment you add 1 to it."] = "Strážní nekonečno. math.MaxInt by přetekl, jakmile k němu přičteš 1.",
  ["A set answers 'seen?' in O(1). A list would make BFS O(n^2)."] = 'Set odpoví na „viděno?" v O(1). Seznam by udělal BFS O(n^2).',
  ["A set built on hashing, CapWords, in std::collections. insert returns false when the value was already in."] = "Množina postavená na hashování, CapWords, v std::collections. insert vrací false, když hodnota už uvnitř byla.",
  ["A set of methods, no fields. Which keyword?"] = "Sada metod, žádná pole. Které klíčové slovo?",
  ["A set of seen stations. Fill the value type: map[string]___"] = "Množina navštívených stanic. Doplň typ hodnoty: map[string]___",
  ["A size is Small or Large and nothing else. Which keyword lists the variants?"] = "Velikost je Small nebo Large a nic jiného. Které klíčové slovo vyjmenuje varianty?",
  ["A slice is Go's stack: this pushes, st[:len(st)-1] pops. Both O(1), amortized."] = "Slice je zásobník v Go: tohle pushuje, st[:len(st)-1] popuje. Obojí O(1), amortizovaně.",
  ["A slice is a stack: append pushes, st[:len(st)-1] pops. Push every opener, match every closer against the top, valid when the stack ends empty. A min stack keeps a second stack of running minimums."] = "Slice je zásobník: append pushuje, st[:len(st)-1] popuje. Pushni každou otevírací, každou zavírací porovnej s vrcholem, platné je to, když zásobník skončí prázdný. Min stack drží druhý zásobník průběžných minim.",
  ["A slice is a view: pointer, len, cap. append may grow it. len is the length."] = "Slice je pohled: ukazatel, len, cap. append ho může zvětšit. len je délka.",
  ["A slice is a window, not a copy. Both look at the same memory."] = "Slice je okno, ne kopie. Oba se dívají do stejné paměti.",
  ["A slice of int, not a fixed array. Fill the type: s := ___{1, 2, 3}"] = "Slice intů, ne pevné pole. Doplň typ: s := ___{1, 2, 3}",
  ["A sorted copy of the prices, leaving the original as it is. Which built-in?"] = "Seřazená kopie cen, originál zůstane, jak je. Která vestavěná funkce?",
  ["A sorted copy, leaving the original untouched, needs a second Vec. Extra space: O(___)"] = "Seřazená kopie, originál nedotčený, potřebuje druhý Vec. Prostor navíc: O(___)",
  ["A sorted copy, leaving the original untouched, needs a second list. Extra space: O(___)"] = "Seřazená kopie, originál nedotčený, potřebuje druhý seznam. Prostor navíc: O(___)",
  ["A sorted copy, leaving the original untouched, needs a second slice. Extra space: O(___)"] = "Seřazená kopie, originál nedotčený, potřebuje druhý slice. Prostor navíc: O(___)",
  ["A stack that also reports its smallest value in O(1). Push keeps a second stack of the smallest so far. Which i32 method picks the smaller of x and m?"] = "Zásobník, který navíc hlásí svou nejmenší hodnotu v O(1). push udržuje druhý zásobník dosavadních minim. Která metoda i32 vybere menší z x a m?",
  ["A star, then the name the body uses. Inside, it is a tuple."] = "Hvězdička a pak jméno, které tělo používá. Uvnitř je to tuple.",
  ["A struct, so it comes as a pointer. r.Method, r.URL, r.Body."] = "Struct, takže přichází jako ukazatel. r.Method, r.URL, r.Body.",
  ["A switch with no condition is Go's if-else chain. sort.SearchInts does this for you."] = "switch bez podmínky je řetěz if-else v Go. sort.SearchInts to udělá za tebe.",
  ["A sync.Mutex is usable at its zero value. Lock, then defer Unlock. Never copy a struct that holds one: go vet calls that passing a lock by value. sync.RWMutex lets many readers in at once with RLock, and TryLock returns instead of waiting."] = "sync.Mutex se dá použít rovnou v nulové hodnotě. Lock a hned potom defer Unlock. Nikdy nekopíruj strukturu, která ho drží: go vet tomu říká předávání zámku hodnotou. sync.RWMutex pustí přes RLock naráz spoustu čtenářů a TryLock se vrátí místo čekání.",
  ["A test function in order_test.go. Fill the name prefix: func ___(t *testing.T)"] = "Testovací funkce v order_test.go. Doplň předponu jména: func ___(t *testing.T)",
  ["A thin arrow, minus then greater-than. Go writes nothing there."] = "Tenká šipka, minus a pak větší než. Go tam nepíše nic.",
  ["A thing that counts, capitalized. It is a dict subclass with 0 for missing keys."] = "Věc, která počítá, s velkým písmenem. Je to podtřída dictu s 0 pro chybějící klíče.",
  ["A thread-safe queue of orders. Which class from the queue module?"] = "Fronta objednávek bezpečná pro vlákna. Která třída z modulu queue?",
  ["A tick and an underscore: the anonymous lifetime."] = "Apostrof a podtržítko: anonymní lifetime.",
  ["A tick and one letter, the same as both inputs."] = "Apostrof a jedno písmeno, stejné jako u obou vstupů.",
  ["A tick and the word for something that never moves."] = "Apostrof a slovo pro něco, co se nikdy nehýbe.",
  ["A timeout is a deadline computed from now. It is inherited: a child can be stricter than its parent, never looser."] = "Timeout je lhůta spočítaná od teď. Dědí se: potomek může být přísnější než rodič, nikdy volnější.",
  ["A trait is a set of methods. impl Trait for Type promises them; dyn Trait picks at run time."] = "Trait je sada metod. impl Trait for Type je slibuje; dyn Trait vybírá za běhu.",
  ["A tree node holds *Node children. insert recurses left or right until nil. height is 1 + max of both sides."] = "Uzel stromu drží potomky *Node. insert jde rekurzivně doleva nebo doprava až k nil. height je 1 + max obou stran.",
  ["A tree node owns Option<Box<Node>> children. insert recurses left or right until None. height is 1 + max of both sides."] = "Uzel stromu vlastní potomky Option<Box<Node>>. insert jde rekurzí doleva nebo doprava až k None. height je 1 + max obou stran.",
  ["A tuple struct with one field whose Ord is the other way round. Same word as the iterator's rev, spelled out."] = "Tuple struct s jedním polem, jehož Ord jde opačně. Stejné slovo jako rev u iterátoru, ale celé.",
  ["A type parameter that accepts anything. Fill: func ident[T ___](v T) T"] = "Typový parametr, který přijme cokoli. Doplň: func ident[T ___](v T) T",
  ["A value receiver copies the struct, mutex and all, and locks the copy. Point at the original."] = "Hodnotový příjemce zkopíruje celou strukturu i s mutexem a zamkne tu kopii. Ukaž na originál.",
  ["A view of the 2nd and 3rd items only (index 1 and 2). Fill: two := tray[___]"] = "Pohled jen na 2. a 3. položku (index 1 a 2). Doplň: two := tray[___]",
  ["A worker only reads jobs. Which channel type says so in the signature?"] = "Worker jen čte jobs. Který typ kanálu to říká v hlavičce?",
  ["A worker pool with queue.Queue"] = "Pool workerů s queue.Queue",
  ["A worker runs until the jobs channel closes. Fill: for j := ___ jobs"] = "Worker běží, dokud se channel jobs nezavře. Doplň: for j := ___ jobs",
  ["ADVANCED  -  the back office"] = "ADVANCED  -  zadní kancelář",
  ["ADVANCED  -  the kitchen"] = "ADVANCED  -  kuchyně",
  ["ANSWER"] = "ODPOVĚĎ",
  ["ARROWS walk    ENTER go    1-7 jump    Q quest    TAB Go/Rust    %s"] = "ŠIPKY chůze    ENTER jdi    1-7 skok    Q mise    TAB Go/Rust    %s",
  ["ARROWS walk    ENTER go    1-7 jump    Q quest    TAB language    %s"] = "ŠIPKY chůze    ENTER vstup    1-7 skok    Q úkol    TAB jazyk    %s",
  ["ASCII letters take one byte; CJK characters take three."] = "Písmena ASCII zabírají jeden bajt; znaky CJK tři.",
  ["ASCII to integer. The line below goes the other way."] = "ASCII na integer. Řádek níže jde opačným směrem.",
  ["AUTO"] = "AUTO",
  ["Able to be turned into bytes by the pickle module. The adjective."] = "Takové, že to modul pickle umí převést na bajty. Přídavné jméno.",
  ["Actually run the Future and get the u32 out. What goes after the call?"] = "Opravdu spusť Future a dostaň z něj u32. Co jde za volání?",
  ["Add 18 to the end of the orders list. Which method?"] = "Přidej 18 na konec seznamu orders. Která metoda?",
  ["Add a dependency at an exact version. Which subcommand?"] = "Přidej závislost v přesné verzi. Který podpříkaz?",
  ["Add a third module to the workspace by hand. Which go.work directive lists a folder?"] = "Přidej do pracovního prostoru ručně třetí modul. Která direktiva go.work vypisuje složku?",
  ["Add a tray to the end of the list. Which method?"] = "Přidat tác na konec seznamu. Která metoda?",
  ["Add before go, Done inside, Wait after. Never Add inside the goroutine."] = "Add před go, Done uvnitř, Wait potom. Nikdy Add uvnitř goroutiny.",
  ["Add before the go statement, Done deferred inside it, Wait after the loop. Add inside the goroutine is the classic race."] = "Add před příkazem go, Done s defer uvnitř a Wait až za smyčkou. Add uvnitř goroutiny je klasický souběh.",
  ["Add before you go. Done in the goroutine. Wait in main."] = "Add před go. Done v goroutine. Wait v main.",
  ["Add every price together through an iterator. Which method finishes the chain?"] = "Sečti všechny ceny přes iterátor. Která metoda řetězec uzavírá?",
  ["Add missing dependencies and drop unused ones. Fill: go mod ___"] = "Přidej chybějící závislosti a zahoď nepoužité. Doplň: go mod ___",
  ["Add one to count, in place: the augmented assignment."] = "Přičti jedna k count, na místě: rozšířené přiřazení.",
  ["Add one to the served count with no lock at all. Which atomic method?"] = "Přičti jedničku k počtu obsloužených úplně bez zámku. Která atomická metoda?",
  ["Add the order number but keep the cause inside. Which verb wraps?"] = "Přidej číslo objednávky, ale nech uvnitř příčinu. Který verb obaluje?",
  ["Add to the end of out. A list, not a tuple, so the end can still be extended later."] = "Přidej na konec out. Seznam, ne tuple, aby se konec dal později ještě prodloužit.",
  ["Add up the bill in one call. Which method?"] = "Sečti účet jedním voláním. Která metoda?",
  ["Adding an edge to a station with no list yet. Which entry method starts an empty Vec on demand?"] = "Přidáváš hranu ke stanici, která ještě nemá seznam. Která metoda na entry založí prázdný Vec podle potřeby?",
  ["Adjacency list: HashMap<u32, Vec<u32>>. BFS uses a VecDeque and pop_front, DFS a Vec and pop. A HashSet remembers visits."] = "Seznam sousednosti: HashMap<u32, Vec<u32>>. BFS používá VecDeque a pop_front, DFS Vec a pop. HashSet si pamatuje návštěvy.",
  ["After breakfast, Lucky Mac wants a delivery app by the lunch rush. Ship it in Go."] = "Po snídani chce Lucky Mac do polední špičky aplikaci na rozvoz. Dodej ji v Go.",
  ["After decorating, fry.__name__ says 'wrapper'. Which functools decorator keeps the original name and docstring?"] = "Po dekorování říká fry.__name__ 'wrapper'. Který dekorátor z functools zachová původní jméno a docstring?",
  ["After flipping, move on: prev becomes cur, and cur becomes the saved node. Fill it."] = "Po otočení dál: prev se stane cur a cur se stane uloženým uzlem. Doplň to.",
  ["After frying, tell the queue this job is finished so join can count it. Which method?"] = "Po smažení říct frontě, že tato úloha je hotová, aby ji join mohl spočítat. Která metoda?",
  ["After let b = a; the name a is invalid. What did the String do?"] = "Po let b = a; je jméno a neplatné. Co String udělal?",
  ["After the loop append the leftovers: out = append(out, l[i:]...) and r[j:]..."] = "Po smyčce připoj zbytky: out = append(out, l[i:]...) a r[j:]...",
  ["After the loop the heap holds the k biggest and the smallest of them is on top: the kth largest. Which method reads the top without removing it?"] = "Po cyklu halda drží k největších a nejmenší z nich je na vrcholu: k-tý největší. Která metoda přečte vrchol bez odebrání?",
  ["After the loop, k items remain and the kth largest is the smallest of them. Which index holds it?"] = "Po cyklu zbývá k prvků a k-tý největší je nejmenší z nich. Který index ho drží?",
  ["After the loop, what makes the string valid? Every opener found its closer, so the stack is what?"] = "Co po cyklu dělá řetězec platným? Každá otevírací našla svou zavírací, takže zásobník je jaký?",
  ["Alex"] = "Alex",
  ["Alias for interface{}. The constraint that allows every type."] = "Alias pro interface{}. Omezení, které povolí každý typ.",
  ["Allocate a slice with length 0 and room for 8. Which built-in?"] = "Alokuj slice s délkou 0 a místem pro 8. Která vestavěná funkce?",
  ["Always assign the result back. It may allocate a new backing array."] = "Výsledek vždy přiřaď zpět. Může alokovat nové podkladové pole.",
  ["Ampersand and the string slice type. Elision fills in the rest."] = "Ampersand a typ řetězcového slice. Elize doplní zbytek.",
  ["Ampersand. & takes an address, * reads through one."] = "Ampersand. & vezme adresu, * skrz ni čte.",
  ["An LRU cache"] = "LRU cache",
  ["An LRU cache with OrderedDict"] = "LRU cache s OrderedDict",
  ["An adjacency list: each station id maps to the ids one hop away. What holds the list of neighbours?"] = "Seznam sousednosti: každé id stanice se mapuje na id vzdálená jeden skok. Co drží seznam sousedů?",
  ["An alternative constructor: Order.from_line('2 x egg'). Which decorator passes the class instead of an instance?"] = "Alternativní konstruktor: Order.from_line('2 x egg'). Který dekorátor předá třídu místo instance?",
  ["An ampersand and the word the body already uses to reach qty."] = "Ampersand a slovo, kterým se tělo už dostává ke qty.",
  ["An ampersand and three letters: the borrowed string slice."] = "Ampersand a tři písmena: vypůjčený řetězcový slice.",
  ["An arrow pointing out of the channel, then the channel's name. Two characters and three."] = "Šipka mířící ven z kanálu a pak jméno kanálu. Dva znaky a tři písmena.",
  ["An asyncio server must not block on a resize. Which loop method hands it to the pool?"] = "Server na asyncio se nesmí zaseknout na zmenšování. Která metoda smyčky to předá fondu?",
  ["An empty stack on a closer is a failure too: ')(' must not pass. Then pop by reslicing."] = "Prázdný zásobník při zavírací závorce je taky chyba: ')(' nesmí projít. Pak pop přeřezáním slice.",
  ["An empty struct. Zero size. The idiom for 'just a signal'."] = "Prázdný struct. Nulová velikost. Idiom pro „jen signál“.",
  ["An empty tray, all fields zero, without typing them. Which call?"] = "Prázdný tác, všechna pole nula, bez vypisování. Které volání?",
  ["An existing key is a touch, not an eviction: get(k) moves it to the back and the len check is skipped."] = "Existující klíč je dotek, ne vyhození: get(k) ho přesune dozadu a kontrola len se přeskočí.",
  ["An import path that starts with a host is fetched from that host: go get github.com/x/y@v1.2.3 downloads the tagged commit into the module cache, adds a require line to go.mod and a hash to go.sum. // indirect marks a dependency of a dependency. Nothing is copied into your repo; everything is reproducible from the two files."] = "Importní cesta začínající hostem se stahuje z toho hosta: go get github.com/x/y@v1.2.3 stáhne otagovaný commit do cache modulů, přidá řádek require do go.mod a hash do go.sum. // indirect značí závislost závislosti. Do tvého repozitáře se nic nekopíruje; všechno je reprodukovatelné z těch dvou souborů.",
  ["An interface is (type, value). The type *Order is set, so it is not the nil interface."] = "Rozhraní je (typ, hodnota). Typ *Order je nastaven, takže to není nil rozhraní.",
  ["An opener goes onto the stack. Which builtin grows the slice?"] = "Otevírací závorka jde na zásobník. Který builtin slice zvětší?",
  ["An opener waits for its closer on the stack. Which list method puts c on top?"] = "Otvírací závorka čeká na zásobníku na svou zavírací. Která metoda seznamu dá c na vršek?",
  ["An opener waits for its partner. Which Vec method puts c on top of the stack?"] = "Otevírací závorka čeká na svého partnera. Která metoda Vec dá c na vrchol zásobníku?",
  ["An unbuffered send needs a receiver already waiting. Put the send in a goroutine or buffer the channel."] = "Odeslání bez bufferu potřebuje čekajícího příjemce. Dej odeslání do goroutine nebo kanálu přidej buffer.",
  ["An underscore and four letters, the same suffix the file name carries. The only case of two packages in one directory."] = "Podtržítko a čtyři písmena, stejná přípona, jakou nese jméno souboru. Jediný případ dvou balíčků v jednom adresáři.",
  ["Anagram: same letters, same counts. Lowercase ASCII only. How many slots does the counter array need?"] = "Přesmyčka: stejná písmena, stejné počty. Jen malé ASCII. Kolik míst potřebuje pole čítačů?",
  ["And on the way out, error or not. Which method closes the file?"] = "A na cestě ven, s chybou i bez. Která metoda zavře soubor?",
  ["And the compiler says my price function does not exist, even though it is right there."] = "A překladač říká, že moje funkce price neexistuje, i když je přímo tam.",
  ["And the log n is how many times you can halve. Levels times work per level."] = "A log n je, kolikrát můžeš půlit. Úrovně krát práce na úroveň.",
  ["And the size is an enum. Small or Large, nothing in between, the compiler makes sure."] = "A velikost je enum. Small nebo Large, nic mezi tím, kompilátor to zajistí.",
  ["Angle brackets around the lifetime, like a generic parameter."] = "Lomené závorky kolem lifetimu, jako u generického parametru.",
  ["Any Cook, chosen at run time, behind a reference. Which keyword?"] = "Libovolný Cook, vybraný za běhu, za referencí. Které klíčové slovo?",
  ["Any type with one method is an error. Which method?"] = "Každý typ s jednou metodou je error. Která metoda?",
  ["Anything under internal/ can be imported only by code rooted at internal's parent. The cousin's shop gets a compile error, and you keep the right to delete."] = "Cokoli pod internal/ smí importovat jen kód s kořenem v rodiči internal. Bratrancův obchod dostane chybu překladu a ty si zachováš právo mazat.",
  ["Append a &str to the end of a mutable String. Which method?"] = "Připoj &str na konec mutable Stringu. Která metoda?",
  ["Apply the timer wrapper to fry without changing its body. Which character goes before timer?"] = "Aplikovat obal timer na fry beze změny jeho těla. Který znak patří před timer?",
  ["Arc shares ownership across threads; Mutex guards changes; atomics count without a lock."] = "Arc sdílí vlastnictví mezi vlákny; Mutex hlídá změny; atomiky počítají bez zámku.",
  ["Arc, Mutex and atomics"] = "Arc, Mutex a atomiky",
  ["Arc::clone(&sold) bumps the count, never copies the data. Same as sold.clone(), but the full path shows it is cheap."] = "Arc::clone(&sold) zvýší počítadlo, nikdy nekopíruje data. Stejné jako sold.clone(), ale plná cesta ukazuje, že je to levné.",
  ["Arc<Mutex<Receiver<Job>>> is Send + Sync, so it can be moved into every worker. The rail is shared, the pull is exclusive."] = "Arc<Mutex<Receiver<Job>>> je Send + Sync, takže se dá přesunout do každého workeru. Lišta je sdílená, odběr je výhradní.",
  ["Arc<Mutex<T>> is the shared-and-mutable idiom. Arc shares, Mutex guards; neither alone is enough."] = "Arc<Mutex<T>> je idiom pro sdílené a měnitelné. Arc sdílí, Mutex hlídá; ani jeden sám nestačí.",
  ["Arc<T> counts references atomically, so clones may live on different threads. Rc is cheaper but not Send."] = "Arc<T> počítá reference atomicky, takže klony mohou žít na různých vláknech. Rc je levnější, ale není Send.",
  ["Arrays, slices, append"] = "Pole, slice, append",
  ["Arrow pointing at the channel. Receive is the same arrow on the left of =."] = "Šipka mířící na kanál. Příjem je stejná šipka vlevo od =.",
  ["Arrow then chan. chan<- string would be send-only."] = "Šipka, pak chan. chan<- string by bylo jen pro odesílání.",
  ["As many new ints as there are old ones. Linear, without the O( )."] = "Tolik nových intů, kolik je starých. Lineární, bez O( ).",
  ["As many new slots as there are old ones. Linear, without the O( )."] = "Tolik nových slotů, kolik je starých. Lineární, bez O( ).",
  ["Ascending: i goes before j when its start is smaller."] = "Vzestupně: i jde před j, když má menší začátek.",
  ["Ask all three riders at once and collect the answers. Which asyncio function?"] = "Zeptat se všech tří kurýrů najednou a posbírat odpovědi. Která funkce z asyncio?",
  ["Ask for warnings about non-idiomatic code. Which subcommand?"] = "Vyžádej si varování o neidiomatickém kódu. Který podpříkaz?",
  ["Ask the compiler to write Clone and Debug for Order. Which attribute?"] = "Požádej kompilátor, aby napsal Clone a Debug pro Order. Který atribut?",
  ["Ask the tool chain to find data races at run time. Fill the flag: go test ___ ./..."] = "Požádej nástroje, ať najdou data race za běhu. Doplň přepínač: go test ___ ./...",
  ["Ask your AI: why is `%s` the answer here, and what breaks with anything else?"] = "Zeptej se své AI: proč je tady odpověď `%s` a co se rozbije s čímkoli jiným?",
  ["Assigning e alone is the classic bug: [1, 10] then [2, 3] would end at 3."] = "Přiřadit samotné e je klasická chyba: [1, 10] a pak [2, 3] by končilo na 3.",
  ["Async in Go: a goroutine and a channel"] = "Async v Go: goroutina a kanál",
  ["AsyncResult.get() blocks and re-raises whatever the worker raised. apply_async plus get is exactly go plus <-ch."] = "AsyncResult.get() blokuje a znovu vyhodí, co vyhodil worker. apply_async plus get je přesně go plus <-ch.",
  ["At most 3 requests in flight: a semaphore from a buffered channel. Fill: make(chan struct{}, ___)"] = "Nejvýš 3 požadavky najednou: semafor z bufferovaného channelu. Doplň: make(chan struct{}, ___)",
  ["Atomics and sync.Once"] = "Atomiky a sync.Once",
  ["Await is a receive with a nicer name. Go left it out of the language because a generic type and one operator are enough."] = "Await je jen příjem s hezčím jménem. Go ho do jazyka nedalo, protože generický typ a jeden operátor stačí.",
  ["BACK"] = "ZPĚT",
  ["BADGE  %s"] = "ODZNAK  %s",
  ["BADGES"] = "ODZNAKY",
  ["BFS and DFS"] = "BFS a DFS",
  ["BFS and DFS on the MTR"] = "BFS a DFS na MTR",
  ["BFS explores outward in rings: everything one stop away, then two. The first path found is the shortest."] = "BFS zkoumá směrem ven v prstencích: všechno na jednu zastávku, pak na dvě. První nalezená cesta je nejkratší.",
  ["BFS: a slice as a queue, pop the front with q[1:]. DFS: recursion plus a visited map."] = "BFS: slice jako fronta, vyjmi zepředu pomocí q[1:]. DFS: rekurze plus mapa navštívených.",
  ["BIG O  -  how fast is it"] = "BIG O  -  jak je to rychlé",
  ["BIG O  ·  the Go round"] = "BIG O  ·  kolo Go",
  ["BIG O  ·  the Python round"] = "BIG O  ·  kolo Pythonu",
  ["BIG O  ·  the Rust round"] = "BIG O  ·  kolo Rustu",
  ["BIG O MASTER"] = "MISTR BIG O",
  ["BST invariant: left < node <= right. Average insert is O(log n)."] = "Invariant BST: levý < uzel <= pravý. Průměrné vložení je O(log n).",
  ["BST rule: everything smaller is in the left subtree. &mut n.left reborrows the child for the recursive call."] = "Pravidlo BST: všechno menší je v levém podstromu. &mut n.left si potomka znovu půjčí pro rekurzivní volání.",
  ["Bake menu.json into the binary at compile time. Fill the directive: //go:___"] = "Zapeč menu.json do binárky při kompilaci. Doplň direktivu: //go:___",
  ["Base case first, always. Without it Python raises RecursionError at depth 1000."] = "Základní případ vždy první. Bez něj Python vyhodí RecursionError v hloubce 1000.",
  ["Base case first, always. Without it the stack overflows."] = "Základní případ vždy jako první. Bez něj přeteče zásobník.",
  ["Base case first, always. Without it the stack overflows. No semicolon: the if is the return value."] = "Vždycky nejdřív bázový případ. Bez něj přeteče zásobník. Bez středníku: if je návratová hodnota.",
  ["Base cases seed the table. From here every entry is built from the two before it."] = "Bázové případy nasadí tabulku. Odsud se každá položka staví ze dvou předchozích.",
  ["Base cases seed the table. dp[0] = 1 is the empty climb; without it dp[2] would be wrong."] = "Základní případy zasejí tabulku. dp[0] = 1 je prázdný výstup; bez něj by dp[2] bylo špatně.",
  ["Because every Go function is already the async one. There is no second colour of function to await."] = "Protože každá funkce v Go už je ta asynchronní. Není tu druhá barva funkcí, na kterou by se čekalo.",
  ["Before the dinner rush, rewrite the delivery backend in Rust. Ship it."] = "Před večerní špičkou přepiš backend rozvozu v Rustu. Dodej ho.",
  ["Before the morning van"] = "Než přijede ranní dodávka",
  ["Benchmark* takes *testing.B and loops b.N times. Go 1.24 adds b.Loop()."] = "Benchmark* bere *testing.B a cyklí b.N-krát. Go 1.24 přidává b.Loop().",
  ["Best k hours in a row: slide a window of size k. One element enters, which one leaves?"] = "Nejlepších k hodin v řadě: posouvej okno velikosti k. Jeden prvek vstoupí, který odejde?",
  ["Best subarray sum: at each x, either extend the current run or start fresh at x. Which method picks the larger?"] = "Nejlepší součet podpole: u každého x buď prodluž aktuální řadu, nebo začni znovu od x. Která metoda vybere větší?",
  ["Big O is one question: when the input doubles, what happens to the work?"] = "Big O je jediná otázka: když se vstup zdvojnásobí, co se stane s prací?",
  ["Binary search and merge sort"] = "Binární vyhledávání a merge sort",
  ["Binary search checks the middle of lo..hi. Which operator finds the midpoint index?"] = "Binární vyhledávání kontroluje střed lo..hi. Který operátor najde prostřední index?",
  ["Binary search checks the middle of lo..hi. Which operator gives a whole-number midpoint?"] = "Binární vyhledávání kontroluje střed lo..hi. Který operátor dá celočíselný střed?",
  ["Binary search halves [lo, hi) with mid. Merge sort splits, recurses, and merges two sorted halves."] = "Binární vyhledávání půlí [lo, hi) pomocí mid. Merge sort rozdělí, rekurzivně zpracuje a slije dvě seřazené půlky.",
  ["Binary search has one precondition. The slice must be ___"] = "Binární vyhledávání má jeden předpoklad. Slice musí být ___",
  ["Binary search tree"] = "Binární vyhledávací strom",
  ["Binary search: the target is bigger than a[mid]. Where does lo move?"] = "Binární vyhledávání: cíl je větší než a[mid]. Kam se posune lo?",
  ["BinaryHeap implements FromIterator, so collect heapifies in O(n). Then k pops: O(n + k log n)."] = "BinaryHeap implementuje FromIterator, takže collect udělá haldu v O(n). Pak k popů: O(n + k log n).",
  ["BinaryHeap is a max-heap. Reverse(x) turns it into a min-heap. kth largest: push everything, pop whenever len > k, peek. Top k frequent: count with a HashMap, collect (count, word) into a heap, pop k times."] = "BinaryHeap je max-halda. Reverse(x) z ní udělá min-haldu. k-tý největší: pushni všechno, popni, kdykoli len > k, peekni. Top k nejčastějších: spočítej přes HashMap, sesbírej (count, word) do haldy, popni k-krát.",
  ["BinaryHeap: kth largest and top k"] = "BinaryHeap: k-tý největší a top k",
  ["Bindings, mutability and types"] = "Vazby, měnitelnost a typy",
  ["Blocking I/O and NumPy's C loops both drop the GIL, so threads overlap waiting perfectly. Pure Python arithmetic never drops it."] = "Blokující I/O i céčkové smyčky v NumPy GIL pouštějí, takže vlákna dokonale překryjí čekání. Čistě pythonovská aritmetika ho nepustí nikdy.",
  ["Blocks are indented, no braces. elif chains ifs. for walks anything iterable; range counts. while loops on a condition."] = "Bloky se odsazují, žádné závorky. elif řetězí ify. for projde cokoli iterovatelného; range počítá. while opakuje podle podmínky.",
  ["Blocks until the counter is zero. In its own goroutine so main can keep reading."] = "Blokuje, dokud čítač není nula. Ve vlastní goroutině, aby main mohl dál číst.",
  ["Borrow only the second and third price, indices 1 and 2. What goes in the brackets?"] = "Vypůjč si jen druhou a třetí cenu, indexy 1 a 2. Co patří do hranatých závorek?",
  ["Both tills add to one sold counter and the number is wrong every time."] = "Obě pokladny přičítají do jednoho čítače prodejů a číslo je pokaždé špatně.",
  ["Bottom-up DP: O(n) time, O(n) table, and two variables would make it O(1) space."] = "DP odspodu: O(n) čas, O(n) tabulka, a dvě proměnné by z toho udělaly O(1) paměti.",
  ["Bottom-up fib: O(n) time, no recursion, and only two cells are ever needed, so O(1) space is possible."] = "Fib odspoda: O(n) času, žádná rekurze, a vždy jsou potřeba jen dvě buňky, takže je možné O(1) paměti.",
  ["Box<Node> is one pointer wide, so Node has a size. Option<Box<T>> costs nothing extra: None is the null pointer."] = "Box<Node> je široký jeden ukazatel, takže Node má velikost. Option<Box<T>> nestojí nic navíc: None je nulový ukazatel.",
  ["Box<dyn Error> accepts any error type via From. Good for main and prototypes, not libraries."] = "Box<dyn Error> přijme přes From jakýkoli typ chyby. Dobré pro main a prototypy, ne pro knihovny.",
  ["Branch on what v really is. Fill: switch x := v.(___)"] = "Větvi podle toho, co v opravdu je. Doplň: switch x := v.(___)",
  ["Breadth first needs a FIFO: in at the back, out at the front. Which std collection?"] = "Průchod do šířky potřebuje FIFO: dovnitř vzadu, ven vepředu. Která kolekce ze std?",
  ["Build a String from pieces without printing it. Which macro?"] = "Sestav String z kousků bez vypisování. Které makro?",
  ["Build a growable list from three literal prices. Which macro?"] = "Postav rostoucí seznam ze tří literálních cen. Které makro?",
  ["Build a max-heap of (count, word) straight from the map's iterator. Which method turns an iterator into a collection?"] = "Postav max-haldu (count, word) rovnou z iterátoru mapy. Která metoda udělá z iterátoru kolekci?",
  ["Build that copy by hand: a new slice as long as a, then copy into it. Which built-in gives the length?"] = "Postavit tu kopii ručně: nový slice dlouhý jako a, pak do něj zkopírovat. Která vestavěná funkce dá délku?",
  ["Build the label as a string, without printing. Which fmt function?"] = "Sestav popisek jako string bez vypisování. Která funkce z fmt?",
  ["By default go get asks proxy.golang.org, which caches every public module for ever and checks its hash against sum.golang.org. A private GitHub repo is invisible to the proxy: set GOPRIVATE=github.com/yourorg/* so the tool goes straight to git, and teach git to use ssh for github.com so the clone authenticates. When the cache turns stale or the disk fills, go clean -modcache."] = "Ve výchozím stavu se go get ptá proxy.golang.org, která navždy cachuje každý veřejný modul a kontroluje jeho hash proti sum.golang.org. Soukromý repozitář na GitHubu je pro proxy neviditelný: nastav GOPRIVATE=github.com/yourorg/*, aby nástroj šel rovnou na git, a nauč git používat pro github.com ssh, aby se klon ověřil. Když cache zestárne nebo se zaplní disk, go clean -modcache.",
  ["By hand: look the answer up before computing. Which dict is checked?"] = "Ručně: podívat se na odpověď, než se počítá. Který dict se kontroluje?",
  ["C  continue at %s   (%d/%d streets clear)"] = "C  pokračovat na %s   (%d/%d ulic hotovo)",
  ["CALLBACK  -  the whiteboard"] = "CALLBACK  -  tabule",
  ["CALLBACK  ·  the Go round"] = "CALLBACK  ·  kolo Go",
  ["CALLBACK  ·  the Python round"] = "CALLBACK  ·  kolo Pythonu",
  ["CALLBACK  ·  the Rust round"] = "CALLBACK  ·  kolo Rustu",
  ["CALLBACK 1  -  the brackets"] = "CALLBACK 1  -  závorky",
  ["CALLBACK 2  -  the stairs"] = "CALLBACK 2  -  schody",
  ["CALLBACK 3  -  the window"] = "CALLBACK 3  -  okno",
  ["CALLBACK 4  -  the heap"] = "CALLBACK 4  -  halda",
  ["CALLBACK 4  -  the top k"] = "CALLBACK 4  -  top k",
  ["CALLBACK 5  -  the calendar"] = "CALLBACK 5  -  kalendář",
  ["CALLBACK 5  -  the shifts"] = "CALLBACK 5  -  směny",
  ["CALLBACK 6  -  the cache"] = "CALLBACK 6  -  cache",
  ["CALLBACK 7  -  the islands"] = "CALLBACK 7  -  ostrovy",
  ["CLEAR"] = "HOTOVO",
  ["CLEAR   ENTER  next"] = "HOTOVO   ENTER  dál",
  ["CLEAR   ENTER back to the map"] = "HOTOVO   ENTER zpět na mapu",
  ["CLEAR   ENTER for the set"] = "HOTOVO   ENTER pro menu",
  ["CLEAR   ENTER for the stamp"] = "HOTOVO   ENTER pro razítko",
  ["CLEAR   ENTER next street"] = "HOTOVO   ENTER další ulice",
  ["CLEARED"] = "HOTOVO",
  ["CODE RUSH  -  the interview"] = "CODE RUSH  -  pohovor",
  ["CODE RUSH  ·  Times Square"] = "CODE RUSH  ·  Times Square",
  ["CODE RUSH  ·  the Python round"] = "CODE RUSH  ·  kolo Pythonu",
  ["CODE RUSH  ·  the Rust round"] = "CODE RUSH  ·  kolo v Rustu",
  ["COMBO x%d"] = "KOMBO x%d",
  ["COMBO x10"] = "KOMBO x10",
  ["COMBO x5"] = "KOMBO x5",
  ["COPIED  %s"] = "ZKOPÍROVÁNO  %s",
  ["COPY  (ask your AI why)"] = "KOPÍROVAT  (zeptej se AI proč)",
  ["Call it what its GitHub URL will be. Every import inside starts with that string."] = "Pojmenuj ho tak, jak bude znít jeho URL na GitHubu. Každý import uvnitř tím řetězcem začíná.",
  ["Call the map API over HTTP with one line. Which popular async client crate?"] = "Zavolej mapové API přes HTTP jedním řádkem. Který populární async klientský crate?",
  ["Callback round, Chef. Whiteboard, no keyboard. First: are these brackets balanced?"] = "Kolo CALLBACK, šéfe. Tabule, žádná klávesnice. Nejdřív: jsou tyhle závorky vyvážené?",
  ["Callback round, Mei. No buzzer this time, just the whiteboard. Warm-up: are these brackets balanced?"] = "Kolo CALLBACK, Mei. Tentokrát žádný bzučák, jen tabule. Rozcvička: jsou tyhle závorky vyvážené?",
  ["Cancel automatically after two seconds. Fill: context.___(ctx, 2*time.Second)"] = "Zruš automaticky po dvou sekundách. Doplň: context.___(ctx, 2*time.Second)",
  ["Capital = exported. Small = private to the package. Same rule for types and fields."] = "Velké = exportované. Malé = soukromé pro balíček. Totéž platí pro typy a pole.",
  ["Capital E, returns string. That one method is the whole error interface."] = "Velké E, vrací string. Ta jediná metoda je celé rozhraní error.",
  ["Capital M. MarshalIndent pretty-prints. The opposite is on the next blank."] = "Velké M. MarshalIndent vypíše hezky. Opak je v další mezeře.",
  ["Capital N. Go's nil, Rust's Option::None. Compare it with is, not ==."] = "Velké N. nil z Go, Option::None z Rustu. Porovnávej pomocí is, ne ==.",
  ["Capital S. The fmt.Stringer interface has exactly this one method."] = "Velké S. Rozhraní fmt.Stringer má přesně tuhle jednu metodu.",
  ["Capital first letter. Lower-case fields are invisible outside the package, json included."] = "Velké první písmeno. Pole s malým jsou mimo balíček neviditelná, json nevyjímaje.",
  ["Capital means exported, and that goes for types, fields, methods and constants too. A struct with lowercase fields cannot even be filled in from another package."] = "Velké písmeno znamená exportované a platí to i pro typy, pole, metody a konstanty. Strukturu s malými poli z jiného balíčku ani nenaplníš.",
  ["Cargo, the build tool"] = "Cargo, nástroj na sestavení",
  ["Carry the order id through five calls of logging. Which constructor?"] = "Prones id objednávky pěti vrstvami logování. Který konstruktor?",
  ["Causeway Bay"] = "Causeway Bay",
  ["Causeway Bay station"] = "Stanice Causeway Bay",
  ["Channel pipelines, closed and nil"] = "Kanálové linky, zavřené a nil",
  ["Channels"] = "Kanály",
  ["Channels in Go, mpsc in Rust, and now a Queue. Same kitchen every time."] = "Kanály v Go, mpsc v Rustu a teď Queue. Vždy stejná kuchyně.",
  ["Check bounds before touching g[r][c]: Python would raise IndexError on the right edge, and g[-1] silently wraps."] = "Zkontroluj meze, než sáhneš na g[r][c]: Python by na pravém okraji vyhodil IndexError a g[-1] se tiše přetočí.",
  ["Check bounds before you index, or the recursion panics at the shoreline."] = "Zkontroluj meze, než indexuješ, jinak rekurze na pobřeží zpanikaří.",
  ["Check for an order without waiting; the till must keep beeping. Which method?"] = "Zkontroluj objednávku bez čekání; pokladna musí dál pípat. Která metoda?",
  ["Check the hints before running the shift. Which tool, the classic one?"] = "Zkontrolovat nápovědy před spuštěním směny. Který nástroj, ten klasický?",
  ["Checking every guest against every other guest for a double booking. Fine with 20. Not with 2000."] = "Porovnávat každého hosta s každým dalším hostem kvůli dvojité rezervaci. S 20 v pohodě. S 2000 ne.",
  ["Checking every guest against every other guest for a double booking. It was fine with 20. It is not fine with 2000."] = "Porovnávat každého hosta s každým dalším hostem kvůli dvojité rezervaci. S 20 to šlo. S 2000 to nejde.",
  ["Chef Bo"] = "Šéfkuchař Bo",
  ["Close results only after every worker is done. Fill: wg.___(); close(results)"] = "Zavři results až poté, co skončí každý worker. Doplň: wg.___(); close(results)",
  ["Close the receipt printer whether the refund worked or not. Which clause always runs?"] = "Zavřít tiskárnu účtenek, ať vratka vyšla nebo ne. Která klauzule proběhne vždy?",
  ["Code is done. Now build it like a Rustacean: one tool for everything. Ticket six."] = "Kód je hotový. Teď ho sestav jako Rustacean: jeden nástroj na všechno. Ticket šest.",
  ["Coin c on top of the best answer for a - c, if that beats what we have. Which built-in keeps the smaller?"] = "Mince c navrch nejlepší odpovědi pro a - c, pokud to přebije, co máme. Která vestavěná funkce nechá menší?",
  ["Coin change, fewest coins. Before the loop, mark every amount with a value no real answer can reach. Which?"] = "Mince, co nejméně. Před cyklem označ každou částku hodnotou, které žádná skutečná odpověď nedosáhne. Kterou?",
  ["Coin change: dp[a] is the fewest coins for amount a. The table starts full of 'impossible'. Which amount costs zero coins?"] = "Rozměňování: dp[a] je nejmenší počet mincí na částku a. Tabulka začíná plná „nemožné“. Která částka stojí nula mincí?",
  ["Coin change: fewest coins for each amount. Unreachable amounts start at infinity. Fill the float."] = "Coin change: nejméně mincí pro každou částku. Nedosažitelné částky začínají na nekonečnu. Doplň float.",
  ["Coins [2] for 3 returns -1. Table, transition, base case, impossible marker: every DP has the four."] = "Mince [2] pro 3 vrátí -1. Tabulka, přechod, základní případ, značka nemožného: každé DP má všechny čtyři.",
  ["Colon then equals. Only inside a function."] = "Dvojtečka a pak rovnítko. Jen uvnitř funkce.",
  ["Compare characters, not bytes, so 銅鑼灣 works. Fill: r := []___(s)"] = "Porovnávej znaky, ne bajty, aby fungovalo 銅鑼灣. Doplň: r := []___(s)",
  ["Compare code against several patterns and pick one arm. Which keyword?"] = "Porovnej code s několika vzory a vyber jednu větev. Které klíčové slovo?",
  ["Compare the start with the end of the last block in out. Equal counts as touching."] = "Porovnej začátek s koncem posledního bloku v out. Rovnost se počítá jako dotyk.",
  ["CompareAndSwap returns false when someone beat you to it, so the loop reads and tries again. That retry loop is how lock-free code is written."] = "Když tě někdo předběhne, CompareAndSwap vrátí false, takže smyčka znovu přečte a zkusí to zas. Ta opakovací smyčka je způsob, jak se píše kód bez zámků.",
  ["Comparing each pair once is n(n-1)/2 checks. For 100 guests, how many?"] = "Porovnat každou dvojici jednou je n(n-1)/2 kontrol. Pro 100 hostů kolik?",
  ["Compile everything into one binary called delivery. Fill: go ___ -o delivery ."] = "Zkompiluj vše do jedné binárky jménem delivery. Doplň: go ___ -o delivery .",
  ["Compile with optimisations for the live server. Which flag?"] = "Zkompiluj s optimalizacemi pro produkční server. Který přepínač?",
  ["Compute, remember, return. Fill the second term: fib(n-1) + fib(___)"] = "Spočítej, zapamatuj, vrať. Doplň druhý člen: fib(n-1) + fib(___)",
  ["Computed once, never again. Put v into the memo under key n. Which method?"] = "Spočítáno jednou, víckrát ne. Ulož v do mema pod klíč n. Která metoda?",
  ["Constant time"] = "Konstantní čas",
  ["Constant. A Python list is an array of pointers; index 3 is base plus 3 times a pointer's size."] = "Konstantní. Pythonový seznam je pole ukazatelů; index 3 je základ plus 3 krát velikost ukazatele.",
  ["Constant. A slice is a pointer and a length; index 3 is pointer plus 3 times the element size, after a bounds check."] = "Konstantní. Slice je ukazatel a délka; index 3 je ukazatel plus 3 krát velikost prvku, po kontrole mezí.",
  ["Constant. The slice knows its base address; index 3 is base plus 3 times the element size."] = "Konstantní. Slice zná svou základní adresu; index 3 je základ plus 3 krát velikost prvku.",
  ["Context and tests"] = "Context a testy",
  ["Context managers"] = "Kontextové manažery",
  ["Conversion is T(x). int and float64 never mix without it."] = "Převod je T(x). int a float64 se bez něj nikdy nemíchají.",
  ["Convert the rune back to a string. The index i is a byte offset."] = "Převeď runu zpět na string. Index i je bajtový offset.",
  ["Copies are the tax of multiprocessing: a global changed in a child stays in the child. multiprocessing.shared_memory.SharedMemory gives every process the same block of bytes, found by name and read through .buf, which NumPy can wrap without copying. You close() your view and unlink() the block exactly once, or it outlives the program."] = "Kopie jsou daň za multiprocessing: globální proměnná změněná v potomkovi zůstane v potomkovi. multiprocessing.shared_memory.SharedMemory dá každému procesu stejný blok bajtů, který se najde podle jména a čte přes .buf, a NumPy ho umí obalit bez kopírování. Svůj pohled zavřeš přes close() a blok odpojíš přes unlink() právě jednou, jinak přežije program.",
  ["Count characters, not bytes. Which iterator do you count?"] = "Počítej znaky, ne bajty. Který iterátor počítáš?",
  ["Count characters, not bytes. Which unicode/utf8 function?"] = "Počítej znaky, ne bajty. Která funkce z unicode/utf8?",
  ["Count each letter of a word in one call. Which collections class?"] = "Spočítat každé písmeno slova jedním voláním. Která třída z collections?",
  ["Count islands: every land cell still standing starts a new one. Fill the call that sinks the whole island."] = "Počítej ostrovy: každá buňka souše, která ještě stojí, začíná nový. Doplň volání, které potopí celý ostrov.",
  ["Count letters of a, uncount letters of b; all zero means anagram. Fill: count[c-'a']___"] = "Napočítej písmena z a, odpočítej písmena z b; samé nuly znamenají anagram. Doplň: count[c-'a']___",
  ["Count muffins per table: insert 0 if the key is new, then add 1. Which HashMap method starts that?"] = "Počítej muffiny na stůl: vlož 0, když je klíč nový, pak přičti 1. Která metoda HashMap to začíná?",
  ["Count the arrows. 2 to this power is 1024."] = "Spočítej šipky. 2 na tuto mocninu je 1024.",
  ["Count the nodes without taking ownership: cur is a &Link. Step to the following node: cur = &node.___"] = "Spočítej uzly bez převzetí vlastnictví: cur je &Link. Posuň se na následující uzel: cur = &node.___",
  ["Count the values. The length is part of the type, so [i32; 4] would be a different type."] = "Spočítej hodnoty. Délka je součástí typu, takže [i32; 4] by byl jiný typ.",
  ["Counter(word).most_common(1) gives the top letter. Go's count[c-'a']++ in one line. Round six to Bo."] = "Counter(word).most_common(1) dá nejčastější písmeno. count[c-'a']++ z Go na jednom řádku. Šesté kolo pro Boa.",
  ["Counting the queue takes one look per person. Twice the queue, twice the looking."] = "Spočítat frontu stojí jeden pohled na osobu. Dvakrát delší fronta, dvakrát více pohledů.",
  ["Crate name, two colons, the function it sits on."] = "Jméno crate, dvě dvojtečky, funkce, na které sedí.",
  ["Create a fresh binary project called delivery. Which cargo subcommand?"] = "Založ nový binární projekt jménem delivery. Který podpříkaz carga?",
  ["Custom errors and ?"] = "Vlastní chyby a ?",
  ["Cut a slice into two slices at mid, no copying. Which slice method returns the pair?"] = "Rozřízni slice na dva slice v mid, bez kopírování. Která metoda slice vrátí ten pár?",
  ["DELIVERY  -  the app"] = "DELIVERY  -  aplikace",
  ["DFS dives down one line before backing up. Same O(V + E) as BFS. Mind the 1000-deep recursion limit. Round three to Bo."] = "DFS se ponoří po jedné lince, než se vrátí. Stejné O(V + E) jako BFS. Pozor na limit rekurze 1000. Třetí kolo pro Boa.",
  ["DFS is recursion plus a visited set. Maps are reference-like: no pointer needed."] = "DFS je rekurze plus množina navštívených. Mapy se chovají jako reference: ukazatel netřeba.",
  ["DP fills a table from small answers up. Stairs: dp[i] = dp[i-1] + dp[i-2]. Coin change: dp[a] = min over coins of dp[a-c] + 1, with amount+1 as 'impossible'."] = "DP plní tabulku od malých odpovědí nahoru. Schody: dp[i] = dp[i-1] + dp[i-2]. Rozměňování mincí: dp[a] = min přes mince z dp[a-c] + 1, s amount+1 jako „nemožné“.",
  ["DP: a table of answers to smaller problems, filled from the base cases up. Stairs: dp[i] = dp[i-1] + dp[i-2]. Coin change: dp[a] = min over coins of dp[a-c] + 1, with a sentinel for 'impossible'."] = "DP: tabulka odpovědí na menší problémy, plněná od základních případů nahoru. Schody: dp[i] = dp[i-1] + dp[i-2]. Mince: dp[a] = min přes mince z dp[a-c] + 1, se strážní hodnotou pro „nejde“.",
  ["DP: solve the small cases once, build the bigger ones from them. Stairs: ways(i) = ways(i-1) + ways(i-2). Coins: dp[a] = min over coins of dp[a-c] + 1, with inf for unreachable."] = "DP: vyřeš malé případy jednou, větší z nich postav. Schody: ways(i) = ways(i-1) + ways(i-2). Mince: dp[a] = min přes mince z dp[a-c] + 1, s inf pro nedosažitelné.",
  ["Declare a function. Which keyword starts the line?"] = "Deklaruj funkci. Které klíčové slovo začíná řádek?",
  ["Declare with an explicit type, outside any function. Which keyword?"] = "Deklaruj s explicitním typem, mimo jakoukoli funkci. Které klíčové slovo?",
  ["Decorators"] = "Dekorátory",
  ["Define your own error type for the kitchen. What must it inherit from?"] = "Definuj vlastní typ chyby pro kuchyni. Z čeho musí dědit?",
  ["Depth first, recursive: visit, then call yourself on each unseen neighbour. Fill the call."] = "Do hloubky, rekurzivně: navštiv, pak zavolej sám sebe na každém neviděném sousedovi. Doplň volání.",
  ["Depth first: same loop, but the newest station goes next. Which Vec method takes from the end?"] = "Do hloubky: stejný cyklus, ale na řadě je nejnovější stanice. Která metoda Vec bere od konce?",
  ["Depth-first: visit, then recurse into each unseen neighbour. Fill the call."] = "Do hloubky: navštiv, pak rekurzivně do každého nenavštíveného souseda. Doplň volání.",
  ["Dicts and sets"] = "Dicty a sety",
  ["Did any of those futures leak? Which runtime call counts the live goroutines?"] = "Unikl někdo z těch futures? Které volání runtime spočítá živé goroutiny?",
  ["Did the child succeed? Which attribute holds its exit status after join?"] = "Povedlo se to potomkovi? Který atribut po join drží jeho návratový stav?",
  ["Different indexes are different memory, so no lock is needed. Since Go 1.22 each iteration gets its own i, so the closure captures the right one."] = "Různé indexy jsou různá paměť, takže zámek není potřeba. Od Go 1.22 má každá iterace vlastní i, takže closure zachytí to správné.",
  ["Directory, package name, exported names"] = "Adresář, jméno balíčku, exportovaná jména",
  ["Display does not care which lifetime Receipt has. Which placeholder says so?"] = "Display nezajímá, který lifetime Receipt má. Který zástupný znak to říká?",
  ["Divide and conquer: split the slice in the middle. Fill: let mid = v.len() / ___"] = "Rozděl a panuj: rozřízni slice uprostřed. Doplň: let mid = v.len() / ___",
  ["Divide, recurse, merge: O(n log n) always. Base case is a slice of length 0 or 1."] = "Rozděl, rekurze, slij: vždy O(n log n). Základní případ je slice délky 0 nebo 1.",
  ["Do not block if nothing is ready. Which case label?"] = "Neblokuj, když nic není připraveno. Které návěští?",
  ["Do not recurse. Fill a table from the bottom step up."] = "Nerekurzuj. Vyplň tabulku od spodního schodu nahoru.",
  ["Do not start a Process per photo. Forty thousand interpreters is not parallelism, it is a fire."] = "Nespouštěj Process na každou fotku. Čtyřicet tisíc interpretů není paralelismus, to je požár.",
  ["Doc comments are the API reference: go doc, gopls hover and pkg.go.dev all read them. Start each with the name it documents so it reads as a sentence."] = "Dokumentační komentáře jsou reference API: go doc, hover v gopls i pkg.go.dev je všechny čtou. Každý začni jménem, které dokumentuje, aby se četl jako věta.",
  ["Does the order contain egg? Which keyword tests membership?"] = "Obsahuje objednávka egg? Které klíčové slovo testuje příslušnost?",
  ["Does this shift start before the last merged block ends? Fill the overlap test."] = "Začíná tahle směna dřív, než poslední sloučený blok končí? Doplň test překryvu.",
  ["Don't share memory. Pass the hash brown on a channel."] = "Nesdílej paměť. Pošli hash brown kanálem.",
  ["Double every price into a new list, in one line. Which keyword sits in the middle of the comprehension?"] = "Zdvojnásobit každou cenu do nového seznamu, na jednom řádku. Které klíčové slovo sedí uprostřed comprehension?",
  ["Double every quantity. How does a closure name its one parameter?"] = "Zdvojnásob každé množství. Jak closure pojmenuje svůj jediný parametr?",
  ["Dunder around the text type's name. Its sibling __repr__ is for the debugger."] = "Dunder okolo jména textového typu. Jeho sourozenec __repr__ je pro debugger.",
  ["Dunder around the verb for going in. Its return value is what as binds."] = "Dunder okolo slovesa pro vstup. Jeho návratová hodnota je to, co naváže as.",
  ["Dunder around the verb for going out. It receives three values about any exception."] = "Dunder okolo slovesa pro odchod. Dostane tři hodnoty o případné výjimce.",
  ["Dynamic programming"] = "Dynamické programování",
  ["Dynamic programming: stairs and coins"] = "Dynamické programování: schody a mince",
  ["EARLY BIRD"] = "RANNÍ PTÁČE",
  ["ENTER  pick a street"] = "ENTER  vyber ulici",
  ["ENTER  street map      ESC  title"] = "ENTER  mapa ulic      ESC  úvod",
  ["ESC back"] = "ESC zpět",
  ["ESC title"] = "ESC úvod",
  ["EXPORT  to ~/Downloads"] = "EXPORT  do ~/Downloads",
  ["Each Fibonacci number is the sum of the two before it."] = "Každé Fibonacciho číslo je součtem dvou předchozích.",
  ["Each call handles one step and delegates the rest: n * (n-1)!"] = "Každé volání zvládne jeden krok a zbytek deleguje: n * (n-1)!",
  ["Each call handles one step and delegates the rest: n * (n-1)!. Python ints never overflow, so fact(100) just works."] = "Každé volání zvládne jeden krok a zbytek deleguje: n * (n-1)!. Inty v Pythonu nikdy nepřetečou, takže fact(100) prostě funguje.",
  ["Each call is one step closer to 1. fact(20) is the biggest that fits in u64. The crowd claps."] = "Každé volání je o krok blíž k 1. fact(20) je největší, co se vejde do u64. Dav tleská.",
  ["Each cell is visited a constant number of times: O(rows*cols). A BFS with a queue avoids deep recursion. OFFER."] = "Každá buňka se navštíví konstantněkrát: O(rows*cols). BFS s frontou se vyhne hluboké rekurzi. OFFER.",
  ["Each closer maps to its opener. Fill the value stored for ')'."] = "Každá zavírací závorka se mapuje na svou otevírací. Doplň hodnotu uloženou pro ')'.",
  ["Each interval is compared with the last merged one, which may need to grow. Which method borrows the last element mutably as Option?"] = "Každý interval se porovná s posledním sloučeným, který může potřebovat růst. Která metoda si měnitelně půjčí poslední prvek jako Option?",
  ["Each n is computed once: O(n) calls, O(n) memory. Round one, no misses. Combo x1."] = "Každé n se spočítá jednou: O(n) volání, O(n) paměti. První kolo, bez chyby. Kombo x1.",
  ["Each node links to the next one. Fill the field type: Next ___"] = "Každý uzel odkazuje na další. Doplň typ pole: Next ___",
  ["Each thread needs its own handle to the same counter. Which call makes one from &sold?"] = "Každé vlákno potřebuje vlastní handle na stejný čítač. Které volání ho vytvoří z &sold?",
  ["Each version is unpacked once into pkg/mod/github.com/alex/luckymac@v1.2.0 and never touched again. go clean -modcache wipes it when the disk fills up."] = "Každá verze se rozbalí jednou do pkg/mod/github.com/alex/luckymac@v1.2.0 a víckrát se na ni nesahá. go clean -modcache ji smaže, když se zaplní disk.",
  ["Eight cooks, one order book. That I understand."] = "Osm kuchařů, jedna objednávková kniha. Tomuhle rozumím.",
  ["Eight cores, one busy"] = "Osm jader, jedno vytížené",
  ["Eight letters, the opposite of external. The rule is in the compiler, not in a linter."] = "Osm písmen, opak external. Pravidlo je v překladači, ne v linteru.",
  ["Eight letters, what a house or an object has. Then o.total works, no parentheses."] = "Osm písmen, to, co má dům nebo objekt. Pak o.total funguje, bez závorek.",
  ["Eight letters: every goroutine waits on every other. The send never returns."] = "Osm písmen: každá goroutine čeká na všechny ostatní. Odeslání se nikdy nevrátí.",
  ["Eight letters: like find, but it gives you where, not what. Option<usize>."] = "Osm písmen: jako find, ale dá ti kde, ne co. Option<usize>.",
  ["Eight shared doubles with a lock and no NumPy. Which multiprocessing class?"] = "Osm sdílených doublů se zámkem a bez NumPy. Která třída z multiprocessing?",
  ["Eight workers, one label printer. The labels came out with two orders on one sticker."] = "Osm workerů, jedna tiskárna štítků. Vyjela nálepka se dvěma objednávkami přes sebe.",
  ["Eight workers, started once, reused all night. Which class?"] = "Osm workerů, spuštěných jednou, používaných celou noc. Která třída?",
  ["Elision: one input reference (here &self) means the output borrows from it. Most signatures need no 'a at all. The receipt prints."] = "Elize: jedna vstupní reference (tady &self) znamená, že výstup si půjčuje z ní. Většina signatur žádné 'a nepotřebuje. Účtenka se tiskne.",
  ["Empty brackets then the element type. [3]int would be an array."] = "Prázdné hranaté závorky a pak typ prvku. [3]int by bylo pole.",
  ["Empty parentheses. go needs a call, not just a function value."] = "Prázdné závorky. go potřebuje volání, ne jen hodnotu funkce.",
  ["Empty the whole map in one call (Go 1.21). Which built-in?"] = "Vyprázdni celou mapu jedním voláním (Go 1.21). Která vestavěná funkce?",
  ["Errors and defer"] = "Chyby a defer",
  ["Errors are exceptions: try runs the risky part, except catches a type, finally always runs, raise throws. Your own errors subclass Exception."] = "Chyby jsou výjimky: try spustí riskantní část, except zachytí typ, finally proběhne vždy, raise vyhodí. Vlastní chyby dědí z Exception.",
  ["Errors: New, wrap, Is, As"] = "Chyby: New, wrap, Is, As",
  ["Even with separate memory, processes still share the machine: one printer, one log file, one counter in shared memory. multiprocessing.Lock is the mutex across processes, used as a with block. Value and Array put a number in shared memory and hand you get_lock() for it, and a Manager serves ordinary dicts and lists over a proxy."] = "I s oddělenou pamětí procesy pořád sdílejí stroj: jednu tiskárnu, jeden soubor s logem, jeden čítač ve sdílené paměti. multiprocessing.Lock je mutex napříč procesy a používá se jako blok with. Value a Array uloží číslo do sdílené paměti a podají ti k němu get_lock(), a Manager nabízí běžné slovníky a seznamy přes proxy.",
  ["Evening edition of CODE RUSH! Rust round. Mei, you're up. Factorial, then fib. Buzzer's live!"] = "Večerní vydání CODE RUSH! Kolo Rustu. Mei, jsi na řadě. Faktoriál, pak fib. Bzučák je živý!",
  ["Every Go file starts with package. import brings other packages in."] = "Každý soubor v Go začíná package. import přináší další balíčky.",
  ["Every Rust program starts in which function?"] = "Každý program v Rustu začíná ve které funkci?",
  ["Every cell is visited once by the loop and at most once by a DFS: O(rows * cols). The screen says OFFER."] = "Každou buňku navštíví cyklus jednou a DFS nejvýš jednou: O(rows * cols). Obrazovka říká OFFER.",
  ["Every closer knows its opener. Fill the opener that } maps to."] = "Každá zavírací závorka zná svou otvírací. Doplň otvírací, na kterou } ukazuje.",
  ["Every dish gets a stamp: time it, log it. I do not want to write that in fifty functions."] = "Každé jídlo dostane razítko: změř ho, zaloguj ho. Nechci to psát do padesáti funkcí.",
  ["Every dish is a function. fry(egg), brew(tea). Someone deleted the word that starts them."] = "Každé jídlo je funkce. fry(egg), brew(tea). Někdo smazal slovo, kterým začínají.",
  ["Every get must be paired with a task_done, or join waits forever. Go's wg.Done()."] = "Každý get musí mít svůj task_done, jinak join čeká navěky. wg.Done() z Go.",
  ["Every get needs one task_done, or q.join() waits for ever. It is the WaitGroup of the queue world."] = "Na každé get patří jedno task_done, jinak q.join() čeká věčně. Je to WaitGroup světa front.",
  ["Every island is counted exactly once because its cells are water by the time the loop reaches them again. OFFER."] = "Každý ostrov je započítán přesně jednou, protože jeho buňky jsou voda, než se k nim cyklus znovu dostane. OFFER.",
  ["Every item is moved exactly once per level, however many pieces there are."] = "Každá položka se přesune přesně jednou na úroveň, ať je kusů kolik chce.",
  ["Every item sent to a worker is pickled and shipped down a pipe. Below a few microseconds of work per item, the shipping is the program."] = "Každá položka poslaná workerovi se zabalí přes pickle a pošle rourou. Pod pár mikrosekund práce na položku je tou hlavní prací doprava.",
  ["Every key of the price map, as an iterator (Go 1.23). Fill: maps.___(prices)"] = "Každý klíč mapy cen jako iterátor (Go 1.23). Doplň: maps.___(prices)",
  ["Every one of these is 'use a map' or 'use two pointers'. Pick the right one."] = "Každá z nich je 'použij mapu' nebo 'použij dva ukazatele'. Vyber správně.",
  ["Every opener must have been closed. What does the function return at the end?"] = "Každá otevírací musela být zavřena. Co funkce na konci vrací?",
  ["Every opener must have found its closer. What does valid return after the loop?"] = "Každá otvírací závorka musela najít svou zavírací. Co valid vrátí po cyklu?",
  ["Every price but the first must lose a comparison to be ruled out. One less than the count."] = "Každá cena kromě první musí prohrát jedno porovnání, aby byla vyřazena. O jedno méně než počet.",
  ["Every process closes its view. Which call, made once, frees the block itself?"] = "Každý proces zavře svůj pohled. Které volání, provedené jednou, uvolní samotný blok?",
  ["Every public download is checked against a transparency log. Name its host."] = "Každé veřejné stažení se kontroluje proti transparentnímu logu. Pojmenuj jeho hosta.",
  ["Every real answer grows out of dp[0]. The marker amount + 1 lets min work without an Option."] = "Každá skutečná odpověď vyrůstá z dp[0]. Značka amount + 1 nechá min pracovat bez Option.",
  ["Every receipt goes onto a min-heap. Which heapq function adds x and keeps the heap order?"] = "Každá účtenka jde na min-haldu. Která funkce z heapq přidá x a zachová pořadí haldy?",
  ["Every recursion stops somewhere. fact(0) and fact(1) evaluate to what?"] = "Každá rekurze někde končí. Jakou hodnotu mají fact(0) a fact(1)?",
  ["Every recursion stops somewhere. fact(0) and fact(1) return what?"] = "Každá rekurze se někde zastaví. Co vrací fact(0) a fact(1)?",
  ["Every runnable Go program lives in which package?"] = "Ve kterém balíčku žije každý spustitelný program v Go?",
  ["Every topping can be on or off. Ten toppings, a thousand combos. Twenty, a million. That is 2^n."] = "Každá příloha může být, nebo nebýt. Deset příloh, tisíc kombinací. Dvacet, milion. To je 2^n.",
  ["Every topping on or off, n toppings. How many combinations, as a power?"] = "Každá příloha ano nebo ne, n příloh. Kolik kombinací, jako mocnina?",
  ["Every worker allocates a receipt buffer. Which sync.Pool method hands one back?"] = "Každý worker si alokuje buffer na účtenku. Která metoda sync.Pool ti jeden podá?",
  ["Every worker must report in before Wait returns. Which method, deferred?"] = "Každý worker se musí ohlásit, než se Wait vrátí. Která metoda, přes defer?",
  ["Everyone's shifts overlap. Six to ten, nine to two, one to four. When is the kitchen actually staffed?"] = "Všem se směny překrývají. Od šesti do deseti, od devíti do dvou, od jedné do čtyř. Kdy je v kuchyni doopravdy někdo?",
  ["Everything bigger than the node. Five letters."] = "Všechno větší než uzel. Pět písmen, anglicky.",
  ["Everything from index 1 to the end. A slice expression, no copy."] = "Vše od indexu 1 do konce. Výraz slice, bez kopie.",
  ["Everything from the second block on. zip stops at the shorter list, so no index error."] = "Všechno od druhého bloku dál. zip se zastaví na kratším seznamu, takže žádná chyba indexu.",
  ["Everything is immutable until you say mut. The tram sign forgot that."] = "Všechno je neměnné, dokud neřekneš mut. Tramvajová tabule na to zapomněla.",
  ["Everything written before the close happens before <-ready returns, so reading menu after it is not a race. That rule is the Go memory model."] = "Všechno zapsané před zavřením se stane dřív, než se <-ready vrátí, takže číst menu potom není souběh. To pravidlo je paměťový model Go.",
  ["Exponential time"] = "Exponenciální čas",
  ["Exponential: two to the power of n. Each level of the call tree is twice as wide as the one above."] = "Exponenciální: dvě na n-tou. Každá úroveň stromu volání je dvakrát širší než ta nad ní.",
  ["F for a file or writer, then printf. The writer is the first argument."] = "F jako file nebo writer, pak printf. Writer je první argument.",
  ["FAILED  %s"] = "SELHALO  %s",
  ["FAST!"] = "RYCHLE!",
  ["FINAL  -  the islands"] = "FINÁLE  -  ostrovy",
  ["FINAL  -  the kitchen"] = "FINÁLE  -  kuchyně",
  ["FIRST CLEAR"] = "PRVNÍ CLEAR",
  ["FIRST STAMP"] = "PRVNÍ RAZÍTKO",
  ["FIVE PERFECTS"] = "PĚT PERFEKTNÍCH",
  ["FULL"] = "CELÁ",
  ["Fan-in: workers send, one closer closes. Closing from a worker would panic the others, so the closer is the goroutine that waits."] = "Fan-in: workeři posílají, zavírá jeden. Kdyby zavřel worker, ostatní by zpanikařili, takže zavírá ta goroutina, která čeká.",
  ["Feed nine orders into the queue. Which method adds one?"] = "Nasypat devět objednávek do fronty. Která metoda přidá jednu?",
  ["Fewest coins wins, so keep the smaller of the old value and the new candidate."] = "Nejméně mincí vyhrává, takže nech menší ze staré hodnoty a nového kandidáta.",
  ["Fibonacci in disguise: the sum of the two entries just before it."] = "Fibonacci v přestrojení: součet dvou položek těsně před ní.",
  ["Final question. A map of the harbour, ones for land, zeros for water. How many islands? Get this and the offer is yours."] = "Poslední otázka. Mapa přístavu, jedničky pevnina, nuly voda. Kolik ostrovů? Dej to a nabídka je tvoje.",
  ["Final round, Mei! Get the drop and the join in the right order and you're HIRED!"] = "Finálové kolo, Mei! Dej drop a join ve správném pořadí a jsi PŘIJATÁ!",
  ["Final round. The delivery map as a grid of 1s and 0s. How many separate islands of buildings?"] = "Finálové kolo. Rozvozová mapa jako mřížka jedniček a nul. Kolik oddělených ostrovů budov?",
  ["Final round: a worker pool. Three cooks, one queue, nine orders. Nothing lost, nothing done twice."] = "Finální kolo: pool workerů. Tři kuchaři, jedna fronta, devět objednávek. Nic ztraceno, nic dvakrát.",
  ["Finally, types. Even if the interpreter ignores them."] = "Konečně typy. I když je interpret ignoruje.",
  ["Find land, sink the whole island, count one. Repeat until the map is all water."] = "Najdi souš, potop celý ostrov, započítej jeden. Opakuj, dokud není mapa samá voda.",
  ["Find suspicious code the compiler allows: wrong Printf verbs, copied locks. Fill: go ___ ./..."] = "Najdi podezřelý kód, který kompilátor pustí: špatné verby Printf, kopírované zámky. Doplň: go ___ ./...",
  ["Find the middle: slow moves one, fast moves two. Fill the fast step: fast = fast.next.___"] = "Najít střed: slow jde o jeden, fast o dva. Doplň rychlý krok: fast = fast.next.___",
  ["Find where 38 belongs in the sorted amounts in O(log n). Which bisect function?"] = "Najít, kam patří 38 v seřazených částkách, v O(log n). Která funkce z bisect?",
  ["Finding the largest of n unsorted prices needs at least how many comparisons?"] = "Najít největší z n neseřazených cen vyžaduje nejméně kolik porovnání?",
  ["Finish Go's proverb: do not communicate by sharing memory; share memory by ___."] = "Dokonči přísloví Go: nekomunikuj sdílením paměti; sdílej paměť ___.",
  ["Five letters, Go's only way to loop over a slice's elements. slices.Contains does exactly this inside."] = "Pět písmen, jediný způsob v Go, jak projít prvky slice. slices.Contains dělá uvnitř přesně toto.",
  ["Five letters, a builtin that takes a channel. It never blocks and every receiver wakes."] = "Pět písmen, vestavěná funkce, která bere kanál. Nikdy neblokuje a probudí každého příjemce.",
  ["Five letters, a stash of things already fetched. Its older sibling takes a maxsize."] = "Pět písmen, skrýš věcí, které už jsi přinesl. Jeho starší sourozenec bere maxsize.",
  ["Five letters, a verb in the third person: what the wrapper does to fn."] = "Pět písmen, sloveso ve třetí osobě: to, co obal dělá s fn.",
  ["Five letters, a verb: wait for it. Rust puts the same word after a dot."] = "Pět písmen, sloveso: počkej na to. Rust dává totéž slovo za tečku.",
  ["Five letters, capitalised: what Value is, but with a length."] = "Pět písmen s velkým počátečním: to, co je Value, ale s délkou.",
  ["Five letters, goes before fn. The opposite of sync."] = "Pět písmen, jde před fn. Opak sync.",
  ["Five letters, lower case: the box has one, and this is how you open it."] = "Pět písmen malými: krabička jedno obsahuje a takhle se otevírá.",
  ["Five letters, lowercase, no package in front of it. Go needs fmt for this; Python does not."] = "Pět písmen, malá, bez balíčku před sebou. Go k tomu potřebuje fmt; Python ne.",
  ["Five letters, meaning 'give way'. Like return, but the function resumes on the next pull."] = 'Pět písmen, ve významu „ustoupit". Jako return, ale při dalším vytažení funkce pokračuje.',
  ["Five letters, plural. for k in menu alone gives only the keys."] = "Pět písmen, množné číslo. Samotné for k in menu dá jen klíče.",
  ["Five letters, same as Go, but Rust insists on the : u8 part."] = "Pět písmen, stejně jako v Go, ale Rust trvá na části : u8.",
  ["Five letters, short for asynchronous. Rust spells it the same way in front of fn."] = "Pět písmen, zkratka za asynchronous. Rust to před fn píše stejně.",
  ["Five letters, short for mutual exclusion."] = "Pět písmen, zkratka pro mutual exclusion.",
  ["Five letters, since Python 3.9: the unbounded memo. Its older cousin takes a maxsize."] = "Pět písmen, od Pythonu 3.9: neomezené memo. Jeho starší bratranec bere maxsize.",
  ["Five letters, the opposite of open. Forgetting it is why the morning count was wrong."] = "Pět písmen, opak open. Zapomenout na ni je důvod, proč byl ranní počet špatně.",
  ["Five letters, the opposite of stop. Not run(): that would call fry in the current thread."] = "Pět písmen, opak stop. Ne run(): to by zavolalo fry v aktuálním vlákně.",
  ["Five letters, the shape of a line at a counter. Go spells it chan."] = "Pět písmen, tvar řady u pultu. Go to píše chan.",
  ["Five letters, the trait every Vec<T: Clone> implements. to_vec() from a slice is the other spelling."] = "Pět písmen, trait, který implementuje každý Vec<T: Clone>. to_vec() ze slice je druhý zápis.",
  ["Five letters, the word for 'above'. It returns a proxy to the parent class."] = 'Pět písmen, slovo pro „nad". Vrací proxy na rodičovskou třídu.',
  ["Five letters, the word for a stash of things you already fetched. Its older sibling takes a maxsize."] = "Pět písmen, slovo pro skrýš věcí, které už jsi přinesl. Jeho starší sourozenec bere maxsize.",
  ["Five letters, what a fish does with eggs. The alternatives are fork and forkserver."] = "Pět písmen, to, co dělá ryba s jikrami. Další možnosti jsou fork a forkserver.",
  ["Five letters, what a fish does with eggs. The closure must be 'static, hence move."] = "Pět písmen, anglicky: co dělá ryba s jikrami. Closure musí být 'static, proto move.",
  ["Five letters. A region with a clear start and end."] = "Pět písmen. Oblast s jasným začátkem a koncem.",
  ["Five letters. A slot for one key, whether it exists yet or not."] = "Pět písmen. Přihrádka pro jeden klíč, ať už existuje, nebo ještě ne.",
  ["Five letters. Also asks for a location."] = "Pět písmen. Také se jím ptáš na místo.",
  ["Five letters. Also ends a switch or select case early."] = "Pět písmen. Předčasně ukončí i case ve switch nebo select.",
  ["Five letters. Explicit, so you always see where the copying cost is."] = "Pět písmen. Výslovné, takže vždy vidíš, kde je cena kopírování.",
  ["Five letters. Go 1.22 borrowed the idea as for i := range 3."] = "Pět písmen. Go 1.22 si ten nápad vypůjčilo jako for i := range 3.",
  ["Five letters. Go called it an interface."] = "Pět písmen. Go tomu říkalo interface.",
  ["Five letters. Go has struct plus methods; Python puts both under one word. Names are CapWords."] = "Pět písmen. Go má struct plus metody; Python dává obojí pod jedno slovo. Jména jsou CapWords.",
  ["Five letters. Go's switch, but exhaustive and it returns a value."] = "Pět písmen. switch z Go, ale úplný a vrací hodnotu.",
  ['Five letters. It returns a Result because "1x8" is not a number.'] = 'Pět písmen. Vrací Result, protože "1x8" není číslo.',
  ["Five letters. On a slice it zeroes every element instead."] = "Pět písmen. Na slice místo toho vynuluje každý prvek.",
  ["Five letters. Return an error for expected failure; this is for the impossible."] = "Pět písmen. Na očekávané selhání vrať error; tohle je pro nemožné.",
  ["Five letters. Same verb as std::thread uses to start a new thread."] = "Pět písmen. Stejné sloveso, jakým std::thread spouští nové vlákno.",
  ["Five letters. Sender has it; Receiver does not."] = "Pět písmen. Sender ji má; Receiver ne.",
  ["Five letters. The same word as in C and Python; Go spells it for."] = "Pět písmen. Stejné slovo jako v C a Pythonu; Go ho píše jako for.",
  ["Five letters. What a key maps to. The json! macro builds one."] = "Pět písmen. To, na co se mapuje klíč. Makro json! ji postaví.",
  ["Five letters. What fish and goroutines do."] = "Pět písmen. To, co dělají ryby a goroutiny, anglicky.",
  ["Five letters. What the kettle does between orders."] = "Pět písmen. To, co dělá konvice mezi objednávkami.",
  ["Five letters. go run compiles and runs; this one only compiles."] = "Pět písmen. go run kompiluje a spouští; tohle jen kompiluje.",
  ["Five letters: the Entry API. One lookup for both the check and the insert."] = "Pět písmen: Entry API. Jedno vyhledání pro kontrolu i vložení.",
  ["Five letters; Java and JavaScript say throw. Rust's panic!, but meant to be caught."] = "Pět písmen; Java a JavaScript říkají throw. panic! z Rustu, ale určený k zachycení.",
  ["Fix the Go bugs. Get the morning set."] = "Oprav bugy v Go. Získej ranní menu.",
  ["Fix the Python scripts. Close the night shift."] = "Oprav pythonové skripty. Uzavři noční směnu.",
  ["Fix the Rust bugs. Get the afternoon tea set."] = "Oprav chyby v Rustu. Získej odpolední svačinu.",
  ["Flip it to > for a max-heap. sort.Interface plus Push and Pop is the whole contract."] = "Otoč to na > pro max-haldu. sort.Interface plus Push a Pop je celý kontrakt.",
  ["Flood fill on a grid: return when out of bounds or not land, sink the cell to mark it, recurse into the four neighbours. Count islands by starting a fill from every land cell still standing."] = "Flood fill na mřížce: vrať se, když jsi mimo meze nebo ne na souši, potop buňku jako značku, rekurzivně do čtyř sousedů. Ostrovy počítej spuštěním výplně z každé buňky souše, která ještě stojí.",
  ["Flood the four neighbours. r + 1 is fine, but r - 1 on a usize at row 0 panics in debug. Which method subtracts and wraps to usize::MAX instead?"] = "Zaplav čtyři sousedy. r + 1 je v pořádku, ale r - 1 na usize v řádku 0 v debugu spanikaří. Která metoda odečte a místo toho přeteče na usize::MAX?",
  ["Flood the four neighbours: down, up, right and one more. Fill the missing one."] = "Zaplav čtyři sousedy: dolů, nahoru, doprava a ještě jeden. Doplň chybějícího.",
  ["Floor 8. Type the floor. Don't hard-code magic."] = "Patro 8. Napiš patro. Žádná magická čísla natvrdo.",
  ["Floor is a named type over int. Convert the int 3 into a Floor. Fill: f := ___(3)"] = "Floor je pojmenovaný typ nad int. Převeď int 3 na Floor. Doplň: f := ___(3)",
  ["Floors 1 to 5, and 5 must be included. Which range operator?"] = "Patra 1 až 5 a pětka musí být včetně. Který operátor rozsahu?",
  ["Floyd's check: if the fast rider ever lands on the slow one, the route loops. Which operator compares identity?"] = "Floydův test: když rychlý kurýr někdy dopadne na pomalého, trasa tvoří smyčku. Který operátor porovnává identitu?",
  ["Floyd: fast moves two steps per turn. Fill: fast = fast.Next.___"] = "Floyd: fast dělá dva kroky na tah. Doplň: fast = fast.Next.___",
  ["Followed by the value, then case labels. No break needed."] = "Za ním hodnota, pak návěští case. break není potřeba.",
  ["For a pure function, the standard library has the whole cache as a decorator. Which keyword caps its size?"] = "Pro čistou funkci má standardní knihovna celou cache jako dekorátor. Které klíčové slovo omezuje její velikost?",
  ["For each amount a and coin c that fits: one coin c on top of the best for a - c. Keep the smaller. Which method?"] = "Pro každou částku a a minci c, která se vejde: jedna mince c navrch nejlepšího pro a - c. Nech si menší. Která metoda?",
  ["For each coin c that fits into a: one coin, plus the best for what is left. Fill the index."] = "Pro každou minci c, která se do a vejde: jedna mince plus nejlepší řešení zbytku. Doplň index.",
  ["For one number, an atomic beats a mutex: atomic.Int64 has Add, Load, Store and CompareAndSwap, all lock free. atomic.Pointer[T] swaps a whole value in one step. sync.Once runs setup exactly once; sync.OnceValue caches what it returned."] = "Když jde o jedno číslo, atomika porazí mutex: atomic.Int64 má Add, Load, Store a CompareAndSwap, všechno bez zámků. atomic.Pointer[T] vymění celou hodnotu jedním krokem. sync.Once spustí přípravu právě jednou; sync.OnceValue si navíc uloží, co vrátila.",
  ["Forty riders, eight bikes"] = "Čtyřicet kurýrů, osm kol",
  ["Forty thousand photos"] = "Čtyřicet tisíc fotek",
  ["Forty thousand photos before the morning van, and threads made it no faster. Fill every core with processes."] = "Čtyřicet tisíc fotek do příjezdu ranní dodávky, a vlákna to nezrychlila. Zaplň procesy každé jádro.",
  ["Forty thousand results will not fit in memory. Which method yields them one by one?"] = "Čtyřicet tisíc výsledků se do paměti nevejde. Která metoda je vydává po jednom?",
  ["Found and removed from its old spot: now k goes to the fresh end. Which VecDeque method appends at the back?"] = "Nalezeno a odebráno ze starého místa: teď jde k na čerstvý konec. Která metoda VecDeque připojí dozadu?",
  ["Four directions, no diagonals. Deep grids hit the recursion limit near 1000: an explicit stack of (r, c) fixes that."] = "Čtyři směry, žádné diagonály. Hluboké mřížky narazí na limit rekurze kolem 1000: explicitní zásobník (r, c) to spraví.",
  ["Four hundred HTTP calls, and four hundred image resizes. Same code, different executor."] = "Čtyři sta HTTP volání a čtyři sta zmenšení obrázků. Stejný kód, jiný executor.",
  ["Four hundred image resizes, eight cores. Which executor class?"] = "Čtyři sta obrázků ke zmenšení, osm jader. Která třída executoru?",
  ["Four letters, a Greek one. Resets to 0 in every const block, +1 per line."] = "Čtyři písmena, řecké písmeno. V každém bloku const začíná od 0, +1 na řádek.",
  ["Four letters, a preposition. It replaces try/finally: f.close() for the common case."] = "Čtyři písmena, předložka. Nahrazuje try/finally: f.close() pro běžný případ.",
  ["Four letters, as in workspace. Go 1.18. It writes a go.work file beside the two folders."] = "Čtyři písmena jako ve workspace. Go 1.18. Zapíše soubor go.work vedle obou složek.",
  ["Four letters, capital K. slices.Sorted(maps.Keys(m)) gives a sorted slice."] = "Čtyři písmena, velké K. slices.Sorted(maps.Keys(m)) dá seřazený slice.",
  ["Four letters, capital O. Its only method is Do."] = "Čtyři písmena, velké O. Jediná metoda je Do.",
  ["Four letters, capital S. SortFunc takes a compare function."] = "Čtyři písmena, velké S. SortFunc bere porovnávací funkci.",
  ["Four letters, capitalised. The same name threading uses, and Go calls it sync.Mutex."] = "Čtyři písmena s velkým počátečním. Stejné jméno jako v threading, Go tomu říká sync.Mutex.",
  ["Four letters, capitalized; Go calls it a Mutex. with acquires and releases it."] = "Čtyři písmena, s velkým písmenem; Go ho nazývá Mutex. with ho získá a uvolní.",
  ["Four letters, plural of what you look a value up by."] = "Čtyři písmena, množné číslo toho, podle čeho vyhledáváš hodnotu.",
  ["Four letters, short for implementation. Go attaches methods one by one; Rust groups them."] = "Čtyři písmena, zkratka pro implementation. Go připojuje metody jednu po druhé; Rust je seskupuje.",
  ["Four letters, short for receive. Returns Result<Job, RecvError>. try_recv would not wait."] = "Čtyři písmena, zkratka pro receive. Vrací Result<Job, RecvError>. try_recv by nečekalo.",
  ["Four letters, the append of every Vec."] = "Čtyři písmena, přidání na konec u každého Vec.",
  ["Four letters, the opposite of Store."] = "Čtyři písmena, opak Store.",
  ["Four letters, the opposite of first. The length is stored, so no counting."] = "Čtyři písmena, opak first. Délka je uložená, takže žádné počítání.",
  ["Four letters, the opposite of send, cut short."] = "Čtyři písmena, opak send, zkrácený.",
  ["Four letters, the same word Go uses for a set of workers reading one channel."] = "Čtyři písmena, stejné slovo, jakým Go označuje skupinu workerů čtoucích jeden kanál.",
  ["Four letters, the same word Rust's JoinHandle uses. Go spells it wg.Wait()."] = "Čtyři písmena, totéž slovo, které používá JoinHandle v Rustu. Go píše wg.Wait().",
  ["Four letters, the same word as Thread.join, but on the queue: wait until the count of unfinished tasks is zero."] = "Čtyři písmena, totéž slovo jako Thread.join, ale na frontě: čekat, dokud počet nedokončených úloh není nula.",
  ["Four letters, the same word threading uses. Go spells it wg.Wait()."] = "Čtyři písmena, stejné slovo jako v threading. Go to píše wg.Wait().",
  ["Four letters, the start of iterator. A for loop calls it for you."] = "Čtyři písmena, začátek slova iterator. Cyklus for ji za tebe zavolá.",
  ["Four letters, the type of true. map[T]struct{} saves a byte per entry and is the other idiom."] = "Čtyři písmena, typ hodnoty true. map[T]struct{} ušetří bajt na položku a je to druhý idiom.",
  ["Four letters, the type {} makes. A list of pairs would need a scan, O(n)."] = "Čtyři písmena, typ, který vytvoří {}. Seznam dvojic by potřeboval průchod, O(n).",
  ["Four letters, the word in the warning itself. It also works on go run and go build."] = "Čtyři písmena, slovo z toho varování samotného. Funguje i u go run a go build.",
  ["Four letters, to enumerate. -m means modules rather than packages; -u adds available upgrades."] = "Čtyři písmena, vyjmenovat. -m znamená moduly místo balíčků; -u přidá dostupné aktualizace.",
  ["Four letters, what a shell puts between two commands. It returns two ends."] = "Čtyři písmena, to, co shell dává mezi dva příkazy. Vrací dva konce.",
  ["Four letters. An alias of int32. byte is the alias of uint8."] = "Čtyři písmena. Alias pro int32. byte je alias pro uint8.",
  ["Four letters. Consumes the handle and returns Result<T, Box<dyn Any + Send>>."] = "Čtyři písmena. Spotřebuje handle a vrátí Result<T, Box<dyn Any + Send>>.",
  ["Four letters. Every file may have one; the runtime calls it for you."] = "Čtyři písmena. Každý soubor ji může mít; runtime ji zavolá za tebe.",
  ["Four letters. Go fakes it with const and iota; Rust has the real thing."] = "Čtyři písmena. Go to napodobuje přes const a iota; Rust má tu pravou věc.",
  ["Four letters. Go writes for { } with no condition; Rust has a word for it."] = "Čtyři písmena. Go píše for { } bez podmínky; Rust na to má slovo.",
  ["Four letters. Go's append, but it changes the Vec in place, so it needs mut."] = "Čtyři písmena. append z Go, ale mění Vec na místě, takže potřebuje mut.",
  ["Four letters. Go's receiver (o *Order), Rust's &self, but here it is an ordinary parameter by convention."] = "Čtyři písmena. Receiver z Go (o *Order), &self z Rustu, ale tady je to podle konvence obyčejný parametr.",
  ["Four letters. It also builds maps and channels."] = "Čtyři písmena. Vytváří i mapy a kanály.",
  ["Four letters. It answers the question 'what type is this'. isinstance(x, float) is the check you use in code."] = 'Čtyři písmena. Odpovídá na otázku „jaký je to typ". V kódu se kontroluje pomocí isinstance(x, float).',
  ["Four letters. It counts the group down; Add counted it up."] = "Čtyři písmena. Odečte skupině jedna; Add jí jedna přidal.",
  ["Four letters. Let go of it now instead of at the end of scope."] = "Čtyři písmena. Pusť ho teď místo na konci bloku.",
  ["Four letters. Like std::mem::take: gives you the value, puts the default (None) back."] = "Čtyři písmena. Jako std::mem::take: dá ti hodnotu a na její místo vrátí výchozí (None).",
  ["Four letters. Not copied: the heap buffer changed hands."] = "Čtyři písmena. Ne zkopírováno: buffer na haldě změnil majitele.",
  ["Four letters. Take it, do not borrow it."] = "Čtyři písmena. Vezmi si to, nepůjčuj si to.",
  ["Four letters. The From trait gives it to you. to_string() does the same job."] = "Čtyři písmena. Dá ti ho trait From. to_string() dělá tu samou práci.",
  ["Four letters. The block gets one from the operating system, like a file in /dev/shm."] = "Čtyři písmena. Blok ho dostane od operačního systému, jako soubor v /dev/shm.",
  ["Four letters. The borrowing one. into_ in front of it would consume the Vec."] = "Čtyři písmena. Ten půjčující. S into_ vpředu by Vec spotřeboval.",
  ["Four letters. The channel is closed when the context is finished, so every watcher wakes at once."] = "Čtyři písmena. Když context skončí, ten kanál se zavře, takže se všichni sledující probudí naráz.",
  ["Four letters. The opposite of None."] = "Čtyři písmena. Opak None.",
  ["Four letters. The same keyword that opens a block of methods, used as a type."] = "Čtyři písmena. Stejné klíčové slovo, které otvírá blok metod, použité jako typ.",
  ["Four letters. The same rule Go applies to a local variable you never read."] = "Čtyři písmena. Stejné pravidlo, jaké Go uplatňuje na lokální proměnnou, kterou nikdy nečteš.",
  ["Four letters. The same word that starts an implementation block."] = "Čtyři písmena. Stejné slovo, kterým začíná implementační blok.",
  ["Four letters. The same word you put in the attribute over the function."] = "Čtyři písmena. Stejné slovo, které dáváš do atributu nad funkci.",
  ["Four letters. The word that follows if. The block must diverge: return, break, panic."] = "Čtyři písmena. Slovo, které následuje po if. Blok musí divergovat: return, break, panic.",
  ["Four letters. Threads use the same word to wait for each other."] = "Čtyři písmena. Vlákna používají stejné slovo, když na sebe čekají.",
  ["Four letters. What Rust does for you at the end of every scope, called by hand."] = "Čtyři písmena. To, co Rust dělá za tebe na konci každého bloku, zavolané ručně.",
  ["Four letters. What you do to a menu."] = "Čtyři písmena. To, co děláš s menu, anglicky.",
  ["Four letters. What you do to a paper napkin, over and over, into one small square."] = "Čtyři písmena. To, co děláš s papírovým ubrouskem, znovu a znovu, až je z něj malý čtvereček.",
  ["Four letters. What you do to the drawer at closing time."] = "Čtyři písmena. To, co uděláš se zásuvkou při zavírání.",
  ["Four letters. What you do with a parcel."] = "Čtyři písmena. To, co uděláš s balíkem, anglicky.",
  ["Four letters. Where two roads meet again."] = "Čtyři písmena. Kde se dvě cesty zase spojí.",
  ["Four letters. fork gives one lazily, spawn makes one from the pickle. Either way it is not yours."] = "Čtyři písmena. fork ji dá líně, spawn ji vyrobí z picklu. Tak či tak není tvoje.",
  ["Four letters: a look at the top. Returns Option<&T>, hence the * and the unwrap."] = "Čtyři písmena: pohled na vrchol. Vrací Option<&T>, odtud * a unwrap.",
  ["Four letters: else and if squeezed into one word."] = "Čtyři písmena: else a if stlačené do jednoho slova.",
  ["Four letters: make it neat. Run it before every commit."] = "Čtyři písmena: udělej pořádek. Spouštěj před každým commitem.",
  ["Four letters: my, and the language's first two. pyright is the other common one."] = "Čtyři písmena: my a první dvě písmena jazyka. pyright je ten druhý běžný.",
  ["Four letters: the one after this one. Rust's iterator method has the same name."] = "Čtyři písmena: ten po tomhle. Iterátorová metoda v Rustu má stejné jméno.",
  ["Four letters: to clean up. The error message itself tells you the command."] = "Čtyři písmena: uklidit. Chybová hláška sama ti ten příkaz říká.",
  ["Four letters: what the threads finally are, and what the build is called."] = "Čtyři písmena: čím vlákna konečně jsou a jak se to sestavení jmenuje.",
  ["Four quests: BASIC, ADVANCED, DELIVERY, CODE RUSH. Q switches."] = "Čtyři mise: ZÁKLADY, POKROČILÉ, ROZVOZ, CODE RUSH. Q přepíná.",
  ["Four recursive calls, each O(1) plus its own flood: every cell is sunk once, so the whole grid is O(rows * cols)."] = "Čtyři rekurzivní volání, každé O(1) plus vlastní záplava: každá buňka se potopí jednou, takže celá mřížka je O(rows * cols).",
  ["Four workers, many eggs, no hand-made threads. Which executor from concurrent.futures?"] = "Čtyři workeři, hodně vajec, žádná ručně dělaná vlákna. Který executor z concurrent.futures?",
  ["Fprintf writes to any io.Writer: files, buffers, network, ResponseWriter."] = "Fprintf píše do jakéhokoli io.Writer: soubory, buffery, síť, ResponseWriter.",
  ["Free the tray right now, before the end of the block. Which function?"] = "Uvolni tác hned teď, před koncem bloku. Která funkce?",
  ["From a str. Two words with an underscore, like the FromStr trait in lowercase."] = "Ze str. Dvě slova s podtržítkem, jako trait FromStr malými písmeny.",
  ["From m to the end. a[:m] and a[m:] cover the slice exactly once."] = "Od m do konce. a[:m] a a[m:] pokryjí slice přesně jednou.",
  ["Functions and Option"] = "Funkce a Option",
  ["Functions and returns"] = "Funkce a návratové hodnoty",
  ["Futures need a runtime. Which attribute makes main async on tokio?"] = "Futures potřebují runtime. Který atribut udělá main async na tokiu?",
  ["GO SET  -  the walk"] = "GO SET  -  procházka",
  ["GO plus the word for not public, all capitals. A comma-separated list of path globs."] = "GO plus slovo pro neveřejné, vše velkými. Čárkami oddělený seznam vzorů cest.",
  ["GO, then the three letters of the file, all capitals. It walks up from the current directory."] = "GO a pak tři písmena souboru, vše velkými. Prochází nahoru od aktuálního adresáře.",
  ["GOMAXPROCS(0) reports without changing it. Thousands of goroutines still exist; only this many are running Go code at any instant."] = "GOMAXPROCS(0) jen hlásí, nic nemění. Goroutin můžou být tisíce; jen tolik jich v daném okamžiku běží v Go kódu.",
  ["GOPATH still exists as the download cache ($GOPATH/pkg/mod) and the go install bin dir, but your code lives wherever you like."] = "GOPATH pořád existuje jako cache stažených modulů ($GOPATH/pkg/mod) a bin adresář pro go install, ale tvůj kód bydlí, kde chceš.",
  ["GOPRIVATE sets GONOPROXY and GONOSUMDB together: those modules skip the proxy and the checksum database, and their hashes go only in your go.sum."] = "GOPRIVATE nastaví GONOPROXY a GONOSUMDB najednou: ty moduly přeskočí proxy i databázi kontrolních součtů a jejich hashe jdou jen do tvého go.sum.",
  ["GOPROXY, GOPRIVATE, ssh"] = "GOPROXY, GOPRIVATE, ssh",
  ["Generators and iterators"] = "Generátory a iterátory",
  ["Generics and trait bounds"] = "Generika a omezení traity",
  ["Generics, embedding, closures"] = "Generika, embedding, closures",
  ["Generics. Say <T> and tell the compiler what T can do."] = "Generika. Napiš <T> a řekni kompilátoru, co T umí.",
  ["Get the guard so you can change the counter. Which method?"] = "Získej guard, abys mohl změnit čítač. Která metoda?",
  ["Get, Put and evict all O(1): that is the whole point of the LRU question."] = "Get, Put i vyhození všechny O(1): to je celá pointa otázky na LRU.",
  ["Get: a hit becomes the most recently used. Which list method moves the node to the front?"] = "Get: zásah se stane naposled použitým. Která metoda seznamu přesune uzel dopředu?",
  ["Give me a pipe. Send on one end, I receive on the other."] = "Dej mi trubku. Pošli na jednom konci, já přijmu na druhém.",
  ["Give the ETA call two seconds and no more. Which constructor?"] = "Dej volání ETA dvě vteřiny a ani o chlup víc. Který konstruktor?",
  ["Give the error a human message for {}. Which fmt trait?"] = "Dej chybě lidskou zprávu pro {}. Který trait z fmt?",
  ["Give the future room for one result so a lost caller cannot strand the goroutine."] = "Dej future místo na jeden výsledek, aby ztracený volající neuvěznil goroutinu.",
  ["Give the opened file a name inside the block. Which keyword?"] = "Dát otevřenému souboru jméno uvnitř bloku. Které klíčové slovo?",
  ["Give up after one second. Fill: case <-time.___(time.Second)"] = "Vzdej to po jedné sekundě. Doplň: case <-time.___(time.Second)",
  ["Gives index and value. The blank _ throws the index away."] = "Dává index a hodnotu. Prázdný _ index zahodí.",
  ["Global Interpreter Lock, by its initials."] = "Global Interpreter Lock, podle iniciál.",
  ["Global Interpreter Lock, said as one word."] = "Global Interpreter Lock, řečeno jedním slovem.",
  ["Go + routine. Not a full OS thread. The scheduler parks them."] = "Go + routine. Ne plné vlákno OS. Plánovač je uspává.",
  ["Go 1.21 has a builtin for the smaller of two numbers."] = "Go 1.21 má builtin pro menší ze dvou čísel.",
  ["Go 1.21 wraps that pattern and caches the result. Which sync helper?"] = "Go 1.21 ten vzorec zabalí a výsledek si i uloží. Který pomocník ze sync?",
  ["Go 1.21-1.23: slices, maps, min, iterators"] = "Go 1.21-1.23: slices, maps, min, iterátory",
  ["Go 1.22 loops over a plain number. Fill: for i := ___ 3"] = "Go 1.22 iteruje přes obyčejné číslo. Doplň: for i := ___ 3",
  ["Go finds the nearest go.mod above you. A second go.mod in a subdirectory starts a different module, which is almost never what you meant."] = "Go najde nejbližší go.mod nad tebou. Druhý go.mod v podadresáři zakládá jiný modul, což skoro nikdy není to, co jsi chtěl.",
  ["Go had goroutines. Where is the go keyword?"] = "Go mělo goroutiny. Kde je klíčové slovo go?",
  ["Go has no async and no await, on purpose. A goroutine plus a buffered channel is a future: go starts it, <-ch awaits it. The runtime parks a goroutine that blocks on I/O and runs another on the same OS thread, so ordinary blocking code is already asynchronous. errgroup runs a batch and returns the first error; runtime.NumGoroutine() shows the ones you forgot to stop."] = "Go nemá async ani await, a je to schválně. Goroutina plus kanál s bufferem je future: go ho spustí, <-ch na něj počká. Runtime odstaví goroutinu zablokovanou na I/O a na stejném vlákně spustí jinou, takže obyčejný blokující kód je už teď asynchronní. errgroup spustí dávku a vrátí první chybu; runtime.NumGoroutine() ukáže ty, které jsi zapomněl zastavit.",
  ["Go has no set type; a map to this type is the idiom. struct{} also works."] = "Go nemá typ množiny; idiomem je mapa na tento typ. struct{} funguje také.",
  ["Go has no while. Which keyword loops while i < 8?"] = "Go nemá while. Které klíčové slovo cyklí, dokud i < 8?",
  ["Go has one loop: for. if needs no parentheses. range walks a slice."] = "Go má jeden cyklus: for. if nepotřebuje závorky. range projde slice.",
  ["Go has structs and methods. Here the method gets self by hand?"] = "Go má struct a metody. Tady metoda dostává self ručně?",
  ["Go never converts numbers silently. Type name, then parentheses. 64-bit float."] = "Go nikdy nepřevádí čísla potichu. Název typu a pak závorky. 64bitový float.",
  ["Go never leaves a variable uninitialized. Numbers start here."] = "Go nikdy nenechá proměnnou neinicializovanou. Čísla začínají tady.",
  ["Go returns errors. Python throws them. Catch the one you expect, let the rest fly."] = "Go chyby vrací. Python je vyhazuje. Zachyť tu, kterou čekáš, ostatní nech letět.",
  ["Go spells every loop for; Python has this second word for the condition-only loop."] = "Go píše každý cyklus jako for; Python má pro cyklus jen s podmínkou toto druhé slovo.",
  ["Go, Chef! Same seven rounds as this afternoon. The memo one is a one-liner in Python."] = "Do toho, šéfe! Stejných sedm kol jako odpoledne. To s memem je v Pythonu na jeden řádek.",
  ["Go, Mei! I did this show at lunch. The memo one gets everybody."] = "Do toho, Mei! Já tuhle show dělal v poledne. Na tom s memem se chytne každý.",
  ["Goroutines"] = "Goroutiny",
  ["Goroutines, then. What is the Python word?"] = "Tak goroutiny. Jak se to řekne v Pythonu?",
  ["Graphs: BFS and DFS"] = "Grafy: BFS a DFS",
  ["Greater than or equal. With > alone, g[g.len()] would panic."] = "Větší nebo rovno. Se samotným > by g[g.len()] spanikařilo.",
  ["Greedy fails on coins {1,3,4} for 6 (4+1+1). DP tries every last coin and finds 3+3."] = "Hladový přístup selže na mincích {1,3,4} pro 6 (4+1+1). DP zkusí každou poslední minci a najde 3+3.",
  ["Grill and Wok are different sizes. What element type lets one Vec hold both?"] = "Grill a Wok mají různou velikost. Který typ prvku nechá jeden Vec držet oba?",
  ["Grill promises to be a Cook. Complete the header."] = "Grill slibuje, že je Cook. Doplň hlavičku.",
  ["Grill, wok, steamer. Every station must answer name() and greet()."] = "Gril, wok, pařák. Každá stanice musí odpovědět na name() a greet().",
  ["Group an item name and a quantity under one named type. Which keyword?"] = "Seskup název položky a množství pod jeden pojmenovaný typ. Které klíčové slovo?",
  ["Group name and price in one type. Which keyword?"] = "Seskup jméno a cenu do jednoho typu. Které klíčové slovo?",
  ["Grow a slice by one hash brown. Which built-in?"] = "Zvětši slice o jeden hash brown. Která vestavěná funkce?",
  ["HERE"] = "TADY",
  ["HIDE"] = "SKRÝT",
  ["HINT"] = "TIP",
  ["Half-open [lo, hi): loop while lo < hi, no off-by-one."] = "Polootevřený [lo, hi): smyčka dokud lo < hi, žádná chyba o jedničku.",
  ["Halve the gap. (lo+hi)/2 can overflow in other languages; this form never does."] = "Rozpůl mezeru. (lo+hi)/2 může v jiných jazycích přetéct; tento tvar nikdy.",
  ["Halve, halve, halve, then zip the halves back together. Ties go left."] = "Půl, půl, půl, a pak půlky zase sešij dohromady. Při shodě jde vlevo.",
  ["Halving gives log n levels. Integer division: 5 / 2 is 2, and that is fine."] = "Půlení dá log n úrovní. Celočíselné dělení: 5 / 2 je 2, a to je v pořádku.",
  ["Hand both values back to the caller. Which keyword?"] = "Vrať obě hodnoty volajícímu. Které klíčové slovo?",
  ["Hand out one bowl at a time and pause. Which keyword makes a function a generator?"] = "Vydat jednu misku a pozastavit se. Které klíčové slovo dělá z funkce generátor?",
  ["Hand the total back to the caller. Which keyword?"] = "Vrátit součet volajícímu. Které klíčové slovo?",
  ["Hand the value to one owner over a channel and there is nothing to lock. The order belongs to whoever received it."] = "Předej hodnotu přes kanál jedinému vlastníkovi a není co zamykat. Objednávka patří tomu, kdo ji dostal.",
  ["Handle + Func. Plain Handle takes an http.Handler value instead."] = "Handle + Func. Samotné Handle bere místo toho hodnotu http.Handler.",
  ["HandleFunc maps a path to func(w, r). Fprintf(w) replies. ListenAndServe runs."] = "HandleFunc mapuje cestu na func(w, r). Fprintf(w) odpoví. ListenAndServe běží.",
  ['HandleFunc registers on the default mux. Go 1.22 routes can say "GET /order/{id}".'] = 'HandleFunc registruje na výchozím muxu. Cesty v Go 1.22 umí "GET /order/{id}".',
  ["Hash brown on one burner. Muffin on another. Both at once."] = "Hash brown na jednom hořáku. Muffin na druhém. Obojí naráz.",
  ["Hash maps, chars and counts"] = "Hash mapy, znaky a počty",
  ["HashMap: O(1) average, O(n) worst case when everything collides. BTreeMap is O(log n) but ordered."] = "HashMap: O(1) v průměru, O(n) v nejhorším, když všechno koliduje. BTreeMap je O(log n), ale uspořádaná.",
  ["HashMap<u32, Vec<u32>>: O(1) to find a station, then its neighbours in order. g[&n] panics on a missing key; get returns Option."] = "HashMap<u32, Vec<u32>>: O(1) na nalezení stanice, pak její sousedé v pořadí. g[&n] panikaří na chybějícím klíči; get vrací Option.",
  ["HashSet: one O(1) insert per guest, O(n) total. Fifty million checks become ten thousand."] = "HashSet: jeden insert O(1) na hosta, celkem O(n). Z padesáti milionů kontrol je deset tisíc.",
  ["Have we seen the partner of x? Fill the lookup: seen[target-x]"] = "Viděli jsme partnera x? Doplň vyhledání: seen[target-x]",
  ["Height is one plus the taller child. Which built-in picks the taller?"] = "Výška je jedna plus vyšší dítě. Která vestavěná funkce vybere vyšší?",
  ["Height is one plus the taller subtree. Fill: 1 + max(height(n.Left), height(n.___))"] = "Výška je jedna plus vyšší podstrom. Doplň: 1 + max(height(n.Left), height(n.___))",
  ["Hello, Python"] = "Ahoj, Pythone",
  ["Hello, Rust"] = "Ahoj, Ruste",
  ["Hints document types without enforcing them: def f(x: int) -> str. list[str], dict[str, float], Optional[str]. mypy checks them before you run."] = "Nápovědy dokumentují typy, aniž by je vynucovaly: def f(x: int) -> str. list[str], dict[str, float], Optional[str]. mypy je zkontroluje před spuštěním.",
  ["How big a batch each worker collects per trip. One word, no underscore."] = "Jak velkou dávku si worker vezme na jednu cestu. Jedno slovo, bez podtržítka.",
  ["How many goroutines may run Go code at the same instant? Which setting?"] = "Kolik goroutin může běžet v Go kódu v jednom okamžiku? Které nastavení?",
  ["How many items are in prices? Which method returns a usize?"] = "Kolik položek je v prices? Která metoda vrací usize?",
  ["How many items are in the slice right now? Which built-in?"] = "Kolik položek je teď ve slice? Která vestavěná funkce?",
  ["How many items fit before append must reallocate? Which built-in?"] = "Kolik položek se vejde, než append musí realokovat? Která vestavěná funkce?",
  ["How many trays? Which built-in counts a list?"] = "Kolik táců? Která vestavěná funkce spočítá seznam?",
  ["How many workers? Ask the machine. Which function?"] = "Kolik workerů? Zeptej se stroje. Která funkce?",
  ["How much room does the belt have in total? Which builtin?"] = "Kolik místa má pás celkem? Která vestavěná funkce?",
  ["I copied the threading code, changed one word, and the script started itself forever."] = "Zkopíroval jsem kód z threading, změnil jedno slovo a skript se začal donekonečna spouštět sám.",
  ["I do not want to tag a release every time I change a line. Point it at my folder."] = "Nechci tagovat vydání pokaždé, když změním řádek. Nasměruj to na mou složku.",
  ["I gave the photo job eight threads. The fan spun up and the clock did not move."] = "Dal jsem té fotkové úloze osm vláken. Ventilátor se rozjel a hodiny se nehnuly.",
  ["I made the repo private and go get says 404, even though I can clone it fine."] = "Udělal jsem repozitář soukromý a go get říká 404, i když ho v pohodě naklonuju.",
  ["If dp[amount] never dropped below the marker, no combination works. What does the function return then?"] = "Pokud dp[amount] nikdy neklesla pod značku, žádná kombinace nefunguje. Co funkce tehdy vrátí?",
  ["If no combination reaches the amount, its cell still holds the sentinel. Return what?"] = "Když částky nedosáhne žádná kombinace, její buňka pořád drží strážní hodnotu. Co vrátit?",
  ["If the amount is still infinite, no coins reach it. What does the function return then?"] = "Pokud je částka stále nekonečná, žádné mince k ní nedosáhnou. Co pak funkce vrátí?",
  ["If the guest leaves, cancel. The fryer stops."] = "Když host odejde, zruš. Fritéza se zastaví.",
  ["If there is a loop the fast runner laps the slow one. O(1) memory."] = "Pokud je tam smyčka, rychlý běžec dohoní pomalého o kolo. Paměť O(1).",
  ["If you miss the word, write it yourself. Fill the body of Await."] = "Jestli ti to slovo chybí, napiš si ho sám. Doplň tělo metody Await.",
  ["Import from GitHub"] = "Import z GitHubu",
  ["Import the package from main.go. Write the whole path."] = "Importuj balíček z main.go. Napiš celou cestu.",
  ["In Go I would write a json tag. Show me the Rust way."] = "V Go bych napsal json tag. Ukaž mi, jak se to dělá v Rustu.",
  ["In Go this was three pointers. In Rust, who owns the next node?"] = "V Go to byly tři ukazatele. V Rustu, kdo vlastní další uzel?",
  ["In JavaScript I would write await fetchMenu(). Go's editor does not even know the word."] = "V JavaScriptu bych napsal await fetchMenu(). Editor pro Go to slovo ani nezná.",
  ["In Rust the compiler stops you. In Go nothing stops you, so the race detector is the compiler you run at test time."] = "V Rustu tě zastaví překladač. V Go tě nezastaví nic, takže detektor souběhů je ten překladač, který pouštíš při testech.",
  ["In Rust, if gives back a value. No ternary needed. The gate forgot its else."] = "V Rustu if vrací hodnotu. Ternární operátor není třeba. Brána zapomněla na else.",
  ["In a {start, end} pair, the end is the second element."] = "V páru {start, end} je konec druhý prvek.",
  ["In order, smallest to largest. The line above the search does it."] = "V pořadí, od nejmenšího k největšímu. Řádek nad vyhledáváním to udělá.",
  ["In real code None is more honest. key in self.d is O(1): a hash lookup."] = "V reálném kódu je None poctivější. key in self.d je O(1): vyhledání hashem.",
  ["In real code: sort a slice of structs by price. Fill: sort.___(orders, func(i, j int) bool {...})"] = "V reálném kódu: seřaď slice structů podle ceny. Doplň: sort.___(orders, func(i, j int) bool {...})",
  ["In-order on a BST yields sorted output. Pre-order (self first) copies a tree; post-order (self last) frees one."] = "In-order na BST dává seřazený výstup. Pre-order (nejdřív sám sebe) kopíruje strom; post-order (sám sebe naposled) ho uvolňuje.",
  ["In-order on a BST yields sorted output. Pre-order: node first. Post-order: node last."] = "In-order na BST dává seřazený výstup. Pre-order: uzel první. Post-order: uzel poslední.",
  ["In-order walk: left subtree, this node, then which subtree? That gives sorted output."] = "Průchod in-order: levý podstrom, tenhle uzel, a pak který podstrom? To dá seřazený výstup.",
  ["Inclusive count from l to r: the difference, plus one."] = "Počet od l do r včetně: rozdíl plus jedna.",
  ["Increment a counter without a mutex. Which package? ___.AddInt64(&count, 1)"] = "Zvyš čítač bez mutexu. Který balíček? ___.AddInt64(&count, 1)",
  ["Indexes start at 0, so the last one is one less than the count. len itself is O(1): Go keeps it in the slice header."] = "Indexy začínají od 0, takže poslední je o jedna méně než počet. Samotné len je O(1): Go ho drží v hlavičce slice.",
  ["Indexes start at 0, so the last one is the length less one. One character."] = "Indexy začínají od 0, takže poslední je délka mínus jedna. Jeden znak.",
  ["Insert at the recent end and get the new node back."] = "Vlož na čerstvý konec a dostaň zpět nový uzel.",
  ["Inside Lucky Mac Express the kitchen runs on Rust threads. Earn the tea set."] = "Kuchyně v Lucky Mac Express běží na rustových vláknech. Vybojuj si čajové menu.",
  ["Inside Lucky Mac the kitchen runs on goroutines. Earn the morning set."] = "Kuchyně v Lucky Macu běží na goroutinách. Vybojuj si snídaňové menu.",
  ["Inside a workspace every listed module is built from disk, so a change in luckymac is seen by cousinshop on the next build. go.work is for your machine; do not commit it."] = "Uvnitř pracovního prostoru se každý uvedený modul staví z disku, takže změnu v luckymac uvidí cousinshop při dalším buildu. go.work je pro tvůj stroj; necommituj ho.",
  ["Is ErrCold anywhere in that chain? Fill: errors.___(err, ErrCold)"] = "Je ErrCold někde v tom řetězu? Doplň: errors.___(err, ErrCold)",
  ["Is a name in the Vec? Without a set you must look at each one. Which iterator adapter stops at the first match?"] = "Je jméno ve Vec? Bez množiny se musíš podívat na každé. Který adaptér iterátoru se zastaví na první shodě?",
  ["Is a name in the list? Python has a keyword for it, but on a list it scans. Which keyword?"] = "Je jméno v seznamu? Python na to má klíčové slovo, ale na seznamu prochází. Které klíčové slovo?",
  ["Is a name in the slice? Without a map you must look at each one. Which keyword walks the slice?"] = "Je jméno ve slice? Bez mapy se musíš podívat na každé. Které klíčové slovo prochází slice?",
  ['Is muffin on the list? Fill: slices.___(names, "muffin")'] = 'Je muffin na seznamu? Doplň: slices.___(names, "muffin")',
  ["Is the ETA Some and under 10 minutes, in one call, no unwrap? Which Option method?"] = "Je ETA Some a pod 10 minut, jedním voláním, bez unwrap? Která metoda Option?",
  ["It appended to its own copy. Nothing crosses a process boundary unless you send it."] = "Udělal append do vlastní kopie. Hranici procesu nepřekročí nic, co sám nepošleš.",
  ["It closes over n. Inner func, outer variable."] = "Uzavírá do sebe n. Vnitřní func, vnější proměnná.",
  ["It did not fall over. It just made the kitchen printer thrash. Give me a queue and a few workers."] = "Nespadlo to. Jen se z toho zbláznila kuchyňská tiskárna. Dej mi frontu a pár workerů.",
  ['It is an error, not a warning, so dead imports never pile up. goimports adds and removes them for you; _ "pkg" keeps one only for its init side effect.'] = 'Je to chyba, ne varování, takže mrtvé importy se nikdy nehromadí. goimports je za tebe přidává i odebírá; _ "pkg" nechává jeden jen kvůli vedlejšímu efektu init.',
  ["It is an operating-system semaphore under the hood, so it works across processes. Like a Queue, it must be created in the parent and passed down."] = "Uvnitř je to semafor operačního systému, takže funguje napříč procesy. Jako Queue musí vzniknout v rodiči a předat se dolů.",
  ["It returns the *Element the map needs. An existing key is an update plus a touch, not a second node."] = "Vrací *Element, který mapa potřebuje. Existující klíč je update plus dotek, ne druhý uzel.",
  ["It runs on your laptop. Make it build on the shop's machine."] = "Na tvém notebooku to běží. Ať se to sestaví i na počítači v obchodě.",
  ["It's DFS, Mei, same as the MTR round, but the neighbours are up, down, left, right. Mind the usize!"] = "Je to DFS, Mei, stejně jako kolo s MTR, ale sousedi jsou nahoře, dole, vlevo, vpravo. Pozor na usize!",
  ["It's fib in a hat, Chef. Then the coin one: fewest coins for the exact change."] = "Je to fib v přestrojení, šéfe. Pak ta s mincemi: nejméně mincí na přesné drobné.",
  ["It's fib with a table instead of a memo. Bottom up, Mei. No recursion, no stack overflow."] = "Je to fib s tabulkou místo mema. Odspoda nahoru, Mei. Žádná rekurze, žádné přetečení zásobníku.",
  ["It's the graph round in disguise, Bo. Sink every island as you find it, and count the finds."] = "Je to grafové kolo v přestrojení, Bo. Každý ostrov potop, jakmile ho najdeš, a počítej nálezy.",
  ["Iterator::eq compares two iterators without building a String. chars() walks Unicode scalars, not bytes."] = "Iterator::eq porovná dva iterátory, aniž by stavěl String. chars() prochází skaláry Unicode, ne bajty.",
  ["Iterators and closures"] = "Iterátory a closures",
  ["JoinHandle<T>: T is what the closure returns, here (). Drop the handle and the thread is detached, still running."] = "JoinHandle<T>: T je to, co closure vrací, tady (). Zahoď handle a vlákno je odpojené, stále běží.",
  ["Jumps to the next iteration. break would leave the loop entirely."] = "Skočí na další iteraci. break by cyklus úplně opustil.",
  ["Just the size, no coefficient. 2n, 3n and n/2 are all the same order."] = "Jen velikost, bez koeficientu. 2n, 3n a n/2 jsou všechno stejný řád.",
  ["Just the size, no coefficient. 2n, 3n and n/2 are the same order."] = "Jen velikost, bez koeficientu. 2n, 3n a n/2 jsou stejný řád.",
  ["Just the sum. Adding a semicolon would turn it into a statement and return ()."] = "Jen součet. Středník by z něj udělal příkaz a vrátil ().",
  ["Kadane's algorithm: O(n), one pass, two variables. A negative prefix is never worth keeping."] = "Kadaneho algoritmus: O(n), jeden průchod, dvě proměnné. Záporný prefix se nikdy nevyplatí držet.",
  ["Kadane's algorithm: O(n), one pass, two variables. A negative run never helps, so it is dropped."] = "Kadaneho algoritmus: O(n), jeden průchod, dvě proměnné. Záporná série nikdy nepomůže, takže se zahodí.",
  ["Kadane's algorithm: a negative run is worth dropping. O(n) time, O(1) space, no nested loop."] = "Kadaneho algoritmus: zápornou řadu se vyplatí zahodit. O(n) času, O(1) paměti, žádný vnořený cyklus.",
  ["Kadane: at each x, extend the run or restart at x, keep the best. A fixed window adds the newcomer and drops a[i-k]. Two pointers only move right: O(n) for the longest substring without repeats."] = "Kadane: u každého x buď prodluž běh, nebo začni znovu u x, drž nejlepší. Pevné okno přidá nováčka a zahodí a[i-k]. Dva ukazatele se hýbou jen doprava: O(n) pro nejdelší podřetězec bez opakování.",
  ["Kadane: cur = max(x, cur + x), best = max(best, cur). A fixed window adds one and drops one. A growing window moves l forward until the window is clean again."] = "Kadane: cur = max(x, cur + x), best = max(best, cur). Pevné okno jeden přidá a jeden zahodí. Rostoucí okno posouvá l dopředu, dokud není okno zase čisté.",
  ["Kadane: cur = x.max(cur + x). A fixed window adds the new item and drops the old one. A growing window moves its left end while a HashSet says repeat. Two pointers walk in from both ends of a sorted slice."] = "Kadane: cur = x.max(cur + x). Pevné okno přidá nový prvek a odebere starý. Rostoucí okno posouvá levý konec, když HashSet hlásí opakování. Dva ukazatele jdou z obou konců seřazeného slice dovnitř.",
  ["Keep a AND give b its own copy of the text. Which method?"] = "Zachovej a A dej b vlastní kopii textu. Která metoda?",
  ["Keep a tiny heap of the k biggest. Whatever falls out was never the answer."] = "Drž malou haldu k největších. Co vypadne, nikdy nebylo odpovědí.",
  ["Keep only paid orders. Which adapter takes a bool closure?"] = "Nech jen zaplacené objednávky. Který adaptér bere closure vracející bool?",
  ["Keep only three, Chef. The smallest of the three is the answer; throw out anything smaller."] = "Nech si jen tři, šéfe. Nejmenší z těch tří je odpověď; cokoli menšího vyhoď.",
  ["Keep serving as long as the queue is not empty. Which keyword loops on a condition?"] = "Vydávat, dokud fronta není prázdná. Které klíčové slovo opakuje podle podmínky?",
  ["Keyword chan, then the element type. make allocates it."] = "Klíčové slovo chan, pak typ prvku. make ho alokuje.",
  ["Kitchen should gain Grill's methods without wrapping. Put Grill where?"] = "Kitchen má získat metody Grill bez obalování. Kam dát Grill?",
  ["Know the algorithm for the whiteboard, use the library in production."] = "Znej algoritmus na tabuli, v produkci použij knihovnu.",
  ["Kth largest: keep a min-heap of the k largest so far. When it grows past k, which heap call drops the smallest?"] = "K-tý největší: drž min-haldu k dosud největších. Když přeroste k, které volání haldy zahodí nejmenší?",
  ["LAND"] = "ŠÍŘKA",
  ["LEVEL UP!  LV %d"] = "NOVÝ LEVEL!  LV %d",
  ["LRU cache"] = "LRU cache",
  ["LRU: a HashMap for the values and a VecDeque for recency, fresh at the back, stale at the front. get moves the key to the back. put evicts the front when full, then inserts. The O(1) version swaps the VecDeque for a linked list."] = "LRU: HashMap na hodnoty a VecDeque na pořadí použití, čerstvé vzadu, staré vpředu. get přesune klíč dozadu. put při plné cache vyhodí předek a pak vloží. Verze v O(1) vymění VecDeque za spojový seznam.",
  ["LRU: a map from key to *list.Element plus a container/list in recency order. Get moves the node to the front, Put pushes a new one at the front, over capacity evicts l.Back() from both the list and the map. Every operation O(1)."] = "LRU: mapa z klíče na *list.Element plus container/list v pořadí podle čerstvosti. Get přesune uzel dopředu, Put nový vloží dopředu, nad kapacitu vyhodí l.Back() ze seznamu i z mapy. Každá operace O(1).",
  ["LRU: least recently used goes first. OrderedDict remembers order: move_to_end on every use, popitem(last=False) evicts the oldest. get and put are O(1). functools.lru_cache is the built-in."] = "LRU: nejdéle nepoužitý jde první. OrderedDict si pamatuje pořadí: move_to_end při každém použití, popitem(last=False) vyhodí nejstarší. get a put jsou O(1). functools.lru_cache je vestavěná.",
  ["LV %d   XP %d / %d"] = "LV %d   XP %d / %d",
  ["LV %d  ·  %d XP  ·  %d badges"] = "LV %d  ·  %d XP  ·  odznaků: %d",
  ["Last board of the night, Python column. Same question: input doubles, then what?"] = "Poslední tabule noci, sloupec Pythonu. Stejná otázka: vstup se zdvojnásobí, a co pak?",
  ["Last customers before the shutter. The queue script decides who gets a bowl."] = "Poslední zákazníci před roletou. Skript fronty rozhoduje, kdo dostane misku.",
  ["Last one. A map of Victoria Harbour as ones and zeros. How many islands?"] = "Poslední. Mapa Victoria Harbour jako jedničky a nuly. Kolik ostrovů?",
  ["Last ticket. Code review. Every match with one arm and an early return gets a modern spelling."] = "Poslední ticket. Code review. Každý match s jednou větví a brzkým return dostane moderní zápis.",
  ["Laying out a repo"] = "Jak rozvrhnout repozitář",
  ["Least recently used. A map for the values and a queue for the order; every get is a touch."] = "Nejdéle nepoužité. Mapa na hodnoty a fronta na pořadí; každý get je dotek.",
  ["Leave note out of the JSON when it is empty. Fill the tag option."] = "Když je note prázdné, vynech ho z JSON. Doplň volbu tagu.",
  ["Leave the function early when n is 0. Which keyword?"] = "Opusť funkci dřív, když je n 0. Které klíčové slovo?",
  ["Leave the note out of the JSON when it is None. Which attribute?"] = "Vynech note z JSONu, když je None. Který atribut?",
  ["Left, node, right: a BST walked in order comes out sorted. if let on &Link needs no unwrap."] = "Levý, uzel, pravý: BST projitý v tomhle pořadí vyjde seřazený. if let na &Link nepotřebuje unwrap.",
  ["Left, self, then which side, to print the values in sorted order?"] = "Vlevo, sám sebe, a pak která strana, aby se hodnoty vytiskly seřazené?",
  ["Left: the same row, one column back."] = "Doleva: stejný řádek, o sloupec zpátky.",
  ["Len, Less, Swap take a value; Push and Pop take a pointer because they resize the slice."] = "Len, Less, Swap berou hodnotu; Push a Pop berou ukazatel, protože mění velikost slice.",
  ["Less than or equal. With a strict < equal items would swap order and the sort would not be stable."] = "Menší nebo rovno. S ostrým < by si stejné položky prohodily pořadí a třídění by nebylo stabilní.",
  ["Less than or equal: the equal case is the touching pair."] = "Menší nebo rovno: případ rovnosti je dotýkající se dvojice.",
  ["Less than, or equal. A strict < would take the right one on a tie and break stability."] = "Menší, nebo rovno. Ostré < by při shodě vzalo to pravé a rozbilo stabilitu.",
  ["Let ? turn a ParseIntError into OrderError by itself. Which trait do you implement?"] = "Nech ? samo převést ParseIntError na OrderError. Který trait implementuješ?",
  ["Let count() read the String without taking it. Which symbol goes before the type?"] = "Nech count() číst String, aniž by si ho vzal. Který symbol patří před typ?",
  ["Let println! print the whole struct with {:?}. Which attribute word generates Debug?"] = "Nech println! vypsat celý struct přes {:?}. Které slovo v atributu generuje Debug?",
  ["Let serde write the JSON code for the struct. Which trait goes with Deserialize?"] = "Nech serde napsat JSON kód pro struct. Který trait patří k Deserialize?",
  ["Level by level with a deque: take from the front. Which method?"] = "Patro po patru s deque: brát zepředu. Která metoda?",
  ["Lifetimes"] = "Lifetimy",
  ["Like %v, but with w for wrap. errors.Unwrap gets the inner error back."] = "Jako %v, ale s w jako wrap. errors.Unwrap vrátí vnitřní error.",
  ["Like fmt.Errorf but on t. Fatalf would stop this test at once."] = "Jako fmt.Errorf, ale na t. Fatalf by tento test hned zastavil.",
  ["Like last(), with the suffix every mutable borrow in std carries."] = "Jako last(), s příponou, kterou nese každá měnitelná výpůjčka ve std.",
  ["Like unwrap, but with your own panic message. Which method?"] = "Jako unwrap, ale s vlastní zprávou pro panic. Která metoda?",
  ["Linear time"] = "Lineární čas",
  ["Linear: the work grows in step with the input. A one-word built-in is still a loop underneath."] = "Lineární: práce roste krok za krokem se vstupem. Jednoslovná vestavěná funkce je pod povrchem stále cyklus.",
  ["Linear: the work grows in step with the input. Iterator chains hide the loop but not the cost."] = "Lineární: práce roste krok za krokem se vstupem. Řetězce iterátorů skrývají cyklus, ale ne cenu.",
  ["Linear: the work grows in step with the input. Write it with a capital O and the size in brackets."] = "Lineární: práce roste krok za krokem se vstupem. Zapiš to s velkým O a velikostí v závorkách.",
  ["Linked list without pointers"] = "Spojový seznam bez ukazatelů",
  ["Linked list: reverse, cycle"] = "Zřetězený seznam: otočení, cyklus",
  ["Linked lists"] = "Spojové seznamy",
  ["Listen, And, Serve. Returns only on error, hence log.Fatal."] = "Listen, And, Serve. Vrací se jen při chybě, proto log.Fatal.",
  ["ListenAndServe blocks forever. Every request runs in its own goroutine."] = "ListenAndServe blokuje navždy. Každý požadavek běží ve vlastní goroutine.",
  ["Lists and slices"] = "Seznamy a řezy",
  ["Load and Store are the read and write. Reading the field directly is a data race even for one int."] = "Load a Store jsou čtení a zápis. Číst to pole přímo je datový souběh, i kdyby šlo o jediný int.",
  ["Lock a shared counter. Fill the type: var mu sync.___"] = "Zamkni sdílený čítač. Doplň typ: var mu sync.___",
  ["Lock then defer Unlock, on the next line, always. A lock released only on the happy path is a deadlock waiting for the first error."] = "Lock a hned na dalším řádku defer Unlock, vždycky. Zámek uvolněný jen na šťastné cestě je deadlock čekající na první chybu.",
  ["Lock; defer Unlock is the pattern. A forgotten Unlock deadlocks the next caller."] = "Lock; defer Unlock je ten vzor. Zapomenutý Unlock zablokuje dalšího volajícího.",
  ["Locks, Value and Manager"] = "Zámky, Value a Manager",
  ["Log each total the moment it lands, in any order. Which helper?"] = "Zaznamenej každý součet, jakmile dorazí, v libovolném pořadí. Který pomocník?",
  ["Logarithmic time"] = "Logaritmický čas",
  ["Logarithmic: O of the logarithm of n. The base does not matter in Big O."] = "Logaritmický: O logaritmu n. Základ v Big O nehraje roli.",
  ["Long bounds go under the signature. Which keyword starts that clause?"] = "Dlouhá omezení jdou pod signaturu. Které klíčové slovo tu klauzuli začíná?",
  ["Longest run of distinct bytes: a window [l, r] and a HashSet of what is inside. When b[r] is already in, drop from the left until it is not. Which HashSet method removes?"] = "Nejdelší řada různých bajtů: okno [l, r] a HashSet toho, co je uvnitř. Když b[r] už uvnitř je, ubírej zleva, dokud není. Která metoda HashSet odebírá?",
  ["Longest run with no repeated dish. When c is already in the window, drop from the left until it is not. Which set method?"] = "Nejdelší série bez opakovaného jídla. Když c už v okně je, odebírej zleva, dokud tam není. Která metoda setu?",
  ["Longest substring without a repeat: remember where each char was last seen. What is stored under last[c]?"] = "Nejdelší podřetězec bez opakování: pamatuj si, kde byl každý znak naposled. Co je uloženo pod last[c]?",
  ["Look at the load: one core at 100, seven asleep. That is not a threading bug, that is the design."] = "Podívej se na zátěž: jedno jádro na 100 a sedm spí. To není chyba vláken, to je návrh.",
  ["Look the answer up before computing. Fill the comma-ok test: if v, ok := memo[n]; ___"] = "Podívat se na odpověď, než se počítá. Doplň test comma-ok: if v, ok := memo[n]; ___",
  ["Look the answer up before computing. Which HashMap method?"] = "Podívat se na odpověď, než se počítá. Která metoda HashMap?",
  ["Looks like switch, but every case is a channel send or receive."] = "Vypadá jako switch, ale každý case je odeslání nebo příjem z kanálu.",
  ["Lowercase, three letters, and a bang because it is a macro."] = "Malá písmena, tři, a vykřičník, protože je to makro.",
  ["Lucky Mac  ·  Causeway Bay"] = "Lucky Mac  ·  Causeway Bay",
  ["Lucky Mac  ·  delivery app"] = "Lucky Mac  ·  rozvozová aplikace",
  ["Lucky Mac  ·  the back office"] = "Lucky Mac  ·  zadní kancelář",
  ["Lucky Mac  ·  the morning set"] = "Lucky Mac  ·  ranní menu",
  ["Lucky Mac  ·  the night shift"] = "Lucky Mac  ·  noční směna",
  ["Lucky Mac Express  ·  Rust backend"] = "Lucky Mac Express  ·  backend v Rustu",
  ["Lucky Mac Express  ·  Times Square"] = "Lucky Mac Express  ·  Times Square",
  ["Lucky Mac Express  ·  the tea set"] = "Lucky Mac Express  ·  svačina",
  ["Lucky Mac is found. Leave the loop right now. Which keyword?"] = "Lucky Mac je nalezen. Opusť cyklus hned teď. Které klíčové slovo?",
  ["Lucky Mac queue"] = "Fronta u Lucky Mac",
  ["Lucky Mac, table 4"] = "Lucky Mac, stůl 4",
  ["MAP"] = "MAPA",
  ["MODULES  -  the repo"] = "MODULES  -  repozitář",
  ["MODULES  ·  the repo"] = "MODULES  ·  repozitář",
  ["MTR exit A, the underpass"] = "Výstup A z MTR, podchod",
  ["Main waits until all nine orders are marked done, then prints the receipt. Which queue method?"] = "Hlavní vlákno čeká, dokud není všech devět objednávek označeno jako hotové, pak tiskne účtenku. Která metoda fronty?",
  ["Make a context you can stop by hand. Which constructor?"] = "Vyrob context, který umíš zastavit ručně. Který konstruktor?",
  ["Make a pipe with a sending end and a receiving end. Which function?"] = "Vytvoř trubku s odesílacím a přijímacím koncem. Která funkce?",
  ["Make an enum, impl Display and Error, impl From so ? converts. Box<dyn Error> catches the rest."] = "Udělej enum, impl Display a Error, impl From, aby ? převádělo. Box<dyn Error> chytí zbytek.",
  ["Make an owned String out of a string literal. Which constructor?"] = "Udělej z řetězcového literálu vlastněný String. Který konstruktor?",
  ["Make that copy without sorting: a new list with the same items. Which built-in, called on a?"] = "Udělat tu kopii bez třídění: nový seznam se stejnými položkami. Která vestavěná funkce, zavolaná na a?",
  ["Make that copy: a new owned Vec with the same contents. Which method?"] = "Udělat tu kopii: nový vlastněný Vec se stejným obsahem. Která metoda?",
  ["Make the Safe class usable with 'with'. Which method runs on the way in?"] = "Udělat třídu Safe použitelnou s 'with'. Která metoda běží na cestě dovnitř?",
  ["Make the menu rangeable. Fill the return type: iter.___[string]"] = "Udělej menu procházitelné přes range. Doplň návratový typ: iter.___[string]",
  ["Make the write visible to the other goroutine. Which builtin call ends the wait?"] = "Zpřístupni ten zápis druhé goroutině. Které vestavěné volání ukončí čekání?",
  ["Many of the thing an operating system schedules. Fifteen letters, one word."] = "Množné číslo toho, co plánuje operační systém. Patnáct písmen, jedno slovo.",
  ["Many readers at once, one writer. Fill the read lock: mu.___()"] = "Mnoho čtenářů naráz, jeden zapisovatel. Doplň zámek pro čtení: mu.___()",
  ["Map keys must support ==. Fill the constraint: func Has[K ___](m map[K]bool, k K)"] = "Klíče map musí podporovat ==. Doplň omezení: func Has[K ___](m map[K]bool, k K)",
  ["Maps"] = "Mapy",
  ["Mark a function so calling it returns a Future instead of running. Which keyword?"] = "Označ funkci tak, aby její zavolání vrátilo Future místo běhu. Které klíčové slovo?",
  ["Mark on enqueue, not on dequeue, or a station can be queued twice from two neighbours."] = "Označuj při zařazení, ne při vyjmutí, jinak může být stanice zařazena dvakrát ze dvou sousedů.",
  ["Mark the cell visited by sinking it. What is written into the grid?"] = "Označ buňku za navštívenou tím, že ji potopíš. Co se zapíše do mřížky?",
  ["Mark the cell visited by turning it into water. Fill the value."] = "Označ buňku jako navštívenou tím, že ji proměníš ve vodu. Doplň hodnotu.",
  ["Marking in place is the visited set: O(1) extra space. Interviewers may ask you not to mutate; then use a HashSet<(usize, usize)>."] = "Značení na místě je množina navštívených: O(1) paměti navíc. Tazatel může chtít, abys nemutovala; pak použij HashSet<(usize, usize)>.",
  ["Marshal returns []byte and an error. Never ignore the error."] = "Marshal vrací []byte a error. Error nikdy neignoruj.",
  ["Max subarray sum: at each x, either extend the current run or start fresh. Fill the fresh start."] = "Max součet podpole: u každého x buď prodluž aktuální běh, nebo začni znovu. Doplň nový začátek.",
  ["Max subarray: extend the current run with x, or restart at x alone. Fill the second choice."] = "Max subarray: prodluž současnou sérii o x, nebo začni znovu jen s x. Doplň druhou možnost.",
  ["Maybe a String, maybe nothing. Which return type?"] = "Možná String, možná nic. Který návratový typ?",
  ["Meeting rooms: sort starts and ends separately. A start reuses a room when the earliest end is already over. Fill the test."] = "Zasedačky: seřaď začátky a konce zvlášť. Začátek znovu použije místnost, když nejdřívější konec už skončil. Doplň test.",
  ["Mei"] = "Mei",
  ["Memoization: check the map before computing. fib(90) becomes instant."] = "Memoizace: před výpočtem se podívej do mapy. fib(90) je rázem okamžité.",
  ["Memoized recursion is DP from the top. Same O(n), but the call stack is n deep: RecursionError near 1000."] = "Memoizovaná rekurze je DP shora. Stejné O(n), ale zásobník volání je n hluboký: RecursionError kolem 1000.",
  ["Merge intervals"] = "Slučování intervalů",
  ["Merge intervals, meeting rooms"] = "Sloučení intervalů, zasedačky",
  ["Merge sort and binary search"] = "Merge sort a binární vyhledávání",
  ["Merge sort has log n levels of splitting. Merging all the pieces on one level costs how much?"] = "Merge sort má log n úrovní dělení. Kolik stojí sloučení všech kusů na jedné úrovni?",
  ["Merge sort recurses on both halves. Fill: merge(mergeSort(a[:m]), mergeSort(a[___]))"] = "Merge sort rekurzivně zpracuje obě půlky. Doplň: merge(mergeSort(a[:m]), mergeSort(a[___]))",
  ["Merge sort splits in the middle. Which operator gives a whole-number midpoint?"] = "Merge sort dělí uprostřed. Který operátor dá celočíselný střed?",
  ["Merge sort: split at len // 2, sort both halves, merge with <=. sorted and list.sort take key=. bisect finds a slot in a sorted list in O(log n)."] = "Merge sort: rozděl na len // 2, seřaď obě půlky, sluč pomocí <=. sorted a list.sort berou key=. bisect najde místo v seřazeném seznamu v O(log n).",
  ["Merge sort: split_at(len / 2), sort both, merge with <= for stability. In practice: sort_by_key, sort_unstable, binary_search."] = "Merge sort: split_at(len / 2), seřaď obě půlky, slij s <= kvůli stabilitě. V praxi: sort_by_key, sort_unstable, binary_search.",
  ["Merge two sorted halves: take from the left while its item is no bigger. Which comparison keeps the sort stable?"] = "Sloučit dvě seřazené půlky: brát zleva, dokud její položka není větší. Které porovnání udrží třídění stabilní?",
  ["Merge two sorted halves: take the smaller head and advance that side. Fill: ___++"] = "Slij dvě seřazené půlky: vezmi menší čelo a posuň tu stranu. Doplň: ___++",
  ["Merging two sorted halves. On a tie take from the left, so equal items keep their order. Which comparison?"] = "Sléváš dvě seřazené půlky. Při shodě ber zleva, aby si stejné prvky udržely pořadí. Které porovnání?",
  ["Method calls bind tighter than +, so it is 1 + (left.max(right)). Round two clean. Combo x2."] = "Volání metod váže silněji než +, takže je to 1 + (left.max(right)). Druhé kolo čisté. Kombo x2.",
  ["Methods are written in a separate block. Which keyword opens it?"] = "Metody se píší v samostatném bloku. Které klíčové slovo ho otevírá?",
  ["Midnight edition of CODE RUSH! Python round. Chef Bo at the keyboard. Factorial, then fib. Buzzer's live!"] = "Půlnoční vydání CODE RUSH! Kolo Pythonu. Šéfkuchař Bo u klávesnice. Faktoriál, pak fib. Bzučák je živý!",
  ["Min of the k largest is the kth largest. Top-k frequent is the same loop over a count map."] = "Minimum z k největších je k-tý největší. Top-k nejčastějších je stejný cyklus nad mapou počtů.",
  ["Modern Rust idioms"] = "Moderní idiomy Rustu",
  ["Module error, trait of the same name with a capital. Every method has a default."] = "Modul error, trait stejného jména s velkým písmenem. Každá metoda má výchozí implementaci.",
  ["Module path plus directory equals import path. That is the whole rule, and it is why a module named after its repo just works from anywhere."] = "Cesta modulu plus adresář rovná se importní cesta. To je celé pravidlo a důvod, proč modul pojmenovaný podle repozitáře prostě funguje odkudkoli.",
  ["Module path plus directory is the import path. Fill the path of the menu package."] = "Cesta modulu plus adresář je importní cesta. Doplň cestu balíčku menu.",
  ["Modules and the go tool"] = "Moduly a nástroj go",
  ["More than k inside: the smallest cannot be the kth largest. Which function removes the root?"] = "Uvnitř je víc než k: nejmenší nemůže být k-tý největší. Která funkce odebere kořen?",
  ["More than k inside: the smallest, on top, has to go. Which method removes the top?"] = "Uvnitř je víc než k: nejmenší, na vrcholu, musí pryč. Která metoda odstraní vrchol?",
  ["Morning set. Don't show him your laptop bugs."] = "Ranní menu. Neukazuj mu bugy z notebooku.",
  ["Morning set. Lucky Mac. The kiosk on the door is stuck on a Go bug."] = "Ranní menu. Lucky Mac. Kiosek na dveřích se zasekl na bugu v Go.",
  ["Most tree questions are this shape: nil returns a base value, else combine both sides."] = "Většina otázek na stromy má tento tvar: nil vrátí základní hodnotu, jinak zkombinuj obě strany.",
  ["Move it to the recent end of the list, which is the front. One method, three words."] = "Přesuň ho na čerstvý konec seznamu, což je začátek. Jedna metoda, tři slova.",
  ["Move next out, flip the arrow, push node onto prev. No take() needed: while let moved cur into node. prev is the new head."] = "Přesuň next ven, otoč šipku, posaď uzel na prev. take() není potřeba: while let přesunul cur do node. prev je nová hlava.",
  ["Muffin ready, or hash brown, or timeout. Pick one."] = "Muffin hotový, nebo hash brown, nebo timeout. Vyber jedno.",
  ["Multiply 100 by 99, then halve it."] = "Vynásob 100 krát 99, pak to vyděl dvěma.",
  ["Must start with Test and take *testing.T. File name ends with _test.go."] = "Musí začínat Test a brát *testing.T. Název souboru končí _test.go.",
  ["Mutating the grid is the O(1) extra-space visited set. Copy it first if the caller needs it back."] = "Změna mřížky je množina navštívených s O(1) paměti navíc. Když ji volající potřebuje zpět, nejdřív ji zkopíruj.",
  ["Mutating the input saves a visited set. If the caller needs the grid back, copy it first."] = "Změna vstupu ušetří množinu navštívených. Pokud volající potřebuje mřížku zpět, nejdřív ji zkopíruj.",
  ["Mutex and WaitGroup"] = "Mutex a WaitGroup",
  ["Mutex locks shared memory. WaitGroup waits for a set of goroutines to finish."] = "Mutex zamyká sdílenou paměť. WaitGroup čeká, až skupina goroutin skončí.",
  ["Mutual exclusion, shortened to five letters. lock() gives a guard; the guard unlocks on drop."] = "Vzájemné vyloučení, zkrácené na pět písmen. lock() dá guard; guard se odemkne při dropu.",
  ["Mutual exclusion. Capital M. In package sync."] = "Vzájemné vyloučení. Velké M. V balíčku sync.",
  ["My cousin's shop wants your menu package. He typed the GitHub path into an import and it just downloaded."] = "Bratrancův obchod chce tvůj balíček menu. Napsal cestu z GitHubu do importu a prostě se to stáhlo.",
  ["My first version started one goroutine per order. Forty thousand orders, forty thousand goroutines."] = "První verze spouštěla jednu goroutinu na objednávku. Čtyřicet tisíc objednávek, čtyřicet tisíc goroutin.",
  ["NEXT"] = "DÁL",
  ["NEXT >"] = "DÁL >",
  ["NICE!"] = "PĚKNĚ!",
  ["NIGHT OWL"] = "NOČNÍ SOVA",
  ["NIGHT SHIFT  -  the kitchen"] = "NIGHT SHIFT  -  kuchyně",
  ["Name the module after the repo it will live in. Fill the path."] = "Pojmenuj modul podle repozitáře, ve kterém bude bydlet. Doplň cestu.",
  ["Named after a paperclip assistant from old office software. Six letters, double p."] = "Pojmenováno po sponkovém asistentovi ze starého kancelářského softwaru. Šest písmen, dvě p.",
  ["Named types, assertions, type switch"] = "Pojmenované typy, aserce, type switch",
  ["Negative indexes count from the end. Go would panic on this."] = "Záporné indexy počítají od konce. Go by na to spadlo s panic.",
  ["Negative indexing counts from the end; the last item is one back."] = "Záporné indexování počítá od konce; poslední prvek je jeden zpět.",
  ["Nested loops multiply their sizes. Two different letters, a star between them."] = "Vnořené cykly násobí své velikosti. Dvě různá písmena, mezi nimi hvězdička.",
  ["Newer Go has helpers for that. Lunch is on the house."] = "Novější Go na to má pomocníky. Oběd je na účet podniku.",
  ["Next of Next. The loop condition already checked fast.Next is not nil."] = "Next od Next. Podmínka smyčky už ověřila, že fast.Next není nil.",
  ["Night shift. Every station runs a Python script I wrote. Tonight none of them start."] = "Noční směna. Každé stanoviště jede na pythonovém skriptu, který jsem napsal já. Dnes v noci se nespustí ani jeden.",
  ["Nine letters, 'to count off'. Go gives you the index for free in range; Python asks you to wrap the list."] = 'Devět písmen, „vyjmenovat". Go ti dá index v range zdarma; Python chce, abys seznam zabalil.',
  ["Nine letters, a railway signal. Go builds the same thing from a buffered channel."] = "Devět písmen, železniční návěstidlo. Go stejnou věc postaví z kanálu s bufferem.",
  ["Nine letters. To number things one by one. zip() pairs two iterators instead."] = "Devět písmen. Očíslovat věci jednu po druhé. zip() místo toho spáruje dva iterátory.",
  ["Nine letters. go test -bench=. runs them."] = "Devět písmen. go test -bench=. je spustí.",
  ["No allocation, O(1): the node is relinked in place. Value is an any, so the type assertion unpacks the entry."] = "Žádná alokace, O(1): uzel se přepojí na místě. Value je any, takže typová aserce rozbalí entry.",
  ["No eggs left: stop the order with an error. Which keyword throws?"] = "Vajíčka došla: zastavit objednávku chybou. Které klíčové slovo vyhazuje?",
  ["No garbage collector, and it still knows when to free the tray?"] = "Žádný garbage collector, a stejně ví, kdy tác uvolnit?",
  ["No input reference to borrow from. Which lifetime does a literal string have?"] = "Žádná vstupní reference, ze které by se dalo půjčit. Který lifetime má řetězcový literál?",
  ["No nested loops. A window slides; the answer updates as it goes."] = "Žádné vnořené cykly. Okno se posouvá; odpověď se průběžně aktualizuje.",
  ["No nil in Rust. If a value may be missing, the type says Option."] = "V Rustu není nil. Když hodnota může chybět, typ říká Option.",
  ["No nil. Every failure is a value you must look at."] = "Žádný nil. Každé selhání je hodnota, na kterou se musíš podívat.",
  ["No note on the order yet. Which value means 'nothing here'?"] = 'Objednávka ještě nemá poznámku. Která hodnota znamená „tady nic není"?',
  ["No overlap, or out is still empty: the current interval starts a new block. Which Vec method appends it?"] = "Bez překryvu, nebo je out ještě prázdný: aktuální interval začíná nový blok. Která metoda Vec ho připojí?",
  ["No overlap: cur starts a new merged interval. Fill the builtin."] = "Žádný překryv: cur začíná nový sloučený interval. Doplň builtin.",
  ["No partner yet: remember this value and where it was. What is stored under seen[x]?"] = "Zatím bez partnera: zapamatovat si tuto hodnotu a kde byla. Co se uloží pod seen[x]?",
  ["Nobody told it to stop. Nothing in Go kills a goroutine from outside."] = "Nikdo jí neřekl, ať přestane. V Go nic nezabije goroutinu zvenčí.",
  ["Node contains Node. The compiler needs a fixed size, so the child lives on the heap behind which pointer?"] = "Node obsahuje Node. Kompilátor potřebuje pevnou velikost, takže potomek žije na haldě za kterým ukazatelem?",
  ["None is a value, not a null pointer. Read it with match or if let Some(s) = seat(t). The board lights up."] = "None je hodnota, ne nulový ukazatel. Čti ho přes match nebo if let Some(s) = seat(t). Tabule se rozsvítí.",
  ["None is the base case: put a fresh leaf there. The Some arms recurse. Match ergonomics let n be &mut Box<Node>."] = "None je bázový případ: dej tam nový list. Větve Some jdou rekurzí. Díky match ergonomics je n typu &mut Box<Node>.",
  ["None is the one value of NoneType. A function with no return gives None too."] = "None je jediná hodnota typu NoneType. Funkce bez return vrací také None.",
  ["None marks an empty subtree. Every tree function starts with: if node is None."] = "None označuje prázdný podstrom. Každá stromová funkce začíná: if node is None.",
  ["None on an empty out falls to the _ arm and pushes. The borrow ends with the match, so out.push is allowed there."] = "None na prázdném out spadne do větve _ a pushne. Výpůjčka končí s match, takže out.push je tam dovolený.",
  ["None terminates the list. Walk with while node: and stop when it is falsy."] = "None ukončuje seznam. Procházej pomocí while node: a zastav se, když je nepravdivý.",
  ["Not TODO (that is a placeholder). The empty, never-cancelled root."] = "Ne TODO (to je zástupka). Prázdný kořen, který se nikdy nezruší.",
  ["Not equal. The statement before ; runs first, and err lives only inside the if."] = "Nerovná se. Příkaz před ; běží první a err žije jen uvnitř if.",
  ["Not null, not None. Three letters. The only zero for interfaces with no type."] = "Ne null, ne None. Tři písmena. Jediná nula pro interface bez typu.",
  ["Not quite. Read the hint and try again. HINT again shows the answer."] = "Skoro. Přečti si tip a zkus to znovu. TIP podruhé ukáže odpověď.",
  ["Not struct. Variants, one of which carries the ParseIntError inside."] = "Ne struct. Varianty, z nichž jedna nese uvnitř ParseIntError.",
  ["Not the stack. The other one, the one the garbage collector sweeps."] = "Ne zásobník. Ta druhá část, kterou zametá garbage collector.",
  ["Nothing runs yet. Which method actually starts the thread?"] = "Zatím nic neběží. Která metoda vlákno skutečně spustí?",
  ["Nothing tells parse which type to build. Say i32 with the turbofish."] = "Nic parse neříká, který typ má postavit. Řekni i32 pomocí turbofish.",
  ["Now collect the number. Which method of the Future?"] = "Teď to číslo vyzvedni. Která metoda Future?",
  ["Now the worker takes two arguments. Which method unpacks each tuple?"] = "Teď worker bere dva argumenty. Která metoda rozbalí každou n-tici?",
  ["Now wait for the answer. Write Go's await."] = "Teď na odpověď počkej. Napiš await po způsobu Go.",
  ["Num, then the thing Go is famous for, singular."] = "Num a pak to, čím je Go proslulé, v jednotném čísle.",
  ["Num, then the three letters on the chip."] = "Num a pak ta tři písmena z čipu.",
  ["Number in the brackets, then the element type. It cannot grow."] = "Číslo v hranatých závorkách, pak typ prvku. Nemůže růst.",
  ["Number of islands"] = "Počet ostrovů",
  ["Number of islands: DFS on a grid"] = "Počet ostrovů: DFS na mřížce",
  ["Number the constants 0, 1, 2 automatically. Which identifier?"] = "Očísluj konstanty 0, 1, 2 automaticky. Který identifikátor?",
  ["Number the trays from 1 while looping. Which built-in pairs an index with each item?"] = "Očíslovat tácy od 1 během procházení. Která vestavěná funkce spáruje index s každou položkou?",
  ["Numbers, strings, None"] = "Čísla, řetězce, None",
  ["O(1) extra, near enough: the list is rearranged where it lives and sort() returns None to say so."] = "O(1) navíc, skoro: seznam se přeuspořádá tam, kde bydlí, a sort() vrací None, aby to řekl.",
  ["O(1) extra: pdqsort swaps within the slice. The input itself is never counted as extra space."] = "O(1) navíc: pdqsort prohazuje uvnitř slice. Samotný vstup se nikdy nepočítá jako prostor navíc.",
  ["O(1) extra: pdqsort swaps within the slice. Vec::sort, the stable one, allocates an O(n) buffer instead."] = "O(1) navíc: pdqsort prohazuje uvnitř slice. Vec::sort, ten stabilní, místo toho alokuje buffer O(n).",
  ["O(1) lookups need a map from key to its node in the list. Fill the value type."] = "Vyhledání v O(1) chce mapu z klíče na jeho uzel v seznamu. Doplň typ hodnoty.",
  ["O(1): a million items or ten, one multiply and one load. Written O(1), read 'order one'."] = 'O(1): milion položek nebo deset, jedno násobení a jedno načtení. Píše se O(1), čte se „řád jedna".',
  ["O(1): the OrderedDict is a doubly linked list plus a dict. The newest lives at the end, the oldest at the front."] = "O(1): OrderedDict je obousměrný spojový seznam plus dict. Nejnovější bydlí na konci, nejstarší na začátku.",
  ["O(1): the bounds check is one compare, the read one load, whatever n is. Read 'order one'."] = 'O(1): kontrola mezí je jedno porovnání, čtení jedno načtení, ať je n cokoli. Čte se „řád jedna".',
  ["O(1): the same number of steps however big the input. Indexing a Vec, a HashMap lookup, .last(). Doubling n changes nothing."] = "O(1): stejný počet kroků, ať je vstup jakkoli velký. Indexování Vec, vyhledání v HashMap, .last(). Zdvojnásobení n nic nemění.",
  ["O(1): the same number of steps however big the input. Indexing a list, a dict lookup, items[-1]. Doubling n changes nothing."] = "O(1): stejný počet kroků, ať je vstup jakkoli velký. Indexování seznamu, vyhledání v dictu, items[-1]. Zdvojnásobení n nic nemění.",
  ["O(1): the same number of steps however big the input. Indexing a slice, a map lookup, the last element. Doubling n changes nothing."] = "O(1): stejný počet kroků, ať je vstup jakkoli velký. Indexování slice, vyhledání v mapě, poslední prvek. Zdvojnásobení n nic nemění.",
  ["O(2^n). fib(35) already takes seconds in Python; fib(50) would take days. The worst curve on the board."] = "O(2^n). fib(35) už v Pythonu trvá sekundy; fib(50) by trvalo dny. Nejhorší křivka na tabuli.",
  ["O(2^n). fib(40) is about a billion calls even in Rust; fib(50) would take a day. The worst curve on the board."] = "O(2^n). fib(40) je asi miliarda volání i v Rustu; fib(50) by trvalo den. Nejhorší křivka na tabuli.",
  ["O(2^n). fib(40) is about a billion calls; fib(50) would take a day. The worst curve on the board."] = "O(2^n). fib(40) je asi miliarda volání; fib(50) by trvalo den. Nejhorší křivka na tabuli.",
  ["O(2^n): the work doubles when n grows by one. Naive fib makes two calls per call. @functools.cache brings it to O(n). Listing every subset of n items is 2^n and cannot be helped."] = "O(2^n): práce se zdvojnásobí, když n vzroste o jedna. Naivní fib dělá dvě volání na volání. @functools.cache ho dostane na O(n). Vypsat každou podmnožinu n položek je 2^n a nedá se s tím nic dělat.",
  ["O(2^n): the work doubles when n grows by one. Naive fib makes two calls per call. A HashMap memo brings it to O(n). Listing every subset of n items is 2^n and cannot be helped."] = "O(2^n): práce se zdvojnásobí, když n vzroste o jedna. Naivní fib dělá dvě volání na volání. Memo v HashMap ho dostane na O(n). Vypsat každou podmnožinu n položek je 2^n a nedá se s tím nic dělat.",
  ["O(2^n): the work doubles when n grows by one. Naive fib makes two calls per call. A memo brings it to O(n). Listing every subset of n items is 2^n and cannot be helped."] = "O(2^n): práce se zdvojnásobí, když n vzroste o jedna. Naivní fib dělá dvě volání na volání. Memo ho dostane na O(n). Vypsat každou podmnožinu n položek je 2^n a nedá se s tím nic dělat.",
  ["O(amount * coins). Each cell asks: which last coin gives the fewest in total?"] = "O(amount * coins). Každá buňka se ptá: která poslední mince dá celkem nejméně?",
  ["O(amount * coins). Greedy fails here: coins [1, 3, 4] for 6 is two coins, not 4 + 1 + 1."] = "O(amount * coins). Hladový přístup tu selže: mince [1, 3, 4] pro 6 jsou dvě mince, ne 4 + 1 + 1.",
  ["O(amount * coins). The greedy 'biggest coin first' fails for coins like 1, 3, 4 and amount 6; the table does not."] = "O(amount * coins). Hladové „největší mince první“ selže u mincí 1, 3, 4 a částky 6; tabulka ne.",
  ["O(log k) per push. Python's heapq is a min-heap only; for a max-heap push -x."] = "O(log k) na push. heapq v Pythonu je jen min-halda; pro max-haldu pushuj -x.",
  ["O(log n) per search. Sorting first pays off after the first few lookups. The sorting hat is done."] = "O(log n) na vyhledání. Seřadit nejdřív se vyplatí po prvních několika hledáních. Třídící klobouk je hotový.",
  ["O(log n) stack frames on average. Every axis on the board has a name now. Alex takes the O(1) stamp."] = "O(log n) rámců zásobníku v průměru. Každá osa na tabuli má teď jméno. Alex bere razítko O(1).",
  ["O(log n) stack frames on average. Every axis on the board has a name. Mei takes the O(1) stamp for the Rust round."] = "O(log n) rámců zásobníku v průměru. Každá osa na tabuli má jméno. Mei bere razítko O(1) za kolo Rustu.",
  ["O(log n) stack frames on average. Every axis on the last board has a name. The Python round takes the O(1) stamp; the night is over."] = "O(log n) rámců zásobníku v průměru. Každá osa na poslední tabuli má jméno. Kolo Pythonu bere razítko O(1); noc skončila.",
  ["O(log n). Balanced trees, heaps and skip lists live here too. It is the second-best cost after O(1)."] = "O(log n). Vyvážené stromy, haldy a skip listy bydlí také tady. Je to druhá nejlepší cena po O(1).",
  ["O(log n). Err(i) even tells you where to insert. BTreeMap and BinaryHeap live at the same cost."] = "O(log n). Err(i) ti dokonce řekne, kam vložit. BTreeMap a BinaryHeap bydlí na stejné ceně.",
  ["O(log n). heapq lives at the same cost per push and pop. The second-best cost after O(1)."] = "O(log n). heapq bydlí na stejné ceně za push a pop. Druhá nejlepší cena po O(1).",
  ["O(log n): each step halves what is left. Binary search on a sorted slice: 1024 items in 10 steps, a million in 20. Needs sorted input."] = "O(log n): každý krok půlí, co zbývá. Binární vyhledávání v seřazeném slice: 1024 položek na 10 kroků, milion na 20. Potřebuje seřazený vstup.",
  ["O(log n): each step halves what is left. bisect on a sorted list: 1024 items in 10 steps, a million in 20. Needs sorted input."] = "O(log n): každý krok půlí, co zbývá. bisect na seřazeném seznamu: 1024 položek na 10 kroků, milion na 20. Potřebuje seřazený vstup.",
  ["O(log n): each step halves what is left. slice::binary_search on a sorted Vec: 1024 items in 10 steps, a million in 20. Needs sorted input."] = "O(log n): každý krok půlí, co zbývá. slice::binary_search na seřazeném Vec: 1024 položek na 10 kroků, milion na 20. Potřebuje seřazený vstup.",
  ["O(n log k) time, O(k) space: better than sorting all n when k is small."] = "Čas O(n log k), paměť O(k): lepší než řadit všech n, když je k malé.",
  ["O(n log n) for the sort; everything after is O(n). Lists sort by first element anyway, so shifts.sort() works here too."] = "O(n log n) na řazení; všechno potom je O(n). Seznamy se stejně řadí podle prvního prvku, takže shifts.sort() tu funguje taky.",
  ["O(n log n), and after it every overlap sits next to its neighbour. slices.SortFunc does the same in Go 1.21."] = "O(n log n), a potom každý překryv sedí vedle svého souseda. slices.SortFunc dělá totéž v Go 1.21.",
  ["O(n log n), and it dominates: the merge walk after it is O(n). mut iv lets the function sort in place."] = "O(n log n), a to dominuje: slučovací průchod za ním je O(n). mut iv nechá funkci řadit na místě.",
  ["O(n log n). A million items: about 20 million comparisons, not a trillion. The proven lower bound for comparison sorts."] = "O(n log n). Milion položek: asi 20 milionů porovnání, ne bilion. Prokázaná dolní mez pro porovnávací třídění.",
  ["O(n log n). A million items: about 20 million comparisons. The proven lower bound for comparison sorts."] = "O(n log n). Milion položek: asi 20 milionů porovnání. Prokázaná dolní mez pro porovnávací třídění.",
  ["O(n log n). A million items: about 20 million comparisons. Timsort is O(n) on already-sorted input, a bonus."] = "O(n log n). Milion položek: asi 20 milionů porovnání. Timsort je na už seřazeném vstupu O(n), bonus.",
  ["O(n log n): the cost of a good sort. Merge sort has log n levels, each doing O(n) work. sort, sort_unstable and sort_by_key all live here. Sort once, search many times."] = "O(n log n): cena dobrého třídění. Merge sort má log n úrovní, každá dělá O(n) práce. sort, sort_unstable a sort_by_key bydlí všechny tady. Seřaď jednou, hledej mnohokrát.",
  ["O(n log n): the cost of a good sort. Merge sort has log n levels, each doing O(n) work. sort.Ints, sort.Strings and slices.Sort all live here. Sort once, search many times."] = "O(n log n): cena dobrého třídění. Merge sort má log n úrovní, každá dělá O(n) práce. sort.Ints, sort.Strings a slices.Sort bydlí všechny tady. Seřaď jednou, hledej mnohokrát.",
  ["O(n log n): the cost of a good sort. Merge sort has log n levels, each doing O(n) work. sorted and list.sort are Timsort and live here. Sort once, search many times."] = "O(n log n): cena dobrého třídění. Merge sort má log n úrovní, každá dělá O(n) práce. sorted a list.sort jsou Timsort a bydlí tady. Seřaď jednou, hledej mnohokrát.",
  ["O(n) instead of O(n * k): the sum is updated, never recomputed. Fixed windows are always this trick."] = "O(n) místo O(n * k): součet se aktualizuje, nikdy nepočítá znovu. Pevná okna jsou vždycky tenhle trik.",
  ["O(n) per level times log n levels. That product is the whole reason n log n exists."] = "O(n) na úroveň krát log n úrovní. Ten součin je celý důvod, proč n log n existuje.",
  ["O(n) time, O(n) table. Keep only the last two entries and it is O(1) space."] = "Čas O(n), tabulka O(n). Nech si jen poslední dvě položky a je to O(1) paměti.",
  ["O(n) with a dict instead of O(n^2) with two loops. Check before storing so x does not pair with itself."] = "O(n) s dictem místo O(n^2) se dvěma cykly. Kontroluj před uložením, aby se x nespárovalo samo se sebou.",
  ["O(n). Big O keeps only the fastest-growing term and drops its coefficient. Sequential loops add; nested loops multiply."] = "O(n). Big O si nechá jen nejrychleji rostoucí člen a zahodí jeho koeficient. Cykly za sebou se sčítají; vnořené se násobí.",
  ["O(n). Every element is touched once. The most common cost in everyday code, and often the best possible."] = "O(n). Každého prvku se dotkneš jednou. Nejběžnější cena v každodenním kódu a často ta nejlepší možná.",
  ["O(n). Memoization trades O(n) memory for the exponential time. The biggest win in this whole quest."] = "O(n). Memoizace vymění O(n) paměti za exponenciální čas. Největší výhra v celém tomto úkolu.",
  ["O(n). Memoization trades O(n) memory for the exponential time. The single biggest win in this whole quest."] = "O(n). Memoizace vymění O(n) paměti za exponenciální čas. Největší výhra v celém tomto úkolu.",
  ["O(n). Merge sort needs the same: an O(n) scratch buffer for merging. Python's sorted() copies too."] = "O(n). Merge sort potřebuje totéž: pracovní buffer O(n) na slučování. sorted() z Pythonu také kopíruje.",
  ["O(n). Rust makes the cost visible: clone() is a word you have to type. Python's sorted() copies silently."] = "O(n). Rust dělá cenu viditelnou: clone() je slovo, které musíš napsat. sorted() z Pythonu kopíruje potichu.",
  ["O(n). Sequential passes add and the constant drops. Nested passes multiply: that is the next street but one."] = "O(n). Průchody za sebou se sčítají a konstanta padá. Vnořené průchody se násobí: to je ulice ob jednu.",
  ["O(n). Sequential passes add and the constant drops. Nested passes multiply: that is two streets on."] = "O(n). Průchody za sebou se sčítají a konstanta padá. Vnořené průchody se násobí: to je o dvě ulice dál.",
  ["O(n). sorted() always copies; a.sort() never does. Choose by whether you still need the original order."] = "O(n). sorted() vždy kopíruje; a.sort() nikdy. Vyber podle toho, zda ještě potřebuješ původní pořadí.",
  ["O(n). sum, map, filter, count: every adapter is one pass. Zero-cost abstractions are still O(n) abstractions."] = "O(n). sum, map, filter, count: každý adaptér je jeden průchod. Abstrakce s nulovou cenou jsou pořád abstrakce O(n).",
  ["O(n). sum, max, min, any, all, list.count: every one is a pass. Faster in C, same order."] = "O(n). sum, max, min, any, all, list.count: každá je jeden průchod. Rychlejší v C, stejný řád.",
  ["O(n): one pass over the input; double n, double the work. A range loop, a sum, a scan for a value. O(n) + O(n) is still O(n): constants drop."] = "O(n): jeden průchod vstupem; zdvojnásob n, zdvojnásobí se práce. Cyklus range, součet, hledání hodnoty. O(n) + O(n) je stále O(n): konstanty padají.",
  ["O(n): one pass over the input; double n, double the work. iter().sum(), any(), Vec::contains. O(n) + O(n) is still O(n): constants drop."] = "O(n): jeden průchod vstupem; zdvojnásob n, zdvojnásobí se práce. iter().sum(), any(), Vec::contains. O(n) + O(n) je stále O(n): konstanty padají.",
  ["O(n): one pass over the input; double n, double the work. sum, max, x in list. O(n) + O(n) is still O(n): constants drop."] = "O(n): jeden průchod vstupem; zdvojnásob n, zdvojnásobí se práce. sum, max, x in list. O(n) + O(n) je stále O(n): konstanty padají.",
  ["O(n*m). Only when both loops run over the same n does it collapse to n^2. The seating chart is fixed."] = "O(n*m). Jen když oba cykly běží přes stejné n, zhroutí se to na n^2. Zasedací pořádek je opravený.",
  ["O(n^2). Double the guests, four times the checks. Bubble sort and selection sort live here too."] = "O(n^2). Dvakrát více hostů, čtyřikrát více kontrol. Bubble sort a selection sort bydlí také tady.",
  ["O(n^2): a loop inside a loop over the same n. Comparing every pair. 100 items is 4950 pairs; 10,000 is fifty million. A HashSet turns most of these into O(n)."] = "O(n^2): cyklus v cyklu přes stejné n. Porovnání každé dvojice. 100 položek je 4950 dvojic; 10 000 je padesát milionů. HashSet z většiny z nich udělá O(n).",
  ["O(n^2): a loop inside a loop over the same n. Comparing every pair. 100 items is 4950 pairs; 10,000 is fifty million. A map turns most of these into O(n)."] = "O(n^2): cyklus v cyklu přes stejné n. Porovnání každé dvojice. 100 položek je 4950 dvojic; 10 000 je padesát milionů. Mapa z většiny z nich udělá O(n).",
  ["O(n^2): a loop inside a loop over the same n. Comparing every pair. 100 items is 4950 pairs; 10,000 is fifty million. A set turns most of these into O(n)."] = "O(n^2): cyklus v cyklu přes stejné n. Porovnání každé dvojice. 100 položek je 4950 dvojic; 10 000 je padesát milionů. Set z většiny z nich udělá O(n).",
  ["OK"] = "OK",
  ["Octopus tap. The gate function returns ok, err."] = "Přilož Octopus. Funkce turniketu vrací ok, err.",
  ["Off the map on any side: stop. Fill the width the column index is checked against."] = "Mimo mapu na kterékoli straně: zastav. Doplň šířku, proti které se kontroluje index sloupce.",
  ["Ok(2). On an unsorted slice the result is meaningless, so sort first. Err(i) is where to insert to stay sorted."] = "Ok(2). Na neseřazeném slice je výsledek nesmyslný, takže nejdřív seřaď. Err(i) je místo, kam vložit, aby zůstalo seřazené.",
  ["Old tutorials talk about GOPATH. What is GO111MODULE since Go 1.16?"] = "Staré návody mluví o GOPATH. Co je GO111MODULE od Go 1.16?",
  ["Once, plus the word for what a function gives back. There is a two-result twin for (T, error)."] = "Once a k tomu slovo pro to, co funkce vrací. Existuje i dvojče se dvěma výsledky pro (T, error).",
  ["One CPython process runs bytecode under a global interpreter lock, so eight threads doing arithmetic still use one core. The GIL is released around I/O and inside C extensions, which is why threads help downloads and not sums. multiprocessing sidesteps it: every process has its own interpreter and its own lock."] = "Jeden proces CPythonu spouští bajtkód pod globálním zámkem interpretu, takže osm vláken počítajících aritmetiku pořád využije jedno jádro. GIL se uvolňuje kolem I/O a uvnitř céčkových rozšíření, a proto vlákna pomáhají stahování a ne sčítání. multiprocessing to obejde: každý proces má vlastní interpret a vlastní zámek.",
  ["One HashSet method adds m and tells you whether it was new. Which one?"] = "Jedna metoda HashSet přidá m a řekne ti, jestli bylo nové. Která?",
  ["One Unicode character in single quotes. Which type?"] = "Jeden znak Unicode v jednoduchých uvozovkách. Jaký typ?",
  ["One cargo command builds the crate and starts it. Which word?"] = "Jeden příkaz cargo crate sestaví a spustí. Které slovo?",
  ["One character passes the error straight back to the caller. Which?"] = "Jeden znak předá chybu rovnou zpět volajícímu. Který?",
  ["One character, the ampersand. The call site already uses it."] = "Jeden znak, ampersand. Místo volání ho už používá.",
  ["One character, the one in an email address. Rust uses it for attributes with #[...] instead."] = "Jeden znak, ten z e-mailové adresy. Rust místo toho používá atributy #[...].",
  ["One character. Go and Rust use two slashes; Python uses the hash sign."] = "Jeden znak. Go a Rust používají dvě lomítka; Python mřížku.",
  ["One character. The same one that returns Err early in a Result function."] = "Jeden znak. Ten samý, který ve funkci s Result brzy vrací Err.",
  ["One character. The same underscore Go uses to throw a value away."] = "Jeden znak. Stejné podtržítko, kterým Go zahazuje hodnotu.",
  ["One cook, one thread. The grill must not wait for the kettle."] = "Jeden kuchař, jedno vlákno. Gril nesmí čekat na konvici.",
  ["One counter, changed by many threads. Which wrapper allows only one writer at a time?"] = "Jeden čítač, měněný mnoha vlákny. Který obal povolí jen jednoho zapisovatele najednou?",
  ["One decorator remembers every result by argument. Which one, from functools?"] = "Jeden dekorátor si pamatuje každý výsledek podle argumentu. Který, z functools?",
  ["One directory is one package: every .go file in it says the same package name, normally the directory's. Only identifiers that start with a capital letter are visible from outside. You import a package by its full path, module path plus directory, never by a relative path, and an import you do not use is a compile error."] = "Jeden adresář je jeden balíček: každý .go soubor v něm uvádí stejné jméno balíčku, obvykle jméno adresáře. Zvenku jsou vidět jen identifikátory začínající velkým písmenem. Balíček importuješ jeho plnou cestou, cesta modulu plus adresář, nikdy relativní cestou, a nepoužitý import je chyba překladu.",
  ["One function for muffin or hash brown. Don't copy-paste."] = "Jedna funkce pro muffin i hash brown. Žádné copy-paste.",
  ["One go.mod at the root"] = "Jeden go.mod v kořeni",
  ["One less than n. fact(n) would never terminate."] = "O jedna méně než n. fact(n) by nikdy neskončilo.",
  ["One less than n. u64 cannot go below zero, which is why the base case checks <= 1."] = "O jedna méně než n. u64 nemůže jít pod nulu, proto bázový případ testuje <= 1.",
  ["One less than zero. Go spells the same thing items[len(items)-1]."] = "O jedna méně než nula. Go totéž píše items[len(items)-1].",
  ["One letter in front of Lock. Its partner is RUnlock."] = "Jedno písmeno před Lock. Jeho parťák je RUnlock.",
  ["One letter: the loop variable. Each goroutine owns exactly one slot."] = "Jedno písmeno: proměnná smyčky. Každá goroutina vlastní právě jednu přihrádku.",
  ["One line: 'open' when bowls remain, otherwise 'closed'. Which keyword completes the conditional expression?"] = "Jeden řádek: 'open', když misky zbývají, jinak 'closed'. Které klíčové slovo dokončí podmíněný výraz?",
  ["One loop over n prices, adding each: what is the cost in Big O?"] = "Jeden cyklus přes n cen, každou přičte: jaká je cena v Big O?",
  ["One main.go with nine hundred lines. Time to split it into packages, and the first question is what to call the module."] = "Jeden main.go o devíti stech řádcích. Je čas ho rozdělit na balíčky a první otázka zní, jak modul pojmenovat.",
  ["One megabyte every process can map. Which class from multiprocessing.shared_memory?"] = "Jeden megabajt, který si namapuje každý proces. Která třída z multiprocessing.shared_memory?",
  ["One more than the amount itself: no real answer uses more coins than the amount."] = "O jednu víc než sama částka: žádná skutečná odpověď nepoužije víc mincí, než je částka.",
  ["One pass, Bo. Keep the run if it's still helping, drop it the moment it isn't."] = "Jeden průchod, Bo. Sérii si nech, dokud ještě pomáhá, a zahoď ji v okamžiku, kdy ne.",
  ["One pass, one HashMap: O(n) instead of the O(n^2) double loop. seen[&want] then fetches the partner's index."] = "Jeden průchod, jedna HashMap: O(n) místo dvojitého cyklu O(n^2). seen[&want] pak vytáhne index partnera.",
  ["One pass, one map: O(n). Store after checking so x does not pair with itself."] = "Jeden průchod, jedna mapa: O(n). Ulož až po kontrole, aby se x nespárovalo samo se sebou.",
  ["One pass. If the running total goes negative, it can only hurt: start again."] = "Jeden průchod. Když průběžný součet klesne pod nulu, může už jen škodit: začni znovu.",
  ["One pointer per node: singly linked. Two (Prev) makes it doubly linked."] = "Jeden ukazatel na uzel: jednosměrně zřetězený. Dva (Prev) dělají obousměrně zřetězený.",
  ["One printer, eight cooks"] = "Jedna tiskárna, osm kuchařů",
  ["One put crashes with TypeError. What must everything on the queue be?"] = "Jedno put spadne s TypeError. Jaké musí být všechno, co jde do fronty?",
  ["One slash. On integers Rust truncates, so no floor operator is needed. lo + (hi-lo)/2 avoids overflow."] = "Jedno lomítko. Na celých číslech Rust ořezává, takže žádný operátor pro zaokrouhlení dolů není třeba. lo + (hi-lo)/2 se vyhne přetečení.",
  ["One slash. On ints Go rounds toward zero, so no floor operator is needed."] = "Jedno lomítko. Na intech Go zaokrouhluje k nule, takže žádný operátor pro zaokrouhlení dolů není třeba.",
  ["One ticket rail: the front sends boxed jobs, the cooks receive them. Which mpsc function makes the (tx, rx) pair?"] = "Jedna lišta s lístky: pult posílá zabalené joby, kuchaři je přijímají. Která funkce z mpsc vyrobí dvojici (tx, rx)?",
  ["One tray, one owner. Hand it over and it is gone. Lend it with & and you keep it."] = "Jeden tác, jeden vlastník. Předej ho a je pryč. Půjč ho přes & a zůstane ti.",
  ["One type, several ways an order can fail. Which keyword declares it?"] = "Jeden typ, několik způsobů, jak objednávka může selhat. Které klíčové slovo ho deklaruje?",
  ["One word, no underscore: the largest size the cache may reach. None means unbounded."] = "Jedno slovo, bez podtržítka: největší velikost, jaké cache smí dosáhnout. None znamená bez omezení.",
  ["One writer at the printer. Which multiprocessing primitive?"] = "U tiskárny jeden pisatel naráz. Který primitiv z multiprocessing?",
  ["Only four riders out at a time. Complete the release at the end of the trip."] = "Venku jsou naráz jen čtyři kurýři. Doplň vrácení místa na konci jízdy.",
  ["Only land spreads the flood. Which byte marks land in the grid?"] = "Záplavu šíří jen souš. Který bajt v mřížce značí souš?",
  ["Only land spreads. Which cell value means a building?"] = "Šíří se jen pevnina. Která hodnota buňky znamená budovu?",
  ["Only names that start with a capital letter leave their package. Which fmt function prints a line?"] = "Jen jména začínající velkým písmenem opouštějí svůj balíček. Která funkce z fmt vytiskne řádek?",
  ["Only one move reaches the first step: a single step of one."] = "Na první schod vede jen jeden tah: jediný krok o jedna.",
  ["Only the sender closes. Sending after this panics."] = "Zavírá jen odesílatel. Poslání po zavření způsobí panic.",
  ["Only the sender should call it. Never close from the receive side."] = "Volá ji jen odesílatel. Nikdy nezavírej ze strany příjemce.",
  ["Only three workers may hit the payments API at once. Which primitive counts?"] = "Na platební API smí naráz jen tři workeři. Který primitiv umí počítat?",
  ["Only types with this marker trait may move to another thread. Which one?"] = "Jen typy s tímto značkovacím traitem se smí přesunout do jiného vlákna. Který to je?",
  ["Only useful inside defer. Returns nil if we are not panicking."] = "Užitečné jen uvnitř defer. Vrací nil, pokud nepanikaříme.",
  ["Open the file so it is closed no matter what happens inside. Which keyword?"] = "Otevřít soubor tak, aby se zavřel, ať se uvnitř stane cokoli. Které klíčové slovo?",
  ["Open the middle, decide left or right, throw half away. The bisect module did it first."] = "Otevři uprostřed, rozhodni vlevo nebo vpravo, zahoď polovinu. Modul bisect to udělal první.",
  ["Open the middle, decide left or right, throw half away. The std library already wrote it."] = "Otevři uprostřed, rozhodni vlevo nebo vpravo, zahoď polovinu. Knihovna std to už napsala.",
  ["Opposite of var. Compile error if you try to change it."] = "Opak var. Chyba překladu, když ji zkusíš změnit.",
  ["Option does the empty case for free: a closer with nothing to pop is a mismatch, no extra if needed."] = "Option vyřeší prázdný případ zdarma: zavírací závorka bez čeho popnout je neshoda, žádný další if není třeba.",
  ["Option<Box<ListNode>>: each node owns the next, the last one holds None. Same size as a raw pointer."] = "Option<Box<ListNode>>: každý uzel vlastní další, poslední drží None. Stejná velikost jako syrový ukazatel.",
  ["Option<T> is an enum in the standard library, generic like your own types. No null anywhere in Rust."] = "Option<T> je enum ze standardní knihovny, generický jako tvoje vlastní typy. Nikde v Rustu žádný null.",
  ["Option<u32> is an enum: Some(12) or None. The caller must handle both, so no nil crash."] = "Option<u32> je enum: Some(12) nebo None. Volající musí ošetřit obě, takže žádný pád na nil.",
  ["Option<usize> would be more Rust; the interview version returns -1. Either way: check the marker before trusting the cell."] = "Option<usize> by bylo víc Rust; pohovorová verze vrací -1. Tak či tak: zkontroluj značku, než buňce uvěříš.",
  ["Optional[str] is str | None. Rust's Option<String>, made visible to the checker."] = "Optional[str] je str | None. Option<String> z Rustu, zviditelněný pro kontrolu.",
  ["Order 18. Morning set. Don't forget to cancel the context."] = "Objednávka 18. Ranní menu. Nezapomeň zrušit context.",
  ["Order is a struct. Point at it. The till talks through an interface."] = "Order je struct. Ukaž na něj. Pokladna mluví přes rozhraní.",
  ["Orders come through the web now. Put a handler on /order."] = "Objednávky teď chodí přes web. Dej handler na /order.",
  ["Over capacity: the least recently used sits at the far end of the list. Which method finds it?"] = "Nad kapacitu: nejdéle nepoužitý sedí na vzdáleném konci seznamu. Která metoda ho najde?",
  ["Overlap: the current interval starts no later than the last one ends. (1,3) and (3,5) touch and should merge. Which comparison?"] = "Překryv: aktuální interval začíná nejpozději tam, kde poslední končí. (1,3) a (3,5) se dotýkají a mají se sloučit. Které porovnání?",
  ["Overlaps are only neighbours once the intervals are ordered by start. Which Vec method sorts by a key closure?"] = "Překryvy jsou sousedy, až když jsou intervaly seřazené podle začátku. Která metoda Vec řadí podle klíče z closure?",
  ["Owner says: ship before 18:00 and the dinner set is on the house."] = "Majitel říká: nasaď to do 18:00 a večerní menu je na účet podniku.",
  ["Ownership and borrowing"] = "Vlastnictví a půjčování",
  ["PARALLEL  -  the night batch"] = "PARALLEL  -  noční dávka",
  ["PARALLEL  ·  the night batch"] = "PARALLEL  ·  noční dávka",
  ["PERFECT STREET"] = "PERFEKTNÍ ULICE",
  ["PERFECT!"] = "SKVĚLE!",
  ["POLYGLOT"] = "POLYGLOT",
  ["PORT"] = "VÝŠKA",
  ["Package name and directory name are separate things that everyone keeps identical. Short, lowercase, no underscores: menu, not menuUtils."] = "Jméno balíčku a jméno adresáře jsou dvě různé věci, které všichni drží stejné. Krátké, malými písmeny, bez podtržítek: menu, ne menuUtils.",
  ["Packages and imports"] = "Balíčky a importy",
  ["Palindrome with two pointers: i at the start, j at the end. Fill: j = len(s) ___ 1"] = "Palindrom se dvěma ukazateli: i na začátku, j na konci. Doplň: j = len(s) ___ 1",
  ["Palindrome: the chars read the same backwards. Which iterator method walks from the end?"] = "Palindrom: znaky se čtou pozpátku stejně. Která metoda iterátoru jde od konce?",
  ["Partial, then the word for ordering. Ord alone is too strict for f64."] = "Partial, pak slovo pro uspořádání. Samotný Ord je pro f64 příliš přísný.",
  ["Pause here until fetch has its answer, letting other tasks run. Which keyword?"] = "Pozastavit se tady, dokud fetch nemá odpověď, a nechat běžet jiné úlohy. Které klíčové slovo?",
  ["Pause this thread for 300 ms. Which function?"] = "Pozastav toto vlákno na 300 ms. Která funkce?",
  ["Pay() can fail. Check the error. Close the drawer with defer."] = "Pay() může selhat. Zkontroluj chybu. Šuplík zavři pomocí defer.",
  ["Peek at the most recent opener without removing it. Which index?"] = "Nakoukni na poslední otvírací závorku bez odebrání. Který index?",
  ["Percival Street"] = "Percival Street",
  ["Percival Street at dawn. Walk if the crossing is clear, else wait. Go has no while: a for with a condition is the while."] = "Percival Street za svítání. Jdi, když je přechod volný, jinak čekej. Go nemá while: for s podmínkou je while.",
  ["Percival Street tram stop"] = "Tramvajová zastávka Percival Street",
  ["Pick a branch by value without a chain of ifs. Which keyword?"] = "Vyber větev podle hodnoty bez řetězce ifů. Které klíčové slovo?",
  ["Pick the bigger of a and b in one line. Which keyword starts the expression?"] = "Vyber větší z a a b na jednom řádku. Které klíčové slovo výraz začíná?",
  ["Pipe() gives two Connection objects with send and recv. It is faster than a Queue and safe for exactly two processes."] = "Pipe() dá dva objekty Connection se send a recv. Je rychlejší než Queue a bezpečná právě pro dva procesy.",
  ["Plain dicts keep insertion order since 3.7, but only this one has move_to_end and popitem(last=False)."] = "Obyčejné dicty drží pořadí vložení od 3.7, ale jen tenhle má move_to_end a popitem(last=False).",
  ["Plain integers: equal values are indistinguishable, so stability is wasted. The faster in-place sort with no allocation?"] = "Obyčejná celá čísla: stejné hodnoty jsou nerozlišitelné, takže stabilita je zbytečná. Které rychlejší řazení na místě bez alokace?",
  ["Plural of the type a single Unicode scalar has in Rust."] = "Množné číslo typu, který má v Rustu jeden Unicode skalár.",
  ["Point the current node backwards. Fill: cur.Next = ___"] = "Otoč aktuální uzel dozadu. Doplň: cur.Next = ___",
  ["Point the import path at the folder next door while you work. Which directive?"] = "Nasměruj importní cestu na vedlejší složku, dokud pracuješ. Která direktiva?",
  ["Pointer receiver to mutate or for big structs; value receiver for small read-only types."] = "Ukazatelový receiver pro změny nebo velké structy; hodnotový receiver pro malé typy jen pro čtení.",
  ["Pointer to the same struct type, like the tree node."] = "Ukazatel na tentýž typ struct, jako u uzlu stromu.",
  ["Pool: map, imap, starmap, chunks"] = "Pool: map, imap, starmap, dávky",
  ["Price list is a map. Hash brown: 8 dollars."] = "Ceník je mapa. Hash brown: 8 dolarů.",
  ["Price now returns cents, not dollars: a breaking change. What does the module path gain?"] = "Price teď vrací centy, ne dolary: nekompatibilní změna. Co cesta modulu získá?",
  ["Print every dish with its price. Which method walks the key-value pairs?"] = "Vytisknout každé jídlo s jeho cenou. Která metoda prochází dvojice klíč–hodnota?",
  ["Print the missing key from the error object. Which keyword binds the exception to a name?"] = "Vytisknout chybějící klíč z objektu chyby. Které klíčové slovo naváže výjimku na jméno?",
  ["Print the struct with its field names. Which verb?"] = "Vypiš struct s názvy polí. Který verb?",
  ["Print the values sorted: left subtree, node, right subtree. Fill the first call."] = "Vypiš hodnoty seřazené: levý podstrom, uzel, pravý podstrom. Doplň první volání.",
  ["Print then ln. fmt.println with a small p does not exist outside fmt."] = "Print a pak ln. fmt.println s malým p mimo fmt neexistuje.",
  ["Problem five: search and sort. Binary search on a sorted slice with half-open bounds, then merge sort, the recursion every interviewer loves. And the one-liner from the library."] = "Úloha pět: hledání a řazení. Binární vyhledávání v seřazeném slice s polootevřenými mezemi, pak merge sort, rekurze, kterou miluje každý u pohovoru. A jednořádkovka z knihovny.",
  ["Problem four: the order queue as a singly linked list. Reverse it in place with three pointers, then detect a cycle with two runners of different speed."] = "Úloha čtyři: fronta objednávek jako jednosměrně zřetězený seznam. Otoč ji na místě třemi ukazateli, pak odhal cyklus dvěma běžci různé rychlosti.",
  ["Problem seven, the one they always ask: N workers pull jobs from a channel and push results. Get the close and the wait in the right order and the job is yours."] = "Úloha sedm, ta, na kterou se ptají vždycky: N workerů bere úlohy z channelu a posílá výsledky. Dej close a wait ve správném pořadí a místo je tvoje.",
  ["Problem six: the classics. Two numbers that add up to the set price, a palindrome check that handles CJK, and whether two dish names are anagrams."] = "Úloha šest: klasika. Dvě čísla se součtem rovným ceně menu, test palindromu, který zvládne CJK, a zda jsou dva názvy jídel anagramy.",
  ["Problem three: walk the MTR graph. Breadth-first with a queue for shortest hops, depth-first with recursion for reachability. Both need a visited set."] = "Úloha tři: projdi graf MTR. Do šířky s frontou pro nejmenší počet přestupů, do hloubky s rekurzí pro dosažitelnost. Obě potřebují množinu navštívených.",
  ["Problem two: a binary search tree of order numbers. Insert, walk in order, measure the height. In Go a tree is just a struct with two pointers and a nil at every leaf."] = "Úloha dvě: binární vyhledávací strom čísel objednávek. Vlož, projdi in-order, změř výšku. V Go je strom jen struct se dvěma ukazateli a nil v každém listu.",
  ["Process, start, join, __main__"] = "Process, start, join, __main__",
  ["ProcessPoolExecutor and choosing"] = "ProcessPoolExecutor a jak vybrat",
  ["Processes share nothing, so everything travels: a multiprocessing.Queue is a pipe plus a feeder thread plus pickle at both ends. put and get carry any picklable object; a Pipe is the raw two-ended version. Workers stop on a sentinel, usually None, and a JoinableQueue lets the parent wait with task_done and join."] = "Procesy nesdílejí nic, takže všechno cestuje: multiprocessing.Queue je roura plus podávací vlákno plus pickle na obou koncích. put a get unesou jakýkoli picklable objekt; Pipe je syrová verze se dvěma konci. Workeři končí na strážné hodnotě, obvykle None, a JoinableQueue nechá rodiče čekat přes task_done a join.",
  ["Pull a *RefundError out of the chain to read its fields. Fill: errors.___(err, &re)"] = "Vytáhni z řetězu *RefundError a přečti jeho pole. Doplň: errors.___(err, &re)",
  ["Pull a crate in from the terminal without editing the file by hand. Which subcommand?"] = "Přitáhni crate z terminálu bez ručního editování souboru. Který podpříkaz?",
  ["Pull exactly one bowl from the generator by hand. Which built-in?"] = "Ručně vytáhnout z generátoru přesně jednu misku. Která vestavěná funkce?",
  ["Push appends through the pointer, because it must change the slice itself. Fill the receiver type."] = "Push appenduje přes ukazatel, protože musí změnit samotný slice. Doplň typ receiveru.",
  ["Push, Pop and Min all O(1): low[len(low)-1] is always the smallest thing still on the stack."] = "Push, Pop i Min všechny O(1): low[len(low)-1] je vždycky to nejmenší, co na zásobníku ještě je.",
  ["Put a new key: a new node at the front, and its address in the map. Fill the list method."] = "Put nového klíče: nový uzel na začátek a jeho adresa do mapy. Doplň metodu seznamu.",
  ["Python 3.13 ships an experimental build without the lock. What is it called?"] = "Python 3.13 přináší experimentální sestavení bez toho zámku. Jak se mu říká?",
  ["Python has no braces, Alex. The indentation is the block."] = "Python nemá složené závorky, Alexi. Odsazení je blok.",
  ["Python ignores the rest of a line after which character?"] = "Po kterém znaku Python ignoruje zbytek řádku?",
  ["Python's nothing, capital N. Go's nil pointer, Rust's Option::None."] = "Pythonové nic, velké N. nil pointer z Go, Option::None z Rustu.",
  ["Python's nothing, capitalised. One per worker, because each one eats exactly one."] = "Pythonovské nic, s velkým písmenem. Jedno na workera, protože každý sní přesně jedno.",
  ["Q other quest"] = "Q jiná mise",
  ["Q: "] = "Q: ",
  ["QUEST %d"] = "MISE %d",
  ["QUEST CLEAR!"] = "VÝPRAVA SPLNĚNA!",
  ["Quadratic time"] = "Kvadratický čas",
  ["Quadratic: n squared. Write the power with a caret."] = "Kvadratický: n na druhou. Mocninu zapiš stříškou.",
  ["Queue board is stuck at zero. Nobody can order until it counts."] = "Tabule fronty stojí na nule. Nikdo si neobjedná, dokud nepočítá.",
  ["Queue for wide, stack for deep. Same loop, different end of the Vec."] = "Fronta na šířku, zásobník na hloubku. Stejný cyklus, jiný konec Vecu.",
  ["Queues, pipes and pickle"] = "Fronty, roury a pickle",
  ["R then Lock. Writers still use Lock and Unlock."] = "R, pak Lock. Zapisovatelé dál používají Lock a Unlock.",
  ["RLock blocks only while a writer holds the lock. Readers never block each other."] = "RLock blokuje jen tehdy, když zámek drží pisatel. Čtenáři se navzájem nikdy neblokují.",
  ["ROUND 1  -  the brackets"] = "KOLO 1  -  závorky",
  ["ROUND 1  -  the buzzer"] = "KOLO 1  -  bzučák",
  ["ROUND 2  -  the stairs"] = "KOLO 2  -  schody",
  ["ROUND 2  -  the tree"] = "KOLO 2  -  strom",
  ["ROUND 3  -  the map"] = "KOLO 3  -  mapa",
  ["ROUND 3  -  the window"] = "KOLO 3  -  okno",
  ["ROUND 4  -  the chain"] = "KOLO 4  -  řetěz",
  ["ROUND 4  -  the top k"] = "KOLO 4  -  top k",
  ["ROUND 5  -  the shifts"] = "KOLO 5  -  směny",
  ["ROUND 5  -  the shuffle"] = "KOLO 5  -  míchání",
  ["ROUND 6  -  the cache"] = "KOLO 6  -  cache",
  ["ROUND 6  -  the classics"] = "KOLO 6  -  klasika",
  ["ROUND 7  -  the kitchen"] = "KOLO 7  -  kuchyně",
  ["RUST SET  -  the walk"] = "RUST SET  -  procházka",
  ["RWMutex: RLock for readers, Lock for the one writer. Use it when reads dominate."] = "RWMutex: RLock pro čtenáře, Lock pro jediného zapisovatele. Použij, když převažuje čtení.",
  ["Race the cooking against the cancel. Which method gives the channel to select on?"] = "Nech vaření závodit se zrušením. Která metoda dá kanál, na kterém se dá selectovat?",
  ["Rc counts on one thread only. Which shared pointer may cross threads?"] = "Rc počítá jen na jednom vlákně. Který sdílený ukazatel smí přejít mezi vlákny?",
  ["Reached an empty spot: make the node here. Fill: if n == ___"] = "Došli jsme na prázdné místo: vytvoř uzel tady. Doplň: if n == ___",
  ["Read JSON bytes into the struct. Fill: json.___(b, &order)"] = "Načti JSON bajty do structu. Doplň: json.___(b, &order)",
  ["Read a price that may not exist, with 0 as the fallback, without a crash. Which method?"] = "Přečíst cenu, která možná neexistuje, s 0 jako záložní hodnotou, bez pádu. Která metoda?",
  ["Read and write, then the word for lock. Readers share it; a writer gets it alone."] = "Čtení a zápis, a pak slovo pro zámek. Čtenáři se o něj dělí, pisatel ho má sám.",
  ["Read the counter without a lock and without a race. Which method?"] = "Přečti čítač bez zámku a bez souběhu. Která metoda?",
  ["Read the root value without moving the Box out of the Option. Which Option method borrows the inside?"] = "Přečti hodnotu kořene, aniž bys vytáhl Box z Option. Která metoda Option půjčí vnitřek?",
  ["Reading items[3] from a Vec of n items: how many steps, in Big O?"] = "Čtení items[3] z Vec o n položkách: kolik kroků, v Big O?",
  ["Reading items[3] from a list of n items: how many steps, in Big O?"] = "Čtení items[3] ze seznamu o n položkách: kolik kroků, v Big O?",
  ["Reading items[3] from a slice of n items: how many steps, in Big O?"] = "Čtení items[3] ze slice o n položkách: kolik kroků, v Big O?",
  ["Real life: sort orders by price, cheapest first, equal prices keep their order. Which stable slice method takes a key closure?"] = "Reálný život: seřaď objednávky podle ceny, nejlevnější první, stejné ceny si drží pořadí. Která stabilní metoda slice bere closure s klíčem?",
  ["Receipt holds a &'a str. What must the struct declare after its name?"] = "Receipt drží &'a str. Co musí struct deklarovat za svým jménem?",
  ["Receipt<'_> means some lifetime, I do not need to name it. Clearer than impl<'a> Display for Receipt<'a> when 'a is never used."] = "Receipt<'_> znamená nějaký lifetime, nemusím ho pojmenovat. Jasnější než impl<'a> Display for Receipt<'a>, když se 'a nikdy nepoužije.",
  ["Receive until the channel is closed. Fill: for m := ___ ch"] = "Přijímej, dokud se kanál nezavře. Doplň: for m := ___ ch",
  ["Receiver is Send but not Sync: three cooks cannot read the rail at once. Arc shares it; what hands out turns?"] = "Receiver je Send, ale ne Sync: tři kuchaři nemůžou číst lištu naráz. Arc ji sdílí; co rozdává pořadí?",
  ["Recurse into the same side you assign to. Mirror of the else branch."] = "Rekurze do stejné strany, do které přiřazuješ. Zrcadlo větve else.",
  ["Recursion and memoization"] = "Rekurze a memoizace",
  ["Recursion uses the call stack. Quicksort's average recursion depth, hence stack space, is O(___)"] = "Rekurze používá zásobník volání. Průměrná hloubka rekurze quicksortu, tedy prostor zásobníku, je O(___)",
  ["Recursive types need a pointer. nil children mark the end."] = "Rekurzivní typy potřebují ukazatel. Potomci nil značí konec.",
  ["Reduce with your own start value and closure. Which method?"] = "Reduce s vlastní počáteční hodnotou a closure. Která metoda?",
  ["Refill the ice only if nobody is at the machine. Which method returns false instead of waiting?"] = "Doplň led jen tehdy, když u stroje nikdo není. Která metoda vrátí false místo čekání?",
  ["Reformat every file to the standard style before the commit. Which subcommand?"] = "Přeformátuj každý soubor do standardního stylu před commitem. Který podpříkaz?",
  ["Release the lock however the function exits. Fill: defer mu.___()"] = "Uvolni zámek, ať funkce skončí jakkoli. Doplň: defer mu.___()",
  ["Release the lock however the function leaves, error or not. Which keyword?"] = "Pusť zámek, ať funkce skončí jakkoli, s chybou i bez ní. Které klíčové slovo?",
  ["Release the module. Which git command names the commit?"] = "Vydej modul. Který git příkaz dá commitu jméno?",
  ["Remember which stations were seen, with O(1) lookup. Which built-in?"] = "Pamatovat si, které stanice byly viděny, s vyhledáním O(1). Která vestavěná funkce?",
  ["Remove a key from a map. Which built-in?"] = "Odstraň klíč z mapy. Která vestavěná funkce?",
  ["Repeat forever until break hands back a value. Which keyword?"] = "Opakuj donekonečna, dokud break nevrátí hodnotu. Které klíčové slovo?",
  ["Repeat while a condition holds. Which keyword?"] = "Opakuj, dokud platí podmínka. Které klíčové slovo?",
  ['Report a failed check and keep the test running. Fill: t.___("got %d", n)'] = 'Nahlas neúspěšnou kontrolu a nech test běžet dál. Doplň: t.___("got %d", n)',
  ["Resize every photo and keep the input order. Which method?"] = "Zmenši každou fotku a zachovej pořadí vstupu. Která metoda?",
  ["Response + Writer. An interface, so no star. It is also an io.Writer."] = "Response + Writer. Rozhraní, takže bez hvězdičky. Je to také io.Writer.",
  ["ResponseWriter: headers, status, body. Write the status before the body."] = "ResponseWriter: hlavičky, status, tělo. Status zapiš před tělem.",
  ["Result and the ? operator"] = "Result a operátor ?",
  ["Result<T, E> is either Ok(value) or Err(error). The compiler makes you check. The till lights up."] = "Result<T, E> je buď Ok(hodnota), nebo Err(chyba). Kompilátor tě donutí to zkontrolovat. Pokladna se rozsvítí.",
  ["Return a plus b without the return keyword. What is the last line of the body?"] = "Vrať a plus b bez klíčového slova return. Jaký je poslední řádek těla?",
  ["Return an iterator without naming its long type. Which keyword in the return position?"] = "Vrať iterátor bez vypisování jeho dlouhého typu. Které klíčové slovo v návratové pozici?",
  ["Return the cached answer if it is there. Fill the comma-ok test: if v, ok := memo[n]; ___"] = "Vrať uloženou odpověď, pokud existuje. Doplň test comma-ok: if v, ok := memo[n]; ___",
  ["Returning &o is safe in Go: the compiler sees the reference outlive the frame and moves the value to the heap. Sharing across goroutines does the same."] = "Vrátit &o je v Go bezpečné: překladač vidí, že reference přežije rámec, a přesune hodnotu na haldu. Sdílení mezi goroutinami dělá totéž.",
  ["Returns a channel that fires once, later. Capital A."] = "Vrací kanál, který jednou, později, vystřelí. Velké A.",
  ["Reverse in place: point the current node back at the one before it. Fill: cur.next = ___"] = "Obrátit na místě: nasměrovat aktuální uzel zpět na ten před ním. Doplň: cur.next = ___",
  ["Reverse with prev/cur/next pointers. Floyd's cycle check: slow moves one, fast moves two."] = "Otočení ukazateli prev/cur/next. Floydův test cyklu: slow jde o jeden, fast o dva.",
  ["Reverse(3) < Reverse(2). Wrapping at push time is the whole trick; no custom Ord impl needed."] = "Reverse(3) < Reverse(2). Obalit při pushi je celý trik; žádná vlastní impl Ord není třeba.",
  ["Reverse: point the current node backwards. Fill: node.next = ___"] = "Otočení: nasměruj aktuální uzel dozadu. Doplň: node.next = ___",
  ["Right minus left, plus one for the inclusive end."] = "Pravý mínus levý, plus jedna za včetně konce.",
  ["Room made: store the value. Which HashMap method writes k to v, replacing an old value if there was one?"] = "Místo uvolněno: ulož hodnotu. Která metoda HashMap zapíše k na v a nahradí starou hodnotu, pokud nějaká byla?",
  ["Round five. A shoebox of receipts on the screen. Bo writes merge sort by hand for the crowd, then admits that sorted() has been Timsort all along, and finds a receipt by amount with bisect."] = "Páté kolo. Krabice od bot s účtenkami na obrazovce. Bo pro dav napíše merge sort ručně, pak přizná, že sorted() byl celou dobu Timsort, a najde účtenku podle částky pomocí bisect.",
  ["Round five. Every cook's shift as [start, end]. When is the kitchen staffed at all, as one clean list?"] = "Páté kolo. Směna každého kuchaře jako [start, end]. Kdy je kuchyně vůbec obsazená, jako jeden čistý seznam?",
  ["Round five. Merge the intervals, Mei. Sort first; the interviewer always waits for that word."] = "Páté kolo. Sluč intervaly, Mei. Nejdřív seřaď; na to slovo tazatel vždycky čeká.",
  ["Round five. Staff shifts as {start, end}. Merge the overlapping ones into one schedule."] = "Kolo pět. Směny personálu jako {start, end}. Slouč překrývající se do jednoho rozvrhu.",
  ["Round five. The night market's noodle stall next door lends its counter as a second whiteboard. Siu Ming lists the cooks' shifts, overlapping every which way, and wants the hours the kitchen is covered as a list of clean blocks. Sort, then one pass: every merged interval is either extended or started."] = "Páté kolo. Nudlový stánek nočního trhu odvedle půjčuje svůj pult jako druhou tabuli. Siu Ming vypisuje směny kuchařů, překrývající se všemi směry, a chce hodiny, kdy je kuchyně pokrytá, jako seznam čistých bloků. Seřaď, pak jeden průchod: každý sloučený interval se buď prodlouží, nebo začne.",
  ["Round five: sort the night's receipts. Write merge sort, then use the built-ins like a grown-up."] = "Páté kolo: seřaď účtenky dnešní noci. Napiš merge sort, pak použij vestavěné funkce jako dospělý.",
  ["Round five: the shuffle. Write merge sort by hand, then show me you know the std sorts. O(n log n) or bust!"] = "Páté kolo: zamíchání. Napiš merge sort ručně, pak mi ukaž, že znáš řazení ze std. O(n log n) nebo nic!",
  ["Round four. A chain of delivery stops, each pointing to the next. Bo reverses it in place, sends two riders down it at different speeds to find the middle, and checks whether the route loops."] = "Čtvrté kolo. Řetěz rozvozových zastávek, každá ukazuje na další. Bo ho obrátí na místě, pošle po něm dva kurýry různou rychlostí, aby našel střed, a ověří, zda trasa tvoří smyčku.",
  ["Round four. A million order totals stream past. The third largest, without sorting them all."] = "Kolo čtyři. Kolem proudí milion součtů objednávek. Třetí největší, bez řazení všech.",
  ["Round four. A million receipts stream past. The third biggest, at any moment, without sorting."] = "Čtvrté kolo. Kolem proudí milion účtenek. Třetí největší, v kterémkoli okamžiku, bez řazení.",
  ["Round four. Receipts by the million, and Siu Ming wants the kth biggest while they are still arriving. Sorting everything is n log n and needs it all in memory; a heap of k keeps just the contenders. Bo draws a small pile with the smallest on top and starts pushing."] = "Čtvrté kolo. Účtenky po milionech a Siu Ming chce k-tou největší, zatímco ještě přicházejí. Seřadit všechno je n log n a potřebuje to celé v paměti; halda o k drží jen kandidáty. Bo kreslí malou hromádku s nejmenším nahoře a začíná pushovat.",
  ["Round four. Ten thousand receipts: the third biggest, and the five dishes ordered most. Without sorting all of it."] = "Čtvrté kolo. Deset tisíc účtenek: třetí největší a pět nejobjednávanějších jídel. Bez řazení všeho.",
  ["Round four: a linked list. Reverse it, find the middle, catch the loop."] = "Čtvrté kolo: spojový seznam. Obrať ho, najdi střed, chyť smyčku.",
  ["Round four: reverse the chain, then find its middle. The borrow checker is watching."] = "Čtvrté kolo: otoč řetěz a pak najdi jeho střed. Borrow checker se dívá.",
  ["Round six, the one we always ask. A cache of the last 100 menus. Get and Put in O(1). Go."] = "Kolo šest, to, na které se ptáme vždycky. Cache posledních 100 menu. Get a Put v O(1). Do toho.",
  ["Round six. A cache that holds n routes. When it is full, the one nobody asked for longest goes."] = "Šesté kolo. Cache, která drží n tras. Když je plná, odejde ta, na kterou se nikdo nejdéle neptal.",
  ["Round six. Fast hands, Mei. The crab on the kiosk is keeping time."] = "Šesté kolo. Rychlé ruce, Mei. Krab na kiosku měří čas.",
  ["Round six. The classics: which two receipts add up to the till's total, are two dish names anagrams, is the shop's slogan a palindrome. A dict, a sort and two pointers. The crowd knows these; Bo has to be fast."] = "Šesté kolo. Klasiky: které dvě účtenky dají dohromady součet kasy, jsou dvě jména jídel anagramy, je slogan obchodu palindrom. Dict, třídění a dva ukazatele. Dav je zná; Bo musí být rychlý.",
  ["Round six. The delivery app looks up the same few routes all night, and the map API charges per call. Siu Ming wants a cache of n routes where the least recently used one leaves first, with get and put in O(1). Bo writes one dict that remembers its order and two methods."] = "Šesté kolo. Rozvozová aplikace celou noc hledá stejných pár tras a mapové API účtuje za každé volání. Siu Ming chce cache n tras, kde nejdéle nepoužitá odchází první, s get a put v O(1). Bo píše jeden dict, který si pamatuje pořadí, a dvě metody.",
  ["Round six. The menu API caches the last hundred dishes. Which one goes when the hundred-and-first arrives?"] = "Šesté kolo. API menu cachuje posledních sto jídel. Které vypadne, když dorazí sto první?",
  ["Round six: the three questions every interview asks. Two-sum, anagram, palindrome. Go!"] = "Šesté kolo: tři otázky, které padnou na každém pohovoru. Two-sum, anagram, palindrom. Start!",
  ["Round three. A week of profits and losses per hour. Which run of hours made the most?"] = "Třetí kolo. Týden zisků a ztrát po hodinách. Která série hodin vydělala nejvíc?",
  ["Round three. Daily sales, some negative. Which stretch of days made the most money?"] = "Kolo tři. Denní tržby, některé záporné. Který úsek dnů vydělal nejvíc?",
  ["Round three. Siu Ming writes a row of numbers on the board: the till, hour by hour, some hours negative. The best run of hours, the best three hours in a row, then the longest streak of orders with no dish repeated. Three windows, each slid across the row exactly once."] = "Třetí kolo. Siu Ming píše na tabuli řadu čísel: kasa hodinu po hodině, některé hodiny záporné. Nejlepší série hodin, nejlepší tři hodiny v řadě, pak nejdelší šňůra objednávek bez opakovaného jídla. Tři okna, každé posunuté přes řadu přesně jednou.",
  ["Round three. The MTR map: stations are nodes, lines are edges. Bo builds the adjacency dict, then finds every station reachable from Causeway Bay, breadth first, then depth first."] = "Třetí kolo. Mapa MTR: stanice jsou uzly, linky hrany. Bo postaví dict sousednosti a pak najde každou stanici dosažitelnou z Causeway Bay, nejdřív do šířky, pak do hloubky.",
  ["Round three: the MTR map as a graph. Breadth first, then depth first. Do not visit a station twice!"] = "Třetí kolo: mapa MTR jako graf. Nejdřív do šířky, pak do hloubky. Žádnou stanici nenavštěvuj dvakrát!",
  ["Round three: the MTR map as a graph. Build it, sweep it wide, then sweep it deep."] = "Třetí kolo: mapa MTR jako graf. Postav ji, zameť do šířky, pak do hloubky.",
  ["Round three: the best run of sales in a week, the busiest k hours, the longest streak of different dishes. All one pass."] = "Třetí kolo: nejlepší řada tržeb v týdnu, nejrušnějších k hodin, nejdelší série různých jídel. Všechno na jeden průchod.",
  ["Round two. Siu Ming draws a staircase and a pile of coins. Bo has climbed the MTR exit ten thousand times and counted the till's change every night; now the question is how many ways and how few coins. A table that fills from the bottom up, and a marker for the impossible."] = "Druhé kolo. Siu Ming kreslí schodiště a hromádku mincí. Bo vyšel východ z MTR desettisíckrát a každou noc počítal drobné v kase; teď je otázka kolik způsobů a jak málo mincí. Tabulka, která se plní odspodu, a značka pro nemožné.",
  ["Round two. The MTR exit has n steps, you take one or two at a time. How many ways up?"] = "Kolo dvě. Výstup z MTR má n schodů, bereš jeden nebo dva najednou. Kolika způsoby nahoru?",
  ["Round two. The Times Square stairs: one or two steps at a time. How many ways up? Then make change for the till."] = "Druhé kolo. Schody na Times Square: po jednom nebo po dvou. Kolika způsoby nahoru? Pak rozměň drobné pro pokladnu.",
  ["Round two. The screen shows the whiteboard from the back office: a tree of order numbers. Smaller to the left, larger to the right. Bo has to grow it, walk it in order, measure it and sweep it level by level."] = "Druhé kolo. Obrazovka ukazuje tabuli ze zadní kanceláře: strom čísel objednávek. Menší vlevo, větší vpravo. Bo ho musí nechat růst, projít in-order, změřit a zamést patro po patru.",
  ["Round two: a binary search tree. Insert, walk it in order, measure it, then level by level."] = "Druhé kolo: binární vyhledávací strom. Vkládej, projdi in-order, změř, pak patro po patru.",
  ["Rows go 0..len, so len itself is out. The same test on c covers the right edge; the top and left are handled by wrapping."] = "Řádky jdou 0..len, takže samotné len je venku. Stejný test na c pokryje pravý okraj; horní a levý řeší wrapping.",
  ["Rows run from 0 to len(g)-1; len(g) itself is already outside."] = "Řádky jdou od 0 do len(g)-1; samotné len(g) je už venku.",
  ["Run close() when this function returns, even on error. Which keyword?"] = "Spusť close(), až tato funkce skončí, i při chybě. Které klíčové slovo?",
  ["Run cross(), then test its error in the same if. Fill the operator: err ___ nil"] = "Spusť cross() a pak otestuj jeho chybu ve stejném if. Doplň operátor: err ___ nil",
  ["Run every function marked with the #[...] attribute for checks. Which subcommand?"] = "Spusť každou funkci označenou atributem #[...] pro kontroly. Který podpříkaz?",
  ["Run fry beside the main thread. Which class from threading?"] = "Spustit fry vedle hlavního vlákna. Která třída z threading?",
  ["Run grind on its own core. Which multiprocessing class?"] = "Spusť grind na vlastním jádře. Která třída z multiprocessing?",
  ["Run the cooks, stop on the first error, wait for all. Fill: g.___()"] = "Spusť kuchaře, zastav při první chybě, počkej na všechny. Doplň: g.___()",
  ["Rune, Count, In, String: one long name. Or len([]rune(s))."] = "Rune, Count, In, String: jeden dlouhý název. Nebo len([]rune(s)).",
  ["Russell Street"] = "Russell Street",
  ["Rust ignores the rest of a line after which two characters?"] = "Po kterých dvou znacích Rust ignoruje zbytek řádku?",
  ["Rust? I only know Go. Is it far?"] = "Rust? Já znám jen Go. Je to daleko?",
  ["RwLock: many .read() guards at once, or one .write(). Use it when reads far outnumber writes; Mutex is simpler otherwise."] = "RwLock: mnoho guardů .read() najednou, nebo jeden .write(). Používej ho, když čtení výrazně převažuje nad zápisy; jinak je Mutex jednodušší.",
  ["S  THIS STREET"] = "S  TATO ULICE",
  ["S  WHOLE QUEST"] = "S  CELÝ ÚKOL",
  ["S  WHOLE TRACK"] = "S  CELÁ TRASA",
  ["S for string, then printf. Fprintf writes to a writer, Printf to stdout."] = "S jako string, pak printf. Fprintf píše do writeru, Printf na stdout.",
  ["SAVED  %s"] = "ULOŽENO  %s",
  ["SAVED %d FILES  in %s"] = "ULOŽENO %d SOUBORŮ  do %s",
  ["SHARE"] = "SDÍLET",
  ["SHARE THIS QUIZ"] = "SDÍLET TENTO KVÍZ",
  ["SHARED IT"] = "SDÍLENO",
  ["SPEED TYPER"] = "RYCHLÉ PRSTY",
  ["STOP"] = "STOP",
  ["STREAK x%d"] = "SÉRIE x%d",
  ["STREET CLEAR!"] = "ULICE HOTOVA!",
  ["Same &mut memo goes into both calls, one after the other. The borrow checker is happy: they do not overlap."] = "Stejný &mut memo jde do obou volání, jedno po druhém. Borrow checker je spokojený: nepřekrývají se.",
  ["Same board, Rust this time. The question never changes: input doubles, then what?"] = "Stejná tabule, tentokrát Rust. Otázka se nikdy nemění: vstup se zdvojnásobí, a co pak?",
  ["Same built-in as for slices. A literal map[string]int{} also works."] = "Stejná vestavěná funkce jako pro slice. Literál map[string]int{} funguje také.",
  ["Same keyword as for slices. No index; just the value."] = "Stejné klíčové slovo jako u slice. Bez indexu; jen hodnota.",
  ["Same lesson as the Go till, one floor up: the resource is shared even when the memory is not."] = "Stejné ponaučení jako u kasy v Go o patro výš: zdroj je sdílený, i když paměť není.",
  ["Same name as Go's entry function, but it needs no package line."] = "Stejné jméno jako vstupní funkce v Go, ale nepotřebuje řádek s package.",
  ["Same name as on HashMap, but on a set it returns bool. No contains check needed first."] = "Stejné jméno jako na HashMap, ale na množině vrací bool. Není potřeba nejdřív kontrola přes contains.",
  ["Same name as strings.Contains. Index returns the position or -1."] = "Stejný název jako strings.Contains. Index vrací pozici nebo -1.",
  ["Same name as the Display helper on any value. to_string_pretty adds newlines."] = "Stejné jméno jako pomocník z Display na každé hodnotě. to_string_pretty přidá nové řádky.",
  ["Same name as the blocking one in the time module, but awaited."] = "Stejné jméno jako blokující verze v modulu time, ale s await.",
  ["Same name as the derived trait, in lowercase."] = "Stejné jméno jako derivovaný trait, malými písmeny.",
  ["Same row, one column to the left."] = "Stejný řádek, o jeden sloupec vlevo.",
  ["Same six letters as Go. Use it for early exits, not for the last line."] = "Stejných šest písmen jako v Go. Používej ho pro brzké ukončení, ne pro poslední řádek.",
  ["Same thing for both repos at once, with no edit to either go.mod. Which subcommand?"] = "Totéž pro oba repozitáře najednou, bez úpravy kteréhokoli go.mod. Který podpříkaz?",
  ["Same thing from a generator: setup, yield, teardown. Which contextlib decorator?"] = "Totéž z generátoru: příprava, yield, úklid. Který dekorátor z contextlib?",
  ["Same verb as go run. cargo build only compiles."] = "Stejné sloveso jako go run. cargo build jen kompiluje.",
  ["Same word as Go and Rust. Its sibling skips to the next turn instead."] = "Stejné slovo jako v Go a Rustu. Jeho sourozenec místo toho skočí na další kolo.",
  ["Same word as Go, but a method that changes the list in place and returns None."] = "Stejné slovo jako v Go, ale metoda, která seznam změní na místě a vrátí None.",
  ["Same word as Go, no quotes, no parentheses. from x import y picks one name out."] = "Stejné slovo jako v Go, bez uvozovek, bez závorek. from x import y vybere jediné jméno.",
  ["Same word as Go. Rust can drop it on the last line; Python cannot."] = "Stejné slovo jako v Go. Rust ho na posledním řádku může vynechat; Python ne.",
  ["Same word as WaitGroup's. It returns the first non-nil error."] = "Stejné slovo jako u WaitGroup. Vrací první error, který není nil.",
  ["Same word as a single import, then parentheses."] = "Stejné slovo jako u jednoho importu, pak závorky.",
  ["Same word as in switch. Turns select into a poll."] = "Stejné slovo jako ve switch. Ze select udělá neblokující dotaz.",
  ["Same word, one letter changed. Go has no public keyword; the first letter is the keyword."] = "Stejné slovo, jedno písmeno jinak. Go nemá klíčové slovo public; klíčovým slovem je první písmeno.",
  ["Same. Big O drops constants: O(2), O(500) are all O(1). The flat line is drawn."] = '„Same", stejná. Big O zahazuje konstanty: O(2), O(500) jsou všechno O(1). Plochá čára je nakreslená.',
  ["Same. Big O drops constants: O(2), O(500) are all written O(1). The flat line is drawn; the counter street is done."] = '„Same", stejná. Big O zahazuje konstanty: O(2), O(500) se všechny píší O(1). Plochá čára je nakreslená; ulice pultu je hotová.',
  ["Satisfied implicitly: any type with those methods implements it."] = "Splněno implicitně: každý typ s těmi metodami ho implementuje.",
  ["Save next, flip the link, advance both. prev is the new head when the loop ends."] = "Ulož next, otoč odkaz, posuň oba. Po skončení smyčky je prev nová hlava.",
  ["Save nxt, flip the pointer, step. Three names, one pass, O(1) space. The tuple swap on the last line steps both."] = "Ulož nxt, otoč ukazatel, krok. Tři jména, jeden průchod, O(1) prostoru. Výměna tuple na posledním řádku posune oba.",
  ["Schedules a call for later. Last in, first out. After the return happens."] = "Naplánuje volání na později. Poslední dovnitř, první ven. Až po return.",
  ["Second python, second core"] = "Druhý python, druhé jádro",
  ["Semantic import versioning: v1 and v2 are different packages with different paths, so one binary can depend on both and nothing breaks by surprise."] = "Sémantické verzování importů: v1 a v2 jsou různé balíčky s různými cestami, takže jedna binárka může záviset na obou a nic se nerozbije překvapením.",
  ["Semver tags and the /v2 rule"] = "Semver tagy a pravidlo /v2",
  ["Send a value into the channel. Fill the operator: ch ___ muffin"] = "Pošli hodnotu do kanálu. Doplň operátor: ch ___ muffin",
  ["Send one job now and keep the handle. Which method?"] = "Pošli jednu úlohu hned a nech si úchyt. Která metoda?",
  ["Send results back to the parent. Which multiprocessing class?"] = "Pošli výsledky zpátky rodiči. Která třída z multiprocessing?",
  ["Send the jobs, then tell the workers there are no more. Which built-in?"] = "Pošli úlohy, pak řekni workerům, že další nebudou. Která vestavěná funkce?",
  ["Send: safe to move to another thread. Sync: safe to share by &T. Rc has neither, Arc<T> has both when T does. The count is right. Milk tea and a pineapple bun: the afternoon tea set is yours."] = "Send: bezpečné přesunout do jiného vlákna. Sync: bezpečné sdílet přes &T. Rc nemá ani jedno, Arc<T> má obojí, když to má T. Počet je správný. Čaj s mlékem a ananasová houska: odpolední svačina je tvoje.",
  ["Sender is Clone, Receiver is not: that is the mp and the sc in mpsc. Both tills feed one kitchen."] = "Sender je Clone, Receiver ne: to je to mp a sc v mpsc. Obě pokladny krmí jednu kuchyni.",
  ["Separate interpreters mean separate memory: nothing is shared by accident, and everything shared on purpose has to be sent."] = "Oddělené interprety znamenají oddělenou paměť: nic se nesdílí omylem a všechno sdílené záměrně se musí poslat.",
  ['Serve /order with the function serve. Fill: http.___("/order", serve)'] = 'Obsluhuj /order funkcí serve. Doplň: http.___("/order", serve)',
  ["Serve three bowls, numbered 0, 1, 2. Which built-in counts for the for loop?"] = "Vydat tři misky, očíslované 0, 1, 2. Která vestavěná funkce počítá pro cyklus for?",
  ["SetMeal extends Order and must run Order's __init__ first. Which built-in reaches the parent?"] = "SetMeal rozšiřuje Order a musí nejdřív spustit __init__ z Order. Která vestavěná funkce sáhne na rodiče?",
  ["Setting a channel to nil disables its case without touching the loop. It is the standard way to drain two inputs that end at different times."] = "Nastavení kanálu na nil vypne jeho větev, aniž bys sáhl na smyčku. Je to standardní způsob, jak vyprázdnit dva vstupy, které končí v různou dobu.",
  ["Seven letters, an adverb: at the end, no matter what. Go's defer."] = "Sedm písmen, příslovce: na konci, ať se děje cokoli. defer z Go.",
  ["Seven letters, the end of almost every iterator chain. The type annotation on the left tells it what to build."] = "Sedm písmen, konec skoro každého řetězce iterátorů. Anotace typu vlevo mu říká, co postavit.",
  ["Seven letters, the opposite of acquire. Go writes it defer mu.Unlock()."] = "Sedm písmen, opak acquire. Go to píše defer mu.Unlock().",
  ["Seven letters, the unbounded one. sync_channel(n) would take a capacity."] = "Sedm písmen, ta neomezená varianta. sync_channel(n) by bralo kapacitu.",
  ["Seven letters, to take back a statement. Go 1.16. The tag stays; go get stops choosing it."] = "Sedm písmen, vzít prohlášení zpět. Go 1.16. Tag zůstává; go get ho přestane vybírat.",
  ["Seven letters. Does the value ... this pattern? Same verb, plural form."] = "Sedm písmen. Odpovídá hodnota tomuto vzoru? Anglické sloveso ve tvaru třetí osoby.",
  ["Seven letters. For humans; Debug is for {:?}."] = "Sedm písmen. Pro lidi; Debug je pro {:?}.",
  ["Seven letters. Gather everything into a container: Vec, String, HashMap, even Result."] = "Sedm písmen. Posbírej všechno do kontejneru: Vec, String, HashMap, i Result.",
  ["Seven letters. Go spelled it chan."] = "Sedm písmen. Go to psalo jako chan.",
  ["Seven letters. The opposite of a debug build. The binary lands in target/ under that name."] = "Sedm písmen. Opak debug buildu. Binárka skončí v target/ pod tím jménem.",
  ["Seven letters: a whole server process that owns the objects and answers questions about them."] = "Sedm písmen: celý serverový proces, který ty objekty vlastní a odpovídá na dotazy o nich.",
  ["Seven letters: swap one thing for another. The arrow reads 'with'."] = "Sedm písmen: vyměnit jednu věc za jinou. Šipka se čte „za“.",
  ["Seven letters: to need. Several of them go in one parenthesised block."] = "Sedm písmen: potřebovat. Několik jich jde do jednoho bloku v závorkách.",
  ["Seven streets of Big O. Read a loop, name its cost, then write the faster one, in Go."] = "Sedm ulic Big O. Přečti cyklus, pojmenuj jeho cenu, pak napiš rychlejší verzi, v Go.",
  ["Seven streets of Big O. Read a loop, name its cost, then write the faster one, in Python."] = "Sedm ulic Big O. Přečti cyklus, pojmenuj jeho cenu, pak napiš rychlejší verzi, v Pythonu.",
  ["Seven streets of Big O. Read a loop, name its cost, then write the faster one, in Rust."] = "Sedm ulic Big O. Přečti cyklus, pojmenuj jeho cenu, pak napiš rychlejší verzi, v Rustu.",
  ["Shared and mutable across threads: wrap it, then lock it."] = "Sdílené a měnitelné napříč vlákny: zabal to, pak to zamkni.",
  ["Shared references and data races"] = "Sdílené reference a datové souběhy",
  ["Shipped. One more: the code still sorts by hand."] = "Nasazeno. Ještě jedno: kód pořád řadí ručně.",
  ["Short declaration. Fill the operator: floor ___ 8"] = "Krátká deklarace. Doplň operátor: floor ___ 8",
  ["Short for format. Println lives there."] = "Zkratka slova format. Println bydlí tam.",
  ["Short for function. Then the name, then arguments in parentheses."] = "Zkratka slova function. Pak jméno, pak argumenty v závorkách.",
  ["Shout the shop name. Which strings function upper-cases?"] = "Zakřič název obchodu. Která funkce ze strings dělá velká písmena?",
  ["Shouted in capitals, and also an environment variable. GO, MAX, and short for processors."] = "Křičí se velkými písmeny a je to i proměnná prostředí. GO, MAX a zkratka pro procesory.",
  ["Signed, 32 bits, the default integer type. Write the annotation."] = "Se znaménkem, 32 bitů, výchozí celočíselný typ. Napiš anotaci.",
  ["Since Go 1.17 go.mod lists every module the build needs, direct or not, so one file describes the whole graph. go mod tidy keeps the comments honest."] = "Od Go 1.17 go.mod vypisuje každý modul, který build potřebuje, přímý či ne, takže jeden soubor popisuje celý graf. go mod tidy udržuje komentáře poctivé.",
  ["Since Go 1.19 the type itself is atomic, so no &x is needed. Name and bit width."] = "Od Go 1.19 je atomický sám typ, takže žádné &x není potřeba. Jméno a šířka v bitech.",
  ["Since Python 3.8 this is real POSIX shared memory: one block of bytes, mapped into every process that asks for it by name."] = "Od Pythonu 3.8 je tohle skutečná POSIXová sdílená paměť: jeden blok bajtů namapovaný do každého procesu, který si o něj řekne jménem.",
  ["Siu Ming"] = "Siu Ming",
  ["Siu Ming draws the Causeway Bay MTR exit: n steps. Then the till: coins of 1, 3 and 4, and an amount to make with the fewest coins. Two problems, one trick: write the answer for the small cases, then build every bigger one out of the ones already on the board."] = "Siu Ming kreslí výstup z MTR Causeway Bay: n schodů. Pak pokladnu: mince 1, 3 a 4 a částku, kterou složit z co nejméně mincí. Dva problémy, jeden trik: napiš odpověď pro malé případy, pak každý větší postav z těch, co už jsou na tabuli.",
  ["Siu Ming pins a strip of numbers to the board: Lucky Mac's daily profit for a month, red on the bad days. Best run of days, best k days in a row, longest run of distinct dishes on the specials board. Three questions, one shape: a window that slides right and never looks back."] = "Siu Ming připne na tabuli pásku čísel: denní zisk Lucky Macu za měsíc, špatné dny červeně. Nejlepší série dnů, nejlepších k dnů v řadě, nejdelší řada různých jídel na tabuli specialit. Tři otázky, jeden tvar: okno, které jede doprava a nikdy se neohlíží.",
  ["Siu Ming pins the week's roster to the board: thirty shifts, half of them overlapping, the manager wants one clean line per stretch of coverage, and then how many cooks are ever on at once. Mei taps the first column: sort by start and the mess becomes a walk."] = "Siu Ming připne na tabuli rozpis týdne: třicet směn, půlka se překrývá, manažer chce jednu čistou čáru na každý souvislý úsek pokrytí a pak kolik kuchařů je kdy najednou ve službě. Mei ťukne na první sloupec: seřaď podle začátku a z chaosu je procházka.",
  ["Siu Ming's phone book of suppliers, sorted by name. Nobody reads it from the front. Open the middle, go left or right, and the book is half as thick every time. Mei draws a line that climbs, then almost stops."] = "Telefonní seznam dodavatelů Siu Minga, seřazený podle jména. Nikdo ho nečte od začátku. Otevři uprostřed, jdi vlevo nebo vpravo a kniha je pokaždé o polovinu tenčí. Mei kreslí čáru, která stoupá a pak se téměř zastaví.",
  ["Siu Ming's phone book of suppliers, sorted by name. Open the middle, go left or right, and the book is half as thick every time. Mei draws the line that climbs, then almost lies down."] = "Telefonní seznam dodavatelů Siu Minga, seřazený podle jména. Otevři uprostřed, jdi vlevo nebo vpravo a kniha je pokaždé o polovinu tenčí. Mei kreslí čáru, která stoupá a pak si téměř lehne.",
  ["Six goroutines write one slice with no lock. Which expression keeps that safe?"] = "Šest goroutin zapisuje bez zámku do jednoho slicu. Který výraz to udrží bezpečné?",
  ["Six letters, capital O. Rust's answer to nil: the type itself says maybe."] = "Šest písmen, velké O. Odpověď Rustu na nil: sám typ říká možná.",
  ["Six letters, same word as Go, but there is no type keyword in front."] = "Šest písmen, stejné slovo jako v Go, ale před ním není klíčové slovo type.",
  ["Six letters, takes a reference to the key, returns the old value as Option."] = "Šest písmen, bere referenci na klíč, vrací starou hodnotu jako Option.",
  ["Six letters, the most recent. @v1 or @main work too: a major, a branch, a commit hash."] = "Šest písmen, nejnovější. Funguje i @v1 nebo @main: major, větev, hash commitu.",
  ["Six letters, the noun for what a function gives back. This one blocks until it exists."] = "Šest písmen, podstatné jméno pro to, co funkce vrací. Tohle blokuje, dokud to nebude existovat.",
  ["Six letters, the same method a HashMap uses to store a key. Takes the value, not a reference."] = "Šest písmen, stejná metoda, kterou HashMap ukládá klíč. Bere hodnotu, ne referenci.",
  ["Six letters, the same word the C library uses for deleting a file."] = "Šest písmen, stejné slovo, jaké céčková knihovna používá pro smazání souboru.",
  ["Six letters, the word Unix uses for a background service."] = "Šest písmen, slovo, kterým Unix označuje službu na pozadí.",
  ["Six letters, the word for a supplier. The folder it makes has the same name."] = "Šest písmen, slovo pro dodavatele. Složka, kterou vytvoří, má stejné jméno.",
  ["Six letters, the write of every HashMap. Returns the previous value as Option."] = "Šest písmen, zápis u každé HashMap. Vrací předchozí hodnotu jako Option.",
  ["Six letters, under sync/. Go 1.19 also has atomic.Int64 with .Add(1)."] = "Šest písmen, pod sync/. Go 1.19 má i atomic.Int64 s .Add(1).",
  ["Six letters, what you do with a form. It returns immediately, with a Future."] = "Šest písmen, to, co uděláš s formulářem. Vrací se hned a s Future.",
  ["Six letters. Every result, in order, comma separated."] = "Šest písmen. Každý výsledek, v pořadí, oddělený čárkou.",
  ["Six letters. Generic over T: Some(T) or None."] = "Šest písmen. Generický přes T: Some(T) nebo None.",
  ["Six letters. Give the field a different name on the wire. rename_all does a whole struct."] = "Šest písmen. Dej poli na drátě jiné jméno. rename_all zvládne celý struct.",
  ["Six letters. Like a coffee one: only what passes the test comes through."] = "Šest písmen. Jako ten na kávu: projde jen to, co splní test.",
  ["Six letters. The closure gets &char and returns bool; true keeps the item."] = "Šest písmen. Closure dostane &char a vrací bool; true prvek ponechá.",
  ["Six letters. The compiler writes the trait implementation for you."] = "Šest písmen. Kompilátor napíše implementaci traitu za tebe.",
  ["Six letters. The word in fmt spelled out. Variables can go straight inside the braces."] = "Šest písmen. Slovo z fmt vypsané celé. Proměnné můžou rovnou do složených závorek.",
  ["Six letters. To obtain from a source."] = "Šest písmen. Odvodit ze zdroje.",
  ["Six letters. Two arms: Ok(T) and Err(E)."] = "Šest písmen. Dvě varianty: Ok(T) a Err(E).",
  ["Six letters. What you do when you are sure it is there."] = "Šest písmen. To, co děláš, když jsi si jistý, že to tam je.",
  ["Six letters: straight to the source, no proxy in between."] = "Šest písmen: rovnou ke zdroji, bez proxy mezi tím.",
  ["Six letters: to bring together. tokio::join! does the same for a fixed number."] = "Šest písmen: shromáždit. tokio::join! dělá totéž pro pevný počet.",
  ["Six letters; other languages say catch. Name the type after it, never bare."] = "Šest písmen; jiné jazyky říkají catch. Za ním pojmenuj typ, nikdy holé.",
  ["Six riders wait on the kerb because the backend asks the map API one address at a time."] = "Šest kurýrů čeká na obrubníku, protože backend se ptá mapového API na jednu adresu po druhé.",
  ["Six tickets sent. Now end the cooks' loops: recv must return Err. What do you do with tx?"] = "Šest lístků odesláno. Teď ukonči smyčky kuchařů: recv musí vrátit Err. Co uděláš s tx?",
  ["Six woks, one tray rack, one map of dish counts. The program died with: concurrent map writes."] = "Šest woků, jeden regál a jedna mapa s počty jídel. Program umřel s hláškou: concurrent map writes.",
  ["Six workers, one out channel. Who ends the range over out, and how?"] = "Šest workerů, jeden kanál out. Kdo a jak ukončí range nad out?",
  ["Size the pool by the machine. Which runtime call reports the cores?"] = "Nastav velikost fondu podle stroje. Které volání runtime hlásí počet jader?",
  ["Skip a closed shop and go on to the next one. Which keyword?"] = "Přeskoč zavřený obchod a jdi na další. Které klíčové slovo?",
  ["Skip writing __init__, __repr__ and __eq__ by hand. Which decorator generates them from the fields?"] = "Ušetřit si ruční psaní __init__, __repr__ a __eq__. Který dekorátor je vygeneruje z polí?",
  ["Slices alias. Use copy() or append([]int(nil), a...) when you need your own."] = "Slice sdílejí paměť. Použij copy() nebo append([]int(nil), a...), když potřebuješ vlastní.",
  ["Sliding window, two pointers"] = "Posuvné okno, dva ukazatele",
  ["Sliding window: O(n) instead of O(n*k) for summing every window from scratch."] = "Posuvné okno: O(n) místo O(n*k) za sčítání každého okna od nuly.",
  ["Sliding windows and two pointers"] = "Posuvná okna a dva ukazatele",
  ["Smaller goes left, bigger goes right. Draw it before you type it."] = "Menší doleva, větší doprava. Nakresli si to, než to napíšeš.",
  ["Smaller goes left, bigger goes right. In Rust a leaf is None and a child is a Box."] = "Menší jde doleva, větší doprava. V Rustu je list None a potomek je Box.",
  ["Smaller left, larger right: the BST invariant. Assigning the result back handles the None case."] = "Menší vlevo, větší vpravo: invariant BST. Přiřazení výsledku zpět řeší případ None.",
  ["Smaller values go down one side. Fill the arm: if v < n.val => insert(&mut n.___, v)"] = "Menší hodnoty jdou dolů jednou stranou. Doplň větev: if v < n.val => insert(&mut n.___, v)",
  ["Smaller values go left. Fill: n.Left = insert(n.___, v)"] = "Menší hodnoty jdou doleva. Doplň: n.Left = insert(n.___, v)",
  ["Smaller wins: the smallest value floats to index 0."] = "Menší vyhrává: nejmenší hodnota vyplave na index 0.",
  ["So I only have to know which one waits and which one computes."] = "Takže si stačí pamatovat, který čeká a který počítá.",
  ["So binary search on n sorted items costs how much, in Big O?"] = "Takže binární vyhledávání v n seřazených položkách stojí kolik, v Big O?",
  ["So binary_search on n sorted items costs how much, in Big O?"] = "Takže binary_search v n seřazených položkách stojí kolik, v Big O?",
  ["So bisect on n sorted items costs how much, in Big O?"] = "Takže bisect v n seřazených položkách stojí kolik, v Big O?",
  ["So put it somewhere they cannot reach. Go has a folder name for exactly that."] = "Tak ji dej tam, kam nedosáhnou. Go má na to přesně jméno složky.",
  ["So share the bytes and send only the name of the block?"] = "Takže sdílet bajty a poslat jen jméno toho bloku?",
  ["Sockets, file handles, locks and lambdas do not travel. Send plain data and let the child open what it needs on its own side."] = "Sockety, souborové handly, zámky a lambdy neputují. Posílej holá data a nech potomka otevřít si, co potřebuje, na své straně.",
  ["Sogo"] = "Sogo",
  ["Sogo's directory is a map from shop name to floor. Missing keys return the zero value, so you must ask comma-ok before you trust the number."] = "Adresář v Sogo je mapa z názvu obchodu na patro. Chybějící klíče vracejí nulovou hodnotu, takže se musíš zeptat comma-ok, než číslu uvěříš.",
  ["Some or None. Rust has no null, so the possibly-empty next is spelled out in the type."] = "Some nebo None. Rust nemá null, takže případná prázdnota v next je vypsaná přímo v typu.",
  ["Sort by start, then walk once: if the next interval starts before the last merged one ends, extend that end to the larger; otherwise push a new interval. O(n log n) for the sort, O(n) for the walk."] = "Seřaď podle začátku, pak jeden průchod: když další interval začíná dřív, než poslední sloučený končí, prodluž ten konec na větší; jinak pushni nový interval. O(n log n) za řazení, O(n) za průchod.",
  ["Sort by start. Walk once: if the next interval starts before the last merged one ends, extend that end to the larger of the two; otherwise start a new block."] = "Seřaď podle začátku. Projdi jednou: pokud další interval začíná dřív, než poslední sloučený končí, prodluž ten konec na větší z obou; jinak začni nový blok.",
  ["Sort first, Bo. Once they're in order, overlaps are always neighbours."] = "Nejdřív seřaď, Bo. Jakmile jsou v pořadí, překryvy jsou vždycky sousedi.",
  ["Sort first. Sorted, the only interval that can overlap is the one you just kept."] = "Nejdřív seřaď. Po seřazení se může překrývat jen ten interval, který sis právě nechal.",
  ["Sort intervals by start; then every overlap is adjacent. Overlap when cur's start <= last's end: extend last's end with max. Otherwise append. Rooms: sort starts and ends separately, two pointers."] = "Seřaď intervaly podle začátku; pak každý překryv sousedí. Překryv, když začátek cur <= konec last: prodluž konec last pomocí max. Jinak append. Místnosti: seřaď začátky a konce zvlášť, dva ukazatele.",
  ["Sort once for O(n log n), then look items up many times. Each lookup then costs O(___)"] = "Seřadit jednou za O(n log n), pak položky mnohokrát vyhledávat. Každé vyhledání pak stojí O(___)",
  ["Sort orders by price with a one-line function. Which keyword makes it?"] = "Seřadit objednávky podle ceny jednořádkovou funkcí. Které klíčové slovo ji vytvoří?",
  ["Sort the amounts a little faster, when equal items may swap order. Which Vec method?"] = "Seřadit částky o něco rychleji, když si stejné položky mohou prohodit pořadí. Která metoda Vec?",
  ["Sort the dish names by length, into a new list. Which built-in?"] = "Seřadit jména jídel podle délky do nového seznamu. Která vestavěná funkce?",
  ["Sort the dish names shortest first, in place. Which built-in is the key?"] = "Seřadit jména jídel od nejkratšího, na místě. Která vestavěná funkce je key?",
  ["Sort the intervals by start, earliest first. Fill the comparison."] = "Seřaď intervaly podle začátku, nejdřívější první. Doplň porovnání.",
  ["Sort the names in place. Fill: slices.___(names)"] = "Seřaď jména na místě. Doplň: slices.___(names)",
  ["Sort the shifts by start time so overlaps sit side by side. Which element does the key pick?"] = "Seřaď směny podle času začátku, aby překryvy seděly vedle sebe. Který prvek key vybere?",
  ["Sort the supplier names. Which function from the sort package?"] = "Seřadit jména dodavatelů. Která funkce z balíčku sort?",
  ["Sort, then one pass with a running last: O(n log n) total, O(n) output. The gaps are between the blocks."] = "Seřaď, pak jeden průchod s průběžným last: celkem O(n log n), O(n) výstup. Díry jsou mezi bloky.",
  ["Sorted input trades the HashMap for two indices: O(n) time and O(1) space after the sort."] = "Seřazený vstup vymění HashMap za dva indexy: O(n) času a O(1) paměti po seřazení.",
  ["Sorted prices. Find 25 in log n. Then sort the unsorted ones in n log n."] = "Seřazené ceny. Najdi 25 v log n. Pak seřaď ty neseřazené v n log n.",
  ["Sorted. Sorting costs O(n log n) once; every search after is O(log n). The phone book street is done."] = '„Sorted", seřazený. Třídění stojí O(n log n) jednou; každé vyhledání potom je O(log n). Ulice telefonního seznamu je hotová.',
  ["Sorting and searching"] = "Řazení a vyhledávání",
  ["Sorting: n log n"] = "Třídění: n log n",
  ["Sounds like request, spelled with a w. Built on hyper and tokio."] = "Zní jako request, píše se s w. Postaveno na hyperu a tokiu.",
  ["Space complexity"] = "Prostorová složitost",
  ["Space counts extra memory, not the input. In-place sort: O(1). A copy of the list: O(n). Recursion uses stack: quicksort O(log n) on average. Memos trade space for time."] = "Prostor počítá paměť navíc, ne vstup. Třídění na místě: O(1). Kopie seznamu: O(n). Rekurze používá zásobník: quicksort O(log n) v průměru. Mema mění prostor za čas.",
  ["Space counts extra memory, not the input. list.sort in place: O(1). sorted() makes a copy: O(n). Recursion uses stack: quicksort O(log n) on average. Memos trade space for time."] = "Prostor počítá paměť navíc, ne vstup. list.sort na místě: O(1). sorted() dělá kopii: O(n). Rekurze používá zásobník: quicksort O(log n) v průměru. Mema mění prostor za čas.",
  ["Space counts extra memory, not the input. sort_unstable in place: O(1). A clone of the Vec: O(n). Recursion uses stack: quicksort O(log n) on average. Memos trade space for time."] = "Prostor počítá paměť navíc, ne vstup. sort_unstable na místě: O(1). Klon Vec: O(n). Rekurze používá zásobník: quicksort O(log n) v průměru. Mema mění prostor za čas.",
  ["Spawn re-imports your file in the child. Anything at top level runs again, including the spawning."] = "spawn si tvůj soubor v potomkovi naimportuje znovu. Všechno na nejvyšší úrovni se spustí zas, včetně toho spouštění.",
  ["Split in half, sort each half, merge. The merge is where the n comes from."] = "Rozděl napůl, seřaď každou půlku, sluč. Z slučování pochází to n.",
  ["Split the app into packages and let the Times Square shop import it from GitHub. Paths, go.mod, go get, tags. Ship v1.0.0."] = "Rozděl aplikaci na balíčky a nech obchod na Times Square, ať si ji importuje z GitHubu. Cesty, go.mod, go get, tagy. Vydej v1.0.0.",
  ["Spread to all four neighbours: down, up, right, and the last one. Fill it."] = "Rozšiř se na všechny čtyři sousedy: dolů, nahoru, vpravo a ten poslední. Doplň ho.",
  ["Sprintf returns the text. %s string, %d int, %v anything."] = "Sprintf vrací text. %s string, %d int, %v cokoli.",
  ["Stairs, one or two steps at a time. How many ways reach step 2?"] = "Schody, jeden nebo dva najednou. Kolika způsoby se dostaneš na schod 2?",
  ["Star before the type. & takes the address. *p reads through it."] = "Hvězdička před typem. & vezme adresu. *p čte skrz něj.",
  ["Star then the type name. A value receiver (o Order) would change a copy."] = "Hvězdička a pak název typu. Hodnotový receiver (o Order) by změnil kopii.",
  ["Start a new module for the project. Fill the subcommand: go ___ init"] = "Založ pro projekt nový modul. Doplň podpříkaz: go ___ init",
  ["Start a new thread that runs this closure. Which function?"] = "Spusť nové vlákno, které provede tuto closure. Která funkce?",
  ["Start a task in the background and keep going. Which tokio function?"] = "Spusť task na pozadí a pokračuj dál. Která funkce z tokia?",
  ["Start an anonymous function as a goroutine. What closes the line?"] = "Spusť anonymní funkci jako goroutine. Co uzavírá řádek?",
  ["Start fetch in the background and keep going without awaiting it yet. Which asyncio function?"] = "Spustit fetch na pozadí a pokračovat, aniž by se na něj zatím čekalo. Která funkce z asyncio?",
  ["Start fry() in a new goroutine. Which keyword?"] = "Spusť fry() v nové goroutine. Které klíčové slovo?",
  ["Start the event loop with main(). Which asyncio function?"] = "Spustit smyčku událostí s main(). Která funkce z asyncio?",
  ["Start the fetch without waiting for it. Which keyword is Go's async?"] = "Spusť fetch, aniž bys na něj čekal. Které klíčové slovo je async v Go?",
  ['Start the server on port 8080 and block. Fill: http.___(":8080", nil)'] = 'Spusť server na portu 8080 a blokuj. Doplň: http.___(":8080", nil)',
  ["Start them all first, then join them all: otherwise the second loop waits for the first wok before lighting the second."] = "Nejdřív všechny spusť, pak na všechny čekej: jinak druhý cyklus čeká na první wok, než zapálí druhý.",
  ["Start three workers, counting each one first. Fill: wg.___(1)"] = "Spusť tři workery, každého nejdřív započítej. Doplň: wg.___(1)",
  ["Start with an empty dict. What literal is it?"] = "Začít s prázdným dictem. Jaký je to literál?",
  ["Starting at 0 would answer 0 for [-3, -1]; the right answer is -1. Seed from the data."] = "Start na 0 by pro [-3, -1] odpověděl 0; správná odpověď je -1. Zasej z dat.",
  ["Starts like is_some(), then one more word joining a condition. Three words, two underscores."] = "Začíná jako is_some(), pak ještě jedno slovo připojující podmínku. Tři slova, dvě podtržítka.",
  ["Station to its neighbours: a dict whose missing keys start as an empty list. Fill the factory."] = "Stanice na své sousedy: dict, jehož chybějící klíče začínají jako prázdný seznam. Doplň továrnu.",
  ["Steam. Hash brown. We did it."] = "Pára. Hash brown. Dokázali jsme to.",
  ["Step i is reached from one step below or two steps below. Fill dp[i]."] = "Na schod i se dostaneš z jednoho schodu níž nebo ze dvou níž. Doplň dp[i].",
  ["Stop everything: the till has no paper and that is a bug. Which built-in raises the crash?"] = "Zastav vše: v pokladně došel papír a to je bug. Která vestavěná funkce vyvolá pád?",
  ["Stop the child from spawning children. Which dunder goes in the guard?"] = "Zabraň potomkovi, aby plodil další potomky. Který dunder patří do stráže?",
  ["Stop when the guest walks out. Fill: case <-ctx.___()"] = "Zastav, když host odejde. Doplň: case <-ctx.___()",
  ["StopIteration ends the protocol; return inside a generator raises it. The conveyor serves ten thousand bowls, one at a time."] = "StopIteration ukončí protokol; return uvnitř generátoru ji vyhodí. Dopravník vydá deset tisíc misek, jednu po druhé.",
  ["Store into memo[n] before returning. Same shape works for any overlapping subproblem."] = "Před návratem ulož do memo[n]. Stejný vzor funguje pro každý překrývající se podproblém.",
  ["String and &str"] = "String a &str",
  ["String owns, &str borrows. len() counts bytes, chars().count() counts characters."] = "String vlastní, &str si půjčuje. len() počítá bajty, chars().count() počítá znaky.",
  ["String() string satisfies fmt.Stringer. Println and %v call it automatically."] = "String() string splňuje fmt.Stringer. Println a %v ji volají automaticky.",
  ['String::from("..") or "..".to_string(). &str borrows, String owns and can grow.'] = 'String::from("..") nebo "..".to_string(). &str si půjčuje, String vlastní a může růst.',
  ['Strings, not ints: "1" != 1 in Python. Read the input type before the first line.'] = 'Řetězce, ne inty: "1" != 1 v Pythonu. Přečti si typ vstupu před prvním řádkem.',
  ["Strings, runes, bytes"] = "Stringy, runy, bajty",
  ["Struct tags and encoding/json"] = "Struct tagy a encoding/json",
  ["Struct tags are strings after the type. json, xml, db... each package reads its own."] = "Struct tagy jsou stringy za typem. json, xml, db... každý balíček čte ten svůj.",
  ["Structs, pointers, methods, interfaces"] = "Structy, ukazatele, metody, rozhraní",
  ["Sum of every window of k items: add the newcomer, subtract the one that just left. Which index left?"] = "Součet každého okna k prvků: přičti nováčka, odečti toho, kdo právě odešel. Který index odešel?",
  ["Summing n prices with an iterator: what is the cost in Big O?"] = "Sečíst n cen iterátorem: jaká je cena v Big O?",
  ["Swap the first word for Thread and the same block does I/O instead. That is the whole API: one word decides which kind of parallelism you get."] = "Vyměň první slovo za Thread a stejný blok dělá I/O. To je celé API: jedno slovo rozhodne, jaký druh paralelismu dostaneš.",
  ["Swap the whole menu in one step while readers are reading. Which atomic type?"] = "Vyměň celé menu jedním krokem, zatímco čtenáři čtou. Který atomický typ?",
  ["Switch one select case off for good. What do you set the channel to?"] = "Vypni jednu větev selectu natrvalo. Na co kanál nastavíš?",
  ["T: PartialOrd + Copy. Bounds are checked at compile time, so largest(&[1.5, 2.5]) and largest(&[18, 22]) both work."] = "T: PartialOrd + Copy. Omezení se kontrolují při kompilaci, takže largest(&[1.5, 2.5]) i largest(&[18, 22]) fungují.",
  ["TAB again: answer   ESC map"] = "TAB znovu: odpověď   ESC mapa",
  ["TAB hint   F5 auto   ESC map"] = "TAB tip   F5 auto   ESC mapa",
  ["TAB hint   F5 auto   F6 share   ESC map"] = "TAB nápověda   F5 auto   F6 sdílet   ESC mapa",
  ["THREADS  -  the lunch rush"] = "THREADS  -  polední špička",
  ["THREADS  ·  the lunch rush"] = "THREADS  ·  polední špička",
  ["THREE LANGUAGES"] = "TŘI JAZYKY",
  ["Table 7 has a seat. Every other table has nothing. What does the last line return?"] = "Stůl 7 má místo. Každý jiný stůl nemá nic. Co vrací poslední řádek?",
  ["Tag it v1.0.0"] = "Otaguj to v1.0.0",
  ["Tags are immutable in Go's world: moving one breaks every go.sum that saw it. retract, then tag v1.0.2, is the only honest fix."] = "Ve světě Go jsou tagy neměnné: posunutí jednoho rozbije každý go.sum, který ho viděl. retract a pak tag v1.0.2 je jediná poctivá oprava.",
  ["Take any Cook without naming a type parameter. Which keyword goes before the trait?"] = "Vezmi libovolného Cook bez pojmenování typového parametru. Které klíčové slovo patří před trait?",
  ["Take one back out of the buffered channel. Arrow, then the channel's name."] = "Vezmi jeden zpátky z kanálu s bufferem. Šipka a pak jméno kanálu.",
  ["Take one from stock, but only if nobody moved it since you read it. Which method?"] = "Odeber jeden kus ze skladu, ale jen pokud s ním od tvého čtení nikdo nehnul. Která metoda?",
  ['Take the address of a new Order so p is a *Order. Fill: p := ___Order{Item: "set"}'] = 'Vezmi adresu nového Order, aby p bylo *Order. Doplň: p := ___Order{Item: "set"}',
  ["Take the front station off the queue. Fill: queue = queue[___]"] = "Vezmi přední stanici z fronty. Doplň: queue = queue[___]",
  ["Take the next result, waiting if the queue is empty. Which method?"] = "Vezmi další výsledek a počkej, pokud je fronta prázdná. Která metoda?",
  ["Take the second and third tray, items 1 and 2. What goes in the brackets?"] = "Vzít druhý a třetí tác, položky 1 a 2. Co patří do hranatých závorek?",
  ["Take the station that has waited longest. Which VecDeque method returns Option<u32> from the front?"] = "Vezmi stanici, která čeká nejdéle. Která metoda VecDeque vrátí Option<u32> zepředu?",
  ["Takes the key and the value by value. Returns the old value as an Option, which we ignore here."] = "Bere klíč i hodnotu hodnotou. Vrací starou hodnotu jako Option, kterou tady ignorujeme.",
  ["Tea first, lifetimes second. The set is almost ready."] = "Nejdřív čaj, pak lifetimy. Menu je skoro hotové.",
  ['Teach println!("{}") to print an Order. Which fmt trait?'] = 'Nauč println!("{}") vypsat Order. Který trait z fmt?',
  ["Tell an empty order from a shut belt. Name the second variable of the receive."] = "Odliš prázdnou objednávku od zastaveného pásu. Pojmenuj druhou proměnnou příjmu.",
  ["Tell receivers no more hash browns will come. Which built-in?"] = "Řekni příjemcům, že další hash browny už nepřijdou. Která vestavěná funkce?",
  ["Test the package the way a caller sees it. Fill the suffix of the test package name."] = "Testuj balíček tak, jak ho vidí volající. Doplň příponu jména testovacího balíčku.",
  ["Text plus a number fails. Which built-in turns 4 into text first?"] = "Text plus číslo selže. Která vestavěná funkce nejdřív udělá ze 4 text?",
  ["That is BFS: pop front, push unseen neighbours. First arrival is the shortest path."] = "To je BFS: vyjmi zepředu, přidej nenavštívené sousedy. První příchod je nejkratší cesta.",
  ["That is a trait. Go had interfaces; Rust makes you say impl."] = "To je trait. Go mělo rozhraní; Rust tě nutí napsat impl.",
  ["That is the module path doing its job. Now he needs it pinned, or tomorrow's build is a different program."] = "To cesta modulu dělá svou práci. Teď ji potřebuje připíchnout, jinak je zítřejší build jiný program.",
  ["That is the second value of a receive. One line tells you which."] = "To je ta druhá hodnota u příjmu. Jeden řádek ti řekne, co z toho.",
  ["That is why the sender closes: only the side that knows nothing more is coming can say so safely."] = "Proto zavírá odesílatel: bezpečně to může říct jen ta strana, která ví, že už nic nepřijde.",
  ["That push is the release. The proxy notices the tag the first time anyone asks for it; there is nothing else to upload."] = "Ten push je vydání. Proxy si tagu všimne, jakmile ho poprvé někdo požaduje; nic dalšího není třeba nahrávat.",
  ["The ! marks a macro call. Macros can take any number of arguments; functions cannot."] = "! označuje volání makra. Makra mohou brát libovolný počet argumentů; funkce ne.",
  ["The * you would write in resize(*job), spelled out, then map."] = "Ta hvězdička, kterou bys napsal v resize(*job), vypsaná slovem, a k tomu map.",
  ["The 1 a.m. callback is the Python round. Seven whiteboard classics. Get the OFFER."] = "Callback v jednu ráno je kolo Pythonu. Sedm klasik od tabule. Získej OFFER.",
  ["The 11:00 price change holds the write side. Which call does a reader make?"] = "Změna cen v 11:00 drží zapisovací stranu. Jak volá čtenář?",
  ["The Express counter"] = "Pult Express",
  ["The Express kiosks run Rust. Finish your coffee, I will show you main."] = "Kiosky Express běží v Rustu. Dopij kávu, ukážu ti main.",
  ["The Express kitchen"] = "Kuchyň v Expressu",
  ["The Express set"] = "Menu v Expressu",
  ["The Express till"] = "Kasa v Expressu",
  ["The GIL protects CPython's own memory bookkeeping. It makes single-threaded code fast and multi-threaded arithmetic pointless."] = "GIL chrání vlastní účetnictví paměti v CPythonu. Dělá jednovláknový kód rychlým a vícevláknovou aritmetiku zbytečnou.",
  ["The GIL serializes bytecode; C extensions and I/O release it. Python 3.13 can build without it. Three woks fry at once; the shift is over."] = "GIL serializuje bytecode; rozšíření v C a I/O ho uvolňují. Python 3.13 lze sestavit bez něj. Tři woky smaží najednou; směna skončila.",
  ["The Go 1.21 builtin that picks the larger of two ints."] = "Builtin z Go 1.21, který vybere větší ze dvou intů.",
  ["The I in the middle of GIL, written out: the thing that runs your bytecode."] = "To I uprostřed GIL, vypsané celé: to, co spouští tvůj bajtkód.",
  ['The JSON says "dish" but the field is name. Which serde attribute maps them?'] = 'JSON říká "dish", ale pole je name. Který atribut serde je namapuje?',
  ["The MTR gate is a function: tap(card) (ok bool, err error). Go functions can return more than one value. That is how errors travel."] = "Turniket MTR je funkce: tap(card) (ok bool, err error). Funkce v Go mohou vracet víc než jednu hodnotu. Tak cestují chyby.",
  ["The MTR map is a graph. Level by level is BFS; as deep as you can is DFS."] = "Mapa MTR je graf. Úroveň po úrovni je BFS; co nejhlouběji je DFS.",
  ["The O(n) fix: remember each name as you go. What value type makes the map a set?"] = "Oprava na O(n): pamatovat si každé jméno za pochodu. Který typ hodnoty udělá z mapy množinu?",
  ["The O(n) fix: remember each name as you go. Which built-in is the set?"] = "Oprava na O(n): pamatovat si každé jméno za pochodu. Která vestavěná funkce je ta množina?",
  ["The O(n) fix: remember each name as you go. Which std collection is the set?"] = "Oprava na O(n): pamatovat si každé jméno za pochodu. Která kolekce ze std je ta množina?",
  ["The __name__ guard: the script runs main() when executed, stays quiet when imported. The shift begins."] = "Stráž __name__: skript při spuštění zavolá main(), při importu mlčí. Směna začíná.",
  ["The amount still to make after spending this one coin."] = "Částka, která zbývá složit po utracení téhle jedné mince.",
  ["The ampersand, then the same word that made a changeable."] = "Ampersand, pak stejné slovo, které udělalo a měnitelným.",
  ["The argument is evaluated on the defer line. Only the call is delayed."] = "Argument se vyhodnotí na řádku s defer. Odloží se jen volání.",
  ["The arrow leans out of the channel this time. Mirror of the chan<- next to it."] = "Tentokrát šipka míří ven z kanálu. Zrcadlo toho chan<- vedle.",
  ["The back office robot runs on generators, decorators and asyncio. Earn the midnight bowl."] = "Robot v zadní kanceláři běží na generátorech, dekorátorech a asyncio. Vybojuj si půlnoční misku.",
  ["The base class of every catchable error, capital E. Not BaseException: that one includes Ctrl-C."] = "Základní třída každé zachytitelné chyby, velké E. Ne BaseException: ta zahrnuje i Ctrl-C.",
  ["The bell"] = "Zvonek",
  ["The belt is closed and empty. What comes out of the next receive?"] = "Pás je zavřený a prázdný. Co vypadne z dalšího příjmu?",
  ["The belt kept handing me empty trays after the kitchen shut. Empty tray, or no more trays?"] = "Pás mi po zavření kuchyně pořád podával prázdné tácy. Prázdný tác, nebo už žádné tácy?",
  ["The belt to the counter"] = "Pás k pultu",
  ["The blank identifier. Compile error if you name a value you never use."] = "Prázdný identifikátor. Chyba překladu, když pojmenuješ hodnotu, kterou nikdy nepoužiješ.",
  ["The board mixes prices, names and a sold-out flag. What is v today?"] = "Tabule míchá ceny, názvy a příznak vyprodáno. Co je v dnes?",
  ["The bool from the map lookup. True when the key exists."] = "Bool z vyhledání v mapě. True, když klíč existuje.",
  ["The booth"] = "Box",
  ["The booth code used to duplicate fry for every item. Generics write it once. A Kitchen that embeds Grill gets Grill's methods for free."] = "Kód u boxu dřív kopíroval fry pro každou položku. Generika ho napíšou jednou. Kitchen, který vnořuje Grill, dostane metody Grill zdarma.",
  ["The buffer size is the number of tokens. The fourth send waits."] = "Velikost bufferu je počet tokenů. Čtvrté odeslání čeká.",
  ["The built-in constraint for types that allow == and !=."] = "Vestavěné omezení pro typy, které umí == a !=.",
  ["The built-in interface for failure. Last return value by convention."] = "Vestavěné rozhraní pro selhání. Podle konvence poslední návratová hodnota.",
  ["The built-in that picks the smaller of two values."] = "Vestavěná funkce, která vybere menší ze dvou hodnot.",
  ["The built-in whole-number type, three letters, after the colon."] = "Vestavěný celočíselný typ, tři písmena, za dvojtečkou.",
  ["The builtin that adds an element to the end of a slice."] = "Builtin, který přidá prvek na konec slice.",
  ["The builtin that adds to the end of a slice and returns the new slice."] = "Builtin, který přidá na konec slice a vrátí nový slice.",
  ["The builtin that ends a range. One goroutine waits for the workers and then calls it once."] = "Vestavěná funkce, která ukončí range. Jedna goroutina počká na workery a pak ji jednou zavolá.",
  ["The builtin that takes a map and a key. Six letters."] = "Builtin, který bere mapu a klíč. Šest písmen.",
  ["The busiest k hours: keep one running sum. The window moves right by one: add a[i], and subtract which element?"] = "Nejrušnějších k hodin: drž jeden průběžný součet. Okno se posune o jedna doprava: přičti a[i] a odečti který prvek?",
  ["The cache is 9 GB and one entry is corrupt. Wipe it. Fill the flag."] = "Cache má 9 GB a jedna položka je poškozená. Vymaž ji. Doplň přepínač.",
  ["The cache is read-only on purpose, so a corrupt entry cannot be edited, only removed. go.sum makes the re-download provably the same code."] = "Cache je schválně jen pro čtení, takže poškozenou položku nelze upravit, jen odstranit. go.sum zaručí, že nové stažení je prokazatelně stejný kód.",
  ["The cheapest of three prices, no loop, no import. Which built-in (Go 1.21)?"] = "Nejlevnější ze tří cen, bez smyčky, bez importu. Která vestavěná funkce (Go 1.21)?",
  ["The child adds to a global and the parent still prints 0. What did the child change?"] = "Potomek přičte do globální proměnné a rodič pořád vypisuje 0. Co potomek změnil?",
  ["The classic bug is forgetting max: a short interval inside a long one must not cut it. last is &mut, so this writes into out."] = "Klasický bug je zapomenout na max: krátký interval uvnitř dlouhého ho nesmí zkrátit. last je &mut, takže tohle zapisuje do out.",
  ["The classics! Two-sum, palindrome, anagram. Everyone has done these. Once."] = "Klasika! Two-sum, palindrom, přesmyčka. Tohle dělal každý. Jednou.",
  ["The closer-to-opener map from the first blank."] = "Mapa zavírací -> otevírací z prvního doplňování.",
  ["The cold room"] = "Chladicí box",
  ["The combinatorics counter"] = "Kombinatorický pult",
  ["The combinatorics counter at the noodle stall: pick any toppings. Bo counts the combinations and the number doubles with every topping. He draws the curve that goes vertical almost at once."] = "Kombinatorický pult u nudlového stánku: vyber si libovolné přílohy. Bo počítá kombinace a číslo se s každou přílohou zdvojnásobí. Kreslí křivku, která jde téměř okamžitě svisle.",
  ["The combinatorics counter at the noodle stall: pick any toppings. Bo counts the combinations and the number doubles with every topping. Mei draws the curve that goes vertical almost at once."] = "Kombinatorický pult u nudlového stánku: vyber si libovolné přílohy. Bo počítá kombinace a číslo se s každou přílohou zdvojnásobí. Mei kreslí křivku, která jde téměř okamžitě svisle.",
  ["The combinatorics counter at the noodle stall: pick any toppings. Bo counts the combinations and the number doubles with every topping. Mei draws the last curve, the one that goes vertical almost at once."] = "Kombinatorický pult u nudlového stánku: vyber si libovolné přílohy. Bo počítá kombinace a číslo se s každou přílohou zdvojnásobí. Mei kreslí poslední křivku, tu, která jde téměř okamžitě svisle.",
  ["The comma-ok idiom. Same word twice on those two lines."] = "Idiom comma-ok. Stejné slovo dvakrát na těch dvou řádcích.",
  ["The compound operator that walks j one step toward the smaller values, on the left."] = "Složený operátor, který posune j o krok k menším hodnotám, doleva.",
  ["The conveyor"] = "Dopravník",
  ["The conveyor carries bowls from the wok to the pass. Its script builds a list of every bowl of the night before serving the first. A generator would hand them out one at a time, and the belt would never wait."] = "Dopravník nese misky od woku k výdeji. Jeho skript sestaví seznam všech misek celé noci, než vydá první. Generátor by je vydával jednu po druhé a pás by nikdy nečekal.",
  ["The conveyor script loads every bowl into memory at once. Ten thousand bowls."] = "Skript dopravníku nahraje všechny misky do paměti najednou. Deset tisíc misek.",
  ["The counter"] = "Pult",
  ["The counts drift and nothing crashes. Which flag makes the test print WARNING: DATA RACE?"] = "Čísla se rozcházejí a nic nespadne. Který přepínač donutí test vypsat WARNING: DATA RACE?",
  ["The cousin asks which version is safe. Right now the answer is 'whichever commit was on main when he ran go get'."] = "Bratranec se ptá, která verze je bezpečná. Teď zní odpověď „kterýkoli commit byl na main, když spustil go get“.",
  ["The cousin wants the newest tag, whatever it is. Fill the version query."] = "Bratranec chce nejnovější tag, ať je jakýkoli. Doplň dotaz na verzi.",
  ["The cousin's shop imported my rider package and now they call the function I wanted to delete."] = "Bratrancův obchod importoval můj balíček rider a teď volají funkci, kterou jsem chtěl smazat.",
  ["The crash that pairs with recover. Six letters here, in the third person."] = "Ten pád, který tvoří dvojici s recover. Tady ve třetí osobě.",
  ["The cube is a slice of ads. append one more."] = "Kostka je slice reklam. append ještě jednu.",
  ["The curly opener, as a char literal in single quotes."] = "Otevírací složená závorka jako znakový literál v jednoduchých uvozovkách.",
  ["The curly opener, as a one-character string like the other two values."] = "Složená otvírací závorka, jako jednoznakový řetězec stejně jako ostatní dvě hodnoty.",
  ["The current index: the right edge of the window."] = "Aktuální index: pravý okraj okna.",
  ["The current value. Its partner is target minus it."] = "Aktuální hodnota. Jejím partnerem je target minus ona.",
  ["The customer closed the app two minutes ago and your goroutine is still fetching the ETA."] = "Zákazník zavřel aplikaci před dvěma minutami a tvoje goroutina pořád shání ETA.",
  ["The decorator builds an inner function and must hand it back. What does timer return?"] = "Dekorátor postaví vnitřní funkci a musí ji vrátit. Co vrací timer?",
  ["The delivery radio"] = "Rozvozová vysílačka",
  ["The delivery radio at the door. Three riders report their position; the script asks each in turn and waits a full second for every answer. Asked at once, the three answers would arrive together."] = "Rozvozová vysílačka u dveří. Tři kurýři hlásí polohu; skript se ptá každého zvlášť a na každou odpověď čeká celou sekundu. Zeptáš-li se najednou, dorazí tři odpovědi společně.",
  ["The dict defined on the first line, the one written to two lines below the blank."] = "Dict definovaný na prvním řádku, ten, do kterého se zapisuje dva řádky pod mezerou.",
  ["The dict from the first line of the body, value to index."] = "Dict z prvního řádku těla, hodnota na index.",
  ["The dict method that removes and returns one (key, value) pair; last=False takes it from the front."] = "Metoda dictu, která odebere a vrátí jednu dvojici (key, value); last=False ji bere ze začátku.",
  ["The digit for land, as a byte literal in single quotes."] = "Číslice pro souš jako bajtový literál v jednoduchých uvozovkách.",
  ["The digit one as a u8: a b before the single quotes."] = "Číslice jedna jako u8: b před jednoduchými uvozovkami.",
  ["The directory the file sits in, nothing more. Look at how rider is done on the next line."] = "Adresář, ve kterém soubor leží, nic víc. Podívej se, jak je na dalším řádku udělaný rider.",
  ["The directory's name. It could legally be anything, and it should be this."] = "Jméno adresáře. Legálně by to mohlo být cokoli a mělo by to být tohle.",
  ["The door sensor counts every customer. Only one number, thousands of times a minute."] = "Čidlo u dveří počítá každého zákazníka. Jediné číslo, tisíckrát za minutu.",
  ["The dumbwaiter"] = "Jídelní výtah",
  ["The element on its own: a run that begins right here and has nothing before it."] = "Prvek sám o sobě: běh, který začíná právě tady a nemá nic před sebou.",
  ["The element that just fell off the left edge: k places behind i."] = "Prvek, který právě vypadl z levého okraje: k míst za i.",
  ["The element that just fell off the left edge: k positions behind i."] = "Prvek, který právě vypadl z levého okraje: k pozic za i.",
  ["The element type, plural, capitalized, like sort.Ints for ints."] = "Typ prvku, množné číslo, s velkým písmenem, jako sort.Ints pro inty.",
  ["The empty till. Making nothing takes no coins at all."] = "Prázdná pokladna. Vydat nic nestojí žádnou minci.",
  ["The end of every Python chain, capital N."] = "Konec každého pythonového řetězu, velké N.",
  ["The entry API: one lookup, insert or update. The classics done, no misses. Combo x6. One round left."] = "API entry: jedno vyhledání, vložení nebo úprava. Klasika hotová, bez chyby. Kombo x6. Zbývá jedno kolo.",
  ["The evening CODE RUSH is the Rust round. Seven classic problems. Get HIRED."] = "Večerní CODE RUSH je kolo Rustu. Sedm klasických úloh. Získej PŘIJAT.",
  ["The evening callback is the Rust round. Seven whiteboard classics. Get the OFFER."] = "Večerní callback je kolo Rustu. Sedm klasik od tabule. Získej OFFER.",
  ["The evicted key must leave the map too, or the cache leaks. Which HashMap method deletes by key?"] = "Vyhozený klíč musí opustit i mapu, jinak cache teče. Která metoda HashMap maže podle klíče?",
  ["The field from stage one. Borrow it with &, and cur stays a &Link."] = "To pole z prvního kroku. Půjč si ho přes &, a cur zůstane &Link.",
  ["The field that is not right. Mei said it in her speech bubble."] = "To pole, které není right. Mei to řekla ve své bublině.",
  ["The file is menu/price.go. What does its first line say?"] = "Soubor je menu/price.go. Co říká jeho první řádek?",
  ["The final round. Three cook threads pull orders from one queue and fry them. Bo has to feed the queue, drain it safely, mark every job finished and wait for the last one before the receipt prints. Then the screen says HIRED."] = "Finální kolo. Tři kuchařská vlákna berou objednávky z jedné fronty a smaží je. Bo musí frontu plnit, bezpečně vyprázdnit, označit každou úlohu jako hotovou a počkat na poslední, než se vytiskne účtenka. Pak obrazovka řekne PŘIJAT.",
  ["The final sheet is a grid of bytes: '1' is land, '0' is water, Hong Kong Island and Kowloon and a scatter of rocks. Siu Ming wants the count. Alex writes a recursive dfs that sinks whatever it touches, then a double loop that calls it on every '1' still standing and counts the calls. The marker squeaks. Then: OFFER."] = "Poslední list je mřížka bajtů: '1' je souš, '0' voda, Hong Kong Island a Kowloon a hrstka skalisek. Siu Ming chce počet. Alex píše rekurzivní dfs, který potopí vše, čeho se dotkne, pak dvojitý cyklus, který ho zavolá na každou '1', která ještě stojí, a počítá volání. Fix zaskřípe. Pak: OFFER.",
  ["The final. 01:40. Siu Ming draws Causeway Bay as a grid: 1 for a building, 0 for the road. Bo has to count the islands of buildings, each a patch of 1s touching up, down, left or right. One DFS per island, sinking it as it goes; the count of sinkings is the answer, and the answer is the OFFER."] = "Finále. 01:40. Siu Ming kreslí Causeway Bay jako mřížku: 1 pro budovu, 0 pro silnici. Bo musí spočítat ostrovy budov, každý je plocha jedniček, které se dotýkají nahoře, dole, vlevo nebo vpravo. Jedno DFS na ostrov, které ho cestou potápí; počet potopení je odpověď a odpověď je OFFER.",
  ["The first element of each pair is the start."] = "První prvek každé dvojice je začátek.",
  ["The first element. The loop then starts from the second, see the slice."] = "První prvek. Cyklus pak začíná od druhého, viz slice.",
  ["The first handler argument is where the reply goes. Fill its type: w http.___"] = "První argument handleru je místo, kam jde odpověď. Doplň jeho typ: w http.___",
  ["The first letter of format. Since Python 3.6."] = "První písmeno slova format. Od Pythonu 3.6.",
  ["The first line of go.mod names the module. Which keyword?"] = "První řádek go.mod pojmenuje modul. Které klíčové slovo?",
  ["The flat"] = "Byt",
  ["The flood function from the blanks above."] = "Záplavová funkce z doplňování výše.",
  ["The flood stops at the edge of the map. Fill the row check."] = "Záplava se zastaví na okraji mapy. Doplň kontrolu řádku.",
  ["The footbridge to Times Square"] = "Lávka k Times Square",
  ["The four-letter function from the prelude that ends a value early. Not close: channels have no close."] = "Ta čtyřpísmenná funkce z prelude, která ukončí hodnotu dřív. Ne close: kanály žádné close nemají.",
  ["The free slots are the gaps between merged blocks: pair each block with the next. Fill the slice."] = "Volná místa jsou mezery mezi sloučenými bloky: spáruj každý blok s dalším. Doplň slice.",
  ["The free-threaded build removes the GIL and pays for it in single-thread speed and C extension support. Until it is the default, processes are the answer."] = "Sestavení free-threaded odstraní GIL a platí za to rychlostí jednoho vlákna a podporou céčkových rozšíření. Dokud nebude výchozí, odpovědí jsou procesy.",
  ["The full word this time. Then the go version, then require lines."] = "Tentokrát celé slovo. Pak verze go, pak řádky require.",
  ["The function calls itself. Same name as on the last line."] = "Funkce volá sama sebe. Stejné jméno jako na posledním řádku.",
  ["The function itself. The map is shared, so a plain map argument works."] = "Funkce sama. Mapa je sdílená, takže stačí obyčejný argument typu map.",
  ["The function that measures a string, passed by name, no parentheses."] = "Funkce, která měří řetězec, předaná jménem, bez závorek.",
  ["The function's own name. The recursion is the stack."] = "Vlastní jméno funkce. Rekurze je zásobník.",
  ["The generic one that holds an address, not a number."] = "Ten generický, co drží adresu, ne číslo.",
  ["The go directive also picks language semantics: for-loop variables became per-iteration only for modules that say go 1.22 or later."] = "Direktiva go vybírá i sémantiku jazyka: proměnné cyklu for se staly per-iteračními jen v modulech, které deklarují go 1.22 nebo novější.",
  ["The grid holds bytes, not ints: '1' is 49, 1 is 1. Compare with the character."] = "Mřížka drží bajty, ne inty: '1' je 49, 1 je 1. Porovnávej se znakem.",
  ["The grid holds one-character strings, and the road is the zero."] = "Mřížka drží jednoznakové řetězce a silnice je nula.",
  ["The grill line"] = "Linka u grilu",
  ["The growable array. Three letters, capital V. A neighbour can be pushed on."] = "Rostoucí pole. Tři písmena, velké V. Dá se na něj pushnout soused.",
  ["The heap never grows past k: O(n log k) time, O(k) space. Sorting would be O(n log n) and O(n)."] = "Halda nikdy nepřeroste k: O(n log k) čas, O(k) paměť. Řazení by bylo O(n log n) a O(n).",
  ["The heap package does the sifting; your Pop only trims the tail. O(log n) per operation."] = "Balíček heap dělá prosívání; tvůj Pop jen ořízne konec. O(log n) na operaci.",
  ["The host, the user, the repo, joined with slashes, no https://. The tool echoes it back on the next line."] = "Host, uživatel, repozitář, spojené lomítky, bez https://. Nástroj to na dalším řádku zopakuje.",
  ["The index enumerate hands out, one letter. The return line reads it back."] = "Index, který vydává enumerate, jedno písmeno. Řádek s return ho čte zpátky.",
  ["The index just checked, plus one: everything up to it is too small."] = "Právě zkontrolovaný index plus jedna: všechno až po něj je příliš malé.",
  ["The index of the left half, mirroring j++ in the else."] = "Index levé půlky, zrcadlo j++ ve větvi else.",
  ["The inner def's name, without parentheses: the function itself, not a call of it."] = "Jméno vnitřního def, bez závorek: samotná funkce, ne její volání.",
  ["The int32 code point type. Indexing a string gives bytes."] = "Typ kódového bodu int32. Indexování stringu dává bajty.",
  ["The interview asked me this three times. Let's get it right in Go first."] = "Na pohovoru se mě na to ptali třikrát. Pojďme to nejdřív udělat správně v Go.",
  ["The interview convention: a negative one, since cached values are non-negative."] = "Pohovorová konvence: minus jedna, protože hodnoty v cache jsou nezáporné.",
  ["The invariant: map.len() == order.len(), always. Break it once and the cap check lies."] = "Invariant: map.len() == order.len(), vždy. Poruš ho jednou a kontrola cap lže.",
  ["The jobs are tiny and the pool is slower than one core. Which argument fixes it?"] = "Úlohy jsou drobné a pool je pomalejší než jedno jádro. Který argument to spraví?",
  ["The key exactly as the phone spells it, inside the quotes."] = "Klíč přesně tak, jak ho píše telefon, uvnitř uvozovek.",
  ["The keyword type, where a type name would go. Only inside a switch."] = "Klíčové slovo type tam, kde by byl název typu. Jen uvnitř switch.",
  ["The kiosk"] = "Kiosek",
  ['The kiosk reads "18" from the keypad. Turn it into an i32. Which method?'] = 'Kiosek přečte z klávesnice "18". Udělej z toho i32. Která metoda?',
  ["The kiosk row"] = "Řada kiosků",
  ["The kiosk wants one function for prices and for weights. Go had any; what now?"] = "Kiosek chce jednu funkci pro ceny i pro váhy. Go mělo any; co teď?",
  ["The kitchen"] = "Kuchyně",
  ["The kitchen at 23:00"] = "Kuchyně ve 23:00",
  ["The kitchen build box has no internet. Copy every dependency into the repo. Fill the subcommand."] = "Sestavovací stroj v kuchyni nemá internet. Zkopíruj každou závislost do repozitáře. Doplň podpříkaz.",
  ["The kitchen is concurrent. One cook cannot wait for the hash brown before starting the muffin. go fry() starts a function in a new goroutine."] = "Kuchyně je souběžná. Kuchař nemůže čekat na hash brown, než začne muffin. go fry() spustí funkci v nové goroutine.",
  ["The kitchen sends one more order after closing. What happens?"] = "Kuchyně po zavření pošle ještě jednu objednávku. Co se stane?",
  ["The kitchen waits until an order arrives. Which method blocks and takes one?"] = "Kuchyně čeká, dokud nedorazí objednávka. Která metoda blokuje a jednu vezme?",
  ["The label maker"] = "Štítkovač",
  ["The label maker printed 'None' on forty bowls. Somebody returned nothing."] = "Štítkovač vytiskl 'None' na čtyřicet misek. Někdo nic nevrátil.",
  ["The label maker prints a name and a price per bowl. Half its functions return None by accident and nobody noticed until forty bowls said so. Type hints would have caught it before the shift."] = "Štítkovač tiskne jméno a cenu na každou misku. Polovina jeho funkcí vrací omylem None a nikdo si toho nevšiml, dokud to neřeklo čtyřicet misek. Typové nápovědy by to chytily před směnou.",
  ["The larger of the two ends wins; a shift fully inside another must not shrink the block."] = "Větší ze dvou konců vyhrává; směna celá uvnitř jiné nesmí blok zmenšit.",
  ["The last arm must catch every other number. Which pattern matches anything?"] = "Poslední větev musí zachytit každé další číslo. Který vzor odpovídá čemukoli?",
  ["The last expression is the return value. One pass, one stack: O(n) time, O(n) space at worst."] = "Poslední výraz je návratová hodnota. Jeden průchod, jeden zásobník: O(n) času, nejhůř O(n) paměti.",
  ["The last index of a slice of n items."] = "Poslední index slice o n prvcích.",
  ["The last item of a Vec in one step, as an Option. Which method?"] = "Poslední položka Vec na jeden krok, jako Option. Která metoda?",
  ["The last item of a list in one step, without len. Which index?"] = "Poslední položka seznamu na jeden krok, bez len. Který index?",
  ["The last item of a slice in one step. What is subtracted from the length?"] = "Poslední položka slice na jeden krok. Co se odečte od délky?",
  ["The last sheet before the break is the classic: an LRU cache. Lucky Mac's menu service is slow, keep the hundred most recently asked-for menus in memory, throw out the one nobody has touched for longest. Alex draws a map on the left and a doubly linked list on the right and joins them with arrows."] = "Poslední list před pauzou je klasika: LRU cache. Služba menu v Lucky Macu je pomalá, drž v paměti sto naposled žádaných menu, vyhoď to, na které nikdo nejdéle nesáhl. Alex kreslí vlevo mapu a vpravo obousměrně zřetězený seznam a spojí je šipkami.",
  ["The last stop points nowhere. What is next set to at creation?"] = "Poslední zastávka nikam neukazuje. Na co se při vytvoření nastaví next?",
  ["The last tray, without len. Which index?"] = "Poslední tác, bez len. Který index?",
  ["The left pointer only ever moves right, so the while loop costs O(n) over the whole run, not per r."] = "Levý ukazatel se posouvá jen doprava, takže cyklus while stojí O(n) za celý běh, ne za každé r.",
  ["The length of any collection has which unsigned, pointer-sized type?"] = "Délka každé kolekce má který bezznaménkový typ o velikosti ukazatele?",
  ["The letter v and the new major number, as the last element of the path. Tag it v2.0.0."] = "Písmeno v a nové číslo major verze jako poslední prvek cesty. Otaguj to v2.0.0.",
  ["The lift"] = "Výtah",
  ["The lift panel is a tiny Go program. Floor, name, and a constant for Lucky Mac's opening hour. Zero values matter: an unset int is not blank."] = "Panel výtahu je malý program v Go. Patro, jméno a konstanta pro otevírací hodinu Lucky Mac. Na nulových hodnotách záleží: nenastavený int není prázdný.",
  ["The list forgot the node; the map must forget the key too. Which builtin removes a map entry?"] = "Seznam uzel zapomněl; mapa musí zapomenout i klíč. Který builtin odstraní položku mapy?",
  ["The list method that grows the end. The end of the list is the top of the stack."] = "Metoda seznamu, která prodlužuje konec. Konec seznamu je vršek zásobníku.",
  ["The lock needs no constructor: its zero value is ready. Which type?"] = "Ten zámek nepotřebuje konstruktor: nulová hodnota je rovnou připravená. Který typ?",
  ["The log tailer must not keep the batch alive. Which flag makes a child die with its parent?"] = "Sledovač logu nesmí držet dávku naživu. Který příznak nechá potomka zemřít s rodičem?",
  ["The loop keyword, inside the brackets, after the expression."] = "Klíčové slovo cyklu, uvnitř hranatých závorek, za výrazem.",
  ["The mall atrium"] = "Atrium obchoďáku",
  ["The map finds the node in O(1); the list moves it in O(1). Neither alone can do both."] = "Mapa najde uzel v O(1); seznam ho přesune v O(1). Ani jeden sám nezvládne obojí.",
  ["The menu board"] = "Tabule s menu",
  ["The menu board at the shutter. Prices live in a dict, dish to dollars. It is Go's map with braces instead of make, and a KeyError instead of a zero value when the dish is missing."] = "Jídelní lístek u rolety. Ceny žijí v dictu, jídlo na dolary. Je to mapa z Go se složenými závorkami místo make a s KeyError místo nulové hodnoty, když jídlo chybí.",
  ["The menu board reads prices from a dict. Ask for a dish we do not have and it crashes."] = "Jídelní lístek čte ceny z dictu. Zeptej se na jídlo, které nemáme, a spadne.",
  ["The menu is read by two hundred goroutines and written once an hour. Which lock?"] = "Menu čte dvě stě goroutin a zapisuje se jednou za hodinu. Který zámek?",
  ["The menu is read often, written rarely. Which method takes a shared read guard?"] = "Menu se často čte, zřídka zapisuje. Která metoda vezme sdílený guard pro čtení?",
  ["The menu maps dish names to prices. Which generic takes two types?"] = "Lístek mapuje jména jídel na ceny. Který generický typ bere dva typy?",
  ["The merge pass is O(n); the sort before it makes the whole thing O(n log n)."] = "Slučovací průchod je O(n); řazení před ním dělá z celku O(n log n).",
  ["The method reads its own item. What is the first parameter of every method?"] = "Metoda čte svůj vlastní item. Jaký je první parametr každé metody?",
  ["The middle index without overflow. Fill: mid := lo + (hi-lo)/___"] = "Prostřední index bez přetečení. Doplň: mid := lo + (hi-lo)/___",
  ["The midnight CODE RUSH is the Python round. Seven classic problems. Get HIRED."] = "Půlnoční CODE RUSH je kolo Pythonu. Sedm klasických úloh. Získej PŘIJAT.",
  ["The mirror of the helper on the next line: n, then the superlative of big."] = "Zrcadlo pomocníka na dalším řádku: n, pak superlativ od big.",
  ["The module name, singular, capitalized. Go's go keyword, as an object."] = "Jméno modulu v jednotném čísle, s velkým písmenem. Klíčové slovo go z Go, jako objekt.",
  ["The module path from the comment, a slash, the directory. Not menu on its own, not ./menu."] = "Cesta modulu z komentáře, lomítko, adresář. Ne samotné menu, ne ./menu.",
  ["The module path is a name, not a URL: nothing is fetched when you init. It only has to match the repo later, when somebody else runs go get on it."] = "Cesta modulu je jméno, ne URL: při init se nic nestahuje. Jen se musí později shodovat s repozitářem, až na něj někdo jiný spustí go get.",
  ["The module path is the import path"] = "Cesta modulu je cesta importu",
  ["The module's name, an underscore, and the side an equal item is inserted on: the left one here."] = "Jméno modulu, podtržítko a strana, na kterou se vkládá stejná položka: tady levá.",
  ["The module's name, capitalized. Not deque: that one has no locks."] = "Jméno modulu, s velkým písmenem. Ne deque: ta nemá zámky.",
  ["The module's name, singular, after the dot. It is a decorator, so it sits on the line above the class."] = "Jméno modulu v jednotném čísle, za tečkou. Je to dekorátor, takže sedí na řádku nad třídou.",
  ["The module's own name in CamelCase, the two words joined."] = "Vlastní jméno modulu v CamelCase, obě slova spojená.",
  ["The module's own name, in double underscores. It is '__main__' only in the script you ran."] = "Vlastní jméno modulu ve dvojitých podtržítkách. Hodnotu '__main__' má jen ve skriptu, který jsi spustil.",
  ["The morning set"] = "Ranní menu",
  ["The multiplicative identity. Returning 0 would zero every factorial."] = "Neutrální prvek násobení. Vrácení 0 by vynulovalo každý faktoriál.",
  ["The name imported on the first line. Since 3.10 you may write the type, a pipe, and None instead."] = "Jméno importované na prvním řádku. Od 3.10 můžeš místo toho napsat typ, svislítko a None.",
  ["The name imported on the first line: a pool of threads that executes."] = "Jméno importované na prvním řádku: pool vláken, který vykonává.",
  ["The name is a short string, so the argument you pickle is tiny no matter how large the block is. That is the whole trick."] = "To jméno je krátký řetězec, takže argument, který picklíš, je titěrný, ať je blok jakkoli velký. V tom je celý trik.",
  ["The name saved on the first line of the loop, before the pointer was flipped. cur.next is no longer it."] = "Jméno uložené na prvním řádku cyklu, před otočením ukazatele. cur.next už to není.",
  ["The name x, wrapped in the vertical bar character on both sides."] = "Jméno x, obalené z obou stran znakem svislé čáry.",
  ["The new sign says 銅鑼灣. The app counts it as nine letters."] = "Na nové ceduli je 銅鑼灣. Appka to počítá jako devět písmen.",
  ["The next sheet is a stream: order totals arriving faster than anyone could sort them. Siu Ming wants the kth largest at any moment. Go has no heap type, only container/heap and an interface to satisfy. Alex writes IntHeap on the board, five methods, and a loop that never lets the heap grow past k."] = "Další list je proud: součty objednávek přicházejí rychleji, než by je kdo stihl seřadit. Siu Ming chce k-tý největší v každém okamžiku. Go nemá typ haldy, jen container/heap a rozhraní k naplnění. Alex píše na tabuli IntHeap, pět metod a cyklus, který haldě nikdy nedovolí přerůst k.",
  ["The night shift at Lucky Mac runs on Chef Bo's Python scripts. Fix every station before closing."] = "Noční směna v Lucky Macu běží na pythonových skriptech šéfkuchaře Boa. Oprav každé stanoviště před zavíračkou.",
  ["The node that was before cur, saved on the first line. That is what reversing means."] = "Uzel, který byl před cur, uložený na prvním řádku. To znamená obrátit.",
  ["The node we just came from. nil on the first step, which becomes the new tail."] = "Uzel, ze kterého jsme přišli. V prvním kroku nil, z něj bude nový konec.",
  ["The note may be text or None. Which typing name says so?"] = "Poznámka může být text nebo None. Které jméno z typing to říká?",
  ["The number of columns: the length of one row, say the first."] = "Počet sloupců: délka jednoho řádku, třeba prvního.",
  ["The number of times you can halve n. Same answer as the phone book, applied to memory."] = "Kolikrát můžeš n půlit. Stejná odpověď jako telefonní seznam, použitá na paměť.",
  ["The old position of this char, from the map lookup."] = "Stará pozice tohoto znaku, z vyhledání v mapě.",
  ["The one everybody gets asked, Chef. In Python the dict already remembers the order for you."] = "Ta, na kterou se ptají všech, šéfe. V Pythonu si dict pořadí pamatuje za tebe.",
  ["The one package name that does not follow its directory. The same word as the function."] = "Jediné jméno balíčku, které nesleduje svůj adresář. Stejné slovo jako ta funkce.",
  ["The opposite end from the front, where the untouched ones drift."] = "Opačný konec než začátek, kam se sunou ty nedotčené.",
  ["The opposite of Lock. defer it on the very next line."] = "Opak Lock. Dej ho do defer hned na dalším řádku.",
  ["The opposite of absolute. Paths that start with ./ or ../ are it."] = "Opak absolutní. Cesty začínající ./ nebo ../ to jsou.",
  ["The opposite of direct. Your code never names it; something you require does."] = "Opak přímé. Tvůj kód ji nikdy nejmenuje; něco, co ty požaduješ, ano.",
  ["The opposite of held. Past participle, eight letters."] = "Opak držení. Příčestí trpné, anglicky osm písmen.",
  ["The opposite of insert, six letters. Takes a reference, returns whether it was there."] = "Opak insert, šest písmen. Bere referenci, vrací, zda tam prvek byl.",
  ["The opposite of output. It shows the prompt and returns a str, always a str."] = "Opak výstupu. Ukáže výzvu a vrátí str, vždy str.",
  ["The opposite of the -- below. Go's ++ is a statement, not an expression."] = "Opak -- níže. ++ je v Go příkaz, ne výraz.",
  ["The order app"] = "Objednávková appka",
  ["The order queue"] = "Fronta objednávek",
  ["The order robot"] = "Objednávkový robot",
  ["The other child. max is a Go 1.21 built-in."] = "Druhý potomek. max je vestavěná funkce od Go 1.21.",
  ["The other direction: struct to bytes. Same word without the De in front."] = "Opačný směr: struct na bajty. Stejné slovo bez De vpředu.",
  ["The other half of Option. Not nil, not null. Four letters, capital N."] = "Ta druhá půlka Option. Ne nil, ne null. Čtyři písmena, velké N.",
  ["The other variant of Option. Capital N, no parentheses."] = "Druhá varianta Option. Velké N, bez závorek.",
  ["The p >= l test matters: a repeat before the window's left edge is already outside and must not pull l back."] = "Test p >= l je důležitý: opakování před levým okrajem okna je už venku a nesmí l stáhnout zpátky.",
  ["The package function that removes the root and returns it."] = "Funkce balíčku, která odstraní kořen a vrátí ho.",
  ["The package that holds WaitGroup and Once, then the six-letter word for a lock."] = "Balík, ve kterém bydlí WaitGroup a Once, a pak šestipísmenné slovo pro zámek.",
  ["The package the Go tool looks for when you type go run."] = "Balíček, který nástroj go hledá, když napíšeš go run.",
  ["The parameter, the station already in seen on the line above."] = "Parametr, stanice, která už je v seen na řádku výše.",
  ["The parent must not print the total before the child finishes. Which method?"] = "Rodič nesmí vypsat součet dřív, než potomek skončí. Která metoda?",
  ["The parse fails. Which method gives a fallback value instead of a panic?"] = "Parsování selže. Která metoda dá záložní hodnotu místo panic?",
  ["The part already flipped. None on the first lap, which becomes the new tail."] = "Ta část, která je už otočená. V prvním kole None, a z toho se stane nový konec.",
  ["The pass"] = "Výdej",
  ["The pass holds three trays; a fourth send should wait. Which constructor?"] = "Výdej pojme tři tácy; čtvrtý send má počkat. Který konstruktor?",
  ["The pass window"] = "Výdejní okno",
  ["The pass window is a channel. One goroutine fries, another plates. Do not share the same variable; send the value through the pipe."] = "Výdejní okénko je kanál. Jedna goroutine smaží, druhá servíruje. Nesdílej stejnou proměnnou; pošli hodnotu rourou.",
  ["The pass window, 22:30. Chef Bo's recipe file is a list of functions: fry, brew, plate. Alex knows func; here it is three letters and a colon, and the body is whatever is indented under it."] = "Výdejní okno, 22:30. Boův soubor receptů je seznam funkcí: fry, brew, plate. Alex zná func; tady jsou to tři písmena a dvojtečka a tělo je cokoli odsazeného pod tím.",
  ["The pass, 21:00"] = "Výdejní okno, 21:00",
  ["The path is long but unambiguous: two modules can both have a menu directory and never collide. The name you use in code is the package's own name, menu."] = "Cesta je dlouhá, ale jednoznačná: dva moduly můžou mít oba adresář menu a nikdy se nesrazí. Jméno, které používáš v kódu, je vlastní jméno balíčku, menu.",
  ["The phone book"] = "Telefonní seznam",
  ["The phone book street's answer, without the O( ). Halving each step."] = "Odpověď z ulice telefonního seznamu, bez O( ). Půlení v každém kroku.",
  ["The phone calls the field dish, not Item. Fill the tag so json reads that key."] = "Telefon říká poli dish, ne Item. Doplň tag, aby json četl ten klíč.",
  ['The phone sends the price as text. Parse "18" into an int. Which strconv function?'] = 'Telefon posílá cenu jako text. Převeď "18" na int. Která funkce ze strconv?',
  ['The phone sends {"dish":"set"}. Our struct says Item. Nothing arrives.'] = 'Telefon posílá {"dish":"set"}. Náš struct říká Item. Nic nedorazí.',
  ["The pickup bell is a select. Whichever channel is ready first wins. If none are ready, default fires instead of blocking the till."] = "Zvonek u výdeje je select. Vyhraje kanál, který je připraven první. Když žádný, spustí se default místo blokování pokladny.",
  ["The pickup queue"] = "Fronta na vyzvednutí",
  ["The pointer field, twice in a row. The while condition guards both hops."] = "Pole ukazatele, dvakrát za sebou. Podmínka while hlídá oba skoky.",
  ["The pointer that walks the list. prev is the new head once it is nil."] = "Ukazatel, který prochází seznam. Jakmile je nil, prev je nová hlava.",
  ["The pot is empty mid-loop. Which keyword leaves the loop at once?"] = "Uprostřed cyklu je hrnec prázdný. Které klíčové slovo okamžitě opustí cyklus?",
  ["The prices are sorted. Find 45 in O(log n). Which slice method returns Result<usize, usize>?"] = "Ceny jsou seřazené. Najdi 45 v O(log n). Která metoda slice vrací Result<usize, usize>?",
  ["The proxy and the private repo"] = "Proxy a soukromý repozitář",
  ["The proxy is why go get is fast and why a deleted GitHub repo does not break the world: it keeps every version it ever served."] = "Proxy je důvod, proč je go get rychlý a proč smazaný repozitář na GitHubu nerozbije svět: uchovává každou verzi, kterou kdy vydala.",
  ["The queue"] = "Fronta",
  ["The queue at Lucky Mac Express"] = "Fronta u Lucky Mac Express",
  ["The queue begins with one station. Which one?"] = "Fronta začíná jednou stanicí. Kterou?",
  ["The queue counter"] = "Čítač u fronty",
  ["The queue is a linked list. Reverse it without allocating, then find the loop."] = "Fronta je zřetězený seznam. Otoč ji bez alokace, pak najdi smyčku.",
  ["The queue is a struct of orders. A method with a pointer receiver can change the order. The till only knows the Pay() interface, not the card type."] = "Fronta je struct objednávek. Metoda s ukazatelovým receiverem může objednávku změnit. Pokladna zná jen rozhraní Pay(), ne typ karty.",
  ["The queue outside the shutter. To total everyone's bill you visit each person once. Bo draws the diagonal, and reminds Alex that a built-in like sum hides the loop, not its cost."] = "Fronta před roletou. Abys sečetl účet všech, navštívíš každého člověka jednou. Bo kreslí diagonálu a připomíná Alexovi, že vestavěná funkce jako sum skrývá cyklus, ne jeho cenu.",
  ["The queue outside the shutter. To total everyone's bill you visit each person once. Mei draws the diagonal again, and Alex writes it as an iterator chain instead of a loop."] = "Fronta před roletou. Abys sečetl účet všech, navštívíš každého člověka jednou. Mei znovu kreslí diagonálu a Alex to píše jako řetězec iterátorů místo cyklu.",
  ["The queue outside the shutter. To total the bill of everyone in it you visit each person once. Mei draws the second line on the whiteboard: a straight diagonal. Double the queue, double the work."] = "Fronta před roletou. Abys sečetl účet všech v ní, navštívíš každého člověka jednou. Mei kreslí na tabuli druhou čáru: rovnou diagonálu. Dvakrát delší fronta, dvakrát více práce.",
  ["The race detector watches real memory accesses, so it only sees races the run actually hits. Run your tests with it in CI."] = "Detektor souběhů sleduje skutečné přístupy do paměti, takže vidí jen ty souběhy, na které běh opravdu narazí. Pouštěj s ním testy v CI.",
  ["The rack script lists trays. It drops the last one every time."] = "Regálový skript vypisuje tácy. Poslední mu vždy vypadne.",
  ["The receipt borrows your name. It must not outlive you. That is all a lifetime says."] = "Účtenka si půjčuje tvoje jméno. Nesmí tě přežít. To je vše, co lifetime říká.",
  ["The recursive call must shrink the problem. Fill: n * fact(___)"] = "Rekurzivní volání musí problém zmenšit. Doplň: n * fact(___)",
  ["The recursive call must shrink the problem. Fill: return n * fact(___)"] = "Rekurzivní volání musí problém zmenšit. Doplň: return n * fact(___)",
  ["The recursive flood written above, four letters. Takes &mut g and the cell."] = "Rekurzivní záplava napsaná výše, čtyři písmena. Bere &mut g a buňku.",
  ["The refund desk"] = "Refundační pult",
  ["The repeat is gone: b[r] joins the window. Which HashSet method adds it?"] = "Opakování je pryč: b[r] se přidá do okna. Která metoda HashSet ho přidá?",
  ["The repeat sits at p, inside the window. The window must restart just after it. Fill."] = "Opakování sedí na p, uvnitř okna. Okno musí začít znovu hned za ním. Doplň.",
  ["The repo is private and the proxy answers 404. Which variable sends those paths straight to git?"] = "Repozitář je soukromý a proxy odpovídá 404. Která proměnná pošle tyhle cesty rovnou do gitu?",
  ["The rest of the chain, or nothing at the end. Which type wraps Box<ListNode> so it can be empty?"] = "Zbytek řetězu, nebo nic na konci. Který typ obalí Box<ListNode>, aby mohl být prázdný?",
  ['The rider app sends JSON with "dish", our struct says "name". serde can bridge it.'] = 'Appka kurýrů posílá JSON s "dish", náš struct říká "name". serde to umí propojit.',
  ["The rider app sends text. Parse it back into an Order. Which function?"] = "Appka kurýrů posílá text. Naparsuj ho zpátky na Order. Která funkce?",
  ["The rider who gave up"] = "Kurýr, který to vzdal",
  ["The road value, as a one-character string. Sinking is the visited set for free."] = "Hodnota silnice, jako jednoznakový řetězec. Potápění je množina navštívených zadarmo.",
  ["The robot is a class. One Order per bowl. It forgot how to make itself."] = "Robot je třída. Jeden Order na misku. Zapomněl, jak se vyrobit.",
  ["The rooftop"] = "Střecha",
  ["The root of a heap lives at the first index of the slice."] = "Kořen haldy bydlí na prvním indexu slice.",
  ["The root of every request tree. Fill: ctx := context.___()"] = "Kořen každého stromu requestů. Doplň: ctx := context.___()",
  ["The round opener, as a rune literal in single quotes."] = "Kulatá otevírací závorka jako rune literál v jednoduchých uvozovkách.",
  ["The run so far with x added. If that is worse than x alone, the old run was dead weight."] = "Dosavadní série s přičteným x. Pokud je to horší než samotné x, stará série byla přítěž.",
  ["The safe"] = "Trezor",
  ["The safe behind the till holds the stock file. The script opens it, writes, and forgets to close when a line is bad. Alex knows defer f.Close(); Python puts the whole idea into one keyword."] = "Trezor za kasou drží skladový soubor. Skript ho otevře, zapíše a zapomene zavřít, když je řádek špatný. Alex zná defer f.Close(); Python vložil celou myšlenku do jednoho klíčového slova.",
  ["The same customer is in the queue list twice. Which built-in keeps each name once?"] = "Stejný zákazník je v seznamu fronty dvakrát. Která vestavěná funkce ponechá každé jméno jen jednou?",
  ["The same function the right side of the == already uses. It takes a string and returns a list of characters."] = "Stejná funkce, kterou už používá pravá strana ==. Vezme řetězec a vrátí seznam znaků.",
  ["The same keyword as for slices, now on an int. No i := 0; i < 3; i++."] = "Stejné klíčové slovo jako u slice, teď na int. Žádné i := 0; i < 3; i++.",
  ["The same mark that ends a question."] = "Stejné znaménko, kterým končí otázka.",
  ["The same method that appends to any Vec. The top of the stack is the end of the Vec."] = "Stejná metoda, která přidává na konec každého Vec. Vrchol zásobníku je konec Vec.",
  ["The same shape as threading.Thread, one word, capitalised. What the operating system schedules."] = "Stejný tvar jako threading.Thread, jedno slovo s velkým písmenem. To, co plánuje operační systém.",
  ["The same three letters as the file next to go.mod. The proxy's sibling."] = "Stejná tři písmena jako soubor vedle go.mod. Sourozenec proxy.",
  ["The same trait String::from comes from. Capital F, one generic parameter."] = "Stejný trait, ze kterého pochází String::from. Velké F, jeden generický parametr.",
  ["The same word as a C-style counted loop."] = "Stejné slovo jako počítaný cyklus ve stylu C.",
  ["The same word as in 'the ___ value of a struct is all fields blank'."] = "Stejné slovo jako v „___ hodnota struktury má všechna pole prázdná“.",
  ["The same word as the blank import above. Go 1.16."] = "Stejné slovo jako v prázdném importu nahoře. Go 1.16.",
  ["The same word as the builtin, capitalised, living in sync."] = "Stejné slovo jako vestavěný typ, s velkým písmenem, bydlící v sync.",
  ["The same word the till used to shut the drawer. It fires on the way out."] = "Stejné slovo, kterým kasa zavírala zásuvku. Spustí se cestou ven.",
  ["The seating chart"] = "Zasedací pořádek",
  ["The seating chart for a banquet. Siu Ming's script checks every guest against every other for a duplicate. Bo draws the curve that leaves the board. Nested loops over the same list: the shape to avoid."] = "Zasedací pořádek na banket. Skript Siu Minga porovnává každého hosta s každým dalším a hledá duplikát. Bo kreslí křivku, která opouští tabuli. Vnořené cykly přes stejný seznam: tvar, kterému se vyhnout.",
  ["The seating chart for a banquet. Siu Ming's script checks every guest against every other for a duplicate. Mei draws a curve that bends upward and leaves the board. Nested loops over the same list: the shape to avoid."] = "Zasedací pořádek na banket. Skript Siu Minga porovnává každého hosta s každým dalším a hledá duplikát. Mei kreslí křivku, která se ohýbá vzhůru a opouští tabuli. Vnořené cykly přes stejný seznam: tvar, kterému se vyhnout.",
  ["The seating chart for a banquet. Siu Ming's script checks every guest against every other for a duplicate. Mei draws the curve that leaves the board. Nested loops over the same Vec: the shape to avoid."] = "Zasedací pořádek na banket. Skript Siu Minga porovnává každého hosta s každým dalším a hledá duplikát. Mei kreslí křivku, která opouští tabuli. Vnořené cykly přes stejný Vec: tvar, kterému se vyhnout.",
  ["The second argument holds the URL, method and body. Fill its type: r *http.___"] = "Druhý argument drží URL, metodu a tělo. Doplň jeho typ: r *http.___",
  ["The second argument to make is the buffer size."] = "Druhý argument make je velikost bufferu.",
  ["The second file guards against a tampered download. Name it."] = "Druhý soubor hlídá proti podvrženému stažení. Pojmenuj ho.",
  ["The second return value is not optional: not calling cancel leaks the context and whatever the parent holds for it."] = "Druhá návratová hodnota není volitelná: bez zavolání cancel uniká context i všechno, co pro něj rodič drží.",
  ["The second value of the map lookup, the boolean that says the key was present."] = "Druhá hodnota vyhledání v mapě, boolean, který říká, že klíč byl přítomen.",
  ["The sentinel is the poison pill. Go closes the channel once and every receiver wakes; Python has to send one pill per worker."] = "Strážná hodnota je otrávená pilulka. Go zavře kanál jednou a probudí všechny příjemce; Python musí poslat jednu pilulku na každého workera.",
  ["The set method that takes one element out; it raises KeyError if the element is missing."] = "Metoda setu, která vyjme jeden prvek; vyhodí KeyError, když prvek chybí.",
  ["The seven-letter word from the second street of this quest."] = "To sedmipísmenné slovo z druhé ulice téhle výpravy.",
  ["The shared till"] = "Sdílená pokladna",
  ["The shared tray rack"] = "Sdílený regál na tácy",
  ["The shutter queue"] = "Fronta u rolety",
  ["The side smaller values live on. The else branch already shows the other side."] = "Strana, kde bydlí menší hodnoty. Větev else už ukazuje tu druhou.",
  ["The side the larger values live on, visited last."] = "Strana, kde bydlí větší hodnoty, navštívená jako poslední.",
  ["The signboard"] = "Cedule",
  ["The slice built-in that grows. Mark visited when you enqueue, not when you pop."] = "Vestavěná funkce, která slice rozšíří. Označ navštívené při zařazení, ne při vyjmutí.",
  ["The smallest buffer that still holds something. One result, one slot."] = "Nejmenší buffer, který ještě něco udrží. Jeden výsledek, jedno místo.",
  ["The sorting hat"] = "Třídící klobouk",
  ["The sorting hat: a shoebox of receipts. Alex sorts them by splitting the pile in half, again and again, then merging back in order. Bo draws the line between linear and quadratic and labels it n log n."] = "Třídící klobouk: krabice od bot s účtenkami. Alex je třídí půlením hromady, znovu a znovu, a pak slučováním zpět v pořadí. Bo kreslí čáru mezi lineárním a kvadratickým a označí ji n log n.",
  ["The sorting hat: a shoebox of receipts. Alex sorts them by splitting the pile in half, again and again, then merging back in order. Mei draws the line between linear and quadratic and labels it n log n."] = "Třídící klobouk: krabice od bot s účtenkami. Alex je třídí půlením hromady, znovu a znovu, a pak slučováním zpět v pořadí. Mei kreslí čáru mezi lineárním a kvadratickým a označí ji n log n.",
  ["The sorting hat: a shoebox of the night's receipts. Alex sorts them by splitting the pile in half, again and again, then merging the piles back in order. Mei draws the line between linear and quadratic."] = "Třídící klobouk: krabice od bot s účtenkami dnešní noci. Alex je třídí půlením hromady, znovu a znovu, a pak slučováním hromádek zpět v pořadí. Mei kreslí čáru mezi lineárním a kvadratickým.",
  ["The stamp desk"] = "Razítkovací přepážka",
  ["The stamp desk. Bo wants every kitchen function timed and logged without touching its body. In Python a function is a value: wrap it in another and put the wrapper's name, with an @, on the line above."] = "Razítkovací přepážka. Bo chce, aby se každá kuchyňská funkce měřila a logovala, aniž by se sáhlo na její tělo. V Pythonu je funkce hodnota: zabal ji do jiné a jméno obalu s @ dej na řádek nad ni.",
  ["The startup calls back. Seven whiteboard classics: stack, DP, window, heap, intervals, LRU, grid. Get the OFFER."] = "Startup volá zpátky. Sedm klasik od tabule: zásobník, DP, okno, halda, intervaly, LRU, mřížka. Získej OFFER.",
  ["The stock file is left open every night. Then the count is wrong in the morning."] = "Skladový soubor zůstává každou noc otevřený. A ráno je počet špatně.",
  ["The stock room"] = "Sklad",
  ["The stock room. A script counts eggs, trays and coffee beans, and it has been dividing with the wrong slash all year. Alex has typed := ten thousand times; here a plain = will do, and there is no type to write."] = "Sklad. Skript počítá vajíčka, tácy a kávová zrna a celý rok dělil špatným lomítkem. Alex napsal := desettisíckrát; tady stačí obyčejné = a žádný typ se nepíše.",
  ["The stock script counts trays. It says we have 4.1666 trays of eggs. We do not."] = "Skladový skript počítá tácy. Říká, že máme 4,1666 táců vajec. Nemáme.",
  ["The storeroom"] = "Sklad",
  ["The storeroom is small. Sort the trays where they stand; do not build a second rack."] = "Sklad je malý. Třiď tácy tam, kde stojí; nestav druhý regál.",
  ["The storeroom: every algorithm needs somewhere to put things. Sorting the trays where they stand costs no shelf; cloning them onto a new rack costs a rack the size of the input. Mei adds the second axis."] = "Sklad: každý algoritmus potřebuje kam odkládat věci. Třídit tácy tam, kde stojí, nestojí žádnou polici; klonovat je na nový regál stojí regál velikosti vstupu. Mei přidává druhou osu.",
  ["The storeroom: every algorithm needs somewhere to put things. Sorting the trays where they stand costs no shelf; copying them onto a new rack costs a rack the size of the input. Mei adds the second axis to the board."] = "Sklad: každý algoritmus potřebuje kam odkládat věci. Třídit tácy tam, kde stojí, nestojí žádnou polici; kopírovat je na nový regál stojí regál velikosti vstupu. Mei přidává na tabuli druhou osu.",
  ["The storeroom: every algorithm needs somewhere to put things. Sorting the trays where they stand costs no shelf; copying them onto a new rack costs a rack the size of the input. Mei adds the second axis to the last board of the night."] = "Sklad: každý algoritmus potřebuje kam odkládat věci. Třídit tácy tam, kde stojí, nestojí žádnou polici; kopírovat je na nový regál stojí regál velikosti vstupu. Mei přidává druhou osu na poslední tabuli noci.",
  ["The table starts with what is already known. One way to stand at the bottom, and how many ways to reach step 1?"] = "Tabulka začíná tím, co už známe. Jeden způsob, jak stát dole, a kolika způsoby se dostaneš na schod 1?",
  ["The tea table"] = "Stůl s čajem",
  ["The thread may outlive this scope. Which keyword gives the closure ownership of order?"] = "Vlákno může přežít tento blok. Které klíčové slovo dá closure vlastnictví order?",
  ["The three biggest prices, biggest first, in one call. Which heapq helper?"] = "Tři největší ceny, největší první, jedním voláním. Který pomocník z heapq?",
  ["The ticket printer skips dish zero and prints dish five twice. Fix the loop."] = "Tiskárna lístků přeskočí jídlo nula a jídlo pět vytiskne dvakrát. Oprav ten cyklus.",
  ["The till"] = "Pokladna",
  ["The till returns (receipt, err). If err is not the zero value of error, stop. defer close() runs even if you return early."] = "Pokladna vrací (receipt, err). Pokud err není nulová hodnota error, zastav. defer close() běží, i když vrátíš dřív.",
  ["The till says Err and then just stops. Mei, does Rust not have nil?"] = "Pokladna řekne Err a pak se prostě zastaví. Mei, Rust nemá nil?",
  ['The till sends "12" as text. Which built-in turns it into a whole number?'] = 'Kasa posílá "12" jako text. Která vestavěná funkce z toho udělá celé číslo?',
  ["The till thinks every order is a tuple. Give it a struct with names."] = "Pokladna si myslí, že každá objednávka je n-tice. Dej jí struct se jmény.",
  ["The trait behind {}. Debug is behind {:?}. You cannot derive this one."] = "Trait za {}. Debug je za {:?}. Tenhle nejde derivovat.",
  ["The tray is on the table. One last lesson: a request has a context so the kitchen can stop if the guest walks out. And a test so the next morning still compiles."] = "Tác je na stole. Poslední lekce: request má context, aby kuchyně mohla skončit, když host odejde. A test, aby se další ráno pořád kompilovalo.",
  ["The tray rack"] = "Regál na tácy",
  ["The tray rack. Bo's rack script keeps trays in a list and reads the last one with index len minus one, off by one, every night. Python has a shorter way to say 'last'."] = 'Regál na tácy. Boův regálový skript drží tácy v seznamu a poslední čte indexem len minus jedna, o jedna vedle, každou noc. Python má kratší způsob, jak říct „poslední".',
  ["The tray rail"] = "Lišta s tácy",
  ["The tuple assignment does all three moves at once: Go evaluates the right side first."] = "Vícenásobné přiřazení udělá všechny tři tahy najednou: Go nejdřív vyhodnotí pravou stranu.",
  ["The two seconds ran out. Which context error is that?"] = "Ty dvě vteřiny vypršely. Která chyba contextu to je?",
  ["The type itself, used as a constructor. a[:] and a.copy() are the other two spellings."] = "Samotný typ, použitý jako konstruktor. a[:] a a.copy() jsou další dva zápisy.",
  ["The type name works as the conversion. Floor and int never mix silently."] = "Název typu funguje jako konverze. Floor a int se nikdy tiše nemíchají.",
  ["The type name, inside the parentheses. The second line shows the safe two-value form."] = "Název typu v závorkách. Druhý řádek ukazuje bezpečnou dvouhodnotovou formu.",
  ["The type of [] itself, with the item type in square brackets. Older code imported a capitalized one from typing."] = "Typ samotného [], s typem položky v hranatých závorkách. Starší kód importoval verzi s velkým písmenem z typing.",
  ["The type of {} itself, lowercase, key type then value type inside the brackets."] = "Typ samotného {}, malými písmeny, v hranatých závorkách typ klíče a pak typ hodnoty.",
  ["The type whose empty value the append needs. Passed as a callable, no parentheses."] = "Typ, jehož prázdnou hodnotu potřebuje append. Předává se jako volatelný objekt, bez závorek.",
  ["The typed-nil trap: return a plain nil error, never a nil *MyError."] = "Past typovaného nil: vracej čistý nil error, nikdy nil *MyError.",
  ["The usual 'no answer' for a count: negative one."] = "Obvyklé „bez odpovědi“ pro počet: mínus jedna.",
  ["The usual 'not found' number, which is why the return type is i64 and not usize."] = "Obvyklé číslo pro „nenalezeno“, a proto je návratový typ i64, ne usize.",
  ["The usual impossible marker: a negative one, since a real count is never below zero."] = "Obvyklá značka nemožného: minus jedna, protože skutečný počet nikdy není pod nulou.",
  ["The value a function without return gives back, capital letter, used as the type here."] = "Hodnota, kterou vrací funkce bez return, s velkým písmenem, tady použitá jako typ.",
  ["The value of nothing, capital letter. Every function without a return statement gives it back."] = "Hodnota ničeho, s velkým písmenem. Vrací ji každá funkce bez příkazu return.",
  ["The walk stops when the runner falls off the end. Fill the condition: ___ != nil"] = "Průchod končí, když běžec spadne z konce. Doplň podmínku: ___ != nil",
  ["The water byte. Same shape as the land literal, other digit."] = "Bajt vody. Stejný tvar jako literál pevniny, jiná číslice.",
  ["The web counter"] = "Webový pult",
  ["The whiteboard again, the Rust column this time. Mei redraws the axes: n across, work up. First street: the operations whose line stays flat, written the Rust way."] = "Tabule znovu, tentokrát sloupec Rustu. Mei překreslí osy: n vodorovně, práce vzhůru. První ulice: operace, jejichž čára zůstává plochá, zapsané po rustovsku.",
  ["The whiteboard in the back office, wiped clean. Mei draws one axis: n, the size of the input. The other axis is work. First street: operations whose line stays flat however far n goes."] = "Tabule v zadní kanceláři, čistě smazaná. Mei kreslí jednu osu: n, velikost vstupu. Druhá osa je práce. První ulice: operace, jejichž čára zůstává plochá, ať n jde jakkoli daleko.",
  ["The whiteboard one more time, the Python column. Chef Bo takes the marker: n across, work up. First street: the operations whose line stays flat, written the Python way."] = "Tabule ještě jednou, sloupec Pythonu. Šéfkuchař Bo bere fix: n vodorovně, práce vzhůru. První ulice: operace, jejichž čára zůstává plochá, zapsané po pythonovsku.",
  ["The window is s[l..r], both ends included. Fill its length."] = "Okno je s[l..r], oba konce včetně. Doplň jeho délku.",
  ["The window is s[l:r+1]. Record its width if it is the widest yet. Fill the width."] = "Okno je s[l:r+1]. Zaznamenej jeho šířku, pokud je zatím nejširší. Doplň šířku.",
  ["The with block closes and joins the pool for you. Without it, a forgotten pool keeps eight interpreters resident."] = "Blok with za tebe pool zavře a udělá join. Bez něj zapomenutý pool drží osm interpretů v paměti.",
  ["The word package, capitalised, followed by the package's name. One comment per package, in one file."] = "Slovo package s velkým písmenem a za ním jméno balíčku. Jeden komentář na balíček, v jednom souboru.",
  ["The word that follows an if block, here in the middle of one line. Python has no ? : operator."] = "Slovo, které následuje po bloku if, tady uprostřed jednoho řádku. Python nemá operátor ? :.",
  ["The worker appended to my list and my list stayed empty. Every single time."] = "Worker mi udělal append do seznamu a můj seznam zůstal prázdný. Pokaždé.",
  ["The worker has to attach to the same block. Which attribute do you send it?"] = "Worker se musí připojit ke stejnému bloku. Který atribut mu pošleš?",
  ["The workers want a real dict everyone can see. Which class serves one over a proxy?"] = "Workeři chtějí opravdový slovník, který uvidí všichni. Která třída ho nabídne přes proxy?",
  ["The workshop"] = "Dílna",
  ["The zero pointer. This is the base case of the tree recursion."] = "Nulový ukazatel. To je základní případ rekurze nad stromem.",
  ["The zero value of a channel. Receiving on it blocks for ever, which select reads as 'never ready'."] = "Nulová hodnota kanálu. Příjem z něj blokuje navždy, což select čte jako „nikdy připraveno“.",
  ["The zero value of a pointer, slice, map, chan, func, or error is ___."] = "Nulová hodnota pointeru, slice, mapy, chan, func nebo error je ___.",
  ["Then I owe him a tag. And a promise about what the number means."] = "Pak mu dlužím tag. A slib o tom, co to číslo znamená.",
  ["There are no relative imports in Go, ever. An import path is always the full name of a package, so it means the same thing from every file in the world."] = "V Go nejsou relativní importy, nikdy. Importní cesta je vždy plné jméno balíčku, takže znamená totéž z každého souboru na světě.",
  ["There is exactly one way to stand still, and one way to take a single step."] = "Existuje přesně jeden způsob, jak zůstat stát, a jeden, jak udělat jediný krok.",
  ["They asked me this one too. A stack, Bo. Every closer looks at the top."] = "Na tohle se ptali i mě. Zásobník, Bo. Každá zavírací závorka se dívá na vršek.",
  ["They overlap: stretch the merged interval to whichever end is farther. Fill the builtin."] = "Překrývají se: natáhni sloučený interval k tomu konci, který je dál. Doplň builtin.",
  ["They overlap: the merged block ends at the later of the two ends. Which built-in?"] = "Překrývají se: sloučený blok končí na pozdějším z obou konců. Která vestavěná funkce?",
  ["They overlap: the merged block ends at the later of the two ends. Which method picks the larger end?"] = "Překrývají se: sloučený blok končí pozdějším ze dvou konců. Která metoda vybere větší konec?",
  ["This cell is land and part of the island. Sink it before flooding onward, so it is never visited twice. What does the cell become?"] = "Tahle buňka je pevnina a část ostrova. Potop ji, než zaplavíš dál, aby se nikdy nenavštívila dvakrát. Čím se buňka stane?",
  ["This is the trap every threading programmer walks into once. Processes share nothing implicitly: results come back through a Queue, a return value, or shared memory."] = "Do téhle pasti jednou spadne každý programátor odkojený vlákny. Procesy nesdílejí implicitně nic: výsledky se vracejí přes Queue, návratovou hodnotu nebo sdílenou paměť.",
  ["This scan is O(n): the honest cost of a VecDeque order. A doubly linked list with map-held nodes makes it O(1)."] = "Tenhle průchod je O(n): poctivá cena pořadí ve VecDeque. Obousměrný spojový seznam s uzly drženými v mapě to udělá O(1).",
  ["Thread(target=fn, args=(...)) wraps a call. It is an OS thread, heavier than a goroutine, fine for I/O."] = "Thread(target=fn, args=(...)) zabalí volání. Je to vlákno OS, těžší než goroutina, na I/O v pohodě.",
  ["Threads"] = "Vlákna",
  ["Threads and the GIL"] = "Vlákna a GIL",
  ["Threads do help downloads. What happens to the GIL around a socket read?"] = "Stahování vlákna pomáhají. Co se s GILem stane kolem čtení ze socketu?",
  ["Threads that borrow menu and are all joined before the block ends. Which function?"] = "Vlákna, která si půjčují menu a všechna se spojí, než blok skončí. Která funkce?",
  ["Three bowls left. If it says zero, we close."] = "Zbývají tři misky. Když řekne nula, zavíráme.",
  ["Three cooks, one ticket rail, one lock on the rail. That is a worker pool."] = "Tři kuchaři, jedna lišta s lístky, jeden zámek na liště. To je worker pool.",
  ["Three cooks, one ticket rail, one pass. That is a worker pool."] = "Tři kuchaři, jedna lišta s lístky, jedno výdejní okno. To je worker pool.",
  ["Three cooks, three OS threads. Which thread function runs a closure and returns a JoinHandle?"] = "Tři kuchaři, tři vlákna OS. Která funkce z thread spustí closure a vrátí JoinHandle?",
  ["Three dots then the element type. Inside the function fares is a []int."] = "Tři tečky a pak typ prvku. Uvnitř funkce je fares []int.",
  ["Three letters for the chip, an underscore, then the verb for counting. os has the same one."] = "Tři písmena pro čip, podtržítko a pak sloveso pro počítání. os má stejnou.",
  ["Three letters from Ord, the twin of the one that picks the smaller."] = "Tři písmena z Ord, dvojče té, která vybírá menší.",
  ["Three letters from Ord. A plain assignment of cur.1 would shrink a block that already reached further."] = "Tři písmena z Ord. Prosté přiřazení cur.1 by zkrátilo blok, který už sahal dál.",
  ["Three letters from Ord: the smaller of the current entry and the new candidate."] = "Tři písmena z Ord: menší z aktuální položky a nového kandidáta.",
  ["Three letters in front of Lock, Go 1.18 and up. It attempts, it does not queue."] = "Tři písmena před Lock, od Go 1.18. Zkusí to, ale nestoupne si do fronty.",
  ["Three letters, O(1) itself: the slice header stores it."] = "Tři písmena, samo O(1): hlavička slice ji ukládá.",
  ["Three letters, a label on a commit. The v in front is not optional for Go."] = "Tři písmena, štítek na commitu. To v vepředu není pro Go volitelné.",
  ["Three letters, a method with parentheses. Go has the same word as a builtin."] = "Tři písmena, metoda se závorkami. Go má stejné slovo jako vestavěnou funkci.",
  ["Three letters, a statement not a method. Go's delete(m, k), shortened."] = "Tři písmena, příkaz, ne metoda. delete(m, k) z Go, zkráceně.",
  ["Three letters, a verb: attempt it. The except below only makes sense after this."] = "Tři písmena, sloveso: zkus to. except níže má smysl jen po tomhle.",
  ["Three letters, an underscore, and the four-letter word for a mutex."] = "Tři písmena, podtržítko a čtyřpísmenné slovo pro mutex.",
  ["Three letters, as in checksum. Commit it next to go.mod, always."] = "Tři písmena jako v checksum. Commituj ho vedle go.mod, vždycky.",
  ["Three letters, capital N. Takes the message, returns an error."] = "Tři písmena, velké N. Bere zprávu, vrací error.",
  ["Three letters, from Ord. Its twin picks the larger one."] = "Tři písmena, z Ord. Její dvojče vybírá větší.",
  ["Three letters, from the Ord trait. a.max(b) reads better than std::cmp::max(a, b)."] = "Tři písmena, z traitu Ord. a.max(b) se čte líp než std::cmp::max(a, b).",
  ["Three letters, like the fastener that joins two sides tooth by tooth."] = "Tři písmena, jako zapínání, které spojuje dvě strany zub po zubu.",
  ["Three letters, no underscore. The opposite of push. Returns Option<T>."] = "Tři písmena, bez podtržítka. Opak push. Vrací Option<T>.",
  ["Three letters, same as the module behind println!. Runs rustfmt."] = "Tři písmena, stejně jako modul za println!. Spouští rustfmt.",
  ["Three letters, same name as on a Vec. It counts bytes, never characters."] = "Tři písmena, stejné jméno jako u Vec. Počítá bajty, nikdy znaky.",
  ["Three letters, short for buffer."] = "Tři písmena, zkratka slova buffer.",
  ["Three letters, short for command. A convention, not a rule, but one every Go repo follows."] = "Tři písmena, zkratka command. Konvence, ne pravidlo, ale drží se jí každý Go repozitář.",
  ["Three letters, short for dynamic."] = "Tři písmena, zkratka pro dynamic.",
  ["Three letters, short for module. The same word as in go.mod."] = "Tři písmena, zkratka pro module. Stejné slovo jako v go.mod.",
  ["Three letters, short for module. Under GOPATH, read-only, shared by every project on the machine."] = "Tři písmena, zkratka module. Pod GOPATH, jen pro čtení, sdílená každým projektem na stroji.",
  ["Three letters, short for reverse. Only a DoubleEndedIterator has it, and Chars is one."] = "Tři písmena, zkratka pro reverse. Má to jen DoubleEndedIterator, a Chars jím je.",
  ["Three letters, short for sequence. Seq2 yields pairs, like index and value."] = "Tři písmena, zkratka pro sequence. Seq2 dává dvojice, třeba index a hodnotu.",
  ["Three letters, the abbreviation everybody uses. It is a convention, not a rule the compiler knows."] = "Tři písmena, zkratka, kterou používají všichni. Je to konvence, ne pravidlo, které by znal překladač.",
  ["Three letters, the math word for a collection with no duplicates. Go has no built-in one; map[T]bool stands in."] = "Tři písmena, matematické slovo pro kolekci bez duplikátů. Go žádnou vestavěnou nemá; zastupuje ji map[T]bool.",
  ["Three letters, the name of the type itself. float() is its cousin."] = "Tři písmena, jméno samotného typu. float() je jeho bratranec.",
  ["Three letters, the opposite of min. Built in; Go only got it in 1.21."] = "Tři písmena, opak min. Vestavěná; Go ji dostalo až v 1.21.",
  ["Three letters, the opposite of push. With no argument it takes the last item."] = "Tři písmena, opak push. Bez argumentu bere poslední prvek.",
  ["Three letters, the opposite of put. Go's <-jobs."] = "Tři písmena, opak put. <-jobs z Go.",
  ["Three letters, the opposite of the last blank. None when the stack is already empty, and None != Some(open)."] = "Tři písmena, opak minulého doplnění. None, když je zásobník už prázdný, a None != Some(open).",
  ["Three letters, the opposite of the method a worker calls. Go's jobs <- order."] = "Tři písmena, opak metody, kterou volá worker. jobs <- order z Go.",
  ["Three letters, the partner of Put."] = "Tři písmena, parťák metody Put.",
  ["Three letters, the partner of put. Pass timeout= if you would rather not wait for ever."] = "Tři písmena, parťák metody put. Předej timeout=, pokud nechceš čekat věčně.",
  ["Three letters, the plainest verb for starting a program. Once, at the top level."] = "Tři písmena, nejprostší sloveso pro spuštění programu. Jednou, na nejvyšší úrovni.",
  ["Three letters, the plainest verb there is. go work use ./kiosk writes the same line."] = "Tři písmena, nejobyčejnější sloveso, jaké je. go work use ./kiosk zapíše stejný řádek.",
  ["Three letters, the same as Go. Not a method: it is a function that takes the list."] = "Tři písmena, stejně jako v Go. Není to metoda: je to funkce, která dostane seznam.",
  ["Three letters, the same builtin a slice uses for its capacity."] = "Tři písmena, stejná vestavěná funkce, jakou slice používá pro kapacitu.",
  ["Three letters, the same name as on a Vec, but here it returns the top of the heap in O(log k)."] = "Tři písmena, stejné jméno jako u Vec, ale tady vrací vrchol haldy v O(log k).",
  ["Three letters, the same name as the builtin it replaces."] = "Tři písmena, stejné jméno jako vestavěná funkce, kterou nahrazuje.",
  ["Three letters, the start of 'define'. Go's func, Rust's fn."] = "Tři písmena, začátek slova 'define'. func z Go, fn z Rustu.",
  ["Three letters, the text type's own name. An f-string would do the same without the call."] = "Tři písmena, vlastní jméno textového typu. f-string by udělal totéž bez volání.",
  ["Three letters, what you do to fetch something. The @ picks the version; without it, latest."] = "Tři písmena, to, co uděláš, když si pro něco jdeš. @ vybírá verzi; bez něj latest.",
  ["Three letters. A slice of pairs would need a scan, O(n); this hashes the key instead."] = "Tři písmena. Slice dvojic by potřeboval průchod, O(n); tohle místo toho hashuje klíč.",
  ["Three letters. Bigger than any coin count, so the first real answer replaces it."] = "Tři písmena. Větší než jakýkoli počet mincí, takže první skutečná odpověď ho nahradí.",
  ["Three letters. Capacity, not length."] = "Tři písmena. Kapacita, ne délka.",
  ["Three letters. Go has var and :=; Rust has one word for both."] = "Tři písmena. Go má var a :=; Rust má pro obojí jedno slovo.",
  ["Three letters. Heap pointer. dyn has no known size, so it must live behind one."] = "Tři písmena. Ukazatel na heap. dyn nemá známou velikost, takže musí bydlet za jedním.",
  ["Three letters. Lists append; sets do this."] = "Tři písmena. Seznamy dělají append; sety dělají tohle.",
  ["Three letters. Plus. Built into cargo since 1.62; remove is its opposite."] = "Tři písmena. Plus. Součást carga od 1.62; remove je jeho opak.",
  ["Three letters. Rust's word for Go's import, one path at a time."] = "Tři písmena. Rustí slovo pro import z Go, jedna cesta po druhé.",
  ["Three letters. Same word as Vec::new. Add --lib for a library instead."] = "Tři písmena. Stejné slovo jako Vec::new. Přidej --lib, když chceš knihovnu.",
  ["Three letters. Short for mutable, the opposite of the default."] = "Tři písmena. Zkratka pro mutable, opak výchozího stavu.",
  ["Three letters. Takes a reference to the key, returns Option<&V>."] = "Tři písmena. Bere referenci na klíč, vrací Option<&V>.",
  ["Three letters. Takes a reference to the key, returns Option<&V>. The &v pattern copies the u64 out."] = "Tři písmena. Bere referenci na klíč, vrací Option<&V>. Vzor &v vykopíruje u64 ven.",
  ["Three letters. The maths word for adding up. product() is its cousin."] = "Tři písmena. Matematické slovo pro sčítání. product() je jeho bratranec.",
  ["Three letters. The owned heap pointer: one owner, freed when dropped. Not Rc, nobody shares a child."] = "Tři písmena. Vlastnící ukazatel na haldu: jeden vlastník, uvolní se při dropu. Ne Rc, potomka nikdo nesdílí.",
  ["Three letters. The type on the left, : i32, tells it what to produce."] = "Tři písmena. Typ vlevo, : i32, mu říká, co má vyrobit.",
  ["Three letters. This is Python's await: the work started at apply_async."] = "Tři písmena. Tohle je await po pythonovsku: práce začala už u apply_async.",
  ["Three letters. Works anywhere; := only works inside a function."] = "Tři písmena. Funguje všude; := funguje jen uvnitř funkce.",
  ["Three letters. impl Trait ___ Type."] = "Tři písmena. impl Trait ___ Type.",
  ["Three letters. max is its twin. Both take any number of ordered values."] = "Tři písmena. max je její dvojče. Obě berou libovolný počet uspořádaných hodnot.",
  ["Three letters. menu[k] raises when k is missing; this one returns the default instead."] = "Tři písmena. menu[k] vyhodí výjimku, když k chybí; tahle místo toho vrátí výchozí hodnotu.",
  ["Three letters: Atomic Reference Counted."] = "Tři písmena: Atomic Reference Counted.",
  ["Three letters: is there any element for which the closure is true. Vec::contains does the same for one value."] = "Tři písmena: existuje nějaký prvek, pro který je closure pravdivá? Vec::contains dělá totéž pro jednu hodnotu.",
  ["Three letters: to examine. ./... means this package and everything under it."] = "Tři písmena: prověřit. ./... znamená tento balíček a vše pod ním.",
  ["Three letters; the loop calls .add on it. len(set(guests)) < len(guests) is the one-liner."] = "Tři písmena; cyklus na ní volá .add. len(set(guests)) < len(guests) je jednořádková verze.",
  ["Three letters; the next line calls .add on it. Go's map[string]bool, Rust's HashSet."] = "Tři písmena; další řádek na ní volá .add. map[string]bool z Go, HashSet z Rustu.",
  ["Three pairs, one match. '\\0' marks an opener; the rest of the loop branches on that."] = "Tři páry, jeden match. '\\0' značí otevírací; zbytek cyklu se podle toho větví.",
  ["Three parts: ampersand, the mutability word, the receiver. o must be let mut to call it."] = "Tři části: ampersand, slovo pro měnitelnost, receiver. o musí být let mut, aby se dala zavolat.",
  ["Three riders, three radios. The script calls them one after another and the noodles go cold."] = "Tři kurýři, tři vysílačky. Skript je volá jednoho po druhém a nudle chladnou.",
  ["Three threads add to one counter. Which threading object guards it?"] = "Tři vlákna přičítají do jednoho čítače. Který objekt z threading ho hlídá?",
  ["Three woks, one cook script. It fries one egg at a time while the other two woks sit cold."] = "Tři woky, jeden kuchařský skript. Smaží jedno vejce a další dva woky stojí studené.",
  ["Three words in one: check the old value, then put the new one. Everyone calls it CAS."] = "Tři slova v jednom: zkontroluj starou hodnotu a pak vlož novou. Všichni tomu říkají CAS.",
  ["Three words joined: what the operating system schedules, a pool of them, and the thing that runs your calls."] = "Tři slova spojená: to, co plánuje operační systém, jejich fond a to, co spouští tvá volání.",
  ["Three words with underscores: relocate the key to the back of the order."] = "Tři slova s podtržítky: přesuň klíč na konec pořadí.",
  ["Three words with underscores: run, in, and the thing you built at the top of this street."] = "Tři slova s podtržítky: run, in a to, co jsi postavil na začátku téhle ulice.",
  ["Three words with underscores: sort, by, and the thing the closure returns."] = "Tři slova s podtržítky: sort, by a to, co closure vrací.",
  ["Three words, two underscores: skip, the verb for writing out, if. It names a predicate."] = "Tři slova, dvě podtržítka: skip, sloveso pro zapisování ven, if. Pojmenovává predikát.",
  ["Throw away the bool, keep the error. What character discards?"] = "Zahoď bool, nech si error. Který znak zahazuje?",
  ["Ticket five: the app needs a server. net/http is in the standard library: a handler is a function, a route is a string, the server is one call."] = "Ticket pět: appka potřebuje server. net/http je ve standardní knihovně: handler je funkce, routa je string, server je jedno volání.",
  ["Ticket four: orders arrive as JSON. The decoder only sees exported fields, and a tag on the field tells it which key to read."] = "Ticket čtyři: objednávky chodí jako JSON. Dekodér vidí jen exportovaná pole a tag na poli mu říká, který klíč číst.",
  ["Ticket one. The receipt cuts the shop name in half. Bytes, not characters."] = "Ticket jedna. Účtenka usekne název obchodu v půlce. Bajty, ne znaky.",
  ["Ticket seven, the rooftop. The app is live. Newer Go has generic helpers so the old hand-written loops can go: slices, maps, min, and iterators you can range over."] = "Ticket sedm, střecha. Appka je živá. Novější Go má generické pomocníky, takže staré ručně psané smyčky můžou pryč: slices, maps, min a iterátory, přes které jde range.",
  ["Ticket six: ship it. A module names the project, go.mod pins the dependencies, and the go tool formats, checks and builds. No Makefile needed."] = "Ticket šest: nasaď to. Modul pojmenuje projekt, go.mod zafixuje závislosti a nástroj go formátuje, kontroluje a sestavuje. Žádný Makefile netřeba.",
  ["Ticket three: the menu board takes any. Before the app can print a price it must ask what is inside. Go asks with an assertion or a type switch."] = "Ticket tři: tabule s menu bere any. Než appka vypíše cenu, musí se zeptat, co je uvnitř. Go se ptá asercí nebo type switchem.",
  ["Ticket two: refunds. An error must say what went wrong, keep its cause, and let the caller ask which kind it was. All of that is in package errors."] = "Ticket dva: refundace. Error musí říct, co se pokazilo, uchovat příčinu a nechat volajícího zeptat se, jaký druh to byl. To všechno je v balíčku errors.",
  ["Tilde. Without it, type Cents int would not satisfy Number."] = "Tilda. Bez ní by type Cents int nesplňoval Number.",
  ["Time is one axis. Memory is the other. Every cache you loved tonight paid rent here."] = "Čas je jedna osa. Paměť ta druhá. Každá cache, která se ti dnes v noci líbila, tady platila nájem.",
  ["Time is one axis. Memory is the other. Every memo you loved tonight paid rent here."] = "Čas je jedna osa. Paměť ta druhá. Každé memo, které se ti dnes v noci líbilo, tady platilo nájem.",
  ["Time is one axis. Memory is the other. Rust makes you see every allocation; that is the point."] = "Čas je jedna osa. Paměť ta druhá. Rust ti dá vidět každou alokaci; o to jde.",
  ["Time the grill. Fill the prefix: func ___Grill(b *testing.B)"] = "Změř gril. Doplň předponu: func ___Grill(b *testing.B)",
  ["Times Square"] = "Times Square",
  ["Times Square atrium"] = "Atrium Times Square",
  ["Times Square's LED cube is a slice of frames. An array has a fixed size in the type. A slice does not. append returns a (maybe new) slice."] = "LED kostka na Times Square je slice snímků. Pole má pevnou velikost v typu. Slice ne. append vrací (možná nový) slice.",
  ["Times Square's live coding show. Seven rounds of classic interview problems. Get HIRED."] = "Živá programátorská show na Times Square. Sedm kol klasických úloh z pohovorů. Získej PŘIJAT.",
  ["To then Upper. Strings are immutable, so it returns a new one."] = "To a pak Upper. Stringy jsou neměnné, takže vrací nový.",
  ["Toast is off the menu tonight. Which statement removes the key?"] = "Toast dnes v noci z lístku mizí. Který příkaz odstraní klíč?",
  ["Top k frequent dishes: count first. Which HashMap method gives a slot for w, creating it with 0 if new?"] = "Top k nejčastějších jídel: nejdřív počítej. Která metoda HashMap dá slot pro w a vytvoří ho s 0, když je nový?",
  ["Top k most ordered dishes. Count them, then take the k highest counts. Which Counter method?"] = "Top k nejobjednávanějších jídel. Spočítej je, pak vezmi k nejvyšších počtů. Která metoda Counteru?",
  ["Top-down instead: recurse, but remember every result. Which functools decorator?"] = "Místo toho shora: rekurze, ale pamatuj si každý výsledek. Který dekorátor z functools?",
  ["Traits"] = "Traity",
  ["Tram or walk? if the light is green, we go."] = "Tramvají, nebo pěšky? if je zelená, jdeme.",
  ["Tray::default() comes from the Default trait: 0 for numbers, empty String, empty Vec. Also ..Default::default() in struct literals."] = "Tray::default() pochází z traitu Default: 0 pro čísla, prázdný String, prázdný Vec. Také ..Default::default() ve struct literálech.",
  ["True only when nothing is left on the stack: compare its length with zero."] = "Pravda jen tehdy, když na zásobníku nic nezbylo: porovnej jeho délku s nulou.",
  ["True when the stack is empty. An empty list is falsy; negate it."] = "True, když je zásobník prázdný. Prázdný seznam je falsy; zneguj ho.",
  ["TryLock is for work you can skip, not for dodging a design problem. If you reach for it often, the shared state is wrong."] = "TryLock je pro práci, kterou můžeš přeskočit, ne pro obcházení návrhové chyby. Když po něm saháš často, je špatně ten sdílený stav.",
  ["Turn an Option into a Result, with this message as the Err. Which method?"] = "Změň Option na Result s touto zprávou jako Err. Která metoda?",
  ["Turn land into water: the byte for water."] = "Udělej ze souše vodu: bajt pro vodu.",
  ["Turn the Order into JSON bytes. Fill: json.___(order)"] = "Převeď Order na JSON bajty. Doplň: json.___(order)",
  ["Turn the Order into a JSON String. Which serde_json function?"] = "Udělej z Order JSON String. Která funkce ze serde_json?",
  ["Turn the lazy chain back into a Vec. Which method finishes it?"] = "Udělej z líného řetězce zpátky Vec. Která metoda ho dokončí?",
  ["Twelve letters. Things the project depends on. dev-... is the variant for tests only."] = "Dvanáct písmen. Věci, na kterých projekt závisí. dev-... je varianta jen pro testy.",
  ["Twenty goroutines want the menu loaded; load it exactly once. Which method of sync.Once?"] = "Dvacet goroutin chce načtené menu; načti ho právě jednou. Která metoda sync.Once?",
  ["Two ETAs at the same time, both results in one tuple. Which tokio macro?"] = "Dvě ETA najednou, oba výsledky v jedné tuple. Které makro z tokia?",
  ["Two English words glued together: this and the thing you are deriving. Not anyhow."] = "Dvě anglická slova slepená k sobě: this a to, co derivuješ. Ne anyhow.",
  ["Two binaries, one repo. Which directory holds one main package per binary?"] = "Dva binární programy, jeden repozitář. Který adresář drží po jednom balíčku main na program?",
  ["Two braces with nothing between. Note: this makes a dict, not a set; set() is spelled out."] = "Dvě složené závorky a mezi nimi nic. Pozor: tohle vytvoří dict, ne set; set se píše set().",
  ["Two braces with nothing inside. Not %d, not %v."] = "Dvě složené závorky a nic mezi nimi. Ne %d, ne %v.",
  ["Two characters: the receive operator, in front of the channel."] = "Dva znaky: operátor příjmu před kanálem.",
  ["Two choices per topping, multiplied n times. Two, a caret, n."] = "Dvě volby na přílohu, násobeno n krát. Dvě, stříška, n.",
  ["Two colons, then the type in angle brackets. It looks like a fish."] = "Dvě dvojtečky, pak typ v lomených závorkách. Vypadá to jako ryba.",
  ["Two cooks increment the same tray count. Without a lock that is a race. WaitGroup.Add, Done, Wait is how the pass knows both items are ready."] = "Dva kuchaři zvyšují stejný počet táců. Bez zámku je to race. Přes WaitGroup.Add, Done, Wait výdej ví, že jsou obě položky hotové.",
  ["Two dots and one more character that says the end counts too."] = "Dvě tečky a ještě jeden znak, který říká, že konec se počítá taky.",
  ["Two dots, then the sign that says equal too."] = "Dvě tečky, pak znak, který říká i rovno.",
  ["Two goroutines touching one variable, one of them writing, is a data race: go test -race finds it. Share by sending on a channel instead, or protect the reference. A plain map crashes under concurrent writes; sync.Map is built for it. Closing a channel publishes everything written before the close."] = "Dvě goroutiny sahající na jednu proměnnou, z toho jedna zapisuje, je datový souběh: najde ho go test -race. Sdílej raději posláním přes kanál, nebo tu referenci ochraň. Obyčejná mapa při souběžném zápisu spadne; sync.Map je přesně na to. Zavření kanálu zveřejní všechno, co bylo zapsáno před ním.",
  ["Two hands, one tray counter. Lock it. Then wait for both cooks."] = "Dvě ruce, jeden čítač táců. Zamkni ho. Pak počkej na oba kuchaře.",
  ["Two less than n. The base case handles 0 and 1, so this never goes negative."] = "O dva méně než n. Základní případ řeší 0 a 1, takže tohle nikdy nejde do záporu.",
  ["Two letters, the opposite of off. The empty default means the same thing now."] = "Dvě písmena, opak off. Prázdná výchozí hodnota dnes znamená totéž.",
  ["Two letters, the same name a map lookup and a type assertion use."] = "Dvě písmena, stejné jméno, jaké používá vyhledání v mapě a typová aserce.",
  ["Two letters, the same word except and import use to bind a name."] = "Dvě písmena, totéž slovo, kterým except a import navazují jméno.",
  ["Two letters, the same word import and with use to give something a local name."] = "Dvě písmena, totéž slovo, kterým import a with dávají něčemu místní jméno.",
  ["Two letters, the same word the for loop uses between the name and the list."] = "Dvě písmena, totéž slovo, které cyklus for používá mezi jménem a seznamem.",
  ["Two letters, the shortest keyword in the language, and the name of the language."] = "Dvě písmena, nejkratší klíčové slovo v jazyce a zároveň jméno toho jazyka.",
  ["Two letters. == only checks the outer error; this unwraps."] = "Dvě písmena. == kontroluje jen vnější error; tohle rozbaluje.",
  ["Two letters. Go's func with the middle taken out."] = "Dvě písmena. func z Go s vyříznutým prostředkem.",
  ["Two letters. In Rust it is an expression, so it can sit after =."] = "Dvě písmena. V Rustu je to výraz, takže může stát za =.",
  ["Two letters. Is matches a value; this matches a type and fills the pointer."] = "Dvě písmena. Is hledá hodnotu; tohle hledá typ a naplní ukazatel.",
  ["Two letters. Rust never converts numbers silently; you write the cast."] = "Dvě písmena. Rust nikdy nepřevádí čísla potichu; přetypování píšeš ty.",
  ["Two letters. The other nineteen goroutines wait inside it until the first is finished."] = "Dvě písmena. Zbylých devatenáct goroutin uvnitř čeká, dokud první neskončí.",
  ["Two letters. The same word the for loop uses. Its cost depends entirely on the type on the right."] = "Dvě písmena. Totéž slovo, které používá cyklus for. Jeho cena závisí zcela na typu vpravo.",
  ["Two letters. Then a function call. The caller does not wait."] = "Dvě písmena. Pak volání funkce. Volající nečeká.",
  ["Two letters: the same object, not merely equal values. == would work here too, but this is the honest one."] = "Dvě písmena: stejný objekt, ne jen stejné hodnoty. == by tady fungovalo také, ale tohle je to poctivé.",
  ["Two numbers that add up to target. Store value to index; for each x ask if target - x is already there. Which method?"] = "Dvě čísla, která dají dohromady target. Ukládej hodnotu na index; u každého x se ptej, jestli tam už je target - x. Která metoda?",
  ["Two of the same character. One of them alone gives 4.1666, a float, every time."] = "Dvakrát stejný znak. Jeden sám dá vždy 4.1666, float.",
  ["Two packages in one file. What keyword opens the grouped list?"] = "Dva balíčky v jednom souboru. Které klíčové slovo otevírá seskupený seznam?",
  ["Two pointers that only move right: O(n) time, O(alphabet) space. 'abcabcbb' gives 3."] = "Dva ukazatele, které se hýbou jen doprava: čas O(n), paměť O(abeceda). 'abcabcbb' dá 3.",
  ["Two pointers walk inward from both ends. Fill the step: i, j = i+1, ___"] = "Dva ukazatele jdou z obou konců dovnitř. Doplň krok: i, j = i+1, ___",
  ["Two pointers: O(n) time, O(1) extra space. Same trick for sorted-array pair sums."] = "Dva ukazatele: čas O(n), O(1) paměti navíc. Stejný trik pro součty dvojic v seřazeném poli.",
  ["Two processes, one conversation, no queue machinery. Which function?"] = "Dva procesy, jedna konverzace, žádná mašinerie front. Která funkce?",
  ["Two repos, one laptop"] = "Dva repozitáře, jeden notebook",
  ["Two runners: slow hops one node a lap, fast two. hop turns Option<Box<T>> into Option<&T>. Which method?"] = "Dva běžci: slow skáče o jeden uzel za kolo, fast o dva. hop mění Option<Box<T>> na Option<&T>. Která metoda?",
  ["Two separate loops over the same n items, one after the other: O(n) + O(n) simplifies to O(___)"] = "Dva oddělené cykly přes stejných n položek, jeden po druhém: O(n) + O(n) se zjednoduší na O(___)",
  ["Two separate passes over the same n items, one after the other: O(n) + O(n) simplifies to O(___)"] = "Dva oddělené průchody přes stejných n položek, jeden po druhém: O(n) + O(n) se zjednoduší na O(___)",
  ["Two singles, or one double. Count them."] = "Dva jednotlivé, nebo jeden dvojitý. Spočítej je.",
  ["Two slashes. A single one makes a float, and a[3.5] raises TypeError."] = "Dvě lomítka. Jedno udělá float a a[3.5] vyhodí TypeError.",
  ["Two slashes. Same as Go, C and JavaScript."] = "Dvě lomítka. Stejně jako v Go, C a JavaScriptu.",
  ["Two slashes: floor division. A single slash would make 3.5 and the slice would raise TypeError."] = "Dvě lomítka: celočíselné dělení. Jedno lomítko by dalo 3.5 a řez by vyhodil TypeError.",
  ["Two sorted lists, two pointers: O(n log n). rooms peaks at the answer and never has to come down."] = "Dva seřazené seznamy, dva ukazatele: O(n log n). rooms vrcholí na odpovědi a nikdy nemusí klesat.",
  ["Two stars, then the name the body reads .items() from. Inside, it is a dict."] = "Dvě hvězdičky a pak jméno, ze kterého tělo čte .items(). Uvnitř je to dict.",
  ["Two stars. Go has no operator for this; Python and Rust's pow() do."] = "Dvě hvězdičky. Go pro to operátor nemá; Python ano a Rust má pow().",
  ["Two steps below i. The loop starts at 2 so this index never goes negative."] = "Dva schody pod i. Cyklus začíná na 2, takže index nikdy nejde do záporu.",
  ["Two steps below i. The same shape as fib, without the recursion."] = "Dva schody pod i. Stejný tvar jako fib, bez rekurze.",
  ["Two tills need two senders into the same pipe. Which method makes the second?"] = "Dvě pokladny potřebují dva odesílatele do stejné trubky. Která metoda vytvoří druhého?",
  ["Two tills, both adding to sold. At 12:04 the screen says 311, the drawer says 317."] = "Dvě kasy, obě přičítají do sold. Ve 12:04 obrazovka hlásí 311 a zásuvka 317.",
  ["Two tills, one counter"] = "Dvě kasy, jeden čítač",
  ["Two tills, one kitchen. Orders pile up on my side and never arrive."] = "Dvě pokladny, jedna kuchyně. Objednávky se hromadí u mě a nikdy nedorazí.",
  ["Two tills, six woks and forty riders touch the same numbers. Lock it, share it, cancel it. And find Go's await."] = "Dvě kasy, šest woků a čtyřicet kurýrů sahá na stejná čísla. Zamkni to, sdílej to, zruš to. A najdi await po způsobu Go.",
  ["Two underscores, the name of the function above, two underscores. As a module the value would be the file name."] = "Dvě podtržítka, jméno funkce nahoře, dvě podtržítka. Jako modul by hodnotou bylo jméno souboru.",
  ["Two underscores, the start of initialize, two underscores. Dunder methods all look like this."] = "Dvě podtržítka, začátek slova initialize, dvě podtržítka. Všechny dunder metody vypadají takto.",
  ["Two words are anagrams if their letters, put in order, match. Which built-in orders them?"] = "Dvě slova jsou anagramy, když se jejich písmena po seřazení shodují. Která vestavěná funkce je seřadí?",
  ["Two words as one, camelCase: use this, instead of that. The ssh form replaces the https prefix."] = "Dvě slova jako jedno, camelCase: použij tohle místo tamtoho. Tvar ssh nahradí předponu https.",
  ["Two words glued: the verb you call to wait, and a thing you hold."] = "Dvě slepená slova: sloveso, které voláš při čekání, a věc, kterou držíš.",
  ["Two words joined by an underscore: the ones that appear the most, the way people say it."] = "Dvě slova spojená podtržítkem: ty, co se objevují nejčastěji, jak to lidi říkají.",
  ["Two words joined, CapWords: stop, and the thing generators do. A for loop catches it silently."] = "Dvě slova spojená, CapWords: zastavit, a to, co generátory dělají. Cyklus for ji tiše zachytí.",
  ["Two words joined, lowercase. The first parameter is spelled cls by convention."] = "Dvě slova spojená, malými písmeny. První parametr se podle konvence píše cls.",
  ["Two words joined, lowercase: not moving, and what a def in a class is."] = "Dvě slova spojená, malými písmeny: nehybný, a jak se říká def ve třídě.",
  ["Two words joined, lowercase: the thing a with statement needs, as one name."] = "Dvě slova spojená, malými písmeny: to, co příkaz with potřebuje, jako jedno jméno.",
  ["Two words joined, no underscore: how it left, as a number. None until it has."] = "Dvě slova spojená bez podtržítka: jak odešel, jako číslo. Do té doby None.",
  ["Two words joined: the mod folder, and what kind of folder it is. Eight letters."] = "Dvě slova spojená: složka mod a jaký druh složky to je. Osm písmen.",
  ["Two words with an underscore: as, then the past participle of complete."] = "Dvě slova s podtržítkem: as a pak příčestí od complete.",
  ["Two words with an underscore: make one of the things the loop schedules. tokio::spawn."] = "Dvě slova s podtržítkem: vytvořit jednu z věcí, které smyčka plánuje. tokio::spawn.",
  ["Two words with an underscore: the task, and the state it is now in."] = "Dvě slova s podtržítkem: úloha a stav, ve kterém teď je.",
  ["Two words with an underscore: the unit of work, then the past tense of finish."] = "Dvě slova s podtržítkem: jednotka práce a pak minulý tvar slovesa dokončit.",
  ["Two words, CamelCase: a dict with an order."] = "Dvě slova, CamelCase: dict s pořadím.",
  ["Two words: the moment you promised, and what the clock did to it. The other one is Canceled."] = "Dvě slova: okamžik, který jsi slíbil, a co s ním udělaly hodiny. To druhé je Canceled.",
  ["Two-sum in one pass: for each x, is target minus x already known? Which dict is checked?"] = "Two-sum na jeden průchod: pro každé x, je target minus x už známé? Který dict se kontroluje?",
  ["Two-sum on a sorted slice, no HashMap: i from the left, j from the right. The sum is too big: which way does j move?"] = "Two-sum na seřazeném slice, bez HashMap: i zleva, j zprava. Součet je moc velký: kam se pohne j?",
  ["Two-sum, anagrams, palindromes"] = "Two-sum, anagramy, palindromy",
  ["Two-sum, palindrome, anagram"] = "Two-sum, palindrom, anagram",
  ["Two-sum: a dict of seen values, one pass. Anagram: sorted(a) == sorted(b), or a Counter. Palindrome: two pointers from both ends."] = "Two-sum: dict viděných hodnot, jeden průchod. Anagram: sorted(a) == sorted(b), nebo Counter. Palindrom: dva ukazatele z obou konců.",
  ["Type hints"] = "Typové nápovědy",
  ["Type name, two colons, the method that copies a handle."] = "Jméno typu, dvě dvojtečky, metoda, která kopíruje handle.",
  ["Type parameters go in [T any]. Embedding promotes methods. A closure captures nearby names."] = "Typové parametry jdou do [T any]. Embedding povyšuje metody. Closure zachytí okolní jména.",
  ["Type the answer, then ENTER."] = "Napiš odpověď a stiskni ENTER.",
  ["Un + Marshal. It needs a pointer so it can fill your variable."] = "Un + Marshal. Potřebuje ukazatel, aby mohl naplnit tvou proměnnou.",
  ["Unchanged. That is the whole meaning of the 1 in O(1)."] = "Nezměněná. To je celý význam té 1 v O(1).",
  ["Unexported fields are skipped silently. Capital letters or nothing."] = "Neexportovaná pole se tiše přeskočí. Velká písmena, nebo nic.",
  ["Unknown shape from the rider app. Which serde_json type holds any JSON?"] = "Neznámý tvar z appky kurýrů. Který typ ze serde_json pojme libovolný JSON?",
  ["Unmarshal(data, &v). Without & it decodes into a copy and you see nothing."] = "Unmarshal(data, &v). Bez & dekóduje do kopie a ty nevidíš nic.",
  ["Unpack the Some or leave the function, no match block. Which keyword completes it?"] = "Rozbal Some, nebo opusť funkci, bez bloku match. Které klíčové slovo to doplní?",
  ["Unseen neighbours go to the back of the queue. Fill: queue = ___(queue, nb)"] = "Nenavštívení sousedé jdou na konec fronty. Doplň: queue = ___(queue, nb)",
  ["Up, down, right, left. A dirs table {{1,0},{-1,0},{0,1},{0,-1}} is the same thing in a loop."] = "Nahoru, dolů, doprava, doleva. Tabulka dirs {{1,0},{-1,0},{0,1},{0,-1}} je totéž v cyklu.",
  ["Valid means matched and closed. O(n) time, O(n) stack in the worst case: a string of openers."] = "Platné znamená spárované a zavřené. Čas O(n), zásobník O(n) v nejhorším případě: řetězec samých otevíracích.",
  ["Valid parentheses and a min stack"] = "Platné závorky a zásobník s minimem",
  ["Valid parentheses, min stack"] = "Platné závorky, min stack",
  ["Value and Array are the small end of shared memory: a type code, a size, and a lock in the box. SharedMemory is the large end."] = "Value a Array jsou malý konec sdílené paměti: kód typu, velikost a zámek v krabičce. SharedMemory je ten velký konec.",
  ["Value ships with a lock so you do not invent one. Read, add, write is three steps here exactly as it was in Go."] = "Value přichází se zámkem, abys žádný nevymýšlel. Přečíst, přičíst, zapsat jsou tři kroky přesně jako v Go.",
  ["Variables need no type. int() and str() convert. // divides down, ** is power. None is no value."] = "Proměnné nepotřebují typ. int() a str() převádějí. // dělí dolů, ** je mocnina. None je žádná hodnota.",
  ["Variables, types, const"] = "Proměnné, typy, const",
  ["Vec grows with push. Arrays have a fixed length in the type. HashMap stores key to value; get returns Option."] = "Vec roste přes push. Pole mají pevnou délku v typu. HashMap ukládá klíč na hodnotu; get vrací Option.",
  ["Vec plus Deque, a double-ended queue. A ring buffer: O(1) at both ends. Vec::remove(0) would be O(n)."] = "Vec plus Deque, oboustranná fronta. Kruhový buffer: O(1) na obou koncích. Vec::remove(0) by bylo O(n).",
  ["Vec, arrays and HashMap"] = "Vec, pole a HashMap",
  ["Vec::sort is a merge sort; sort_unstable is pattern-defeating quicksort. Both n log n."] = "Vec::sort je merge sort; sort_unstable je pattern-defeating quicksort. Oboje n log n.",
  ["Vec<Box<dyn Cook>>: every Box is one pointer wide, so the Vec is happy. Dispatch happens at run time. The kiosk shows one list."] = "Vec<Box<dyn Cook>>: každý Box je široký jako jeden ukazatel, takže Vec je spokojený. Dispatch se děje za běhu. Kiosek ukazuje jeden seznam.",
  ["VecDeque::from([start]) seeds the queue. seen starts with start too, so it is never queued twice."] = "VecDeque::from([start]) naplní frontu. seen taky začíná se start, takže se nikdy nezařadí dvakrát.",
  ["WHAT ALEX LEARNED: Go basics.   PRIZE: the morning set."] = "CO SE ALEX NAUČIL: základy Go.   ODMĚNA: ranní menu.",
  ["WHAT ALEX LEARNED: Mutex and atomics, shared references, worker pools, pipelines, context, and that go plus a channel is await.   PRIZE: the SYNCED stamp."] = "CO SE NAUČIL ALEX: Mutex a atomiky, sdílené reference, fondy workerů, linky, context, a že go plus kanál je await.   CENA: razítko SYNCED.",
  ["WHAT ALEX LEARNED: O(1) to O(2^n), and how to read a loop.   PRIZE: the O(1) stamp."] = "CO SE ALEX NAUČIL: od O(1) po O(2^n) a jak číst cyklus.   CENA: razítko O(1).",
  ["WHAT ALEX LEARNED: O(1) to O(2^n), maps beat loops, sort then search.   PRIZE: the O(1) stamp."] = "CO SE ALEX NAUČIL: od O(1) po O(2^n), mapy porážejí cykly, nejdřív seřadit, pak hledat.   CENA: razítko O(1).",
  ["WHAT ALEX LEARNED: Python basics, lists, dicts, classes.   PRIZE: the shutter comes down."] = "CO SE ALEX NAUČIL: základy Pythonu, listy, dicty, třídy.   CENA: roleta jde dolů.",
  ["WHAT ALEX LEARNED: Result, traits, lifetimes, threads, Arc<Mutex>.   PRIZE: milk tea and a pineapple bun."] = "CO SE ALEX NAUČIL: Result, traity, lifetimy, vlákna, Arc<Mutex>.   CENA: čaj s mlékem a ananasová houska.",
  ["WHAT ALEX LEARNED: Rust basics, ownership.   PRIZE: the afternoon tea set."] = "CO SE ALEX NAUČIL: základy Rustu, vlastnictví.   CENA: odpolední svačina.",
  ["WHAT ALEX LEARNED: String, errors, iterators, serde, async, cargo.   PRIZE: the service shipped."] = "CO SE ALEX NAUČIL: String, chyby, iterátory, serde, async, cargo.   CENA: služba běží.",
  ["WHAT ALEX LEARNED: exceptions, generators, decorators, with, asyncio, typing.   PRIZE: the midnight bowl."] = "CO SE ALEX NAUČIL: výjimky, generátory, dekorátory, with, asyncio, typování.   CENA: půlnoční miska.",
  ["WHAT ALEX LEARNED: goroutines, channels, sync.   PRIZE: the morning set."] = "CO SE ALEX NAUČIL: goroutiny, kanály, sync.   ODMĚNA: ranní menu.",
  ["WHAT ALEX LEARNED: recursion, trees, graphs, lists, sorting, hashing, workers.   PRIZE: HIRED."] = "CO SE ALEX NAUČIL: rekurze, stromy, grafy, seznamy, řazení, hashování, workery.   ODMĚNA: PŘIJAT.",
  ["WHAT ALEX LEARNED: stacks, DP, sliding windows, heaps, intervals, LRU, grid DFS.   PRIZE: the OFFER."] = "CO SE ALEX NAUČIL: zásobníky, DP, posuvná okna, haldy, intervaly, LRU, DFS v mřížce.   ODMĚNA: OFFER.",
  ["WHAT ALEX LEARNED: strings, errors, JSON, HTTP.   PRIZE: the app is live."] = "CO SE ALEX NAUČIL: stringy, chyby, JSON, HTTP.   ODMĚNA: aplikace běží.",
  ["WHAT ALEX LEARNED: the module path is the import path, a folder is a package, go get and go.sum, internal and cmd, replace and go.work, semver tags and /v2, the proxy and GOPRIVATE.   PRIZE: the v1.0.0 tag."] = "CO SE NAUČIL ALEX: cesta modulu je cesta importu, složka je balíček, go get a go.sum, internal a cmd, replace a go.work, semver tagy a /v2, proxy a GOPRIVATE.   CENA: tag v1.0.0.",
  ["WHAT CHEF BO LEARNED: the GIL, Process and the main guard, Pool and chunksize, Queue and Pipe, locks and Value, shared_memory, ProcessPoolExecutor.   PRIZE: the SCALED stamp."] = "CO SE NAUČIL ŠÉF BO: GIL, Process a stráž main, Pool a chunksize, Queue a Pipe, zámky a Value, shared_memory, ProcessPoolExecutor.   CENA: razítko SCALED.",
  ["WHAT CHEF BO SHOWED: list stacks, DP, windows, heapq, intervals, OrderedDict LRU, grid DFS.   PRIZE: the OFFER."] = "CO UKÁZAL ŠÉFKUCHAŘ BO: zásobníky ze seznamů, DP, okna, heapq, intervaly, LRU z OrderedDict, DFS v mřížce.   CENA: OFFER.",
  ["WHAT CHEF BO SHOWED: recursion, trees, graphs, lists, sorting, hashing, workers, in Python.   PRIZE: HIRED."] = "CO UKÁZAL ŠÉFKUCHAŘ BO: rekurzi, stromy, grafy, seznamy, třídění, hashování, workery, v Pythonu.   CENA: PŘIJAT.",
  ["WHAT MEI SHOWED: O(1) to O(2^n), HashMap beats Vec::contains, sort then binary_search.   PRIZE: the O(1) stamp."] = "CO UKÁZALA MEI: od O(1) po O(2^n), HashMap poráží Vec::contains, nejdřív seřadit, pak binary_search.   CENA: razítko O(1).",
  ["WHAT MEI SHOWED: Vec as a stack, DP tables, windows, BinaryHeap, intervals, an LRU, grid DFS.   PRIZE: the OFFER."] = "CO MEI PŘEDVEDLA: Vec jako zásobník, DP tabulky, okna, BinaryHeap, intervaly, LRU, DFS v mřížce.   CENA: OFFER.",
  ["WHAT MEI SHOWED: recursion, trees, graphs, lists, sorting, hashing, workers, in Rust.   PRIZE: HIRED."] = "CO MEI PŘEDVEDLA: rekurzi, stromy, grafy, seznamy, třídění, hashování, workery, v Rustu.   CENA: PŘIJATA.",
  ["WIND"] = "OKNO",
  ["Wait for all three woks before printing the receipt. Which method blocks until a thread is done?"] = "Počkat na všechny tři woky, než se vytiskne účtenka. Která metoda blokuje, dokud vlákno neskončí?",
  ["Wait for every cook to finish before closing the kitchen. Which JoinHandle method blocks until the thread ends?"] = "Počkej, až každý kuchař skončí, než zavřeš kuchyni. Která metoda JoinHandle blokuje, dokud vlákno neskončí?",
  ["Wait for the tea thread and take its result. Which method?"] = "Počkej na vlákno s čajem a vezmi si jeho výsledek. Která metoda?",
  ["Wait on muffin or hash brown, whichever is ready. Which keyword?"] = "Čekej na muffin nebo hash brown, co je dřív hotové. Které klíčové slovo?",
  ["Wait one second without freezing the loop. Which asyncio function, never time.sleep?"] = "Počkat sekundu bez zamrznutí smyčky. Která funkce z asyncio, nikdy time.sleep?",
  ["Wait then close(results) in a goroutine: the receiver's range ends cleanly. No leaks."] = "Wait a pak close(results) v goroutině: range příjemce čistě skončí. Žádné úniky.",
  ["Wait until both cooks call Done. Fill: var wg sync.___"] = "Čekej, až oba kuchaři zavolají Done. Doplň: var wg sync.___",
  ["WaitGroup.Add(n), Done(), Wait(). The tray leaves when n hits zero."] = "WaitGroup.Add(n), Done(), Wait(). Tác odjíždí, když n klesne na nulu.",
  ["Waiting on the network or burning the CPU: which word changes for CPU work?"] = "Čekání na síť, nebo pálení procesoru: které slovo se pro procesorovou práci změní?",
  ["Waiting overlaps under the GIL; computing does not. That one sentence chooses the executor every time."] = "Čekání se pod GILem překrývá, počítání ne. Ta jediná věta vybere executor pokaždé.",
  ["Walk every cell. Each unsunk building starts a new island: sink it whole, then add one. Fill the operator."] = "Projdi každou buňku. Každá nepotopená budova začíná nový ostrov: potop ho celý, pak přičti jedna. Doplň operátor.",
  ["Walk every cell. Land that is still standing is a new island: count it and sink all of it. Which function does the sinking?"] = "Projdi každou buňku. Pevnina, která ještě stojí, je nový ostrov: započítej ho a celý potop. Která funkce potápí?",
  ["Walk every shop name in a slice. Fill: for _, name := ___ shops"] = "Projdi každé jméno obchodu ve slice. Doplň: for _, name := ___ shops",
  ["Walk from the flat to Lucky Mac. Fix every Go bug on the way."] = "Dojdi z bytu do Lucky Macu. Cestou oprav každý Go bug.",
  ["Walk names and quantities side by side. Which built-in pairs two lists?"] = "Projít jména a množství vedle sebe. Která vestavěná funkce spáruje dva seznamy?",
  ["Walk over a Vec by reference, no index. Which method starts the iterator?"] = "Projdi Vec přes referenci, bez indexu. Která metoda spustí iterátor?",
  ["Walk with Mei to Lucky Mac Express. Fix every Rust kiosk on the way."] = "Dojdi s Mei do Lucky Mac Express. Cestou oprav každý rustový kiosek.",
  ["Walking by reference: no clone, no take, nothing moves. node is &Box<ListNode>, auto-deref reaches next."] = "Průchod referencí: žádný clone, žádný take, nic se nepřesouvá. node je &Box<ListNode>, auto-deref se dostane na next.",
  ["Warm the grill exactly once, however many cooks call it. Fill: var once sync.___"] = "Rozehřej gril přesně jednou, ať ho volá kolik chce kuchařů. Doplň: var once sync.___",
  ["Warm, fry and brew at once; stop all three on the first error. Which package?"] = "Ohřát, osmažit a zalít naráz; při první chybě zastavit všechno. Který balík?",
  ["Was the key there? The second result is a bool named ___."] = "Byl tam klíč? Druhý výsledek je bool jménem ___.",
  ["Water, or land already sunk, ends the flood. The grid holds bytes: which byte literal is land?"] = "Voda, nebo už potopená pevnina, záplavu ukončí. Mřížka drží bajty: který bajtový literál je pevnina?",
  ["Ways to climb 0 steps and 1 step: one each. Fill the base cases."] = "Způsoby, jak vyjít 0 schodů a 1 schod: po jednom. Doplň základní případy.",
  ["We already checked mid, so skip past it. hi = mid keeps the half-open rule."] = "mid jsme už zkontrolovali, tak ho přeskoč. hi = mid drží polootevřené pravidlo.",
  ["Welcome back, Alex. The callback is the whiteboard round. First: are these brackets balanced?"] = "Vítej zpátky, Alexi. Callback je kolo u tabule. Nejdřív: jsou tyhle závorky vyvážené?",
  ["Welcome to CODE RUSH! Round one: factorial, then fib without the exponential blowup. Buzzer's live!"] = "Vítej v CODE RUSH! Kolo jedna: faktoriál, pak fib bez exponenciální exploze. Bzučák je živý!",
  ["What a channel does. The -ing form of the verb in the first half of the line."] = "To, co dělá kanál. Tvar slovesa na -ing z první poloviny řádku.",
  ["What goes between the parameter list and the return type u32?"] = "Co patří mezi seznam parametrů a návratový typ u32?",
  ["What is __name__ equal to when the file is run directly, not imported?"] = "Čemu se rovná __name__, když se soubor spustí přímo, ne importem?",
  ["What is the lightweight thread go starts called?"] = "Jak se jmenuje lehké vlákno, které go spouští?",
  ["What is the three-letter name of the lock that lets one thread run bytecode at a time?"] = "Jak se třemi písmeny jmenuje zámek, který nechá spouštět bajtkód jen jedno vlákno naráz?",
  ["What versions of everything is this build using? Fill the subcommand."] = "Jaké verze všeho tento build používá? Doplň podpříkaz.",
  ["Whatever opened last must close first. That sentence is a stack."] = "Co se otevřelo naposled, musí se zavřít první. Ta věta je zásobník.",
  ["When fast reaches the end, slow is halfway. One pass, no length count."] = "Když fast dojde na konec, slow je v půlce. Jeden průchod, žádné počítání délky.",
  ["When fast runs out, slow stands in the middle. O(n) time, O(1) space, and Option<&T> is Copy so the hops are free. Combo x4."] = "Až fast dojde, slow stojí uprostřed. Čas O(n), paměť O(1), a Option<&T> je Copy, takže skoky jsou zadarmo. Kombo x4.",
  ["When you edit a library and its caller at the same time, replace points a module path at a folder on disk, and go.work does it for a whole workspace without touching any go.mod. cannot find module means the import path and go.mod disagree; go mod tidy repairs go.mod from the imports. go mod vendor copies every dependency into the repo for builds with no network."] = "Když upravuješ knihovnu a jejího volajícího zároveň, replace nasměruje cestu modulu na složku na disku a go.work to udělá pro celý pracovní prostor bez sahání na jakýkoli go.mod. cannot find module znamená, že importní cesta a go.mod nesouhlasí; go mod tidy opraví go.mod podle importů. go mod vendor zkopíruje každou závislost do repozitáře pro buildy bez sítě.",
  ["Where did the download actually land? Fill the last directory of the cache."] = "Kam stažení doopravdy přistálo? Doplň poslední adresář cache.",
  ["Where do cur and best start? Not at 0: a list of only losses still has a best hour."] = "Kde začínají cur a best? Ne na 0: seznam samých ztrát má pořád nejlepší hodinu.",
  ["Where does a context go? Name the first parameter every Go API uses."] = "Kam patří context? Pojmenuj první parametr, který používá každé Go API.",
  ["Where does go get look first, and what does it fall back to? Fill the fallback."] = "Kam se go get dívá nejdřív a k čemu se uchýlí potom? Doplň záložní hodnotu.",
  ["Where is await?"] = "Kde je await?",
  ["Which Cargo.toml section lists the crates the project uses?"] = "Která sekce Cargo.toml vyjmenovává crates, které projekt používá?",
  ["Which Go type finds a price by name in O(1), on average?"] = "Který typ v Go najde cenu podle jména v O(1), v průměru?",
  ["Which built-in reads a line typed at the terminal?"] = "Která vestavěná funkce přečte řádek napsaný v terminálu?",
  ["Which built-in tells you what kind of value price is?"] = "Která vestavěná funkce ti řekne, jakého druhu je hodnota price?",
  ["Which built-in type finds a price by name in O(1), on average?"] = "Který vestavěný typ najde cenu podle jména v O(1), v průměru?",
  ["Which built-in writes a line to the terminal?"] = "Která vestavěná funkce vypíše řádek do terminálu?",
  ["Which directory name makes a package importable only from inside this module?"] = "Které jméno adresáře udělá balíček importovatelný jen zevnitř tohoto modulu?",
  ["Which go.mod is in charge here? Ask the tool for the file it found."] = "Který go.mod tady velí? Zeptej se nástroje, jaký soubor našel.",
  ["Which keyword before def makes fetch a coroutine?"] = "Které klíčové slovo před def udělá z fetch korutinu?",
  ["Which keyword binds a name to a value in Rust?"] = "Které klíčové slovo v Rustu sváže jméno s hodnotou?",
  ["Which keyword brings HashMap from the standard library into this file?"] = "Které klíčové slovo přinese HashMap ze standardní knihovny do tohoto souboru?",
  ["Which keyword brings the time module in?"] = "Které klíčové slovo přinese modul time?",
  ["Which keyword declares a function in Rust?"] = "Které klíčové slovo v Rustu deklaruje funkci?",
  ["Which keyword declares a set of methods that types can promise?"] = "Které klíčové slovo deklaruje sadu metod, kterou typy mohou slíbit?",
  ["Which keyword defines a new type?"] = "Které klíčové slovo definuje nový typ?",
  ["Which keyword opens the block whose errors you want to catch?"] = "Které klíčové slovo otevírá blok, jehož chyby chceš zachytit?",
  ["Which keyword starts a function definition?"] = "Které klíčové slovo začíná definici funkce?",
  ["Which letter before the quote lets {n} be replaced by the value of n?"] = "Které písmeno před uvozovkou nechá {n} nahradit hodnotou n?",
  ["Which method returns 9 for the three characters of 銅鑼灣?"] = "Která metoda vrátí 9 pro tři znaky 銅鑼灣?",
  ["Which operator raises 2 to the tenth power?"] = "Který operátor umocní 2 na desátou?",
  ["Which placeholder inside the string prints the value of n?"] = "Který zástupný znak uvnitř řetězce vypíše hodnotu n?",
  ["Which special method runs when Order('noodles') is created?"] = "Která speciální metoda běží, když se vytvoří Order('noodles')?",
  ["Which standard library module gives real parallelism for CPU work?"] = "Který modul standardní knihovny dá skutečnou paralelizaci pro práci s procesorem?",
  ["Which standard package prints to the terminal?"] = "Který standardní balíček tiskne do terminálu?",
  ["Which std collection finds a price by name in O(1), on average?"] = "Která kolekce ze std najde cenu podle jména v O(1), v průměru?",
  ["Which std trait, with an empty body, makes OrderError a real error?"] = "Který trait ze std, s prázdným tělem, udělá z OrderError opravdovou chybu?",
  ["Why do four threads not make four times the arithmetic? Name the lock, three letters."] = "Proč čtyři vlákna nezvládnou čtyřnásobek aritmetiky? Pojmenuj ten zámek, tři písmena.",
  ["Why does a second process escape the lock? Each one has its own ___."] = "Proč druhý proces tomu zámku unikne? Každý má vlastní ___.",
  ["Why threads do not go faster"] = "Proč vlákna nezrychlí",
  ["With a JoinableQueue the parent waits for the work, not the workers. Which call acknowledges one item?"] = "S JoinableQueue čeká rodič na práci, ne na workery. Které volání potvrdí jednu položku?",
  ["With a cache every fib(k) is computed once. The cost drops to O(___)"] = "S cache se každé fib(k) spočítá jednou. Cena klesne na O(___)",
  ["With a memo every fib(k) is computed once. The cost drops to O(___)"] = "S memem se každé fib(k) spočítá jednou. Cena klesne na O(___)",
  ["With a vendor directory present, go build uses it and never touches the network or the cache. It is the whole dependency set, checked in, reviewable in a diff."] = "S přítomným adresářem vendor ho go build použije a nikdy se nedotkne sítě ani cache. Je to celá sada závislostí, commitnutá, revidovatelná v diffu.",
  ["With cap 1 the sender finishes even if the context won the select. With an unbuffered channel that goroutine would block for ever: a leak."] = "S kapacitou 1 odesílatel doběhne, i když v selectu vyhraje context. S kanálem bez bufferu by ta goroutina blokovala navždy: únik.",
  ["With, then a duration word. The twin that takes a time.Time is WithDeadline."] = "With a k tomu slovo pro dobu trvání. Dvojče, které bere time.Time, je WithDeadline.",
  ["With, then the verb for stopping. Its siblings are WithTimeout and WithDeadline."] = "With a k tomu sloveso pro zastavení. Sourozenci jsou WithTimeout a WithDeadline.",
  ["With, then the word for a time limit. WithDeadline takes a clock time instead."] = "With, pak slovo pro časový limit. WithDeadline místo toho bere čas na hodinách.",
  ["With, then the word for what is stored. The key is a private type so nobody can collide with it."] = "With a k tomu slovo pro to, co se ukládá. Klíč je soukromý typ, aby se s ním nikdo nesrazil.",
  ["WithTimeout returns a child that cancels itself. Always defer cancel() or you leak."] = "WithTimeout vrací potomka, který se sám zruší. Vždy defer cancel(), jinak vznikne únik.",
  ["WithValue is for request-scoped data that crosses API boundaries: a trace id, not the parameters of your function."] = "WithValue je pro data v rámci požadavku, která překračují hranice API: id trasování ano, parametry tvé funkce ne.",
  ["Without a with block, what must always follow acquire()?"] = "Co musí bez bloku with vždycky následovat po acquire()?",
  ["Without the guard, spawn re-imports the file, the import starts another Process, and that is the fork bomb you just wrote by accident."] = "Bez té stráže spawn soubor naimportuje znovu, import spustí další Process, a to je forková bomba, kterou jsi právě omylem napsal.",
  ["Without with, which method must you remember to call on the file?"] = "Bez with, kterou metodu musíš na souboru nezapomenout zavolat?",
  ["Word count. New word: start at 0. Seen word: bump it. One entry call does both. Fill: entry(w).___(0)"] = "Počítání slov. Nové slovo: začni na 0. Viděné slovo: přičti. Jedno volání entry zvládne obojí. Doplň: entry(w).___(0)",
  ["Worker pool and pipeline"] = "Worker pool a pipeline",
  ["Worker pool with threads"] = "Worker pool s vlákny",
  ["Worker pool: N goroutines range over a jobs channel; close(jobs) ends them; WaitGroup then close(results)."] = "Worker pool: N goroutin dělá range přes channel jobs; close(jobs) je ukončí; WaitGroup a pak close(results).",
  ["Worker pool: an mpsc channel of jobs, the Receiver in Arc<Mutex<>>, N thread::spawn workers looping on recv. drop(tx) ends them, join waits."] = "Worker pool: kanál mpsc s joby, Receiver v Arc<Mutex<>>, N workerů přes thread::spawn ve smyčce na recv. drop(tx) je ukončí, join čeká.",
  ["Worker pools and how many to start"] = "Fondy workerů a kolik jich spustit",
  ["Workers are identical goroutines sharing one input channel. The channel is the queue."] = "Workery jsou totožné goroutiny sdílející jeden vstupní channel. Ten channel je fronta.",
  ["Works on slices, strings, maps, channels. cap is the capacity."] = "Funguje na slice, stringech, mapách, kanálech. cap je kapacita.",
  ["Wrap the bytes as an array without copying them. Which attribute is the memoryview?"] = "Obal ty bajty jako pole, aniž bys je kopíroval. Který atribut je ten memoryview?",
  ["Write the reply into w, not the terminal. Which fmt function?"] = "Zapiš odpověď do w, ne do terminálu. Která funkce z fmt?",
  ["You can clone it. The proxy cannot. Tell the tool which paths to fetch itself."] = "Ty ho naklonuješ. Proxy ne. Řekni nástroji, které cesty si má stáhnout sám.",
  ["You did tokio this afternoon. asyncio is the same shape: one loop, many awaits."] = "Odpoledne jsi dělal tokio. asyncio má stejný tvar: jedna smyčka, mnoho await.",
  ["You fixed Price in luckymac, but the cousin's shop still builds against v1.2.0 from the cache. Of course it does."] = "Opravil jsi Price v luckymac, ale bratrancův obchod pořád staví proti v1.2.0 z cache. Samozřejmě.",
  ["You got HIRED at seven. This is the OFFER round. A stack, Mei, it's always a stack."] = "V sedm jsi dostala HIRED. Tohle je kolo OFFER. Zásobník, Mei, je to vždycky zásobník.",
  ["You imported rider and then deleted the call. Finish the error."] = "Importoval jsi rider a pak smazal volání. Dokonči chybu.",
  ["You made a menu folder and wrote package pricing inside it. Go accepts it. Every reader will hate it."] = "Udělal jsi složku menu a napsal do ní package pricing. Go to vezme. Každý čtenář to bude nenávidět.",
  ["You only need a bool: is the order in one of two states? Which macro?"] = "Potřebuješ jen bool: je objednávka v jednom ze dvou stavů? Které makro?",
  ["You reach step i from one below or two below. Fill the second term: dp[i - 1] + dp[___]"] = "Na schod i dojdeš z jednoho níž nebo ze dvou níž. Doplň druhý člen: dp[i - 1] + dp[___]",
  ["You reach step i from one step below or two steps below. Fill the second index."] = "Na schod i se dostaneš o schod níž nebo o dva schody níž. Doplň druhý index.",
  ["You still want the position of every dish on the ticket. Which adapter adds it?"] = "Pořád chceš pozici každého jídla na lístku. Který adaptér ji přidá?",
  ["Your workers each pickled two gigabytes of the same table. That is the whole runtime, right there."] = "Každý tvůj worker si přes pickle vzal dva gigabajty té samé tabulky. Přesně tam je celý čas běhu.",
  ["[0i32; 26] lives on the stack: no HashMap, no allocation. Add for a, subtract for b, all zero means anagram."] = "[0i32; 26] žije na zásobníku: žádná HashMap, žádná alokace. Přičti za a, odečti za b, samé nuly znamenají přesmyčku.",
  ["[1,6] absorbs [2,4]: without the larger-end rule you would shrink it to [1,4]. last is a slice, so out sees the change."] = "[1,6] pohltí [2,4]: bez pravidla většího konce bys ho smrskl na [1,4]. last je slice, takže out změnu vidí.",
  ["[3]string is an array: a value, fixed length, copied on assignment. []string is a slice."] = "[3]string je pole: hodnota, pevná délka, kopíruje se při přiřazení. []string je slice.",
  ["[T any] is the widest constraint. comparable is for map keys."] = "[T any] je nejširší omezení. comparable je pro klíče map.",
  ["[[9, 11], [10, 12], [13, 15]] becomes [[9, 12], [13, 15]]. Sort plus one pass: O(n log n)."] = "[[9, 11], [10, 12], [13, 15]] se změní na [[9, 12], [13, 15]]. Řazení plus jeden průchod: O(n log n).",
  ["[]int is a slice. [3]int is an array of three. Slices are what you use."] = "[]int je slice. [3]int je pole tří prvků. Používej slice.",
  ["[]rune(s) once, then index freely. Interviewers check this in Go."] = "[]rune(s) jednou, pak indexuj volně. U pohovoru na Go to zkoušejí.",
  ["[dependencies] asks for versions; Cargo.lock records the exact ones. Commit the lock for binaries."] = "[dependencies] žádá verze; Cargo.lock zapíše ty přesné. U binárek lock commituj.",
  ["[expr for x in xs if cond] is a list comprehension. Rust's iter().map().collect(), in one readable line."] = "[expr for x in xs if cond] je list comprehension. iter().map().collect() z Rustu na jednom čitelném řádku.",
  ["[i32; 3] lives on the stack and never grows. Vec is for lists that change size."] = "[i32; 3] žije na zásobníku a nikdy neroste. Vec je pro seznamy, které mění velikost.",
  ['[package]\nname = "delivery"\nedition = "2021"\n\n[___]\nserde = { version = "1", features = ["derive"] }\ntokio = { version = "1", features = ["full"] }\n'] = '[package]\nname = "delivery"\nedition = "2021"\n\n[___]\nserde = { version = "1", features = ["derive"] }\ntokio = { version = "1", features = ["full"] }\n',
  ["_ matches anything and binds nothing. Without it the match is not exhaustive and will not compile. The gate shows set."] = "_ odpovídá čemukoli a nic neváže. Bez něj match není úplný a nezkompiluje se. Brána ukazuje set.",
  ["_ means I know this exists and I am ignoring it on purpose."] = "_ znamená: vím, že to existuje, a schválně to ignoruji.",
  ['___ OPEN: u8 = 7;        // hour the Express opens\n\nfn main() {\n    println!("opens at {}", OPEN);\n}\n'] = '___ OPEN: u8 = 7;        // hodina, kdy Express otevírá\n\nfn main() {\n    println!("opens at {}", OPEN);\n}\n',
  ['___ Order {\n    item: String,\n    qty: u32,\n}\nlet o = Order { item: "muffin".to_string(), qty: 2 };\n'] = '___ Order {\n    item: String,\n    qty: u32,\n}\nlet o = Order { item: "muffin".to_string(), qty: 2 };\n',
  ["___ Order:\n    pass\n\no = Order()\n"] = "___ Order:\n    pass\n\no = Order()\n",
  ["___ Size { Small, Large }\n\nlet size = Size::Large;\nlet extra = match size {\n    Size::Small => 0,\n    Size::Large => 5,       // every variant handled\n};\n"] = "___ Size { Small, Large }\n\nlet size = Size::Large;\nlet extra = match size {\n    Size::Small => 0,\n    Size::Large => 5,       // každá varianta ošetřena\n};\n",
  ['___ fry("hashbrown")\n___ toast("muffin")\n'] = '___ fry("hashbrown")\n___ toast("muffin")\n',
  ['___ fry(item):\n    print("frying", item)\n\nfry("egg")\n'] = '___ fry(item):\n    print("frying", item)\n\nfry("egg")\n',
  ['___ greet() {\n    println!("welcome to Lucky Mac Express");\n}\n// no arrow: this one returns the unit type ()\n'] = '___ greet() {\n    println!("welcome to Lucky Mac Express");\n}\n// žádná šipka: tahle vrací typ unit ()\n',
  ["___ luckymac/delivery\n\ngo 1.22\n\nrequire github.com/lib/pq v1.10.9\n"] = "___ luckymac/delivery\n\ngo 1.22\n\nrequire github.com/lib/pq v1.10.9\n",
  ['___ night shift starts at 21:00\nprint("open")\n'] = '___ noční směna začíná v 21:00\nprint("open")\n',
  ['___ open("stock.csv") as f:\n    for line in f:\n        count(line)\n# f is closed here\n'] = '___ open("stock.csv") as f:\n    for line in f:\n        count(line)\n# tady je f zavřený\n',
  ['___ queue:\n    person = queue.pop(0)\n    print("bowl for", person)\n'] = '___ queue:\n    person = queue.pop(0)\n    print("bowl for", person)\n',
  ['___ std::collections::HashMap;\n\nfn main() {\n    let mut stock = HashMap::new();\n    stock.insert("muffin", 4);\n}\n'] = '___ std::collections::HashMap;\n\nfn main() {\n    let mut stock = HashMap::new();\n    stock.insert("muffin", 4);\n}\n',
  ["___ tap(card string) bool {\n    return true\n}\n"] = "___ tap(card string) bool {\n    return true\n}\n",
  ['___ time\ntime.sleep(1)     # let the wok heat\nprint("ready")\n'] = '___ time\ntime.sleep(1)     # nech wok rozehřát\nprint("ready")\n',
  ["___ {\ncase m := <-muffin:\n    serve(m)\ncase h := <-hash:\n    serve(h)\n}\n"] = "___ {\ncase m := <-muffin:\n    serve(m)\ncase h := <-hash:\n    serve(h)\n}\n",
  ['___("Lucky Mac night shift")\n'] = '___("Lucky Mac night shift")\n',
  ["___(ch)\nx, ok := <-ch          // ok is false after\n"] = "___(ch)\nx, ok := <-ch          // ok je pak false\n",
  ["___(floors)                  // len(floors) == 0 after\n"] = "___(floors)                  // potom len(floors) == 0\n",
  ['___(prices, "closed")\n'] = '___(prices, "closed")\n',
  ['___, err := tap("octopus")\n'] = '___, err := tap("octopus")\n',
  ["___:\n    qty = int(raw)\nexcept ValueError:\n    qty = 0\n"] = "___:\n    qty = int(raw)\nexcept ValueError:\n    qty = 0\n",
  ['___timer\ndef fry(item):\n    return f"fried {item}"\n'] = '___timer\ndef fry(item):\n    return f"fried {item}"\n',
  ["__enter__ runs at the with line. Return self or the resource. Rust would use Drop for the other half."] = "__enter__ běží na řádku s with. Vrať self nebo zdroj. Rust by pro druhou půlku použil Drop.",
  ["__exit__(self, exc_type, exc, tb) always runs. Return True to swallow the exception; return None to let it propagate."] = "__exit__(self, exc_type, exc, tb) běží vždy. Vrať True, aby výjimku spolkl; vrať None, aby se šířila dál.",
  ["__init__ is the constructor body; self.item = item makes an attribute. __new__ exists too, rarely needed."] = "__init__ je tělo konstruktoru; self.item = item vytvoří atribut. Existuje i __new__, zřídka potřebný.",
  ["__str__ is what print and str() use; __repr__ is the unambiguous form, used when __str__ is missing. Go's String()."] = "__str__ používají print a str(); __repr__ je jednoznačná podoba, použitá, když __str__ chybí. String() z Go.",
  ["a + b with no semicolon is the value of the block. Go coders write return; Rust coders usually do not."] = "a + b bez středníku je hodnotou bloku. Programátoři v Go píší return; v Rustu obvykle ne.",
  ["a := []int{1, 2, 3}\nb := a[:2]\nb[0] = 9\nfmt.Println(a[0])       // prints ___\n"] = "a := []int{1, 2, 3}\nb := a[:2]\nb[0] = 9\nfmt.Println(a[0])       // vytiskne ___\n",
  ["a if cond else b reads left to right like English. The shutter sign flips to 'closed' at the last bowl."] = "a if cond else b se čte zleva doprava jako angličtina. Cedule na roletě se s poslední miskou přepne na 'closed'.",
  ["a lesson you can carry in a photo album"] = "lekce, kterou nosíš ve fotoalbu",
  ["a to z. The array length is part of the type, so it must be a constant."] = "a až z. Délka pole je součást typu, takže to musí být konstanta.",
  ["a.clone() allocates a second buffer. Cheap types derive Copy instead and never need it."] = "a.clone() alokuje druhý buffer. Levné typy místo toho derivují Copy a nikdy ho nepotřebují.",
  ["a.clone(). Allocation is where space complexity is paid; drop frees it at the end of scope, no collector needed."] = "a.clone(). Alokace je místo, kde se platí prostorová složitost; drop ji uvolní na konci rozsahu, žádný collector není třeba.",
  ["a.sort()                              # once: n log n\nfor x in queries:\n    i = bisect.bisect_left(a, x)      # each: O(___)\n"] = "a.sort()                              # jednou: n log n\nfor x in queries:\n    i = bisect.bisect_left(a, x)      # každé: O(___)\n",
  ["a.sort()    # in place: O(___) extra space (Timsort's small buffer aside)\n"] = "a.sort()    # na místě: O(___) prostoru navíc (odhlédneme-li od malého bufferu Timsortu)\n",
  ["a.sort() sorts the list where it is. Extra memory, in Big O: O(___)"] = "a.sort() třídí seznam tam, kde je. Paměť navíc, v Big O: O(___)",
  ["a.sort();                                  // once: n log n\nfor x in &queries {\n    let hit = a.binary_search(x).is_ok();  // each: O(___)\n}\n"] = "a.sort();                                  // jednou: n log n\nfor x in &queries {\n    let hit = a.binary_search(x).is_ok();  // každé: O(___)\n}\n",
  ["a.sort_unstable();    // in place: O(___) extra space\n"] = "a.sort_unstable();    // na místě: O(___) prostoru navíc\n",
  ["a[-1] is the last item, a[-2] the one before. Bo's off-by-one is gone."] = "a[-1] je poslední položka, a[-2] ta před ní. Boova chyba o jedna je pryč.",
  ["a[1:3] copies items 1 and 2 into a new list. a[:2], a[2:], a[::2] and a[::-1] (reversed) all work."] = "a[1:3] zkopíruje položky 1 a 2 do nového seznamu. a[:2], a[2:], a[::2] i a[::-1] (obráceně) fungují všechny.",
  ["a[mid] is too small: the answer is to the right. Fill: lo = ___ + 1"] = "a[mid] je moc malé: odpověď je vpravo. Doplň: lo = ___ + 1",
  ["add changes qty. Which receiver borrows the order with write access?"] = "add mění qty. Který receiver si půjčí objednávku s přístupem pro zápis?",
  ["amounts.___();     // pdqsort, no scratch buffer, O(n log n)\n"] = "amounts.___();     // pdqsort, žádný pracovní buffer, O(n log n)\n",
  ["amounts.sort();    // ___ : stable merge sort\n"] = "amounts.sort();    // ___ : stabilní merge sort\n",
  ["append is amortized O(1). Python has no stack class; a list is the stack."] = "append je amortizovaně O(1). Python nemá třídu zásobníku; zásobník je seznam.",
  ["apply_async returned a handle. Which method waits for the value?"] = "apply_async vrátilo úchyt. Která metoda počká na hodnotu?",
  ["arr writes straight into the shared block, so every process sees the change with no send at all. This is how big NumPy jobs go parallel."] = "arr zapisuje rovnou do sdíleného bloku, takže změnu vidí každý proces a nic se neposílá. Takhle se paralelizují velké úlohy s NumPy.",
  ["arrows walk   ESC map"] = "šipky chůze   ESC mapa",
  ["as f binds what __enter__ returned. with a() as x, b() as y: manages two at once."] = "as f naváže to, co vrátil __enter__. with a() as x, b() as y: spravuje dva najednou.",
  ["as usize widens the u8 for free. A u8 index would not compile: Rust never converts integers silently."] = "as usize rozšíří u8 zadarmo. Index typu u8 by se nezkompiloval: Rust nikdy nepřevádí celá čísla potichu.",
  ["as_ followed by the short word for reference. Its cousin as_deref goes one step further, to Option<&Node>."] = "as_ a za ním krátké anglické slovo pro referenci. Jeho bratranec as_deref jde o krok dál, na Option<&Node>.",
  ["as_completed is Go's select over many channels: whoever finishes first is served first, and a slow chunk never holds up the log."] = "as_completed je select z Go nad mnoha kanály: kdo doběhne první, ten je obsloužen první, a pomalá dávka nikdy nezdrží log.",
  ["as_ref would give Option<&Box<T>>. This one also derefs the Box. as_ plus deref."] = "as_ref by dal Option<&Box<T>>. Tenhle navíc dereferencuje i Box. as_ plus deref.",
  ["async and tokio"] = "async a tokio",
  ["async def fetch(rider):\n    await asyncio.___(1)     # the radio takes a second\n    return rider\n"] = "async def fetch(rider):\n    await asyncio.___(1)     # vysílačce to trvá sekundu\n    return rider\n",
  ['async def main():\n    riders = ["Ken", "Mei", "Bo"]\n    where = await asyncio.___(*(fetch(r) for r in riders))\n    print(where)     # one second total, not three\n'] = 'async def main():\n    riders = ["Ken", "Mei", "Bo"]\n    where = await asyncio.___(*(fetch(r) for r in riders))\n    print(where)     # celkem jedna sekunda, ne tři\n',
  ['async def main():\n    t = asyncio.___(fetch("Ken"))\n    print("radio sent")\n    print(await t)\n'] = 'async def main():\n    t = asyncio.___(fetch("Ken"))\n    print("radio sent")\n    print(await t)\n',
  ['async def main():\n    where = ___ fetch("Ken")\n    print(where)\n'] = 'async def main():\n    where = ___ fetch("Ken")\n    print(where)\n',
  ["async def makes a coroutine; await pauses it until the result is in. asyncio.run starts the loop, gather runs several at once, sleep waits without blocking, create_task fires and forgets."] = "async def vytvoří korutinu; await ji pozastaví, dokud nepřijde výsledek. asyncio.run spustí smyčku, gather spustí několik najednou, sleep čeká bez blokování, create_task vypálí a zapomene.",
  ["async def returns a coroutine object when called; nothing runs until it is awaited or scheduled."] = "async def po zavolání vrátí objekt korutiny; nic neběží, dokud se na něj nezavolá await nebo se nenaplánuje.",
  ["async fn eta(url: &str) -> Result<String, Box<dyn Error>> {\n    // GET, wait for headers, then wait for the body\n    let body = ___::get(url).await?.text().await?;\n    Ok(body)\n}\n"] = "async fn eta(url: &str) -> Result<String, Box<dyn Error>> {\n    // GET, počkej na hlavičky, pak počkej na tělo\n    let body = ___::get(url).await?.text().await?;\n    Ok(body)\n}\n",
  ["async fn fetch_eta(..) -> u32 really returns impl Future<Output = u32>. Nothing runs until polled."] = "async fn fetch_eta(..) -> u32 ve skutečnosti vrací impl Future<Output = u32>. Nic neběží, dokud se nepolluje.",
  ['async fn plan() {\n    // suspends here; other tasks run while we wait\n    let eta = fetch_eta(7)___;\n    println!("rider back in {eta} min");\n}\n'] = 'async fn plan() {\n    // tady se pozastaví; zatímco čekáme, běží jiné tasky\n    let eta = fetch_eta(7)___;\n    println!("rider back in {eta} min");\n}\n',
  ["async fn returns a Future; .await drives it. tokio runs them; spawn and join! run them at once."] = "async fn vrací Future; .await ho pohání. tokio je spouští; spawn a join! je pustí najednou.",
  ["asyncio"] = "asyncio",
  ["asyncio handles the waiting, processes handle the computing, and await joins them. Go does the same thing with one goroutine and no ceremony."] = "asyncio se stará o čekání, procesy o počítání a await obojí spojí. Go dělá totéž s jednou goroutinou a bez obřadů.",
  ["asyncio.run(main()) creates the loop, runs the coroutine, closes the loop. Rust's #[tokio::main]."] = "asyncio.run(main()) vytvoří smyčku, spustí korutinu, zavře smyčku. #[tokio::main] z Rustu.",
  ["atomic.Int64 keeps its own value, so nobody can read it the unsafe way. The old atomic.AddInt64(&n, 1) still works, but the type is safer."] = "atomic.Int64 si hodnotu drží sám, takže ji nikdo nepřečte nebezpečně. Staré atomic.AddInt64(&n, 1) pořád funguje, ale typ je bezpečnější.",
  ["atomic.Pointer[Menu] gives copy-on-write config: build a new menu, Store it, and every reader after that sees the new one whole."] = "atomic.Pointer[Menu] dává konfiguraci stylem copy-on-write: postav nové menu, ulož ho přes Store a každý další čtenář uvidí celé nové.",
  ["await asyncio.sleep(1) yields to the loop; time.sleep(1) would freeze every task. Same trap as in tokio."] = "await asyncio.sleep(1) předá slovo smyčce; time.sleep(1) by zamrazil každou úlohu. Stejná past jako v tokiu.",
  ["await hands control to the event loop until the coroutine finishes. Only allowed inside async def."] = "await předá řízení smyčce událostí, dokud korutina neskončí. Povoleno jen uvnitř async def.",
  ["b := make([]int, ___(a))    // allocate n ints\ncopy(b, a)                  // O(n) time, O(n) space\n"] = "b := make([]int, ___(a))    // alokuj n intů\ncopy(b, a)                  // O(n) času, O(n) prostoru\n",
  ["b := slices.Clone(a)    // a second slice of n ints: O(___)\nsort.Ints(b)\n"] = "b := slices.Clone(a)    // druhý slice n intů: O(___)\nsort.Ints(b)\n",
  ["b = ___(a)    # allocate n slots and copy: O(n) time, O(n) space\n"] = "b = ___(a)    # alokuj n slotů a zkopíruj: O(n) času, O(n) prostoru\n",
  ["b = sorted(a)    # a second list of n items: O(___)\n"] = "b = sorted(a)    # druhý seznam n položek: O(___)\n",
  ["b shares a's array. After b[0] = 9, what does a[0] print?"] = "b sdílí pole a. Co vytiskne a[0] po b[0] = 9?",
  ["b'1' is 49u8, the ASCII byte. Vec<Vec<u8>> is what you get from lines of a text map via as_bytes()."] = "b'1' je 49u8, bajt ASCII. Vec<Vec<u8>> je to, co dostaneš z řádků textové mapy přes as_bytes().",
  ['b, err := json.___(order)   // []byte\nfmt.Println(string(b))      // {"dish":"set"}\n'] = 'b, err := json.___(order)   // []byte\nfmt.Println(string(b))      // {"dish":"set"}\n',
  ["binary, underscore, search. Takes a reference to the wanted value. Err carries the insertion point."] = "binary, podtržítko, search. Bere referenci na hledanou hodnotu. Err nese místo pro vložení.",
  ["binary_search has one precondition. The slice must be ___"] = "binary_search má jeden předpoklad. Slice musí být ___",
  ["bisect has one precondition. The list must be ___"] = "bisect má jeden předpoklad. Seznam musí být ___",
  ["bisect_left returns the first index >= x; bisect_right the one after equals. insort inserts. Round five to Bo."] = "bisect_left vrátí první index >= x; bisect_right ten za stejnými. insort vkládá. Páté kolo pro Boa.",
  ["break ends the loop; continue skips to the next item. A for loop may have an else: that runs only if no break happened."] = "break ukončí cyklus; continue skočí na další položku. Cyklus for může mít else: proběhne jen, když nedošlo k break.",
  ["break leaves the innermost for, switch or select. A label breaks an outer one."] = "break opustí nejvnitřnější for, switch nebo select. Návěští přeruší vnější.",
  ["brew takes a whole number of cups and returns text. Annotate the parameter."] = "brew bere celý počet šálků a vrací text. Anotuj parametr.",
  ["c - b'a' is a u8 from 0 to 25. Arrays are indexed by exactly one integer type. Cast to which?"] = "c - b'a' je u8 od 0 do 25. Pole se indexují právě jedním celočíselným typem. Přetypuj na který?",
  ["cannot find module providing package. Which subcommand rebuilds go.mod from the imports?"] = "cannot find module providing package. Který podpříkaz znovu sestaví go.mod z importů?",
  ["cap is the room in the backing array. append doubles it when len reaches cap."] = "cap je místo v podkladovém poli. append ho zdvojnásobí, když len dosáhne cap.",
  ["cargo add serde --features derive writes the line for you and picks the newest version."] = "cargo add serde --features derive napíše řádek za tebe a vybere nejnovější verzi.",
  ["cargo clippy is the linter; -- -D warnings makes CI fail on any lint. The crab approves."] = "cargo clippy je linter; -- -D warnings nechá CI spadnout na každém lintu. Krab souhlasí.",
  ["cargo fmt rewrites in place; --check only reports. Build green, lint clean. Ticket six closed."] = "cargo fmt přepíše soubory na místě; --check jen hlásí. Build zelený, lint čistý. Ticket šest uzavřen.",
  ["cargo new makes Cargo.toml, src/main.rs and a git repo. cargo init does it in an existing folder."] = "cargo new vytvoří Cargo.toml, src/main.rs a git repozitář. cargo init to udělá v existující složce.",
  ["cargo new, add, build --release, test, clippy, fmt. Cargo.toml asks, Cargo.lock pins."] = "cargo new, add, build --release, test, clippy, fmt. Cargo.toml žádá, Cargo.lock fixuje.",
  ["cargo run. cargo new makes a project, cargo build compiles, cargo test runs tests. The kiosk boots."] = "cargo run. cargo new založí projekt, cargo build kompiluje, cargo test spouští testy. Kiosek nabíhá.",
  ["cargo test builds a test binary and runs #[test] fns in parallel. cargo test name filters."] = "cargo test sestaví testovací binárku a spustí #[test] funkce paralelně. cargo test jméno filtruje.",
  ["ch := make(___)        // unbuffered\n"] = "ch := make(___)        // bez bufferu\n",
  ["ch := make(chan Order, 8)\nch <- Order{id: 1}\nfmt.Println(len(ch), ___(ch))\n// 1 8\n"] = "ch := make(chan Order, 8)\nch <- Order{id: 1}\nfmt.Println(len(ch), ___(ch))\n// 1 8\n",
  ["ch := make(chan int)\nch <- 1                // nobody receives\nfmt.Println(<-ch)\n// fatal error: all goroutines are asleep - ___!\n"] = "ch := make(chan int)\nch <- 1                // nikdo nepřijímá\nfmt.Println(<-ch)\n// fatal error: all goroutines are asleep - ___!\n",
  ['ch := make(chan string)\nch ___ "muffin"        // send\n'] = 'ch := make(chan string)\nch ___ "muffin"        // odeslání\n',
  ['ch := make(chan string, ___)   // buffered\nch <- "muffin"                 // does not block yet\n'] = 'ch := make(chan string, ___)   // s bufferem\nch <- "muffin"                 // zatím neblokuje\n',
  ["ch <- x sends. x := <-ch receives. Same operator, different place."] = "ch <- x odesílá. x := <-ch přijímá. Stejný operátor, jiné místo.",
  ["chan is a typed pipe. <- sends and receives. close tells receivers to stop."] = "chan je typovaná roura. <- odesílá a přijímá. close řekne příjemcům, ať skončí.",
  ["chan struct{} plus close is the cheapest done signal. context.Done() returns one."] = "chan struct{} plus close je nejlevnější signál hotovo. context.Done() takový vrací.",
  ["chars().count() walks the string and counts. The receipt prints 銅鑼灣 in full."] = "chars().count() projde řetězec a počítá. Účtenka vytiskne 銅鑼灣 celé.",
  ["cheapest := ___(muffin, hash, coffee)   // built-in\n"] = "cheapest := ___(muffin, hash, coffee)   // vestavěná\n",
  ["class ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = ___\n"] = "class ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = ___\n",
  ["class MinStack:\n    def __init__(self):\n        self.st, self.lows = [], []\n    def push(self, x):\n        self.st.append(x)\n        m = self.lows[-1] if self.lows else x\n        self.lows.append(___(x, m))\n"] = "class MinStack:\n    def __init__(self):\n        self.st, self.lows = [], []\n    def push(self, x):\n        self.st.append(x)\n        m = self.lows[-1] if self.lows else x\n        self.lows.append(___(x, m))\n",
  ["class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = ___\n        self.right = ___\n"] = "class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = ___\n        self.right = ___\n",
  ["class Order:\n    @___\n    def from_line(cls, line):\n        qty, _, item = line.split()\n        return cls(item, int(qty))\n"] = "class Order:\n    @___\n    def from_line(cls, line):\n        qty, _, item = line.split()\n        return cls(item, int(qty))\n",
  ['class Order:\n    def ___(self, item):\n        self.item = item\n\no = Order("noodles")\nprint(o.item)\n'] = 'class Order:\n    def ___(self, item):\n        self.item = item\n\no = Order("noodles")\nprint(o.item)\n',
  ['class Order:\n    def __init__(self, item):\n        self.item = item\n\n    def ___(self):\n        return f"Order({self.item})"\n'] = 'class Order:\n    def __init__(self, item):\n        self.item = item\n\n    def ___(self):\n        return f"Order({self.item})"\n',
  ['class Order:\n    def __init__(self, item):\n        self.item = item\n\n    def label(___):\n        return f"1 x {___.item}"\n'] = 'class Order:\n    def __init__(self, item):\n        self.item = item\n\n    def label(___):\n        return f"1 x {___.item}"\n',
