  ["def palindrome(s):\n    i, j = 0, len(s) ___ 1\n    while i < j:\n        if s[i] != s[j]:\n            return False\n        i, j = i + 1, j - 1\n    return True\n"] = "def palindrome(s):\n    i, j = 0, len(s) ___ 1\n    while i < j:\n        if s[i] != s[j]:\n            return False\n        i, j = i + 1, j - 1\n    return True\n",
  ["def reverse(head):\n    prev, cur = None, head\n    while cur:\n        nxt = cur.next\n        cur.next = ___\n        prev, cur = cur, nxt\n    return prev\n"] = "def reverse(head):\n    prev, cur = None, head\n    while cur:\n        nxt = cur.next\n        cur.next = ___\n        prev, cur = cur, nxt\n    return prev\n",
  ["def search(a, x):\n    lo, hi = 0, len(a)\n    while lo < hi:\n        mid = (lo + hi) // 2\n        if a[mid] == x: return mid\n        if a[mid] < x: lo = ___ + 1\n        else: hi = mid\n"] = "def search(a, x):\n    lo, hi = 0, len(a)\n    while lo < hi:\n        mid = (lo + hi) // 2\n        if a[mid] == x: return mid\n        if a[mid] < x: lo = ___ + 1\n        else: hi = mid\n",
  ["def stairs(n):\n    # ways to climb n steps, one or two at a time\n    dp = [0] * (n + 1)\n    dp[0] = dp[1] = ___\n    for i in range(2, n + 1):\n        dp[i] = dp[i - 1] + dp[i - 2]\n    return dp[n]\n"] = "def stairs(n):\n    # způsoby na n schodů, po jednom nebo dvou\n    dp = [0] * (n + 1)\n    dp[0] = dp[1] = ___\n    for i in range(2, n + 1):\n        dp[i] = dp[i - 1] + dp[i - 2]\n    return dp[n]\n",
  ['def take(stock, item):\n    if stock[item] == 0:\n        ___ ValueError(f"no {item} left")\n    stock[item] -= 1\n'] = 'def take(stock, item):\n    if stock[item] == 0:\n        ___ ValueError(f"no {item} left")\n    stock[item] -= 1\n',
  ["def timer(fn):\n    def wrapper(*args, **kwargs):\n        t0 = time.perf_counter()\n        out = fn(*args, **kwargs)\n        print(fn.__name__, time.perf_counter() - t0)\n        return out\n    return ___\n"] = "def timer(fn):\n    def wrapper(*args, **kwargs):\n        t0 = time.perf_counter()\n        out = fn(*args, **kwargs)\n        print(fn.__name__, time.perf_counter() - t0)\n        return out\n    return ___\n",
  ["def total(___):\n    return sum(items)\n\nprint(total(3, 5))\nprint(total(3, 5, 8))\n"] = "def total(___):\n    return sum(items)\n\nprint(total(3, 5))\nprint(total(3, 5, 8))\n",
  ["def total(prices):\n    s = 0\n    for p in prices:\n        s += p\n    ___ s\n"] = "def total(prices):\n    s = 0\n    for p in prices:\n        s += p\n    ___ s\n",
  ["def two_sum(nums, target):\n    seen = {}\n    for i, x in enumerate(nums):\n        if target - x in ___:\n            return seen[target - x], i\n        seen[x] = i\n"] = "def two_sum(nums, target):\n    seen = {}\n    for i, x in enumerate(nums):\n        if target - x in ___:\n            return seen[target - x], i\n        seen[x] = i\n",
  ["def two_sum(nums, target):\n    seen = {}\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            return seen[target - x], i\n        seen[x] = ___\n"] = "def two_sum(nums, target):\n    seen = {}\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            return seen[target - x], i\n        seen[x] = ___\n",
  ['def valid(s):\n    pairs = {")": "(", "]": "[", "}": ___}\n    st = []\n    for c in s:\n        if c in "([{":\n            st.append(c)\n'] = 'def valid(s):\n    pairs = {")": "(", "]": "[", "}": ___}\n    st = []\n    for c in s:\n        if c in "([{":\n            st.append(c)\n',
  ["def, return, *args, lambda"] = "def, return, *args, lambda",
  ["default: runs when every channel would block. The till stays free."] = "default: běží, když by každý kanál blokoval. Pokladna zůstává volná.",
  ["defaultdict(list) calls list() for a missing key. Go's map[string][]string with the nil-slice append trick, built in."] = "defaultdict(list) zavolá list() pro chybějící klíč. map[string][]string z Go s trikem append na nil slice, vestavěně.",
  ["defer captures its arguments now, not later. What does this print?"] = "defer zachytí argumenty hned, ne později. Co tohle vypíše?",
  ["defer evaluates arguments immediately. defer func() { fmt.Println(x) }() would print 2."] = "defer vyhodnotí argumenty ihned. defer func() { fmt.Println(x) }() by vypsalo 2.",
  ["defer f.Close(). The drawer shuts even if Pay fails."] = "defer f.Close(). Šuplík se zavře, i když Pay selže.",
  ["defer func() {\n    if r := ___(); r != nil {\n        // saved the till\n    }\n}()\n"] = "defer func() {\n    if r := ___(); r != nil {\n        // pokladna zachráněna\n    }\n}()\n",
  ["del menu[k] raises if k is missing; menu.pop(k, None) removes quietly and returns the value."] = "del menu[k] vyhodí výjimku, když k chybí; menu.pop(k, None) odstraní potichu a vrátí hodnotu.",
  ["delete(m, k) removes it. Maps grow by assignment, shrink by this."] = "delete(m, k) ho odstraní. Mapy rostou přiřazením, zmenšují se tímhle.",
  ["delete(m, key). Safe if the key is already gone."] = "delete(m, key). Bezpečné, i když klíč už chybí.",
  ["deque.popleft is O(1); that is why BFS uses a deque and never a list. Round two to Bo."] = "deque.popleft je O(1); proto BFS používá deque a nikdy seznam. Druhé kolo pro Boa.",
  ["derive Serialize and Deserialize, then serde_json::to_string and from_str. Attributes shape the JSON."] = "derive Serialize a Deserialize, pak serde_json::to_string a from_str. Atributy tvarují JSON.",
  ["derive(Serialize, Deserialize) needs the derive feature in Cargo.toml. serde_json does the format."] = "derive(Serialize, Deserialize) potřebuje v Cargo.toml feature derive. Formát dělá serde_json.",
  ["dict: hash, slot, compare. O(1) average, O(n) worst when everything collides. Go's map, Rust's HashMap."] = "dict: hash, slot, porovnání. O(1) v průměru, O(n) v nejhorším, když všechno koliduje. map z Go, HashMap z Rustu.",
  ["dict[str, float]. Go's map[string]float64, Rust's HashMap<String, f64>. TypedDict names each key."] = "dict[str, float]. map[string]float64 z Go, HashMap<String, f64> z Rustu. TypedDict pojmenuje každý klíč.",
  ["done := make(chan ___)   // zero bytes per value\ngo func() {\n    cook()\n    close(done)\n}()\n<-done\n"] = "done := make(chan ___)   // nula bajtů na hodnotu\ngo func() {\n    cook()\n    close(done)\n}()\n<-done\n",
  ['done = mp.Value("i", 0)\n\nwith done.___():\n    done.value += 1\n'] = 'done = mp.Value("i", 0)\n\nwith done.___():\n    done.value += 1\n',
  ['done = mp.Value("i", 0)\n\nwith done.get_lock():\n    done.___ += 1\n'] = 'done = mp.Value("i", 0)\n\nwith done.get_lock():\n    done.___ += 1\n',
  ["dp[0] = 0: zero coins make zero. Everything else waits at inf until a coin reaches it."] = "dp[0] = 0: nula mincí dá nulu. Vše ostatní čeká na inf, dokud k tomu nějaká mince nedosáhne.",
  ["drop(tray) takes ownership and frees it. Normally the closing brace of the scope does this. No GC needed."] = "drop(tray) převezme vlastnictví a uvolní ho. Normálně to dělá zavírací závorka bloku. Žádný GC není třeba.",
  ["drop(tx) runs Drop now. tx2 is dropped when its thread ends; with both gone, rx sees the end and the for loop stops."] = "drop(tx) spustí Drop hned. tx2 se zahodí, když skončí jeho vlákno; když jsou oba pryč, rx vidí konec a cyklus for se zastaví.",
  ["drop(tx): the channel closes when the last Sender is gone. Queued jobs are still delivered first. Forget this and join waits forever."] = "drop(tx): kanál se zavře, až zmizí poslední Sender. Joby ve frontě se ale ještě doručí. Zapomeň na to a join čeká navěky.",
  ['drop(tx);\n// wait for each cook; unwrap re-raises a panic from it\nfor h in handles {\n    h.___().unwrap();\n}\nprintln!("kitchen closed");\n'] = 'drop(tx);\n// počkej na každého kuchaře; unwrap znovu vyvolá jeho paniku\nfor h in handles {\n    h.___().unwrap();\n}\nprintln!("kitchen closed");\n',
  ["drop, then join, in that order. Seven rounds, no misses, combo x7. The screen says HIRED and the crab on the kiosk waves."] = "drop, pak join, v tomhle pořadí. Sedm kol, bez chyby, kombo x7. Na obrazovce svítí PŘIJATA a krab na kiosku mává.",
  ["eggs = 25\ntrays = eggs ___ 6      # whole trays\nleft = eggs % 6         # 1 egg over\nprint(trays, left)\n"] = "eggs = 25\ntrays = eggs ___ 6      # celé tácy\nleft = eggs % 6         # 1 vejce navíc\nprint(trays, left)\n",
  ["elif chains tests top to bottom; the first true branch runs, the rest are skipped. No switch in Python before match."] = "elif řetězí testy shora dolů; první pravdivá větev se provede, ostatní se přeskočí. Před match Python žádný switch nemá.",
  ["entry(a).or_default() returns &mut Vec<u32>, so push works in one line. One hash lookup, not two."] = "entry(a).or_default() vrací &mut Vec<u32>, takže push funguje na jednom řádku. Jedno vyhledání v hashi, ne dvě.",
  ["entry(k).or_insert(0) returns &mut to the value; * dereferences it. get(k) returns Option, so a missing key is None, not a panic."] = "entry(k).or_insert(0) vrací &mut na hodnotu; * ji dereferencuje. get(k) vrací Option, takže chybějící klíč je None, ne panic.",
  ["enum OrderError lists every failure. Debug is required by the Error trait later."] = "enum OrderError vyjmenuje každé selhání. Debug bude později vyžadovat trait Error.",
  ["enum Size { Small, Large } Variants can carry data too, like Some(12). match without a Medium arm is a compile error, not a bug at the till."] = "enum Size { Small, Large } Varianty mohou nést i data, jako Some(12). match bez větve Medium je chyba při kompilaci, ne bug u pokladny.",
  ['enum State { Queued, Cooking, Riding, Done }\n// a pattern test that returns true or false\nlet busy = ___!(state, State::Cooking | State::Riding);\nif busy { println!("not yet"); }\n'] = 'enum State { Queued, Cooking, Riding, Done }\n// test vzoru, který vrací true nebo false\nlet busy = ___!(state, State::Cooking | State::Riding);\nif busy { println!("not yet"); }\n',
  ["enumerate() gives (index, item). zip(prices) would give (dish, price). No off-by-one."] = "enumerate() dává (index, položka). zip(prices) by dal (jídlo, cena). Žádná chyba o jedničku.",
  ["enumerate(xs, start) yields (i, x). Never write for i in range(len(xs)) when you also need xs[i]."] = "enumerate(xs, start) dává (i, x). Nikdy nepiš for i in range(len(xs)), když potřebuješ i xs[i].",
  ["errgroup.WithContext cancels the shared ctx the moment one task fails, and Wait returns that first error. It is Go's Promise.all."] = "errgroup.WithContext zruší sdílený ctx ve chvíli, kdy jeden úkol selže, a Wait vrátí tu první chybu. Je to Promise.all po způsobu Go.",
  ["error is an interface. Check err != nil. defer runs when the function returns."] = "error je interface. Kontroluj err != nil. defer běží, když funkce vrací.",
  ["error is interface{ Error() string }. Your own types can carry data."] = "error je interface{ Error() string }. Vlastní typy mohou nést data.",
  ["errors.As finds the first error of that type and stores it in re."] = "errors.As najde první error toho typu a uloží ho do re.",
  ["errors.Is compares values down the chain. Use it instead of ==."] = "errors.Is porovnává hodnoty podél řetězu. Používej ho místo ==.",
  ["errors.New for fixed messages; name them ErrSomething at package level."] = "errors.New pro pevné zprávy; na úrovni balíčku je pojmenuj ErrSomething.",
  ["errors.New makes one. %w wraps one. errors.Is and errors.As search the chain."] = "errors.New ho vytvoří. %w ho obalí. errors.Is a errors.As prohledají řetěz.",
  ["eta.cache_info() shows hits and misses; eta.cache_clear() empties it. Arguments must be hashable. Round six to Bo."] = "eta.cache_info() ukáže hits a misses; eta.cache_clear() ji vyprázdní. Argumenty musí být hashovatelné. Šesté kolo pro Boa.",
  ["except KeyError as e: e is the exception; str(e) is its message, e.args the details. The name dies after the block."] = "except KeyError as e: e je výjimka; str(e) je její zpráva, e.args podrobnosti. Jméno po bloku zaniká.",
  ["except ValueError: catches only that. A bare except: swallows everything, even Ctrl-C. Name the type."] = "except ValueError: zachytí jen tohle. Holé except: spolkne všechno, i Ctrl-C. Pojmenuj typ.",
  ["expect(msg) panics with msg on Err. Use it for real bugs, not for user input. The till is back; Siu Ming exhales."] = "expect(msg) při Err zpanikaří se zprávou msg. Používej ho na skutečné bugy, ne na vstup od uživatele. Pokladna je zpět; Siu Ming vydechne.",
  ['f = open("stock.csv", "w")\nf.write("egg,12\\n")\nf.___()      # flush and release; with does this for you\n'] = 'f = open("stock.csv", "w")\nf.write("egg,12\\n")\nf.___()      # vyprázdní a uvolní; with to udělá za tebe\n',
  ['f"..." is an f-string: any expression inside {} is evaluated. {n:>4} pads, {price:.2f} rounds.'] = 'f"..." je f-string: jakýkoli výraz uvnitř {} se vyhodnotí. {n:>4} zarovná, {price:.2f} zaokrouhlí.',
  ['f, err := os.Open("order.txt")\n___ f.Close()\n'] = 'f, err := os.Open("order.txt")\n___ f.Close()\n',
  ["f.close() flushes the buffer. Until then the last lines may not be on disk. The safe locks properly tonight."] = "f.close() vyprázdní buffer. Do té doby poslední řádky možná nejsou na disku. Dnes v noci trezor zamkne pořádně.",
  ["fetch, underscore, then the arithmetic you want."] = "fetch, podtržítko, pak aritmetika, kterou chceš.",
  ["fetch_add(1, Ordering::SeqCst) adds and returns the old value atomically. SeqCst is the strictest, simplest ordering."] = "fetch_add(1, Ordering::SeqCst) atomicky přičte a vrátí starou hodnotu. SeqCst je nejpřísnější a nejjednodušší uspořádání.",
  ["fib calls itself twice per call, no cache. Cost, in Big O?"] = "fib volá sám sebe dvakrát na volání, bez cache. Cena, v Big O?",
  ["fib calls itself twice per call, no memo. Cost, in Big O?"] = "fib volá sám sebe dvakrát na volání, bez mema. Cena, v Big O?",
  ["fib(40) naively is a billion calls. Look the answer up first. Which HashMap method?"] = "fib(40) naivně je miliarda volání. Nejdřív odpověď vyhledej. Která metoda HashMap?",
  ["fib(40) naively is a billion calls. One decorator remembers every result. Which one, from functools?"] = "Naivní fib(40) je miliarda volání. Jeden dekorátor si pamatuje každý výsledek. Který, z functools?",
  ["fib(n) = fib(n-1) + the one before that. The base case n < 2 guarantees this never underflows."] = "fib(n) = fib(n-1) + ten před ním. Bázový případ n < 2 zaručuje, že to nikdy nepodteče.",
  ["fib(n) is the sum of the two before it. Fill the second call: fib(n - 1) + fib(___)"] = "fib(n) je součet dvou předchozích. Doplň druhé volání: fib(n - 1) + fib(___)",
  ["fib(n-1) + fib(n-2): two calls, so 2^n without a memo. With one, each n is computed once. Round one to Chef Bo."] = "fib(n-1) + fib(n-2): dvě volání, takže bez mema 2^n. S ním se každé n spočítá jednou. První kolo pro šéfkuchaře Boa.",
  ["filter keeps items where the closure is true. It is lazy until collect pulls."] = "filter nechá položky, kde closure vrátí true. Je líný, dokud collect netahá.",
  ["filter, map, collect: the chain is lazy until collect. Collecting once lets us iterate twice, forwards and rev."] = "filter, map, collect: řetěz je líný až do collect. Jedno posbírání nám dovolí iterovat dvakrát, dopředu i přes rev.",
  ["finally: runs after try and except, even on return or a fresh exception. else: runs only when nothing was raised."] = "finally: běží po try a except, i při return nebo nové výjimce. else: běží jen, když nic nebylo vyhozeno.",
  ["first() gives an Option. Return None early if the order is empty. Which operator?"] = "first() dává Option. Vrať brzy None, když je objednávka prázdná. Který operátor?",
  ["fmt prints a type your way if it has one method. Fill: func (o Order) ___() string"] = "fmt vytiskne typ po tvém, když má jednu metodu. Doplň: func (o Order) ___() string",
  ["fmt.Println(runtime.___(0))\n// 8: eight OS threads may run Go code at once\n"] = "fmt.Println(runtime.___(0))\n// 8: tolik vláken smí naráz běžet v Go\n",
  ['fmt.___(w, "served %s", item)   // w is an io.Writer\n'] = 'fmt.___(w, "served %s", item)   // w je io.Writer\n',
  ["fn add(&mut self, n: u32). Self with a capital S names the type itself, handy in fn new() -> Self."] = "fn add(&mut self, n: u32). Self s velkým S pojmenovává samotný typ, hodí se ve fn new() -> Self.",
  ["fn add_edge(g: &mut Graph, a: u32, b: u32) {\n    // no list for a yet? start an empty one, then push b\n    g.entry(a).___().push(b);\n    // the long spelling of the same thing, other direction\n    g.entry(b).or_insert_with(Vec::new).push(a);\n}\n"] = "fn add_edge(g: &mut Graph, a: u32, b: u32) {\n    // pro a ještě není seznam? založ prázdný a pushni b\n    g.entry(a).___().push(b);\n    // dlouhý zápis téhož, druhý směr\n    g.entry(b).or_insert_with(Vec::new).push(a);\n}\n",
  ['fn assign(order: &Order) {\n    // Rust 1.65: a refutable pattern with a fallback block\n    let Some(rider) = pick_rider(order) ___ { return };\n    println!("{rider} takes order {}", order.id);\n}\n'] = 'fn assign(order: &Order) {\n    // Rust 1.65: vyvratitelný vzor se záložním blokem\n    let Some(rider) = pick_rider(order) ___ { return };\n    println!("{rider} takes order {}", order.id);\n}\n',
  ["fn bfs(g: &Graph, start: u32) -> Vec<u32> {\n    let mut order = Vec::new();\n    let mut seen = HashSet::from([start]);\n    // FIFO: newest at the back, oldest out at the front\n    let mut q = ___::from([start]);\n"] = "fn bfs(g: &Graph, start: u32) -> Vec<u32> {\n    let mut order = Vec::new();\n    let mut seen = HashSet::from([start]);\n    // FIFO: nejnovější dozadu, nejstarší ven zepředu\n    let mut q = ___::from([start]);\n",
  ['fn change(coins: &[usize], amount: usize) -> i64 {\n    // amount + 1 is more than any real answer: "impossible"\n    let mut dp = vec![amount + 1; amount + 1];\n    dp[___] = 0;\n'] = 'fn change(coins: &[usize], amount: usize) -> i64 {\n    // amount + 1 je víc než každá reálná odpověď: "nemožné"\n    let mut dp = vec![amount + 1; amount + 1];\n    dp[___] = 0;\n',
  ["fn climb(n: usize) -> u64 {\n    let mut dp = vec![0u64; n + 1];\n    dp[0] = 1;              // stand still\n    dp[1] = ___;            // a single step\n"] = "fn climb(n: usize) -> u64 {\n    let mut dp = vec![0u64; n + 1];\n    dp[0] = 1;              // stůj na místě\n    dp[1] = ___;            // jediný krok\n",
  ['fn count(s: ___String) -> usize {\n    s.len()\n}\nlet a = String::from("coffee");\nlet n = count(&a);\nprintln!("{} {}", a, n);   // a still alive\n'] = 'fn count(s: ___String) -> usize {\n    s.len()\n}\nlet a = String::from("coffee");\nlet n = count(&a);\nprintln!("{} {}", a, n);   // a stále žije\n',
  ['fn dfs(g: &Graph, start: u32, seen: &mut HashSet<u32>) {\n    let mut stack = vec![start];     // a Vec is a stack too\n    while let Some(n) = stack.___() { // LIFO: newest first\n        if !seen.insert(n) { continue; }\n        print!("{n} "); stack.extend(&g[&n]);\n    }\n}\n'] = 'fn dfs(g: &Graph, start: u32, seen: &mut HashSet<u32>) {\n    let mut stack = vec![start];     // Vec je taky zásobník\n    while let Some(n) = stack.___() { // LIFO: nejnovější první\n        if !seen.insert(n) { continue; }\n        print!("{n} "); stack.extend(&g[&n]);\n    }\n}\n',
  ["fn discount(n: u32) -> u32 {\n    if n == 0 {\n        ___ 0;        // early exit, with a semicolon\n    }\n    n * 18 - 5\n}\n"] = "fn discount(n: u32) -> u32 {\n    if n == 0 {\n        ___ 0;        // brzký odchod, se středníkem\n    }\n    n * 18 - 5\n}\n",
  ["fn f<T: Bound> is checked at compile time. dyn Trait in a Box decides at run time."] = "fn f<T: Bound> se kontroluje při kompilaci. dyn Trait v Boxu rozhoduje za běhu.",
  ["fn fact(n: u64) -> u64 {\n    if n <= 1 {\n        1\n    } else {\n        n * fact(___)        // toward the base case\n    }\n}\n"] = "fn fact(n: u64) -> u64 {\n    if n <= 1 {\n        1\n    } else {\n        n * fact(___)        // blíž k bázovému případu\n    }\n}\n",
  ["fn fact(n: u64) -> u64 {\n    if n <= 1 {\n        ___                  // base case\n    } else {\n        n * fact(n - 1)\n    }\n}\n"] = "fn fact(n: u64) -> u64 {\n    if n <= 1 {\n        ___                  // bázový případ\n    } else {\n        n * fact(n - 1)\n    }\n}\n",
  ["fn fib(n: u64) -> u64 {\n    if n < 2 { return n; }\n    fib(n - 1) + fib(n - 2)   // ___ : two calls each\n}\n"] = "fn fib(n: u64) -> u64 {\n    if n < 2 { return n; }\n    fib(n - 1) + fib(n - 2)   // ___ : dvě volání každé\n}\n",
  ["fn fib(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {\n    if let Some(&v) = memo.___(&n) { return v; }\n    let v = if n < 2 { n } else { fib(n - 1, memo) + fib(n - 2, memo) };\n    memo.insert(n, v);\n    v\n}\n"] = "fn fib(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {\n    if let Some(&v) = memo.___(&n) { return v; }\n    let v = if n < 2 { n } else { fib(n - 1, memo) + fib(n - 2, memo) };\n    memo.insert(n, v);\n    v\n}\n",
