  ["gather runs them concurrently and returns the results in order. One second total. The noodles stay hot."] = "gather je spustí souběžně a vrátí výsledky v pořadí. Celkem jedna sekunda. Nudle zůstanou horké.",
  ["gen = belt(orders)\nfirst = ___(gen)\nprint(first)\n"] = "gen = belt(orders)\nfirst = ___(gen)\nprint(first)\n",
  ["get and put both O(1). Overwriting a key must also move it to the end, hence the move before the check."] = "get i put oba O(1). Přepsání klíče ho musí také přesunout na konec, proto ten přesun před kontrolou.",
  ["get blocks until an item arrives; get(timeout=1) raises queue.Empty. Three cooks each block on the same call."] = "get blokuje, dokud nedorazí položka; get(timeout=1) vyhodí queue.Empty. Tři kuchaři blokují na tomtéž volání.",
  ["get of a key that is not cached. What does it return, by the usual convention?"] = "get klíče, který není v cache. Co vrátí, podle obvyklé konvence?",
  ["get(1) made 1 fresh, so put(3) evicts 2. That trace is the whole interview: touch on read, evict the front on write."] = "get(1) udělalo 1 čerstvou, takže put(3) vyhodí 2. Ten průběh je celý pohovor: dotek při čtení, vyhození předku při zápisu.",
  ["get: the key was used just now, so it moves to the back of the order. First find its index. Which iterator method returns the index of the first match?"] = "get: klíč byl právě použit, takže se přesune na konec pořadí. Nejdřív najdi jeho index. Která metoda iterátoru vrací index první shody?",
  ["git clones over https and asks for a password. Make it use your ssh key. Fill the git config key."] = "git klonuje přes https a chce heslo. Přiměj ho použít tvůj ssh klíč. Doplň klíč git configu.",
  ["go 1.23\n\n___ (\n    ./cousinshop\n    ./luckymac\n    ./kiosk\n)\n"] = "go 1.23\n\n___ (\n    ./cousinshop\n    ./luckymac\n    ./kiosk\n)\n",
  ["go build makes a single binary with no runtime to install. GOOS=linux cross-compiles."] = "go build vytvoří jedinou binárku bez runtime k instalaci. GOOS=linux kompiluje pro jinou platformu.",
  ["go f() is the whole of 'async': the call runs on its own goroutine and the current line moves on immediately."] = "go f() je celý „async“: volání běží ve vlastní goroutině a aktuální řádek jde hned dál.",
  ["go fetchMenu()\ntime.Sleep(time.Millisecond)\nfmt.Println(runtime.___())\n// 2: main, and the one nobody is waiting for\n"] = "go fetchMenu()\ntime.Sleep(time.Millisecond)\nfmt.Println(runtime.___())\n// 2: main a ta, na kterou nikdo nečeká\n",
  ["go fry() returns at once. fry runs concurrently. Two burners, one program."] = "go fry() se vrátí hned. fry běží souběžně. Dva hořáky, jeden program.",
  ['go func() {\n    fry("hashbrown")\n}___                    // call it right away\n'] = 'go func() {\n    fry("hashbrown")\n}___                    // hned ji zavolej\n',
  ["go func() {\n    wg.Wait()\n    ___(out)\n}()\nfor d := range out {\n    serve(d)\n}\n"] = "go func() {\n    wg.Wait()\n    ___(out)\n}()\nfor d := range out {\n    serve(d)\n}\n",
  ["go func() {\n    wg.___()                 // all workers returned\n    close(results)\n}()\nfor r := range results {\n    fmt.Println(r)\n}\n"] = "go func() {\n    wg.___()                 // všichni workeři se vrátili\n    close(results)\n}()\nfor r := range results {\n    fmt.Println(r)\n}\n",
  ["go func(){...}() is the everyday goroutine launcher. Pass loop variables as arguments."] = "go func(){...}() je běžný spouštěč goroutin. Proměnné cyklu předávej jako argumenty.",
  ["go get always shells out to git for a direct fetch, so git's own config decides the transport. The tool never sees your key; git does."] = "go get při přímém stažení vždycky volá git, takže o přenosu rozhoduje vlastní nastavení gitu. Nástroj tvůj klíč nikdy nevidí; git ano.",
  ["go get resolves the host from the path itself: github.com means a git clone over HTTPS, through the proxy by default. No registry, no publish step."] = "go get odvodí hosta z cesty samotné: github.com znamená git clone přes HTTPS, ve výchozím stavu přes proxy. Žádný registr, žádný krok publikování.",
  ["go get wrote the pin into go.mod. Which directive?"] = "go get zapsal připíchnutí do go.mod. Která direktiva?",
  ["go get, require, go.sum"] = "go get, require, go.sum",
  ["go install github.com/alex/luckymac/cmd/kiosk@latest builds a binary named kiosk: the last path element becomes the program name."] = "go install github.com/alex/luckymac/cmd/kiosk@latest sestaví binárku jménem kiosk: poslední prvek cesty se stane jménem programu.",
  ["go list -m -u all is the upgrade report; go get -u ./... takes them all. go mod why tells you which import dragged a module in."] = "go list -m -u all je zpráva o aktualizacích; go get -u ./... je vezme všechny. go mod why ti řekne, který import modul zatáhl dovnitř.",
  ["go mod init makes go.mod. The module path is how others import you."] = "go mod init vytvoří go.mod. Cesta modulu je to, čím tě ostatní importují.",
  ["go mod init, tidy, vet, build: one static binary. //go:embed bundles files."] = "go mod init, tidy, vet, build: jedna statická binárka. //go:embed přibalí soubory.",
  ["go mod tidy is the only dependency command most projects need."] = "go mod tidy je jediný příkaz pro závislosti, který většina projektů potřebuje.",
  ["go starts a goroutine: a lightweight thread the runtime multiplexes onto OS threads."] = "go spustí goroutine: lehké vlákno, které runtime multiplexuje na vlákna OS.",
  ["go test -race catches unsynchronized access while the tests run. Turn it on in CI."] = "go test -race chytí nesynchronizovaný přístup během testů. Zapni ho v CI.",
  ["go vet and go fmt run in CI on every Go project. staticcheck goes further."] = "go vet a go fmt běží v CI na každém Go projektu. staticcheck jde dál.",
  ["go vet says: passes lock by value. Fix the receiver."] = "go vet hlásí: passes lock by value. Oprav příjemce.",
  ["go.mod's second line pins the minimum Go. Fill the directive's value."] = "Druhý řádek go.mod připíchne minimální Go. Doplň hodnotu direktivy.",
  ["go.sum is not a lock file, it is a list of hashes: if GitHub ever served different bytes for v1.2.0, the build fails instead of running them."] = "go.sum není lock soubor, je to seznam hashů: kdyby GitHub někdy pro v1.2.0 poslal jiné bajty, build selže místo toho, aby je spustil.",
  ["golang.org/x/sync/errgroup: WaitGroup plus errors plus context cancel. The interview answer for fan-out."] = "golang.org/x/sync/errgroup: WaitGroup plus chyby plus zrušení contextu. Odpověď na pohovoru pro fan-out.",
  ["greet takes a borrowed text: a literal or a borrowed String both fit. Which parameter type?"] = "greet bere vypůjčený text: hodí se literál i vypůjčený String. Který typ parametru?",
  ["h := &IntHeap{}\nfor _, x := range nums {\n    heap.Push(h, x)\n    if h.Len() > k {\n        heap.___(h)         // the smallest leaves\n    }\n}\n"] = "h := &IntHeap{}\nfor _, x := range nums {\n    heap.Push(h, x)\n    if h.Len() > k {\n        heap.___(h)         // nejmenší odchází\n    }\n}\n",
  ["h[0] peeks in O(1). Never index deeper: the rest of the list is only partially ordered."] = "h[0] nakoukne v O(1). Nikdy neindexuj hlouběji: zbytek seznamu je jen částečně seřazený.",
  ["head.take() is how you move out of a &mut Option. The ? returns None on an empty list. Then relink the head."] = "head.take() je způsob, jak vytáhnout hodnotu z &mut Option. ? vrátí None u prázdného seznamu. Pak přepoj hlavu.",
  ["heap plus the stack verb for adding, one word, lowercase."] = "heap plus zásobníkové sloveso pro přidání, jedno slovo, malými písmeny.",
  ["heap plus the stack verb for taking, one word. It returns the smallest."] = "heap plus zásobníkové sloveso pro odebrání, jedno slovo. Vrací nejmenší.",
  ["heap.Pop swaps the root to the end first, so Pop returns the last element and shrinks. Fill both blanks."] = "heap.Pop nejdřív prohodí kořen na konec, takže Pop vrátí poslední prvek a zkrátí. Doplň obě mezery.",
  ["heapq turns a list into a min-heap: heappush and heappop are O(log n), h[0] is the smallest. Keep a heap of size k and its root is the kth largest. nlargest, nsmallest and Counter.most_common are the shortcuts."] = "heapq udělá ze seznamu min-haldu: heappush a heappop jsou O(log n), h[0] je nejmenší. Drž haldu velikosti k a její kořen je k-tý největší. nlargest, nsmallest a Counter.most_common jsou zkratky.",
  ["heapq: kth largest, top k"] = "heapq: k-tý největší, top k",
  ["height is 1 plus the taller of the two subtrees. Which method picks the larger of two usize?"] = "height je 1 plus vyšší ze dvou podstromů. Která metoda vybere větší ze dvou usize?",
  ["i := 0\n___ i < 8 {            // the only loop\n    i++\n}\n"] = "i := 0\n___ i < 8 {            // jediný cyklus\n    i++\n}\n",
  ["i for integer (signed), then the bit width. u32 is the unsigned twin."] = "i jako integer (se znaménkem), pak počet bitů. u32 je bezznaménkové dvojče.",
  ["i, found := slices.BinarySearch(a, x)   // ___\n"] = "i, found := slices.BinarySearch(a, x)   // ___\n",
  ["i8 i16 i32 i64 i128, u8 to u128, f32 f64, bool, char. Number types are spelled by size."] = "i8 i16 i32 i64 i128, u8 až u128, f32 f64, bool, char. Číselné typy se píší podle velikosti.",
  ['if __name__ == "__main__":\n    asyncio.___(main())\n'] = 'if __name__ == "__main__":\n    asyncio.___(main())\n',
  ['if bowls == 0:\n    print("closed")\n___ bowls < 3:\n    print("almost out")\nelse:\n    print("open")\n'] = 'if bowls == 0:\n    print("closed")\n___ bowls < 3:\n    print("almost out")\nelse:\n    print("open")\n',
  ["if dp[amount] > amount {\n    return ___              // never reached\n}\nreturn dp[amount]\n"] = "if dp[amount] > amount {\n    return ___              // nikdy nedosaženo\n}\nreturn dp[amount]\n",
  ["if err != nil { return err }. The first line after a call that can fail."] = "if err != nil { return err }. První řádek po volání, které může selhat.",
  ['if err := brew(); err != nil {\n    return fmt.Errorf("order %d: ___", id, err)\n}\n'] = 'if err := brew(); err != nil {\n    return fmt.Errorf("order %d: ___", id, err)\n}\n',
  ["if err := cross(); err ___ nil {   // init; condition\n    return err\n}\n"] = "if err := cross(); err ___ nil {   // init; podmínka\n    return err\n}\n",
  ['if errors.Is(ctx.Err(), context.___) {\n    log.Print("the customer stopped waiting")\n}\n'] = 'if errors.Is(ctx.Err(), context.___) {\n    log.Print("zákazník přestal čekat")\n}\n',
  ["if errors.___(err, ErrCold) {   // walks the chain\n    refund(order)\n}\n"] = "if errors.___(err, ErrCold) {   // prochází řetěz\n    refund(order)\n}\n",
  ["if init; cond scopes err to one block. The most common line in Go."] = "if init; cond omezí err na jeden blok. Nejčastější řádek v Go.",
  ["if is an expression. loop can break with a value. for walks a range. match must cover every case."] = "if je výraz. loop může skončit přes break s hodnotou. for prochází rozsah. match musí pokrýt každý případ.",
  ["if let Some(id) = ... runs only when there is a value. No unwrap, no panic. Order 8 goes out."] = "if let Some(id) = ... běží jen tehdy, když hodnota existuje. Žádný unwrap, žádný panic. Objednávka 8 odchází.",
  ["if mu.___() {\n    defer mu.Unlock()\n    refillIce()\n}\n"] = "if mu.___() {\n    defer mu.Unlock()\n    refillIce()\n}\n",
  ['if paper == 0 {\n    ___("till: no paper")   // unwinds, runs defers\n}\n'] = 'if paper == 0 {\n    ___("till: no paper")   // odvine zásobník, spustí defery\n}\n',
  ['if slices.___(names, "muffin") {\n    serve("muffin")\n}\n'] = 'if slices.___(names, "muffin") {\n    serve("muffin")\n}\n',
  ["if v, ok := memo[n]; ok. Hit: return. Miss: compute and store. Python spells this @functools.cache."] = "if v, ok := memo[n]; ok. Zásah: vrať. Minutí: spočítej a ulož. Python to píše @functools.cache.",
  ["if, for, switch, range"] = "if, for, switch, range",
  ["if, for, while"] = "if, for, while",
  ["if, loops and match"] = "if, cykly a match",
  ["imap gives a lazy iterator in order; imap_unordered gives them as they finish, which keeps every worker busy when the jobs are uneven."] = "imap dá líný iterátor v pořadí; imap_unordered je vydává, jak dobíhají, což udrží každého workera vytíženého, když jsou úlohy nestejné.",
  ["impl Cook for Grill. Rust is explicit: no implicit interfaces like Go. The grill station lights up."] = "impl Cook for Grill. Rust je výslovný: žádná implicitní rozhraní jako v Go. Stanice grilu se rozsvítí.",
  ["impl Cook in argument position is sugar for a generic <C: Cook>. Static dispatch, no Box."] = "impl Cook na pozici argumentu je zkratka pro generický <C: Cook>. Statický dispatch, žádný Box.",
  ["impl Order {\n    fn add(___, n: u32) {\n        self.qty += n;\n    }\n}\nlet mut o = Order { qty: 1 };\no.add(2);                   // qty is 3\n"] = "impl Order {\n    fn add(___, n: u32) {\n        self.qty += n;\n    }\n}\nlet mut o = Order { qty: 1 };\no.add(2);                   // qty je 3\n",
  ["impl Order {\n    fn total(___) -> u32 {\n        self.qty * 18       // read only\n    }\n}\n"] = "impl Order {\n    fn total(___) -> u32 {\n        self.qty * 18       // jen pro čtení\n    }\n}\n",
  ["impl Order { } holds the methods. Data and behaviour stay in two blocks. o.total() is 36."] = "impl Order { } drží metody. Data a chování zůstávají ve dvou blocích. o.total() je 36.",
  ["impl Receipt<'_> {\n    // Self in, one reference out: no lifetime name needed.\n    fn who(&self) -> ___ {\n        self.name\n    }\n}\n"] = "impl Receipt<'_> {\n    // Self dovnitř, jedna reference ven: jméno lifetimu není třeba.\n    fn who(&self) -> ___ {\n        self.name\n    }\n}\n",
  ["impl Trait in return position: static dispatch, no Box, closures stay unnamed."] = "impl Trait v návratové pozici: statický dispatch, žádný Box, closures zůstávají bezejmenné.",
  ['impl ___<ParseIntError> for OrderError {\n    fn from(e: ParseIntError) -> Self {\n        OrderError::BadQty(e)\n    }\n}\n// "1x8".parse::<i32>()? now becomes BadQty\n'] = 'impl ___<ParseIntError> for OrderError {\n    fn from(e: ParseIntError) -> Self {\n        OrderError::BadQty(e)\n    }\n}\n// "1x8".parse::<i32>()? se teď změní na BadQty\n',
  ["impl fmt::Display gives to_string() and {} for free. The till prints one clean line."] = "impl fmt::Display dá to_string() a {} zadarmo. Kasa vytiskne jeden čistý řádek.",
  ["impl fmt::Display gives {} and .to_string() for free. The order board reads: pineapple bun x2."] = "impl fmt::Display dává {} a .to_string() zdarma. Na tabuli objednávek stojí: pineapple bun x2.",
  ["impl std::error::Error for OrderError {} - now it fits in Box<dyn Error> and ? chains."] = "impl std::error::Error for OrderError {} - teď se vejde do Box<dyn Error> a ? řetězí.",
  ['import "./menu"\n// main.go:4:8: "./menu" is ___, but\n// ___ import paths are not supported in module mode\n'] = 'import "./menu"\n// main.go:4:8: "./menu" is ___, but\n// ___ import paths are not supported in module mode\n',
  ['import "./menu" fails. Which word does the error use for that kind of path?'] = 'import "./menu" selže. Jakým slovem chyba označuje takový druh cesty?',
  ['import "errors"\nvar ErrCold = errors.___("coffee is cold")\n'] = 'import "errors"\nvar ErrCold = errors.___("coffee is cold")\n',
  ['import "fmt" then fmt.Println. The kiosk beeps.'] = 'import "fmt" a pak fmt.Println. Kiosek pípne.',
  ['import "github.com/alex/luckymac/rider"\n// main.go:5:2: "github.com/alex/luckymac/rider"\n//     imported and not ___\n'] = 'import "github.com/alex/luckymac/rider"\n// main.go:5:2: "github.com/alex/luckymac/rider"\n//     imported and not ___\n',
  ['import "maps"\n\nfor k := range maps.___(prices) {   // iterator\n    fmt.Println(k)\n}\n'] = 'import "maps"\n\nfor k := range maps.___(prices) {   // iterátor\n    fmt.Println(k)\n}\n',
  ['import "net/http"\n\nhttp.___("/order", serve)   // path -> function\n'] = 'import "net/http"\n\nhttp.___("/order", serve)   // cesta -> funkce\n',
  ['import "slices"\n\nslices.___(names)          // in place, any ordered type\n'] = 'import "slices"\n\nslices.___(names)          // na místě, jakýkoli uspořádaný typ\n',
  ['import "strconv"\nn, err := strconv.___("18")   // 18, nil\ns := strconv.Itoa(n)          // back to "18"\n'] = 'import "strconv"\nn, err := strconv.___("18")   // 18, nil\ns := strconv.Itoa(n)          // zpět na "18"\n',
