  ['import _ "embed"\n\n//go:___ menu.json\nvar menu []byte\n'] = 'import _ "embed"\n\n//go:___ menu.json\nvar menu []byte\n',
  ["import ___\n\nwith ___.Pool() as pool:\n    pool.map(resize, photos)\n"] = "import ___\n\nwith ___.Pool() as pool:\n    pool.map(resize, photos)\n",
  ['import asyncio\n\n___ def fetch(rider):\n    await asyncio.sleep(1)\n    return f"{rider}: Percival St"\n'] = 'import asyncio\n\n___ def fetch(rider):\n    await asyncio.sleep(1)\n    return f"{rider}: Percival St"\n',
  ["import bisect\n\namounts = [6, 12, 38, 52]\ni = bisect.___(amounts, 38)\nprint(i)     # 2\n"] = "import bisect\n\namounts = [6, 12, 38, 52]\ni = bisect.___(amounts, 38)\nprint(i)     # 2\n",
  ["import bisect\ni = bisect.bisect_left(a, x)    # ___\n"] = "import bisect\ni = bisect.bisect_left(a, x)    # ___\n",
  ["import dataclasses\n\n@dataclasses.___\nclass Order:\n    item: str\n    qty: int = 1\n"] = "import dataclasses\n\n@dataclasses.___\nclass Order:\n    item: str\n    qty: int = 1\n",
  ["import functools\n\n@functools.___\ndef fib(n):\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)\n"] = "import functools\n\n@functools.___\ndef fib(n):\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)\n",
  ["import functools\n\ndef timer(fn):\n    @functools.___(fn)\n    def wrapper(*a, **kw):\n        return fn(*a, **kw)\n    return wrapper\n"] = "import functools\n\ndef timer(fn):\n    @functools.___(fn)\n    def wrapper(*a, **kw):\n        return fn(*a, **kw)\n    return wrapper\n",
  ["import heapq\nprices = [38, 12, 55, 20, 41]\ntop3 = heapq.___(3, prices)      # [55, 41, 38]\nlow2 = heapq.nsmallest(2, prices)   # [12, 20]\n"] = "import heapq\nprices = [38, 12, 55, 20, 41]\ntop3 = heapq.___(3, prices)      # [55, 41, 38]\nlow2 = heapq.nsmallest(2, prices)   # [12, 20]\n",
  ['import multiprocessing as mp\n\nmp.set_start_method("___")\n# fresh interpreter, nothing inherited\n'] = 'import multiprocessing as mp\n\nmp.set_start_method("___")\n# čerstvý interpret, nic se nedědí\n',
  ['import multiprocessing as mp\n\nn = mp.___()\nprint(f"{n} cores, {n} workers")\n'] = 'import multiprocessing as mp\n\nn = mp.___()\nprint(f"{n} cores, {n} workers")\n',
  ["import multiprocessing as mp\n\np = mp.___(target=grind, args=(rows,))\n"] = "import multiprocessing as mp\n\np = mp.___(target=grind, args=(rows,))\n",
  ["import multiprocessing as mp\n\nprinter = mp.___()\nmp.Process(target=label, args=(printer,)).start()\n"] = "import multiprocessing as mp\n\nprinter = mp.___()\nmp.Process(target=label, args=(printer,)).start()\n",
  ["import multiprocessing as mp\n\nq = mp.___()\nmp.Process(target=worker, args=(q,)).start()\n"] = "import multiprocessing as mp\n\nq = mp.___()\nmp.Process(target=worker, args=(q,)).start()\n",
  ['import multiprocessing as mp\n\nsums = mp.___("d", 8)\nsums[3] = 12.5\n'] = 'import multiprocessing as mp\n\nsums = mp.___("d", 8)\nsums[3] = 12.5\n',
  ["import multiprocessing as mp\n\nwith mp.___(8) as pool:\n    sizes = pool.map(resize, photos)\n"] = "import multiprocessing as mp\n\nwith mp.___(8) as pool:\n    sizes = pool.map(resize, photos)\n",
  ['import numpy as np\n\narr = np.ndarray((1024,), "f8", shm.___)\narr[0] = 42.0\n'] = 'import numpy as np\n\narr = np.ndarray((1024,), "f8", shm.___)\narr[0] = 42.0\n',
