  ['import threading\n\nt = threading.___(target=fry, args=("egg",))\n'] = 'import threading\n\nt = threading.___(target=fry, args=("egg",))\n',
  ["import time binds the module; time.sleep reaches into it. from time import sleep would bind just sleep."] = "import time naváže modul; time.sleep do něj sáhne. from time import sleep by navázalo jen sleep.",
  ["init runs after package variables are set and before main. Keep it small."] = "init běží po nastavení proměnných balíčku a před main. Ať je krátká.",
  ["input() returns text. int(input()) if you need a number. The robot takes its first order."] = "input() vrací text. int(input()), když potřebuješ číslo. Robot přijímá první objednávku.",
  ["insert walks down until it finds an empty spot. Which pattern is the empty spot?"] = "insert schází dolů, dokud nenajde prázdné místo. Který vzor je to prázdné místo?",
  ['int is 0, string is "", bool is false, pointer is nil.'] = 'int je 0, string je "", bool je false, ukazatel je nil.',
  ['int("12") is 12. int("12.5") raises ValueError; float first if the text has a dot.'] = 'int("12") je 12. int("12.5") vyhodí ValueError; má-li text tečku, nejdřív float.',
  ["int('abc') fails. Which keyword catches that error type?"] = "int('abc') selže. Které klíčové slovo zachytí ten typ chyby?",
  ["interface { Pay(int) error }. The till does not care if it is Octopus or cash."] = "interface { Pay(int) error }. Pokladně je jedno, jestli je to Octopus, nebo hotovost.",
  ["iota is Go's enum counter. Lines without a value repeat the one above."] = "iota je čítač enumů v Go. Řádky bez hodnoty opakují tu nad sebou.",
  ["is compares identity. Two riders in a loop must meet; on a straight route fast falls off the end. Round four to Bo."] = "is porovnává identitu. Dva kurýři ve smyčce se musí potkat; na rovné trase fast spadne z konce. Čtvrté kolo pro Boa.",
  ["is_some_and(|e| e < 10) beats map(..).unwrap_or(false). Review clean at 17:59. SHIPPED."] = "is_some_and(|e| e < 10) poráží map(..).unwrap_or(false). Review čisté v 17:59. NASAZENO.",
  ['it = iter([1])\nnext(it)      # 1\ntry:\n    next(it)\nexcept ___:\n    print("belt empty")\n'] = 'it = iter([1])\nnext(it)      # 1\ntry:\n    next(it)\nexcept ___:\n    print("belt empty")\n',
  ["items.last() is items.get(len - 1). O(1), and no panic on an empty Vec. push at the end is O(1) amortized."] = "items.last() je items.get(len - 1). O(1) a na prázdném Vec žádný panic. push na konec je amortizovaně O(1).",
  ["items[-1]. Python adds len for you. Constant time, like append at the end (amortized) and pop()."] = "items[-1]. Python len přičte za tebe. Konstantní čas, jako append na konec (amortizovaně) a pop().",
  ["items[len(items)-1]. Python spells it items[-1]. Both constant time. So is append at the end, amortized."] = "items[len(items)-1]. Python to píše items[-1]. Oboje konstantní čas. Stejně jako append na konec, amortizovaně.",
  ["iter() borrows, into_iter() consumes. map, filter, collect, sum, fold: no index bugs."] = "iter() si půjčuje, into_iter() spotřebuje. map, filter, collect, sum, fold: žádné bugy s indexy.",
  ["iter() yields &T. into_iter() yields T and eats the Vec. Dish zero prints again."] = "iter() dává &T. into_iter() dává T a sní Vec. Jídlo nula se zase tiskne.",
  ["iter().sum() needs the result type written down. map, filter, count and collect live on the same chain."] = "iter().sum() potřebuje mít zapsaný typ výsledku. map, filter, count a collect žijí na stejném řetězci.",
  ["iter(x) calls x.__iter__(); next(it) calls __next__. That pair is the whole iterator protocol."] = "iter(x) volá x.__iter__(); next(it) volá __next__. Tato dvojice je celý iterátorový protokol.",
  ["iter.Seq[T] is func(yield func(T) bool). for x := range Items() just works."] = "iter.Seq[T] je func(yield func(T) bool). for x := range Items() prostě funguje.",
  ["j moves left as i moves right. Stop when they meet."] = "j jde doleva, zatímco i jde doprava. Zastav, když se potkají.",
  ["jobs := make(chan int, 10)\nresults := make(chan int, 10)\nvar wg sync.WaitGroup\nfor w := 1; w <= 3; w++ {\n    wg.___(1)\n    go worker(jobs, results, &wg)\n}\n"] = "jobs := make(chan int, 10)\nresults := make(chan int, 10)\nvar wg sync.WaitGroup\nfor w := 1; w <= 3; w++ {\n    wg.___(1)\n    go worker(jobs, results, &wg)\n}\n",
  ["jobs = [(p, 512) for p in photos]\nwith mp.Pool(8) as pool:\n    pool.___(resize, jobs)\n"] = "jobs = [(p, 512) for p in photos]\nwith mp.Pool(8) as pool:\n    pool.___(resize, jobs)\n",
  ["jobs.join() returns when every put has a matching task_done. daemon=True lets the idle cooks die with main. Seven rounds, no misses. HIRED, at midnight, in Python."] = "jobs.join() se vrátí, když každý put má odpovídající task_done. daemon=True nechá nečinné kuchaře skončit s hlavním vláknem. Sedm kol, bez chyby. PŘIJAT, o půlnoci, v Pythonu.",
  ["join! waits for all; select! returns on the first. 200 ms total instead of 400."] = "join! čeká na všechny; select! se vrátí s prvním. Celkem 200 ms místo 400.",
  ["join() blocks until the child exits. Without it the parent can reach the end of the script and leave orphans behind."] = "join() blokuje, dokud potomek neskončí. Bez něj může rodič dojít na konec skriptu a nechat za sebou sirotky.",
  ["join() blocks until the thread ends and returns Result<T>; Err means the thread panicked. 180 seconds to steep."] = "join() blokuje, dokud vlákno neskončí, a vrací Result<T>; Err znamená, že vlákno zpanikařilo. 180 sekund louhování.",
  ["json only sees exported fields. Name the item field: Item or item?"] = "json vidí jen exportovaná pole. Pojmenuj pole položky: Item, nebo item?",
  ["json sees exported fields only. Tags pick the key. Marshal out, Unmarshal in."] = "json vidí jen exportovaná pole. Tagy volí klíč. Marshal ven, Unmarshal dovnitř.",
  ["k contenders left; the smallest of them is the kth largest overall. Which index holds it?"] = "Zbylo k kandidátů; nejmenší z nich je celkově k-tý největší. Který index ho drží?",
  ["k positions behind the newest one."] = "k pozic za tím nejnovějším.",
  ["kb = 2 ___ 10\nprint(kb)          # 1024\n"] = "kb = 2 ___ 10\nprint(kb)          # 1024\n",
  ["key= is called once per item; sort by its result. sorted(words, key=str.lower) is the case-insensitive classic."] = "key= se volá jednou na položku; třídí se podle jejího výsledku. sorted(words, key=str.lower) je klasika bez ohledu na velikost písmen.",
  ["kth largest: keep only the k biggest in a MIN-heap, so the smallest of them sits on top. BinaryHeap is a max-heap: which std::cmp wrapper flips the order?"] = "k-tý největší: drž jen k největších v MIN-haldě, aby nejmenší z nich seděl na vrcholu. BinaryHeap je max-halda: který obal ze std::cmp obrátí pořadí?",
  ["l only moves right, so each character enters and leaves once: O(n) despite the nested while."] = "l se posouvá jen doprava, takže každý znak vstoupí a odejde jednou: O(n) navzdory vnořenému while.",
  ["l[i] <= r[j] keeps the merge stable. The leftovers are appended with extend. O(n) per merge."] = "l[i] <= r[j] drží slévání stabilní. Zbytky se připojí přes extend. O(n) na jedno slití.",
  ['label := fmt.___("%s $%d", item, price)   // "set $25"\n'] = 'label := fmt.___("%s $%d", item, price)   // "set $25"\n',
  ["lambda o: o[1] is an anonymous one-expression function. For anything longer, use def."] = "lambda o: o[1] je anonymní funkce s jediným výrazem. Na cokoli delšího použij def.",
  ["largest compares with >. Which trait must T promise?"] = "largest porovnává přes >. Který trait musí T slíbit?",
  ["last := items[len(items)___]    // still O(1): len is stored\n"] = "last := items[len(items)___]    // stále O(1): len je uložená\n",
  ["last := map[rune]int{}\nl, best := 0, 0\nfor r, c := range s {\n    if p, ok := last[c]; ok && p >= l {\n        l = p + 1           // jump past the repeat\n    }\n    last[c] = ___\n"] = "last := map[rune]int{}\nl, best := 0, 0\nfor r, c := range s {\n    if p, ok := last[c]; ok && p >= l {\n        l = p + 1           // skoč za opakování\n    }\n    last[c] = ___\n",
  ["last = items[___]    # still O(1): negative indexes count from the end\n"] = "last = items[___]    # stále O(1): záporné indexy počítají od konce\n",
  ["latest means the highest tagged release, never a pre-release and never main. Without any tag at all you get a pseudo-version like v0.0.0-20260904164500-abc123def456."] = "latest znamená nejvyšší otagované vydání, nikdy pre-release a nikdy main. Bez jakéhokoli tagu dostaneš pseudoverzi jako v0.0.0-20260904164500-abc123def456.",
  ["len counts bytes. 灣 is one character. In UTF-8, how many bytes?"] = "len počítá bajty. 灣 je jeden znak. Kolik bajtů má v UTF-8?",
  ["len is how many you can see. cap is how many fit before a new array."] = "len je, kolik vidíš. cap je, kolik se vejde, než vznikne nové pole.",
  ["len is what is waiting, cap is the buffer size. A buffer smooths bursts; it never removes the need to handle a slow consumer."] = "len je to, co čeká, cap je velikost bufferu. Buffer vyhladí nárazy; nikdy tě nezbaví nutnosti řešit pomalého konzumenta.",
  ["len works on lists, strings, dicts, sets, anything with __len__. It is O(1): the length is stored."] = "len funguje na seznamech, řetězcích, dictech, setech, na čemkoli s __len__. Je O(1): délka je uložená.",
  ["len() is bytes. Slicing &s[0..4] in the middle of 鑼 panics: not a char boundary."] = "len() jsou bajty. Řez &s[0..4] uprostřed 鑼 zpanikaří: není to hranice znaku.",
  ["len() returns usize. The second let shadows n with a new binding; the old one is gone. Next tram in 7."] = "len() vrací usize. Druhé let zastíní n novou vazbou; stará je pryč. Další tramvaj za 7.",
  ["len(a) // 2 splits [3, 1, 2] into [3] and [1, 2]. Each level halves; log2(n) levels."] = "len(a) // 2 rozdělí [3, 1, 2] na [3] a [1, 2]. Každá úroveň půlí; log2(n) úrovní.",
  ["len(s) - 1 is the last index. Two pointers meet in the middle: O(n) time, O(1) space. s == s[::-1] is the one-liner."] = "len(s) - 1 je poslední index. Dva ukazatele se sejdou uprostřed: O(n) času, O(1) prostoru. s == s[::-1] je jednořádková verze.",
  ["len(s) is bytes, not characters. That is why the sign counted nine."] = "len(s) jsou bajty, ne znaky. Proto cedule napočítala devět.",
  ["let (mut i, mut j) = (0, a.len() - 1);     // a is sorted\nwhile i < j {\n    match (a[i] + a[j]).cmp(&target) {\n        Ordering::Equal => return Some((i, j)),\n        Ordering::Less => i += 1,        // need more\n        Ordering::Greater => j ___ 1,    // need less\n    }\n"] = "let (mut i, mut j) = (0, a.len() - 1);     // a je seřazené\nwhile i < j {\n    match (a[i] + a[j]).cmp(&target) {\n        Ordering::Equal => return Some((i, j)),\n        Ordering::Less => i += 1,        // potřeba víc\n        Ordering::Greater => j ___ 1,    // potřeba míň\n    }\n",
  ["let (mut lo, mut hi) = (0, a.len());\nwhile lo < hi {\n    let mid = lo + (hi - lo) ___ 2;   // integer division on usize\n    if a[mid] < x { lo = mid + 1 } else { hi = mid }\n}\n"] = "let (mut lo, mut hi) = (0, a.len());\nwhile lo < hi {\n    let mid = lo + (hi - lo) ___ 2;   // celočíselné dělení na usize\n    if a[mid] < x { lo = mid + 1 } else { hi = mid }\n}\n",
  ['let (tx, rx) = mpsc::channel();\n// Two tills, one kitchen: each till needs its own sender.\nlet tx2 = tx.___();\nthread::spawn(move || tx.send("till 1").unwrap());\nthread::spawn(move || tx2.send("till 2").unwrap());\nfor msg in rx { println!("{msg}"); }\n'] = 'let (tx, rx) = mpsc::channel();\n// Dvě pokladny, jedna kuchyně: každá pokladna potřebuje vlastního odesílatele.\nlet tx2 = tx.___();\nthread::spawn(move || tx.send("till 1").unwrap());\nthread::spawn(move || tx2.send("till 2").unwrap());\nfor msg in rx { println!("{msg}"); }\n',
  ['let (tx, rx) = mpsc::channel();\nlet tx2 = tx.clone();\nthread::spawn(move || tx2.send("bun").unwrap());\n___(tx);   // otherwise the loop below never ends\nfor msg in rx { println!("{msg}"); }\n'] = 'let (tx, rx) = mpsc::channel();\nlet tx2 = tx.clone();\nthread::spawn(move || tx2.send("bun").unwrap());\n___(tx);   // jinak cyklus níže nikdy neskončí\nfor msg in rx { println!("{msg}"); }\n',
  ["let (tx, rx) = mpsc::channel();\ntx.send(7).unwrap();\n// The kitchen waits here until an order arrives.\nlet order: u32 = rx.___().unwrap();\n"] = "let (tx, rx) = mpsc::channel();\ntx.send(7).unwrap();\n// Kuchyně tady čeká, dokud nedorazí objednávka.\nlet order: u32 = rx.___().unwrap();\n",
  ["let Reverse(kth) = ... destructures the wrapper in the pattern. peek is O(1)."] = "let Reverse(kth) = ... destrukturuje obal ve vzoru. peek je O(1).",
  ["let Some(x) = opt else { return }; binds x for the rest of the function. No nesting."] = "let Some(x) = opt else { return }; naváže x pro zbytek funkce. Žádné zanoření.",
  ["let b = a.___();    // allocate n ints and copy: O(n) time, O(n) space\n"] = "let b = a.___();    // alokuj n intů a zkopíruj: O(n) času, O(n) prostoru\n",
  ["let b = s.as_bytes();\nlet mut seen = HashSet::new();\nlet (mut l, mut best) = (0, 0);\nfor r in 0..b.len() {\n    while seen.contains(&b[r]) {\n        seen.___(&b[l]);    // the left end leaves\n        l += 1;\n"] = "let b = s.as_bytes();\nlet mut seen = HashSet::new();\nlet (mut l, mut best) = (0, 0);\nfor r in 0..b.len() {\n    while seen.contains(&b[r]) {\n        seen.___(&b[l]);    // levý konec odchází\n        l += 1;\n",
  ["let bill = vec![18, 0, 42, 0, 25];\n// into_iter gives i32; the closure sees &i32\nlet ok: Vec<_> = bill.into_iter().___(|p| *p > 0).collect();\nassert_eq!(ok, vec![18, 42, 25]);\n"] = "let bill = vec![18, 0, 42, 0, 25];\n// into_iter dává i32; closure vidí &i32\nlet ok: Vec<_> = bill.into_iter().___(|p| *p > 0).collect();\nassert_eq!(ok, vec![18, 42, 25]);\n",
  ["let binds. mut allows change. const needs a type. as converts. A new let can shadow an old name."] = "let váže. mut povolí změnu. const potřebuje typ. as převádí. Nové let může zastínit staré jméno.",
  ['let dish = "curry rice";\nlet qty = 2;\n// like println! but it returns the String\nlet line = ___!("{qty} x {dish}");\n'] = 'let dish = "curry rice";\nlet qty = 2;\n// jako println!, ale vrací String\nlet line = ___!("{qty} x {dish}");\n',
  ['let dishes = ["curry rice", "noodles", "toast"];\n// nothing runs before this call; turbofish names the type\nlet lens = dishes.iter().map(|d| d.len()).___::<Vec<_>>();\nassert_eq!(lens, vec![10, 7, 5]);\n'] = 'let dishes = ["curry rice", "noodles", "toast"];\n// před tímto volání nic neběží; turbofish pojmenuje typ\nlet lens = dishes.iter().map(|d| d.len()).___::<Vec<_>>();\nassert_eq!(lens, vec![10, 7, 5]);\n',
  ['let dishes = ["curry rice", "noodles", "toast"];\n// yields (usize, &&str) pairs, starting from 0\nfor (i, d) in dishes.iter().___() {\n    println!("{}. {d}", i + 1);\n}\n'] = 'let dishes = ["curry rice", "noodles", "toast"];\n// dává dvojice (usize, &&str), počítá od 0\nfor (i, d) in dishes.iter().___() {\n    println!("{}. {d}", i + 1);\n}\n',
  ['let dishes = vec!["curry rice", "noodles", "toast"];\n// borrows every element as &&str; dishes stays usable\nfor d in dishes.___() {\n    println!("ticket: {d}");\n}\n'] = 'let dishes = vec!["curry rice", "noodles", "toast"];\n// půjčí si každý prvek jako &&str; dishes zůstává použitelné\nfor d in dishes.___() {\n    println!("ticket: {d}");\n}\n',
  ['let district = "銅鑼灣";\nlet n = district.___().count();\nassert_eq!(n, 3);\n// the receipt now cuts at whole characters\n'] = 'let district = "銅鑼灣";\nlet n = district.___().count();\nassert_eq!(n, 3);\n// účtenka teď řeže na celých znacích\n',
  ["let else, matches!, impl Trait, ..=, ? on Option, is_some_and: less nesting, same safety."] = "let else, matches!, impl Trait, ..=, ? na Option, is_some_and: méně zanoření, stejná bezpečnost.",
  ['let eta: Option<u32> = fetch_eta_cached(order.id);\n// Rust 1.70: None -> false, Some(e) -> the closure result\nlet fast = eta.___(|e| e < 10);\nif fast { println!("promise the customer 10 minutes"); }\n'] = 'let eta: Option<u32> = fetch_eta_cached(order.id);\n// Rust 1.70: None -> false, Some(e) -> výsledek closure\nlet fast = eta.___(|e| e < 10);\nif fast { println!("promise the customer 10 minutes"); }\n',
  ['let menu = vec!["bun", "egg tart", "milk tea"];\n// Borrow menu from threads; all end before the block does.\nthread::___(|s| {\n    s.spawn(|| println!("{}", menu[0]));\n    s.spawn(|| println!("{}", menu[1]));\n});\n'] = 'let menu = vec!["bun", "egg tart", "milk tea"];\n// Půjč si menu z vláken; všechna skončí dřív než blok.\nthread::___(|s| {\n    s.spawn(|| println!("{}", menu[0]));\n    s.spawn(|| println!("{}", menu[1]));\n});\n',
  ["let mut b = a.clone();    // a second Vec of n ints: O(___)\nb.sort();\n"] = "let mut b = a.clone();    // druhý Vec n intů: O(___)\nb.sort();\n",
  ["let mut count = 0; Immutable by default is Rust's first safety rule. The sign counts again."] = "let mut count = 0; Neměnnost jako výchozí stav je první bezpečnostní pravidlo Rustu. Tabule zase počítá.",
  ["let mut counts: HashMap<&str, u32> = HashMap::new();\nfor w in \"muffin coffee muffin\".split(' ') {\n    // start at 0 if w is new, then bump it either way\n    *counts.entry(w).___(0) += 1;\n}\nassert_eq!(counts[\"muffin\"], 2);\n"] = "let mut counts: HashMap<&str, u32> = HashMap::new();\nfor w in \"muffin coffee muffin\".split(' ') {\n    // začni na 0, když je w nové, a tak jako tak přičti\n    *counts.entry(w).___(0) += 1;\n}\nassert_eq!(counts[\"muffin\"], 2);\n",
  ["let mut handles = Vec::new();\nfor id in 0..3 {\n    let rx = Arc::clone(&rx);\n    // a new OS thread runs the closure; move hands over rx\n    handles.push(thread::___(move || worker(id, rx)));\n}\n"] = "let mut handles = Vec::new();\nfor id in 0..3 {\n    let rx = Arc::clone(&rx);\n    // nové vlákno OS spustí closure; move předá rx\n    handles.push(thread::___(move || worker(id, rx)));\n}\n",
  ["let mut ids = vec![9, 2, 7, 2, 5];\n// equal ids may swap places; nobody can tell\nids.___();\nassert_eq!(ids, [2, 2, 5, 7, 9]);\n"] = "let mut ids = vec![9, 2, 7, 2, 5];\n// stejná id si můžou prohodit místa; nikdo to nepozná\nids.___();\nassert_eq!(ids, [2, 2, 5, 7, 9]);\n",
  ['let mut left = 3;\n___ left > 0 {\n    left -= 1;\n    if left == 1 { continue; }   // skip this round\n    println!("{}", left);\n}\n'] = 'let mut left = 3;\n___ left > 0 {\n    left -= 1;\n    if left == 1 { continue; }   // přeskoč toto kolo\n    println!("{}", left);\n}\n',
  ["let mut max = prices[0];\nfor &p in &prices[1..] {    // ___ comparisons\n    if p > max { max = p; }\n}\n"] = "let mut max = prices[0];\nfor &p in &prices[1..] {    // ___ porovnání\n    if p > max { max = p; }\n}\n",
  ["let mut n = 0;\nfor r in 0..g.len() {\n    for c in 0..g[0].len() {\n        // land still standing: a new island, flood it\n        if g[r][c] == b'1' { n += 1; ___(&mut g, r, c); }\n    }\n}\n"] = "let mut n = 0;\nfor r in 0..g.len() {\n    for c in 0..g[0].len() {\n        // pevnina ještě stojí: nový ostrov, zaplav ho\n        if g[r][c] == b'1' { n += 1; ___(&mut g, r, c); }\n    }\n}\n",
  ['let mut order = String::new();\norder.___("curry rice");\norder.___(" + hash brown");\nlet loud = order.to_uppercase();\n'] = 'let mut order = String::new();\norder.___("curry rice");\norder.___(" + hash brown");\nlet loud = order.to_uppercase();\n',
  ["let mut seen = ___::new();\nfor g in &guests {               // one pass: O(n)\n    if !seen.insert(g) { dup = true; }   // false = already there\n}\n"] = "let mut seen = ___::new();\nfor g in &guests {               // jeden průchod: O(n)\n    if !seen.insert(g) { dup = true; }   // false = už tam byl\n}\n",
  ["let mut st: Vec<char> = Vec::new();\nfor c in s.chars() {\n    let open = closer_of(c);\n    if open == '\\0' {\n        st.___(c);          // wait here for the closer\n        continue;\n    }\n"] = "let mut st: Vec<char> = Vec::new();\nfor c in s.chars() {\n    let open = closer_of(c);\n    if open == '\\0' {\n        st.___(c);          // tady čeká na zavírací\n        continue;\n    }\n",
  ['let mut tray = vec![7, 8];\n// pop returns an Option: a value, or None if empty.\nif let ___(id) = tray.pop() {\n    println!("serving order {id}");\n}\n'] = 'let mut tray = vec![7, 8];\n// pop vrací Option: hodnotu, nebo None, když je prázdný.\nif let ___(id) = tray.pop() {\n    println!("serving order {id}");\n}\n',
  ['let mut tries = 0;\nlet code = ___ {\n    tries += 1;\n    if tries == 3 { break tries * 10; }\n};\nprintln!("{}", code);   // 30\n'] = 'let mut tries = 0;\nlet code = ___ {\n    tries += 1;\n    if tries == 3 { break tries * 10; }\n};\nprintln!("{}", code);   // 30\n',
  ["let n = if a > b { a } else { b }; Both branches must have the same type. n is 22."] = "let n = if a > b { a } else { b }; Obě větve musí mít stejný typ. n je 22.",
  ['let order = Order { name: "toast".into(), qty: 2 };\n// takes a reference; returns Result<String, Error>\nlet text = serde_json::___(&order)?;\nassert_eq!(text, r#"{"name":"toast","qty":2}"#);\n'] = 'let order = Order { name: "toast".into(), qty: 2 };\n// bere referenci; vrací Result<String, Error>\nlet text = serde_json::___(&order)?;\nassert_eq!(text, r#"{"name":"toast","qty":2}"#);\n',
  ['let order = String::from("pineapple bun");\n// The thread may outlive this block: give it the String.\nlet h = thread::spawn(___ || {\n    println!("toasting {order}");\n});\nh.join().unwrap();\n'] = 'let order = String::from("pineapple bun");\n// Vlákno může přežít tento blok: dej mu ten String.\nlet h = thread::spawn(___ || {\n    println!("toasting {order}");\n});\nh.join().unwrap();\n',
  ["let price = 28; The type is inferred as i32. Without mut it can never change."] = "let price = 28; Typ se odvodí jako i32. Bez mut se už nikdy nezmění.",
  ['let prices = [18, 22, 45, 60];       // already sorted\n// halve the range each step\nmatch prices.___(&45) {\n    Ok(i) => println!("found at {i}"),\n    Err(i) => println!("would insert at {i}"),\n}\n'] = 'let prices = [18, 22, 45, 60];       // už seřazeno\n// každý krok rozpůlí rozsah\nmatch prices.___(&45) {\n    Ok(i) => println!("found at {i}"),\n    Err(i) => println!("would insert at {i}"),\n}\n',
  ["let prices = vec![18, 42, 25];\n// acc starts at 0; the closure returns the next acc\nlet total = prices.iter().___(0, |acc, p| acc + p);\nassert_eq!(total, 85);\n"] = "let prices = vec![18, 42, 25];\n// acc začíná na 0; closure vrací další acc\nlet total = prices.iter().___(0, |acc, p| acc + p);\nassert_eq!(total, 85);\n",
  ["let prices = vec![18, 42, 25];\n// the turbofish tells it which number type to add into\nlet total = prices.iter().___::<i32>();\nassert_eq!(total, 85);\n"] = "let prices = vec![18, 42, 25];\n// turbofish mu řekne, do jakého číselného typu sčítat\nlet total = prices.iter().___::<i32>();\nassert_eq!(total, 85);\n",
  ["let qty = vec![1, 2, 3];\n// a closure: the parameter sits between two pipes\nlet doubled: Vec<i32> = qty.iter().map(___ x * 2).collect();\nassert_eq!(doubled, vec![2, 4, 6]);\n"] = "let qty = vec![1, 2, 3];\n// closure: parametr sedí mezi dvěma svislými čárami\nlet doubled: Vec<i32> = qty.iter().map(___ x * 2).collect();\nassert_eq!(doubled, vec![2, 4, 6]);\n",
  ["let sold = Arc::new(Mutex::new(0u32));\n// Each thread needs its own handle to the same counter.\nlet mine = ___(&sold);\nthread::spawn(move || { *mine.lock().unwrap() += 1; });\n"] = "let sold = Arc::new(Mutex::new(0u32));\n// Každé vlákno potřebuje vlastní handle na stejný čítač.\nlet mine = ___(&sold);\nthread::spawn(move || { *mine.lock().unwrap() += 1; });\n",
  ["let sold = Arc::new(Mutex::new(0u32));\n// Take the guard; it opens again when it goes out of scope.\nlet mut n = sold.___().unwrap();\n*n += 1;\n"] = "let sold = Arc::new(Mutex::new(0u32));\n// Vezmi guard; znovu se otevře, když opustí blok.\nlet mut n = sold.___().unwrap();\n*n += 1;\n",
  ["let tail = items.___();    // Some(&x) or None; still O(1)\n"] = "let tail = items.___();    // Some(&x) nebo None; stále O(1)\n",
  ['let text = r#"{"dish":"toast","tags":["hot","new"]}"#;\n// an enum: Null, Bool, Number, String, Array, Object\nlet v: serde_json::___ = serde_json::from_str(text)?;\nprintln!("{}", v["tags"][0]);   // "hot"\n'] = 'let text = r#"{"dish":"toast","tags":["hot","new"]}"#;\n// enum: Null, Bool, Number, String, Array, Object\nlet v: serde_json::___ = serde_json::from_str(text)?;\nprintln!("{}", v["tags"][0]);   // "hot"\n',
  ['let text = r#"{"name":"noodles","qty":1}"#;\n// the type annotation tells serde what to build\nlet order: Order = serde_json::___(text)?;\nassert_eq!(order.qty, 1);\n'] = 'let text = r#"{"name":"noodles","qty":1}"#;\n// typová anotace říká serde, co má postavit\nlet order: Order = serde_json::___(text)?;\nassert_eq!(order.qty, 1);\n',
  ["let total: i32 = prices.iter().sum();        // n steps\nlet max = prices.iter().max();                // n more\n// 2n steps, written O(___)\n"] = "let total: i32 = prices.iter().sum();        // n kroků\nlet max = prices.iter().max();                // n dalších\n// 2n kroků, zapsáno O(___)\n",
  ["let total: i32 = prices.iter().sum();   // ___ : n items, n adds\n"] = "let total: i32 = prices.iter().sum();   // ___ : n položek, n součtů\n",
  ['let typed = "18";\n// FromStr does the work; the turbofish picks the type\nlet qty = typed.___::<i32>()?;\nprintln!("{qty} sets");\n'] = 'let typed = "18";\n// práci dělá FromStr; turbofish vybere typ\nlet qty = typed.___::<i32>()?;\nprintln!("{qty} sets");\n',
  ['light := "green"\n___ light {\ncase "green":\n    walk()\n}\n'] = 'light := "green"\n___ light {\ncase "green":\n    walk()\n}\n',
  ["list(a), a[:] or a.copy(): all shallow, all O(n). Allocation is where space complexity is paid."] = "list(a), a[:] nebo a.copy(): všechny mělké, všechny O(n). Alokace je místo, kde se platí prostorová složitost.",
  ["list[str] since 3.9; typing.List[str] before. Go's []string, Rust's Vec<String>."] = "list[str] od 3.9; typing.List[str] dříve. []string z Go, Vec<String> z Rustu.",
  ["lo = mid + 1 drops the left half. Each step halves the range: O(log n). The array must be sorted first."] = "lo = mid + 1 zahodí levou půlku. Každý krok půlí rozsah: O(log n). Pole musí být nejdřív seřazené.",
  ["lo, hi := 0, len(a)\nfor lo < hi {\n    mid := (lo + hi) ___ 2   // integer division in Go\n    if a[mid] < x { lo = mid + 1 } else { hi = mid }\n}\n"] = "lo, hi := 0, len(a)\nfor lo < hi {\n    mid := (lo + hi) ___ 2   // celočíselné dělení v Go\n    if a[mid] < x { lo = mid + 1 } else { hi = mid }\n}\n",
  ["lo, hi := 0, len(a)         // [lo, hi)\nfor lo < hi {\n    mid := lo + (hi-lo)/___\n"] = "lo, hi := 0, len(a)         // [lo, hi)\nfor lo < hi {\n    mid := lo + (hi-lo)/___\n",
  ["lo, hi = 0, len(a)\nwhile lo < hi:\n    mid = (lo + hi) ___ 2    # floor division\n    if a[mid] < x: lo = mid + 1\n    else: hi = mid\n"] = "lo, hi = 0, len(a)\nwhile lo < hi:\n    mid = (lo + hi) ___ 2    # celočíselné dělení\n    if a[mid] < x: lo = mid + 1\n    else: hi = mid\n",
  ["lock = threading.___()\nserved = 0\n\ndef serve():\n    global served\n    with lock:\n        served += 1\n"] = "lock = threading.___()\nserved = 0\n\ndef serve():\n    global served\n    with lock:\n        served += 1\n",
  ["lock() returns a MutexGuard; unwrap fails only if another thread panicked while holding it. The guard unlocks on drop."] = "lock() vrací MutexGuard; unwrap selže, jen když jiné vlákno zpanikařilo, zatímco ho drželo. Guard se odemkne při drop.",
  ["log n levels, n work per level: O(n log n). The base case is a slice of 0 or 1."] = "log n úrovní, n práce na úroveň: O(n log n). Bázový případ je slice o 0 nebo 1 prvku.",
  ["log prints and returns nothing. What goes after the arrow?"] = "log tiskne a nic nevrací. Co patří za šipku?",
  ["log() prints but never returns. What does print(log('x')) show on its second line?"] = "log() tiskne, ale nikdy nevrací. Co ukáže print(log('x')) na druhém řádku?",
  ['log.Fatal(http.___(":8080", nil))   // nil = default mux\n'] = 'log.Fatal(http.___(":8080", nil))   // nil = výchozí mux\n',
  ["longest returns one of its inputs. Which lifetime does the return value carry?"] = "longest vrací jeden ze svých vstupů. Který lifetime nese návratová hodnota?",
  ["loop = asyncio.get_running_loop()\nsize = await loop.___(ex, resize, photo)\n"] = "loop = asyncio.get_running_loop()\nsize = await loop.___(ex, resize, photo)\n",
  ["loop { ... break value; } is an expression. code becomes 30. The gate stops spinning."] = "loop { ... break value; } je výraz. code bude 30. Brána se přestane točit.",
  ["low:high. Includes low, excludes high. Same backing array, no copy."] = "low:high. Zahrnuje low, vynechává high. Stejné podkladové pole, žádná kopie.",
  ["lows[-1] is always the minimum of what is on st. pop both lists together. O(1) push, pop and get_min."] = "lows[-1] je vždy minimum toho, co je na st. pop obou seznamů zároveň. O(1) push, pop i get_min.",
  ["luckymac itself needs a JSON library you never import. How does go.mod mark it?"] = "luckymac sám potřebuje JSON knihovnu, kterou ty nikdy neimportuješ. Jak ji go.mod označí?",
  ["luckymac/\n  ___/luckymac/main.go   # go build ./___/luckymac\n  ___/kiosk/main.go      # go build ./___/kiosk\n  menu/  internal/\n"] = "luckymac/\n  ___/luckymac/main.go   # go build ./___/luckymac\n  ___/kiosk/main.go      # go build ./___/kiosk\n  menu/  internal/\n",
  ["luckymac/\n  ___/rider/rider.go     <- only luckymac/... may import\n  menu/price.go          <- anyone may import\n"] = "luckymac/\n  ___/rider/rider.go     <- smí importovat jen luckymac/...\n  menu/price.go          <- smí importovat kdokoli\n",
  ['luckymac/           module github.com/alex/luckymac\n  menu/price.go     import "github.com/alex/luckymac/___"\n  rider/eta.go      import "github.com/alex/luckymac/rider"\n'] = 'luckymac/           module github.com/alex/luckymac\n  menu/price.go     import "github.com/alex/luckymac/___"\n  rider/eta.go      import "github.com/alex/luckymac/rider"\n',
  ["m := <-res blocks this goroutine, not the program. That is exactly what await does, minus the keyword and minus the coloured functions."] = "m := <-res zablokuje tuhle goroutinu, ne program. Přesně to dělá await, jen bez klíčového slova a bez obarvených funkcí.",
  ["macOS and Windows do not fork by default. Name their start method."] = "macOS a Windows ve výchozím stavu nedělají fork. Pojmenuj jejich metodu spuštění.",
  ["main calls menu.Price and the compiler says undefined. Fix the name."] = "main volá menu.Price a překladač hlásí undefined. Oprav jméno.",
  ["main can fail in many ways. Which pointer type wraps any dyn Error?"] = "main může selhat mnoha způsoby. Který typ ukazatele zabalí libovolný dyn Error?",
  ["main sends on an unbuffered channel with nobody receiving. The runtime reports: all goroutines are asleep - ___!"] = "main odesílá do kanálu bez bufferu a nikdo nepřijímá. Runtime hlásí: all goroutines are asleep - ___!",
  ["make (or a {} literal) before the first write. Reading a nil map is safe."] = "make (nebo literál {}) před prvním zápisem. Čtení z nil mapy je bezpečné.",
  ["make(T, len, cap) for slices, maps, channels. new(T) only gives a zeroed pointer."] = "make(T, len, cap) pro slice, mapy, kanály. new(T) dá jen vynulovaný ukazatel.",
  ["make([]int, len(a)) then copy. Allocation is where space complexity is paid; the garbage collector collects the rent later."] = "make([]int, len(a)) a pak copy. Alokace je místo, kde se platí prostorová složitost; garbage collector vybere nájem později.",
  ["make(chan string). Unbuffered: send waits for receive."] = "make(chan string). Bez bufferu: odeslání čeká na příjem.",
  ["map with an i in front, as in iterator. There is an _unordered twin that is faster."] = "map s i vpředu, jako iterator. Existuje i rychlejší dvojče _unordered.",
  ["map, then [key type], then value type."] = "map, pak [typ klíče], pak typ hodnoty.",
  ["map[K]bool is the everyday set. Missing keys read as false."] = "map[K]bool je každodenní množina. Chybějící klíče se čtou jako false.",
  ["map[string]bool as a set: one O(1) lookup per guest, O(n) total. Fifty million checks become ten thousand."] = "map[string]bool jako množina: jedno vyhledání O(1) na hosta, celkem O(n). Z padesáti milionů kontrol je deset tisíc.",
  ["map[string]int. make(map[string]int) if you start empty."] = "map[string]int. make(map[string]int), když začínáš prázdný.",
  ["map[string]int: hash, bucket, compare. O(1) average, O(n) worst when everything collides. Python's dict, Rust's HashMap."] = "map[string]int: hash, bucket, porovnání. O(1) v průměru, O(n) v nejhorším, když všechno koliduje. dict z Pythonu, HashMap z Rustu.",
  ["maps.Keys and maps.Values return iter.Seq, so range works on them directly."] = "maps.Keys a maps.Values vracejí iter.Seq, takže range na nich funguje přímo.",
  ['match a.binary_search(&x) {     // ___\n    Ok(i) => println!("at {i}"),\n    Err(i) => println!("insert at {i}"),\n}\n'] = 'match a.binary_search(&x) {     // ___\n    Ok(i) => println!("at {i}"),\n    Err(i) => println!("insert at {i}"),\n}\n',
  ["match code { 1 => ..., _ => ... } Each arm is pattern => value. The compiler checks every case is covered."] = "match code { 1 => ..., _ => ... } Každá větev je vzor => hodnota. Kompilátor kontroluje, že je pokrytý každý případ.",
  ["matches!(v, Pat) expands to match v { Pat => true, _ => false }. Guards allowed: Some(n) if n > 3."] = "matches!(v, Pat) se rozvine na match v { Pat => true, _ => false }. Guardy jsou povolené: Some(n) if n > 3.",
  ["max := prices[0]\nfor _, p := range prices[1:] {   // ___ comparisons\n    if p > max {\n        max = p\n    }\n}\n"] = "max := prices[0]\nfor _, p := range prices[1:] {   // ___ porovnání\n    if p > max {\n        max = p\n    }\n}\n",
  ["memo = {}\ndef fib(n):\n    if n in ___:\n        return memo[n]\n    v = n if n < 2 else fib(n - 1) + fib(n - 2)\n    memo[n] = v\n    return v\n"] = "memo = {}\ndef fib(n):\n    if n in ___:\n        return memo[n]\n    v = n if n < 2 else fib(n - 1) + fib(n - 2)\n    memo[n] = v\n    return v\n",
  ["memo.get(&n) is O(1). Hit: return it. Miss: compute it. That is memoization."] = "memo.get(&n) je O(1). Trefa: vrať to. Vedle: spočítej to. To je memoizace.",
  ["memo.get(&n) is O(1). Hit: return. Miss: compute and insert. Go spells this the comma-ok test; Python @functools.cache."] = "memo.get(&n) je O(1). Zásah: vrať. Minutí: spočítej a insert. Go to píše testem comma-ok; Python @functools.cache.",
  ['menu = ___\nmenu["tea"] = 12\nmenu["noodles"] = 38\nprint(menu["tea"])     # 12\n'] = 'menu = ___\nmenu["tea"] = 12\nmenu["noodles"] = 38\nprint(menu["tea"])     # 12\n',
  ['menu = ___(tea=12, noodles=38)\nprice = menu["tea"]    # hash the key, jump to the slot\n'] = 'menu = ___(tea=12, noodles=38)\nprice = menu["tea"]    # zahashuj klíč, skoč na slot\n',
  ["menu = {\"tea\": 12, \"noodles\": 38}\ndishes = list(menu.___())\nprint(dishes)     # ['tea', 'noodles']\n"] = "menu = {\"tea\": 12, \"noodles\": 38}\ndishes = list(menu.___())\nprint(dishes)     # ['tea', 'noodles']\n",
  ['menu = {"tea": 12, "noodles": 38}\nprint(menu.___("congee", 0))   # 0, no KeyError\n'] = 'menu = {"tea": 12, "noodles": 38}\nprint(menu.___("congee", 0))   # 0, žádný KeyError\n',
  ["menu = {\"tea\": 12, \"toast\": 18}\n___ menu[\"toast\"]\nprint(menu)     # {'tea': 12}\n"] = "menu = {\"tea\": 12, \"toast\": 18}\n___ menu[\"toast\"]\nprint(menu)     # {'tea': 12}\n",
  ['menu: ___[str, float] = {"tea": 12.0}\n'] = 'menu: ___[str, float] = {"tea": 12.0}\n',
  ["min, max and clear joined len, cap, append in Go 1.21."] = "min, max a clear se v Go 1.21 přidaly k len, cap, append.",
  ["module github.com/alex/luckymac\n\ngo 1.23\n\n___ v1.0.1 // wrong price for the tea set\n"] = "module github.com/alex/luckymac\n\ngo 1.23\n\n___ v1.0.1 // špatná cena za tea set\n",
  ["module github.com/alex/luckymac\n\ngo ___\n"] = "module github.com/alex/luckymac\n\ngo ___\n",
  ['module github.com/alex/luckymac/___\n\n// callers: import "github.com/alex/luckymac/___/menu"\n'] = 'module github.com/alex/luckymac/___\n\n// volající: import "github.com/alex/luckymac/___/menu"\n',
  ["module github.com/siuming/cousinshop\n\ngo 1.23\n\n___ github.com/alex/luckymac v1.2.0\n"] = "module github.com/siuming/cousinshop\n\ngo 1.23\n\n___ github.com/alex/luckymac v1.2.0\n",
  ["module, go, require. go.sum next to it holds the checksums."] = "module, go, require. go.sum vedle něj drží kontrolní součty.",
  ["most_common uses heapq.nlargest inside when k is given. Count in O(n), pick in O(n log k). Round four to Bo."] = "most_common uvnitř používá heapq.nlargest, když je zadáno k. Spočítej v O(n), vyber v O(n log k). Čtvrté kolo pro Boa.",
  ["move || captures by value. Without it the closure would borrow order, and a borrow cannot be proven to outlive the thread."] = "move || zachytává hodnotou. Bez něj by si closure order půjčila a o výpůjčce nelze dokázat, že přežije vlákno.",
  ["mp.Process is a whole python interpreter of its own. It costs milliseconds to start, not microseconds: give it work worth the trip."] = "mp.Process je celý vlastní interpret pythonu. Spuštění stojí milisekundy, ne mikrosekundy: dej mu práci, která tu cestu vyváží.",
  ["mp.Queue is safe for many producers and many consumers. It must be created in the parent and passed in as an argument, never made inside the child."] = "mp.Queue je bezpečná pro mnoho producentů i konzumentů. Musí vzniknout v rodiči a předat se jako argument, nikdy se nevyrábí uvnitř potomka.",
  ["mp.Value('i', 0) is four bytes of shared memory with a type code. The object is shared; the number inside it is what you touch."] = "mp.Value('i', 0) jsou čtyři bajty sdílené paměti s kódem typu. Sdílený je ten objekt; ty saháš na číslo uvnitř.",
  ["mp.cpu_count() is Go's runtime.NumCPU(). It counts logical cores, so on a laptop with hyper-threading it is twice the physical ones."] = "mp.cpu_count() je runtime.NumCPU() po způsobu Go. Počítá logická jádra, takže na notebooku s hyper-threadingem je to dvojnásobek fyzických.",
  ["mpsc: multi-producer, single-consumer. Job is Send so it may cross to another thread; FnOnce because each ticket runs once."] = "mpsc: multi-producer, single-consumer. Job je Send, takže může přejít do jiného vlákna; FnOnce, protože každý lístek běží jednou.",
  ["mpsc::channel gives a Sender and a Receiver. Clone the Sender for many producers; the loop ends when all are dropped."] = "mpsc::channel dá Sender a Receiver. Sender klonuj pro více producentů; cyklus skončí, když jsou všichni zahozeni.",
  ["mpsc::channel() returns (Sender<T>, Receiver<T>). mpsc: multi-producer, single-consumer. The pipe is unbounded."] = "mpsc::channel() vrací (Sender<T>, Receiver<T>). mpsc: multi-producer, single-consumer. Trubka je neomezená.",
  ["mu.Lock()\ndefer mu.___()          // even on panic\ncount++\n"] = "mu.Lock()\ndefer mu.___()          // i při panic\ncount++\n",
  ['mu.Lock()\nmenu["set"] = 42\nmu.Unlock()\n\nmu.___()\n'] = 'mu.Lock()\nmenu["set"] = 42\nmu.Unlock()\n\nmu.___()\n',
  ["multiprocessing copies the threading API onto processes, so the code looks the same and the cores actually fill up."] = "multiprocessing překlopí API z threading na procesy, takže kód vypadá stejně a jádra se opravdu zaplní.",
  ["multiprocessing.Process(target=f, args=(x,)) is threading's API on a real process: start() forks or spawns it, join() waits, exitcode says how it went and daemon=True lets it die with the parent. Under the spawn start method the child imports your file again, so everything that runs must sit behind if __name__ == '__main__'."] = "multiprocessing.Process(target=f, args=(x,)) je API z threading nad skutečným procesem: start() ho spustí přes fork nebo spawn, join() počká, exitcode řekne, jak dopadl, a daemon=True ho nechá zemřít s rodičem. Při metodě spawn si potomek tvůj soubor znovu naimportuje, takže všechno, co se spouští, musí být za if __name__ == '__main__'.",
  ["mypy runs no code; it reads the hints. Go and Rust do this in the compiler; Python does it on request. The labels print right."] = "mypy nespouští žádný kód; čte nápovědy. Go a Rust to dělají v kompilátoru; Python na vyžádání. Štítky se tisknou správně.",
  ["n := 7\nhalf := ___(n) / 2      // 3.5, not 3\n"] = "n := 7\nhalf := ___(n) / 2      // 3.5, ne 3\n",
  ["n := runtime.___()\nfor i := 0; i < n; i++ {\n    go worker(jobs, done)\n}\n"] = "n := runtime.___()\nfor i := 0; i < n; i++ {\n    go worker(jobs, done)\n}\n",
  ['n = 4\nprint(___"tables open: {n}")\n'] = 'n = 4\nprint(___"tables open: {n}")\n',
  ["n doubles from 1000 to 2000 items. An O(1) operation takes how long compared to before, in one word?"] = "n se zdvojnásobí z 1000 na 2000 položek. Jak dlouho trvá operace O(1) ve srovnání s dřívějškem, jedním slovem?",
  ["n in memo is O(1). Hit: return it. Miss: compute, store, return. That is memoization, spelled out."] = "n in memo je O(1). Zásah: vrať ho. Minutí: spočítej, ulož, vrať. To je memoizace, rozepsaná.",
  ["n is an int. Divide it as a floating point number. Fill: half := ___(n) / 2"] = "n je int. Vyděl ho jako číslo s plovoucí čárkou. Doplň: half := ___(n) / 2",
  ["n pushes and pops on a heap of k: O(n log k) time, O(k) space. Sorting would be O(n log n) and O(n)."] = "n pushů a popů na haldě velikosti k: O(n log k) času, O(k) paměti. Řazení by bylo O(n log n) a O(n).",
  ["n times the logarithm of n. No comparison sort can beat it in the worst case."] = "n krát logaritmus n. Žádné porovnávací třídění ho v nejhorším případě nepřekoná.",
  ["n+1 distinct inputs, each solved once. Linear, without the O( )."] = "n+1 různých vstupů, každý vyřešen jednou. Lineární, bez O( ).",
  ['n, ___ := prices["hashbrown"]\nif !___ {\n    // missing\n}\n'] = 'n, ___ := prices["hashbrown"]\nif !___ {\n    // chybí\n}\n',
  ["n-1 comparisons, which is O(n): you cannot know the max without seeing every value. The diagonal is drawn."] = "n-1 porovnání, což je O(n): maximum nemůžeš znát, aniž bys viděl každou hodnotu. Diagonála je nakreslená.",
  ["n-1 comparisons, which is O(n): you cannot know the max without seeing every value. iter().max() does exactly this."] = "n-1 porovnání, což je O(n): maximum nemůžeš znát, aniž bys viděl každou hodnotu. iter().max() dělá přesně toto.",
  ["n-1 comparisons, which is O(n): you cannot know the max without seeing every value. max() does exactly this."] = "n-1 porovnání, což je O(n): maximum nemůžeš znát, aniž bys viděl každou hodnotu. max() dělá přesně toto.",
  ['name = ___("Order for: ")\nprint(f"one bowl for {name}")\n'] = 'name = ___("Order for: ")\nprint(f"one bowl for {name}")\n',
  ['names := []string{"Wing", "Bo", "Mei"}\nsort.___(names)          // O(n log n)\nfmt.Println(names)       // [Bo Mei Wing]\n'] = 'names := []string{"Wing", "Bo", "Mei"}\nsort.___(names)          // O(n log n)\nfmt.Println(names)       // [Bo Mei Wing]\n',
  ['names = ["Mei", "Alex", "Mei", "Ken"]\nunique = ___(names)\nprint(len(unique))     # 3\n'] = 'names = ["Mei", "Alex", "Mei", "Ken"]\nunique = ___(names)\nprint(len(unique))     # 3\n',
  ['names = ["egg", "tea"]\nqtys = [2, 1]\nfor name, qty in ___(names, qtys):\n    print(qty, "x", name)\n'] = 'names = ["egg", "tea"]\nqtys = [2, 1]\nfor name, qty in ___(names, qtys):\n    print(qty, "x", name)\n',
  ['names = ["noodles", "tea", "toast"]\nshort_first = ___(names, key=len)    # O(n log n)\n'] = 'names = ["noodles", "tea", "toast"]\nshort_first = ___(names, key=len)    # O(n log n)\n',
  ["net/http: handlers and a server"] = "net/http: handlery a server",
  ["next() on an exhausted generator raises which exception?"] = "next() na vyčerpaném generátoru vyhodí kterou výjimku?",
  ["next(gen) runs to the next yield. next(gen, None) returns None at the end instead of raising."] = "next(gen) doběhne k dalšímu yield. next(gen, None) vrátí na konci None místo výjimky.",
  ["nil check first, then recurse. insert returns the (possibly new) subtree root."] = "Nejdřív kontrola nil, pak rekurze. insert vrací (možná nový) kořen podstromu.",
  ["nlargest(n, xs, key=...) is O(n log k) and takes a key. sorted(xs)[-3:] would be O(n log n)."] = "nlargest(n, xs, key=...) je O(n log k) a bere key. sorted(xs)[-3:] by bylo O(n log n).",
  ["not st first: pop on an empty list raises IndexError. Then compare with the opener the dict expects."] = "not st nejdřív: pop na prázdném seznamu vyhodí IndexError. Pak porovnej s otvírací závorkou, kterou dict očekává.",
  ['note = ___          # nothing yet\nif not note:\n    print("no note")\n'] = 'note = ___          # zatím nic\nif not note:\n    print("no note")\n',
  ['o := Order{Item: "set", Price: 25}\nfmt.Printf("___\\n", o)    // {Item:set Price:25}\n'] = 'o := Order{Item: "set", Price: 25}\nfmt.Printf("___\\n", o)    // {Item:set Price:25}\n',
  ["o.label() passes o as self automatically. Forgetting self is the most common TypeError in a beginner's class."] = "o.label() předá o jako self automaticky. Zapomenout self je nejčastější TypeError ve třídě začátečníka.",
  ["ok is false only when the channel is closed and drained. It says nothing about the value: that one is always the zero value."] = "ok je false jen tehdy, když je kanál zavřený a vyprázdněný. O hodnotě to neříká nic: ta je vždycky nulová.",
  ["ok, an underscore, then the word you use to offer an alternative."] = "ok, podtržítko, pak slovo, kterým nabízíš alternativu.",
  ["ok_or(err) maps Some(v) to Ok(v) and None to Err(err). Now ? works on it too."] = "ok_or(err) mapuje Some(v) na Ok(v) a None na Err(err). Teď na něm funguje i ?.",
  ['omit + empty, one word, after the comma. json:"-" hides a field entirely.'] = 'omit + empty, jedno slovo, za čárkou. json:"-" pole skryje úplně.',
  ['omitempty drops zero values. "-" drops the field always.'] = 'omitempty vynechá nulové hodnoty. "-" vynechá pole vždy.',
  ["once.Do(f) runs f the first time and blocks the rest until it returns, so nobody sees a half-loaded menu."] = "once.Do(f) spustí f poprvé a ostatní zadrží, dokud se nevrátí, takže nikdo neuvidí menu načtené jen napůl.",
  ["or, underscore, insert. Takes the starting value and returns &mut u32, which the * dereferences."] = "or, podtržítko, insert. Bere počáteční hodnotu a vrací &mut u32, který * dereferencuje.",
  ["or_ plus the word for Default::default(). An empty Vec is the default Vec."] = "or_ a k tomu anglické slovo pro Default::default(). Prázdný Vec je ten výchozí.",
  ["or_insert returns &mut usize, so the * dereferences and += 1 bumps it in place. O(n) to count."] = "or_insert vrací &mut usize, takže * dereferencuje a += 1 zvýší hodnotu na místě. Počítání je O(n).",
  ['order = ["noodles", "egg", "tea"]\nif "egg" ___ order:\n    print("fry one")\n'] = 'order = ["noodles", "egg", "tea"]\nif "egg" ___ order:\n    print("fry one")\n',
  ["order('noodles', spicy=True, egg=2): how is the parameter written to collect any keyword options?"] = "order('noodles', spicy=True, egg=2): jak se zapíše parametr, aby posbíral libovolné pojmenované volby?",
  ["order.total should read like an attribute but be computed. Which built-in decorator?"] = "order.total se má číst jako atribut, ale počítat se. Který vestavěný dekorátor?",
  ["ordered = sorted(amounts)    # ___ : Timsort\n"] = "ordered = sorted(amounts)    # ___ : Timsort\n",
  ["orders = [(\"tea\", 12), (\"noodles\", 38), (\"egg\", 6)]\ncheap = sorted(orders, key=___ o: o[1])\nprint(cheap[0])     # ('egg', 6)\n"] = "orders = [(\"tea\", 12), (\"noodles\", 38), (\"egg\", 6)]\ncheap = sorted(orders, key=___ o: o[1])\nprint(cheap[0])     # ('egg', 6)\n",
  ["orders = ___\nselect {\ncase o := <-orders:\n    cook(o)\ncase <-quit:\n    return\n}\n"] = "orders = ___\nselect {\ncase o := <-orders:\n    cook(o)\ncase <-quit:\n    return\n}\n",
  ["orders.push(18). pop() takes the last one back. The Vec reallocates when it runs out of room."] = "orders.push(18). pop() vezme poslední zpět. Vec se realokuje, když mu dojde místo.",
  ['orders: ___[str] = []\norders.append("noodles")\n'] = 'orders: ___[str] = []\norders.append("noodles")\n',
  ["out := [][]int{iv[0]}\nfor _, cur := range iv[1:] {\n    last := out[len(out)-1]\n    if cur[0] <= last[___] {    // they touch or overlap\n"] = "out := [][]int{iv[0]}\nfor _, cur := range iv[1:] {\n    last := out[len(out)-1]\n    if cur[0] <= last[___] {    // dotyk nebo překryv\n",
  ["out := make([]Dish, len(orders))\nfor i := range orders {\n    go func() {\n        out[___] = cook(orders[i])\n    }()\n}\n"] = "out := make([]Dish, len(orders))\nfor i := range orders {\n    go func() {\n        out[___] = cook(orders[i])\n    }()\n}\n",
  ["out = [[9, 12], [13, 15], [16, 18]]\n# the free slots between blocks: (12, 13), (15, 16)\nfree = [(a[1], b[0]) for a, b in zip(out, out[___])]\n"] = "out = [[9, 12], [13, 15], [16, 18]]\n# volná místa mezi bloky: (12, 13), (15, 16)\nfree = [(a[1], b[0]) for a, b in zip(out, out[___])]\n",
  ["out[-1] is the last merged block, [1] its end. The sort guarantees s is never before the block's start."] = "out[-1] je poslední sloučený blok, [1] jeho konec. Řazení zaručuje, že s nikdy není před začátkem bloku.",
  ['p := ___Order{Item: "set"}   // p is *Order\np.Price = 25                  // Go dereferences for you\n'] = 'p := ___Order{Item: "set"}   // p je *Order\np.Price = 25                  // Go dereferencuje za tebe\n',
  ["p = mp.Process(target=tail_log)\np.___ = True\np.start()\n"] = "p = mp.Process(target=tail_log)\np.___ = True\np.start()\n",
  ['p.join()\nif p.___ != 0:\n    print("the night batch died")\n'] = 'p.join()\nif p.___ != 0:\n    print("noční dávka umřela")\n',
  ['p.start()\np.___()\nprint("child finished")\n'] = 'p.start()\np.___()\nprint("child finished")\n',
  ['package main\n___ (\n    "fmt"\n    "os"\n)\n'] = 'package main\n___ (\n    "fmt"\n    "os"\n)\n',
  ["package main\n___ opens = 6          // Lucky Mac hour, never changes\n"] = "package main\n___ opens = 6          // hodina Lucky Mac, nikdy se nemění\n",
  ['package main\n___ shop string = "Lucky Mac"   // package level: no :=\nfunc main() {\n    fmt.Println(shop)\n}\n'] = 'package main\n___ shop string = "Lucky Mac"   // úroveň balíčku: žádné :=\nfunc main() {\n    fmt.Println(shop)\n}\n',
  ["package main\nfunc main() {\n    floor ___ 8      // type inferred as int\n}\n"] = "package main\nfunc main() {\n    floor ___ 8      // typ odvozen jako int\n}\n",
  ['package main\nimport "___"\nfunc main() {\n    Println("hash brown")\n}\n'] = 'package main\nimport "___"\nfunc main() {\n    Println("hash brown")\n}\n',
  ['package main\nimport "fmt"\nfunc main() {\n    fmt.___("morning set")   // capital P: exported\n}\n'] = 'package main\nimport "fmt"\nfunc main() {\n    fmt.___("morning set")   // velké P: exportované\n}\n',
  ['package main\nvar menu map[string]int\nfunc ___() {                // before main\n    menu = map[string]int{"muffin": 18}\n}\nfunc main() {}\n'] = 'package main\nvar menu map[string]int\nfunc ___() {                // před main\n    menu = map[string]int{"muffin": 18}\n}\nfunc main() {}\n',
  ["package main is the entry. Other folders are libraries."] = "package main je vstupní bod. Ostatní složky jsou knihovny.",
  ["package main plus func main is a program; anything else is a library. Nobody can import a main package, so keep it thin and put the logic in a package others can test."] = "package main plus func main je program; cokoli jiného je knihovna. Balíček main nikdo nemůže importovat, tak ho drž tenký a logiku dej do balíčku, který můžou ostatní testovat.",
  ["package menu_test can only use the exported API, so the tests prove what callers can do. Plain package menu tests reach the unexported parts."] = "package menu_test může používat jen exportované API, takže testy dokazují, co volající dokážou. Testy v prostém package menu dosáhnou i na neexportované části.",
  ["pairs := map[rune]rune{\n    ')': ___,           // closer -> opener\n    ']': '[',\n    '}': '{',\n}\n"] = "pairs := map[rune]rune{\n    ')': ___,           // zavírací -> otevírací\n    ']': '[',\n    '}': '{',\n}\n",
  ["panic stops the goroutine. recover() inside defer can save it. Rare in libraries."] = "panic zastaví goroutine. recover() uvnitř defer ji může zachránit. V knihovnách vzácné.",
  ["panic unwinds the stack running every defer. recover in a defer can stop it."] = "panic odvine zásobník a spustí každý defer. recover v deferu ho může zastavit.",
  ["parent_conn, child_conn = mp.___()\nmp.Process(target=cook, args=(child_conn,)).start()\nprint(parent_conn.recv())\n"] = "parent_conn, child_conn = mp.___()\nmp.Process(target=cook, args=(child_conn,)).start()\nprint(parent_conn.recv())\n",
  ["parse::<i32>() names the generic explicitly. Same trick: collect::<Vec<_>>(). 12 x 18 = 216."] = "parse::<i32>() pojmenuje generikum výslovně. Stejný trik: collect::<Vec<_>>(). 12 x 18 = 216.",
  ["pkg.go.dev shows the first sentence of the package comment. Start it properly."] = "pkg.go.dev ukazuje první větu komentáře balíčku. Začni ji správně.",
  ["plate only receives. Fill the parameter type: in ___ string"] = "plate jen přijímá. Doplň typ parametru: in ___ string",
  ["pool.map blocks until the last worker is done and returns a list in order. The function and its arguments have to be picklable, so no lambdas."] = "pool.map blokuje, dokud neskončí poslední worker, a vrátí seznam v pořadí. Funkce i její argumenty musí být picklable, takže žádné lambdy.",
  ["pool.map keeps order; pool.submit returns a Future. ProcessPoolExecutor is the same API on processes, past the GIL."] = "pool.map zachová pořadí; pool.submit vrací Future. ProcessPoolExecutor je stejné API nad procesy, mimo GIL.",
  ["pool.map(scan, [(shm.___, i) for i in parts])\n\n# inside the worker:\n# SharedMemory(key) attaches here\n"] = "pool.map(scan, [(shm.___, i) for i in parts])\n\n# uvnitř workera:\n# SharedMemory(key) se připojí tady\n",
  ["pop pops both stacks, so the smallest is always on top of low. O(1) push, pop and get, O(n) space."] = "pop popne oba zásobníky, takže minimum je vždy na vrcholu low. push, pop i get v O(1), O(n) paměti.",
  ["pop returns an Option. Which arm holds a value?"] = "pop vrací Option. Která varianta drží hodnotu?",
  ["pop the first node. We only have &mut head, so move the node out and leave None behind. Which Option method?"] = "Vyndej první uzel. Máme jen &mut head, takže uzel přesuň ven a nech za sebou None. Která metoda Option?",
  ["pop, but from the left end, one word. list.pop(0) would be O(n)."] = "pop, ale z levého konce, jedním slovem. list.pop(0) by bylo O(n).",
  ["pop, underscore, the end that is not back. The while let ends when it returns None."] = "pop, podtržítko, a ten konec, který není back. while let skončí, až to vrátí None.",
  ["pop, underscore, the stale end. The mirror of the last blank."] = "pop, podtržítko, starý konec. Zrcadlo minulého doplnění.",
  ["pop_front is BFS, pop is DFS: the only difference is which end. Both O(V + E). Combo x3."] = "pop_front je BFS, pop je DFS: jediný rozdíl je, který konec. Obojí O(V + E). Kombo x3.",
  ["pop_front is O(1). Stations come out in rings: one hop, two hops, three. That is BFS."] = "pop_front je O(1). Stanice vycházejí v prstencích: jeden skok, dva skoky, tři. To je BFS.",
  ["price = 18.5\nprint(___(price))    # <class 'float'>\n"] = "price = 18.5\nprint(___(price))    # <class 'float'>\n",
  ['prices := ___{\n    "muffin": 18,\n}\n'] = 'prices := ___{\n    "muffin": 18,\n}\n',
  ["prices = [38, 6, 12]\ncheap = ___(prices)\nprint(cheap, prices)   # [6, 12, 38] [38, 6, 12]\n"] = "prices = [38, 6, 12]\ncheap = ___(prices)\nprint(cheap, prices)   # [6, 12, 38] [38, 6, 12]\n",
  ["prices = [6, 12, 38]\ndoubled = [p * 2 ___ p in prices]\nprint(doubled)     # [12, 24, 76]\n"] = "prices = [6, 12, 38]\ndoubled = [p * 2 ___ p in prices]\nprint(doubled)     # [12, 24, 76]\n",
  ["prices.len() is 3. is_empty() is the idiomatic way to ask for zero. The board counts to twelve."] = "prices.len() je 3. is_empty() je idiomatický způsob, jak se zeptat na nulu. Tabule počítá do dvanácti.",
  ["print writes a line. # starts a comment. f-strings put values in text. import brings a module in."] = "print vypíše řádek. # začíná komentář. f-stringy vkládají hodnoty do textu. import přináší modul.",
  ["print() is a built-in: no import, no package. Python 3 needs the parentheses. The pass screen lights up."] = "print() je vestavěná: žádný import, žádný balíček. Python 3 potřebuje závorky. Obrazovka u výdeje se rozsvítí.",
  ["print(o) shows <Order object at 0x...>. Which special method gives it a readable form?"] = "print(o) ukáže <Order object at 0x...>. Která speciální metoda mu dá čitelnou podobu?",
  ["printer.acquire()\ntry:\n    print_label(order)\nfinally:\n    printer.___()\n"] = "printer.acquire()\ntry:\n    print_label(order)\nfinally:\n    printer.___()\n",
  ["println is a macro, not a function. Which character ends its name?"] = "println je makro, ne funkce. Kterým znakem končí jeho jméno?",
  ["push adds one char. This one adds a whole str. Two words, underscore."] = "push přidá jeden char. Tahle přidá celý str. Dvě slova, podtržítko.",
  ["push, underscore, the end that is not the front."] = "push, podtržítko, ten konec, který není front.",
  ["push_str borrows the &str and copies it in. to_uppercase() makes a new String."] = "push_str si půjčí &str a zkopíruje ho dovnitř. to_uppercase() vytvoří nový String.",
  ["put blocks only when maxsize is reached. put_nowait raises queue.Full instead."] = "put blokuje jen při dosažení maxsize. put_nowait místo toho vyhodí queue.Full.",
  ["put made the cache one too big. Remove the oldest pair, at the front. Which method, with last=False?"] = "put udělal cache o jednu větší. Odeber nejstarší dvojici, na začátku. Která metoda, s last=False?",
  ["put on a new key when the cache is full: the stale end goes first. Which VecDeque method removes the front as Option?"] = "put nového klíče, když je cache plná: starý konec jde první. Která metoda VecDeque odebere předek jako Option?",
  ["q.get() blocks like <-ch in Go. get_nowait() raises queue.Empty instead, which is the select default case."] = "q.get() blokuje jako <-ch v Go. get_nowait() místo toho vyhodí queue.Empty, což odpovídá větvi default u selectu.",
  ['q.put(Order(7, "set"))\nq.put(open("menu.txt"))\n# TypeError: the file object is not ___\n'] = 'q.put(Order(7, "set"))\nq.put(open("menu.txt"))\n# TypeError: objekt souboru není ___\n',
  ["queue.Queue is thread-safe: put adds a job, get takes one, task_done marks it finished, join waits until every job is done."] = "queue.Queue je bezpečná pro vlákna: put přidá úlohu, get jednu vezme, task_done ji označí hotovou, join čeká, dokud není hotová každá úloha.",
  ["queue.Queue locks every operation. Queue(maxsize=3) blocks put when full: a buffered channel."] = "queue.Queue zamyká každou operaci. Queue(maxsize=3) blokuje put, když je plná: bufferovaný kanál.",
  ["queue[0] then queue[1:] is the Go queue. For big queues use a ring or container/list."] = "queue[0] a pak queue[1:] je fronta v Go. Pro velké fronty použij ring nebo container/list.",
  ["r - l + 1 is the window's width. Grow on the right, shrink on the left: O(n) with at most 256 bytes in the set."] = "r - l + 1 je šířka okna. Roste vpravo, zmenšuje se vlevo: O(n) s nejvýše 256 bajty v množině.",
  ["r must be allowed to change a. Which two-part borrow gives write access?"] = "r musí smět měnit a. Která dvoudílná výpůjčka dává přístup pro zápis?",
  ["raise ValueError(...) throws an instance. A bare raise inside except re-throws the current one."] = "raise ValueError(...) vyhodí instanci. Holé raise uvnitř except znovu vyhodí tu aktuální.",
  ["range 3 counts 0..2. Since 1.22 each iteration also gets its own i."] = "range 3 počítá 0..2. Od 1.22 dostane každá iterace také vlastní i.",
  ["range decodes UTF-8 for you: byte index plus rune. string(r) turns it back."] = "range dekóduje UTF-8 za tebe: bajtový index plus runa. string(r) ji převede zpět.",
  ["range over a channel ends when the sender calls close. Without close it blocks forever."] = "range přes kanál končí, když odesílatel zavolá close. Bez close blokuje navždy.",
  ["range over a channel. Note the directional channel types in the signature."] = "range přes channel. Všimni si směrových typů channelů v signatuře.",
  ["range over a string gives runes. Print each one as text: fill ___(r)"] = "range přes string dává runy. Vypiš každou jako text: doplň ___(r)",
  ["range over an int, min and max, slices and maps packages, iter.Seq for range."] = "range přes int, min a max, balíčky slices a maps, iter.Seq pro range.",
  ["range(3) yields 0, 1, 2. range(1, 4) starts at 1; range(0, 10, 2) steps by two. It is lazy: nothing is built."] = "range(3) dává 0, 1, 2. range(1, 4) začíná od 1; range(0, 10, 2) jde po dvou. Je lenivý: nic se nestaví.",
  ['raw = "12"\nqty = ___(raw)\nprint(qty + 1)     # 13, not "121"\n'] = 'raw = "12"\nqty = ___(raw)\nprint(qty + 1)     # 13, ne "121"\n',
  ["ready := make(chan struct{})\ngo func() {\n    menu = loadMenu()\n    ___(ready)\n}()\n<-ready\nuse(menu)\n"] = "ready := make(chan struct{})\ngo func() {\n    menu = loadMenu()\n    ___(ready)\n}()\n<-ready\nuse(menu)\n",
  ["recv blocks with no busy loop. Not while let: its temporaries live for the whole body and would hold the lock during job()."] = "recv blokuje bez aktivního čekání. Ne while let: jeho dočasné hodnoty žijí celé tělo a držely by zámek během job().",
  ["replace applies only in the main module: the cousin's users never see it. Keep the require line, and take the replace out before you commit."] = "replace platí jen v hlavním modulu: bratrancovi uživatelé ho nikdy neuvidí. Řádek require nech a replace před commitem vyndej.",
  ["replace, go.work, vendor"] = "replace, go.work, vendor",
  ["require (\n    github.com/alex/luckymac v1.2.0\n    github.com/goccy/go-json v0.10.3 // ___\n)\n"] = "require (\n    github.com/alex/luckymac v1.2.0\n    github.com/goccy/go-json v0.10.3 // ___\n)\n",
  ["require github.com/alex/luckymac v1.2.0\n\n___ github.com/alex/luckymac => ../luckymac\n"] = "require github.com/alex/luckymac v1.2.0\n\n___ github.com/alex/luckymac => ../luckymac\n",
  ["require is a minimum, not an exact pin: if another dependency needs v1.3.0, the build uses v1.3.0. Minimal version selection, no lock file solver."] = "require je minimum, ne přesné připíchnutí: když jiná závislost potřebuje v1.3.0, build použije v1.3.0. Výběr minimální verze, žádný řešitel lock souboru.",
  ["reqwest::get(url).await?.text().await? - two awaits, two places it can fail. Riders roll out."] = "reqwest::get(url).await?.text().await? - dva awaity, dvě místa, kde to může selhat. Kurýři vyjíždějí.",
  ["res := make(chan Menu, 1)\n___ func() { res <- fetchMenu() }()\nprintReceipt()\n"] = "res := make(chan Menu, 1)\n___ func() { res <- fetchMenu() }()\nprintReceipt()\n",
  ["res := make(chan Menu, 1)\ngo func() { res <- fetchMenu() }()\nprintReceipt()\nm := ___\n"] = "res := make(chan Menu, 1)\ngo func() { res <- fetchMenu() }()\nprintReceipt()\nm := ___\n",
  ["res := make(chan Menu, ___)\ngo func() { res <- fetchMenu() }()\nselect {\ncase m := <-res:\n    use(m)\ncase <-ctx.Done():\n}\n"] = "res := make(chan Menu, ___)\ngo func() { res <- fetchMenu() }()\nselect {\ncase m := <-res:\n    use(m)\ncase <-ctx.Done():\n}\n",
  ["result() is await, and it re-raises the worker's exception in your process with the child's traceback attached."] = "result() je await a výjimku z workera vyhodí znovu ve tvém procesu i s traceem z potomka.",
  ["return 0; exits at once. The tail expression n * 18 - 5 handles every other case."] = "return 0; skončí okamžitě. Koncový výraz n * 18 - 5 obslouží každý další případ.",
  ["return s. A function that falls off the end returns None. return a, b hands back a tuple."] = "return s. Funkce, která doběhne na konec, vrací None. return a, b vrací tuple.",
  ["return sends every result at once. The bool and the error travel together."] = "return pošle všechny výsledky najednou. bool a error cestují spolu.",
  ["return wrapper, not wrapper(). The caller gets the wrapper and calls it later; *args, **kwargs pass anything through."] = "return wrapper, ne wrapper(). Volající dostane obal a zavolá ho později; *args, **kwargs propustí cokoli.",
  ["rune is one code point. 'x' literals are runes, \"x\" literals are strings."] = "rune je jeden kódový bod. Literály 'x' jsou runy, literály \"x\" jsou řetězce.",
  ["runtime.NumCPU() is the usual pool size for CPU-bound work. For I/O-bound work the right number is higher and only a benchmark knows it."] = "runtime.NumCPU() je obvyklá velikost fondu pro práci vázanou na procesor. U práce vázané na I/O je správné číslo vyšší a ví ho jen benchmark.",
  ["rx.recv() blocks until a value arrives; Err when every Sender is gone. Order 7 hits the pass."] = "rx.recv() blokuje, dokud nedorazí hodnota; Err, když je každý Sender pryč. Objednávka 7 dorazí na výdej.",
  ['s := "灣"\nfmt.Println(len(s))     // prints ___\n'] = 's := "灣"\nfmt.Println(len(s))     // vypíše ___\n',
  ["s := ___{1, 2, 3}     // slice, length 3\n"] = "s := ___{1, 2, 3}     // slice, délka 3\n",
  ["s[1:3] is a slice of a slice. Changing two[0] changes tray[1] too."] = "s[1:3] je slice ze slice. Změna two[0] změní i tray[1].",
  ["seats as f64. i32 / f64 does not compile in Rust; as makes the intent explicit."] = "seats as f64. i32 / f64 se v Rustu nezkompiluje; as dělá záměr výslovným.",
  ["seats is an i32 but the division needs a float. Which keyword converts it?"] = "seats je i32, ale dělení potřebuje float. Které klíčové slovo ho převede?",
  ["seen := map[int]int{}          // value -> index\nfor i, x := range nums {\n    if j, ok := seen[target-___]; ok {\n        return []int{j, i}\n    }\n    seen[x] = i\n}\n"] = "seen := map[int]int{}          // hodnota -> index\nfor i, x := range nums {\n    if j, ok := seen[target-___]; ok {\n        return []int{j, i}\n    }\n    seen[x] = i\n}\n",
  ["seen := map[string]___{}\nfor _, g := range guests {        // one pass: O(n)\n    if seen[g] { dup = true }\n    seen[g] = true\n}\n"] = "seen := map[string]___{}\nfor _, g := range guests {        // jeden průchod: O(n)\n    if seen[g] { dup = true }\n    seen[g] = true\n}\n",
  ["seen = ___()\nfor g in guests:            # one pass: O(n)\n    if g in seen:\n        dup = True\n    seen.add(g)\n"] = "seen = ___()\nfor g in guests:            # jeden průchod: O(n)\n    if g in seen:\n        dup = True\n    seen.add(g)\n",
  ["seen.insert(m) is one lookup for check and mark. Without it, a loop in the map queues forever."] = "seen.insert(m) je jedno vyhledání pro kontrolu i označení. Bez toho by cyklus v mapě zařazoval donekonečna.",
  ["seen[x] = i maps value to position. Returning (seen[target - x], i) gives the pair of indexes the question wants."] = "seen[x] = i mapuje hodnotu na pozici. Vrácení (seen[target - x], i) dává dvojici indexů, kterou otázka chce.",
  ["select"] = "select",
  ["select waits on several channel ops. default is the non-blocking branch."] = "select čeká na několik operací s kanály. default je neblokující větev.",
  ["select {\ncase d := <-cooked:\n    return d, nil\ncase <-ctx.___():\n    return Dish{}, ctx.Err()\n}\n"] = "select {\ncase d := <-cooked:\n    return d, nil\ncase <-ctx.___():\n    return Dish{}, ctx.Err()\n}\n",
  ["select {\ncase m := <-muffin:\n    serve(m)\n___:\n    skip()\n}\n"] = "select {\ncase m := <-muffin:\n    serve(m)\n___:\n    skip()\n}\n",
  ["select {\ncase m := <-muffin:\n    serve(m)\ncase <-ctx.___():\n    return ctx.Err()\n}\n"] = "select {\ncase m := <-muffin:\n    serve(m)\ncase <-ctx.___():\n    return ctx.Err()\n}\n",
  ['select {\ncase m := <-muffin:\n    serve(m)\ncase <-time.___(time.Second):\n    fmt.Println("timeout")\n}\n'] = 'select {\ncase m := <-muffin:\n    serve(m)\ncase <-time.___(time.Second):\n    fmt.Println("timeout")\n}\n',
  ["select { case x := <-ch: ... }. Random choice if several are ready."] = "select { case x := <-ch: ... }. Náhodná volba, když je připraveno víc.",
  ["sem := make(chan struct{}, 4)\nsem <- struct{}{}\ngo func() {\n    deliver(o)\n    ___\n}()\n"] = "sem := make(chan struct{}, 4)\nsem <- struct{}{}\ngo func() {\n    deliver(o)\n    ___\n}()\n",
  ["sem := make(chan struct{}, ___)\nfor _, u := range urls {\n    sem <- struct{}{}        // acquire (blocks when full)\n    go func(u string) {\n        defer func() { <-sem }()   // release\n        fetch(u) }(u)\n}\n"] = "sem := make(chan struct{}, ___)\nfor _, u := range urls {\n    sem <- struct{}{}        // získej (blokuje, když je plno)\n    go func(u string) {\n        defer func() { <-sem }()   // uvolni\n        fetch(u) }(u)\n}\n",
  ["serde and JSON"] = "serde a JSON",
  ["serde_json::Value indexes with [] and returns Null when missing. Ticket four closed."] = "serde_json::Value indexuje přes [] a vrátí Null, když klíč chybí. Ticket čtyři uzavřen.",
  ["serde_json::from_str::<Order>(text). from_slice for bytes, from_reader for files."] = "serde_json::from_str::<Order>(text). from_slice pro bajty, from_reader pro soubory.",
  ["serde_json::to_string(&order) -> compact JSON. to_vec gives bytes, to_writer streams."] = "serde_json::to_string(&order) -> kompaktní JSON. to_vec dá bajty, to_writer streamuje.",
  ["set(names) drops duplicates; x in s is O(1). {1, 2} is a set literal, but {} is a dict. Sets have no order."] = "set(names) zahodí duplikáty; x in s je O(1). {1, 2} je literál setu, ale {} je dict. Sety nemají pořadí.",
  ["set: one O(1) check per guest, O(n) total. Fifty million checks become ten thousand."] = "set: jedna kontrola O(1) na hosta, celkem O(n). Z padesáti milionů kontrol je deset tisíc.",
  ["shared_memory: no copy at all"] = "shared_memory: vůbec žádná kopie",
  ["shifts = [[13, 15], [9, 11], [10, 12]]\n# sort by start so overlapping shifts sit side by side\nshifts.sort(key=lambda iv: iv[___])\nprint(shifts)    # [[9, 11], [10, 12], [13, 15]]\n"] = "shifts = [[13, 15], [9, 11], [10, 12]]\n# seřaď podle začátku, ať překryvy sedí vedle sebe\nshifts.sort(key=lambda iv: iv[___])\nprint(shifts)    # [[9, 11], [10, 12], [13, 15]]\n",
  ["shm.close()\n\n# in the parent only, once:\nshm.___()\n"] = "shm.close()\n\n# jen v rodiči, jednou:\nshm.___()\n",
  ['shops := []string{"Lucky Mac", "Sogo"}\nfor _, name := ___ shops {\n    fmt.Println(name)\n}\n'] = 'shops := []string{"Lucky Mac", "Sogo"}\nfor _, name := ___ shops {\n    fmt.Println(name)\n}\n',
  ['sign = "open" if bowls > 0 ___ "closed"\nprint(sign)\n'] = 'sign = "open" if bowls > 0 ___ "closed"\nprint(sign)\n',
  ["sink stops off the map. usize never goes below zero, so only the far edges need a test. Row r is outside when r is what, compared with the row count?"] = "sink se zastaví mimo mapu. usize nikdy neklesne pod nulu, takže test potřebují jen vzdálené okraje. Řádek r je venku, když je r jaké, ve srovnání s počtem řádků?",
  ['skip_serializing_if = "Option::is_none" drops empty fields. default fills them on the way in.'] = 'skip_serializing_if = "Option::is_none" vynechá prázdná pole. default je doplní na cestě dovnitř.',
  ["slices.Contains, Index, Reverse, Max: the loops you used to write by hand."] = "slices.Contains, Index, Reverse, Max: smyčky, které jsi dřív psal ručně.",
  ["slices.Sort is generic: no sort.Strings / sort.Ints per type any more."] = "slices.Sort je generický: už žádné sort.Strings / sort.Ints pro každý typ.",
  ["slow, fast := head, head\nfor fast != nil && fast.Next != nil {\n    slow = slow.Next\n    fast = fast.Next.___\n    if slow == fast { return true }   // cycle\n}\n"] = "slow, fast := head, head\nfor fast != nil && fast.Next != nil {\n    slow = slow.Next\n    fast = fast.Next.___\n    if slow == fast { return true }   // cyklus\n}\n",
  ["sold++ is three machine steps. Two goroutines can land between them. Put a lock around it."] = "sold++ jsou tři strojové kroky. Dvě goroutiny se mezi ně vejdou. Obal to zámkem.",
  ["sort, an underscore, and the word for 'may reorder equal items'."] = 'sort, podtržítko a slovo pro „může přeuspořádat stejné položky".',
  ["sort, by, key with underscores. The closure returns something Ord; here a u32."] = "sort, by, key s podtržítky. Closure vrací něco s Ord; tady u32.",
  ["sort, underscore, the opposite of stable. A pattern-defeating quicksort inside."] = "sort, podtržítko, a opak slova stable. Uvnitř pattern-defeating quicksort.",
  ["sort.Ints on n receipts: what does it cost, in Big O?"] = "sort.Ints na n účtenkách: co to stojí, v Big O?",
  ["sort.Ints sorts the slice where it is. Extra memory, in Big O: O(___)"] = "sort.Ints třídí slice tam, kde je. Paměť navíc, v Big O: O(___)",
  ["sort.Ints(a)                        // once: n log n\nfor _, x := range queries {\n    _, ok := slices.BinarySearch(a, x)   // each: O(___)\n}\n"] = "sort.Ints(a)                        // jednou: n log n\nfor _, x := range queries {\n    _, ok := slices.BinarySearch(a, x)   // každé: O(___)\n}\n",
  ["sort.Ints(a)    // in place: O(___) extra space\n"] = "sort.Ints(a)    // na místě: O(___) prostoru navíc\n",
  ["sort.Ints(amounts)    // ___ : pdqsort, comparison-based\n"] = "sort.Ints(amounts)    // ___ : pdqsort, založený na porovnávání\n",
  ["sort.Ints(starts); sort.Ints(ends)\nrooms, e := 0, 0\nfor _, s := range starts {\n    if s ___ ends[e] {      // one meeting already over\n        e++\n    } else {\n        rooms++\n"] = "sort.Ints(starts); sort.Ints(ends)\nrooms, e := 0, 0\nfor _, s := range starts {\n    if s ___ ends[e] {      // jedna schůzka už skončila\n        e++\n    } else {\n        rooms++\n",
  ["sort.Slice with a less function. slices.SortFunc is the generic Go 1.21 way."] = "sort.Slice s funkcí less. slices.SortFunc je generická cesta od Go 1.21.",
  ["sort.Slice(iv, func(i, j int) bool {\n    return iv[i][0] ___ iv[j][0]    // earliest start first\n})\n"] = "sort.Slice(iv, func(i, j int) bool {\n    return iv[i][0] ___ iv[j][0]    // nejdřívější start první\n})\n",
  ["sort.Strings(names). Go 1.21's slices.Sort(names) is generic and does the same. Both n log n."] = "sort.Strings(names). slices.Sort(names) z Go 1.21 je generický a dělá totéž. Oboje n log n.",
  ["sort.___(orders, func(i, j int) bool {\n    return orders[i].Price < orders[j].Price\n})\n"] = "sort.___(orders, func(i, j int) bool {\n    return orders[i].Price < orders[j].Price\n})\n",
  ["sort_by_key is a stable merge sort, like the one you just wrote. sort_by takes a full comparator instead."] = "sort_by_key je stabilní merge sort, jako ten, co jsi právě napsal. sort_by místo toho bere celý komparátor.",
  ["sort_unstable sorts the Vec where it is. Extra memory, in Big O: O(___)"] = "sort_unstable třídí Vec tam, kde je. Paměť navíc, v Big O: O(___)",
  ["sort_unstable: O(n log n), in place, usually faster than sort. Use sort only when order among equals matters. Combo x5."] = "sort_unstable: O(n log n), na místě, obvykle rychlejší než sort. Používej sort jen tehdy, když záleží na pořadí mezi shodnými. Kombo x5.",
  ["sort_unstable: same O(n log n), less memory, usually faster. sort_by_key(|o| o.price) sorts by a field."] = "sort_unstable: stejné O(n log n), méně paměti, obvykle rychlejší. sort_by_key(|o| o.price) třídí podle pole.",
  ["sorted on n receipts: what does it cost, in Big O?"] = "sorted na n účtenkách: co to stojí, v Big O?",
  ["sorted() is Timsort: merge sort that notices runs already in order. Still n log n in the worst case."] = "sorted() je Timsort: merge sort, který si všímá úseků, které už jsou v pořadí. V nejhorším případě stále n log n.",
  ["sorted(a) == sorted(b) is O(n log n) and one line. Counter(a) == Counter(b) is O(n) and just as short."] = "sorted(a) == sorted(b) je O(n log n) a jeden řádek. Counter(a) == Counter(b) je O(n) a stejně krátký.",
  ["sorted(names, key=len). The key is called n times, O(n), then Timsort. Both together: n log n."] = "sorted(names, key=len). key se zavolá n krát, O(n), pak Timsort. Oboje dohromady: n log n.",
  ["sorted(xs) returns a new list, xs.sort() sorts in place. Both take key= and reverse=True. The rack is in order."] = "sorted(xs) vrací nový seznam, xs.sort() třídí na místě. Oba berou key= a reverse=True. Regál je v pořádku.",
  ["spawn returns a handle you can wait on. What is its type?"] = "spawn vrací handle, na který můžeš čekat. Jaký je jeho typ?",
  ["spawn starts a clean interpreter and pickles the target across, so nothing is silently inherited. fork is faster and shares everything, including locks held at the wrong moment."] = "spawn spustí čistý interpret a target pošle přes pickle, takže se potichu nedědí nic. fork je rychlejší a sdílí všechno, včetně zámků držených v nevhodnou chvíli.",
  ["split, underscore, at. Panics if mid is past the end; here it never is."] = "split, podtržítko, at. Panikaří, když je mid za koncem; tady nikdy není.",
  ["split_at gives (&v[..mid], &v[mid..]) as one tuple. Two shared borrows of one slice are fine."] = "split_at dá (&v[..mid], &v[mid..]) jako jednu n-tici. Dvě sdílené výpůjčky jednoho slice jsou v pořádku.",
  ["st := []rune{}\nfor _, c := range s {\n    if _, closer := pairs[c]; !closer {\n        st = ___(st, c)     // an opener waits here\n        continue\n    }\n}\n"] = "st := []rune{}\nfor _, c := range s {\n    if _, closer := pairs[c]; !closer {\n        st = ___(st, c)     // otevírací tu čeká\n        continue\n    }\n}\n",
  ['st = []\nst.append("(")\nst.append("[")\ntop = st[___]        # the most recent opener\nprint(top)           # [\n'] = 'st = []\nst.append("(")\nst.append("[")\ntop = st[___]        # poslední otvírací\nprint(top)           # [\n',
  ["st[-1] is the peek. Guard it with if st: the same way as pop."] = "st[-1] je nakouknutí. Ohlídej ho pomocí if st: stejně jako pop.",
  ["starmap(f, [(a, b), ...]) calls f(a, b). It is the difference between one argument and several, and the reason you rarely need a wrapper function."] = "starmap(f, [(a, b), ...]) volá f(a, b). Je to rozdíl mezi jedním argumentem a několika a důvod, proč málokdy potřebuješ obalovou funkci.",
  ["start:stop, the stop is not included. Same rule as Go's a[1:3]."] = "start:stop, stop není zahrnut. Stejné pravidlo jako a[1:3] v Go.",
  ['str(4) is "4". "Table " + 4 raises TypeError: Python never converts silently. The stock count comes out whole.'] = 'str(4) je "4". "Table " + 4 vyhodí TypeError: Python nikdy nepřevádí potichu. Stav skladu vychází celý.',
  ["strconv.Atoi / Itoa for ints, ParseFloat and FormatFloat for floats."] = "strconv.Atoi / Itoa pro inty, ParseFloat a FormatFloat pro floaty.",
  ["string is bytes, rune is a code point. utf8 counts characters, strconv converts."] = "string jsou bajty, rune je kódový bod. utf8 počítá znaky, strconv převádí.",
  ["strings has Split, Join, Contains, TrimSpace, ToUpper... all return new strings."] = "strings má Split, Join, Contains, TrimSpace, ToUpper... všechny vracejí nové řetězce.",
  ['struct Grill;\n// Grill promises every method of Cook.\nimpl Cook ___ Grill {\n    fn name(&self) -> String {\n        "grill".to_string()\n    }\n}\n'] = 'struct Grill;\n// Grill slibuje každou metodu Cook.\nimpl Cook ___ Grill {\n    fn name(&self) -> String {\n        "grill".to_string()\n    }\n}\n',
  ["struct ListNode {\n    val: i32,\n    next: ___<Box<ListNode>>,   // the rest, or the end\n}\n"] = "struct ListNode {\n    val: i32,\n    next: ___<Box<ListNode>>,   // zbytek, nebo konec\n}\n",
  ["struct Order { id: u32, price: u32 }\nlet mut orders = vec![\n    Order { id: 7, price: 45 },\n    Order { id: 3, price: 18 },\n];\n// cheapest first; equal prices keep their order (stable)\norders.___(|o| o.price);\n"] = "struct Order { id: u32, price: u32 }\nlet mut orders = vec![\n    Order { id: 7, price: 45 },\n    Order { id: 3, price: 18 },\n];\n// nejlevnější první; stejné ceny si drží pořadí (stabilní)\norders.___(|o| o.price);\n",
  ["struct Order { item: String, qty: u32 } Fields are private to the module unless marked pub."] = "struct Order { item: String, qty: u32 } Pole jsou soukromá pro modul, pokud nejsou označená pub.",
  ["struct Order { qty: u32 }\n\n___ Order {\n    fn total(&self) -> u32 {\n        self.qty * 18\n    }\n}\n"] = "struct Order { qty: u32 }\n\n___ Order {\n    fn total(&self) -> u32 {\n        self.qty * 18\n    }\n}\n",
  ["struct Receipt<'a> { name: &'a str }: a Receipt cannot outlive the name it borrows. The compiler now checks it for you."] = "struct Receipt<'a> { name: &'a str }: Receipt nemůže přežít jméno, které si půjčuje. Kompilátor to teď kontroluje za tebe.",
  ['struct Wok;\nimpl Cook for Wok {\n    fn name(&self) -> String { "wok".to_string() }\n}\n// Any Cook, decided at run time, behind a reference.\nfn call(c: &___ Cook) { println!("{}", c.greet()); }\ncall(&Grill); call(&Wok);\n'] = 'struct Wok;\nimpl Cook for Wok {\n    fn name(&self) -> String { "wok".to_string() }\n}\n// Libovolný Cook, rozhodnutý za běhu, za referencí.\nfn call(c: &___ Cook) { println!("{}", c.greet()); }\ncall(&Grill); call(&Wok);\n',
  ["struct groups fields. *T is a pointer. Methods have a receiver. interface is a set of methods."] = "struct seskupuje pole. *T je ukazatel. Metody mají receiver. interface je sada metod.",
  ["struct groups fields. impl adds methods that take &self or &mut self. enum lists variants; match handles them all."] = "struct seskupuje pole. impl přidává metody, které berou &self nebo &mut self. enum vyjmenovává varianty; match je všechny ošetří.",
  ["struct, impl and enum"] = "struct, impl a enum",
  ["submit(f, *args) is go f(args): the call is already running somewhere else and you hold the receipt."] = "submit(f, *args) je go f(args): volání už běží někde jinde a ty držíš stvrzenku.",
  ["sum := 0\nfor _, p := range prices {    // ___ : n items, n adds\n    sum += p\n}\n"] = "sum := 0\nfor _, p := range prices {    // ___ : n položek, n součtů\n    sum += p\n}\n",
  ["sum over n prices: what is the cost in Big O?"] = "sum přes n cen: jaká je cena v Big O?",
  ["sum takes any number of fares. Fill the parameter type: fares ___"] = "sum bere libovolný počet jízdných. Doplň typ parametru: fares ___",
  ["sum.golang.org records the hash of every public version once, so two people who go get the same tag either get identical bytes or an error."] = "sum.golang.org zaznamená hash každé veřejné verze jednou, takže dva lidé, kteří udělají go get na stejný tag, dostanou buď totožné bajty, nebo chybu.",
  ["sum::<i32>() adds &i32 into an i32. Without the turbofish Rust cannot pick the type."] = "sum::<i32>() sečte &i32 do i32. Bez turbofishe Rust nedokáže vybrat typ.",
  ["super().__init__(item) runs the parent constructor. class SetMeal(Order) is inheritance; Go embeds instead."] = "super().__init__(item) spustí rodičovský konstruktor. class SetMeal(Order) je dědičnost; Go místo toho vkládá.",
  ['switch light { case "green": walk() }. No break: cases do not fall through.'] = 'switch light { case "green": walk() }. Bez break: případy nepropadají dál.',
  ["switch v.(type) gives x the concrete type in every case."] = "switch v.(type) dá x v každém case konkrétní typ.",
  ['switch x := v.(___) {\ncase int:\n    fmt.Println(x + 1)      // x is an int here\ncase string:\n    fmt.Println(x + "!")    // and a string here\n}\n'] = 'switch x := v.(___) {\ncase int:\n    fmt.Println(x + 1)      // x je tady int\ncase string:\n    fmt.Println(x + "!")    // a tady string\n}\n',
  ["sync, underscore, then the word for the pipe itself."] = "sync, podtržítko, pak slovo pro samotnou trubku.",
  ["sync.Map pays off for keys written once and read often. For anything else a plain map behind a Mutex is faster and clearer."] = "sync.Map se vyplatí u klíčů zapsaných jednou a čtených často. Na cokoli jiného je obyčejná mapa za mutexem rychlejší a srozumitelnější.",
  ["sync.Mutex. Lock, change, Unlock. Prefer channels when you can."] = "sync.Mutex. Lock, změna, Unlock. Kde to jde, dej přednost kanálům.",
  ["sync.Mutex: one goroutine at a time"] = "sync.Mutex: jedna goroutina naráz",
  ["sync.Once.Do runs the function once and blocks the others until it finishes. Go 1.21 adds sync.OnceValue."] = "sync.Once.Do spustí funkci jednou a ostatní blokuje, dokud neskončí. Go 1.21 přidává sync.OnceValue.",
  ["sync.OnceValue(f) returns a function: the first call runs f, every later call returns the cached value. sync.OnceValues does the (T, error) pair."] = "sync.OnceValue(f) vrací funkci: první volání spustí f, každé další vrátí uloženou hodnotu. Dvojici (T, error) obslouží sync.OnceValues.",
  ["sync.Pool recycles short-lived allocations across goroutines. It is a garbage-collector optimisation, never a place to keep state."] = "sync.Pool recykluje krátkověké alokace mezi goroutinami. Je to optimalizace pro garbage collector, nikdy ne místo na ukládání stavu.",
  ["sync.RWMutex: any number of RLock holders, or exactly one Lock holder. Worth it when reads dominate."] = "sync.RWMutex: držitelů RLock může být libovolně mnoho, držitel Lock právě jeden. Vyplatí se, když převažuje čtení.",
  ["sync/atomic is for single words: counters, flags. Anything bigger wants a Mutex."] = "sync/atomic je pro jednotlivá slova: čítače, příznaky. Cokoli většího chce Mutex.",
  ["sync_channel(n) is bounded: send blocks when n values wait. Backpressure, like a buffered Go channel. The queue moves."] = "sync_channel(n) je omezený: send blokuje, když čeká n hodnot. Protitlak, jako bufferovaný kanál v Go. Fronta se hýbe.",
  ['t = threading.Thread(target=fry, args=("egg",))\nt.___()\nprint("frying in the background")\n'] = 't = threading.Thread(target=fry, args=("egg",))\nt.___()\nprint("frying in the background")\n',
  ["t.Errorf marks failure and continues; t.Fatalf stops. Table tests loop over cases with t.Run."] = "t.Errorf označí selhání a pokračuje; t.Fatalf zastaví. Tabulkové testy procházejí případy přes t.Run.",
  ["t.start() spawns the OS thread and returns at once. t.run() is the body; calling it yourself gains nothing."] = "t.start() vytvoří vlákno OS a hned se vrátí. t.run() je tělo; volat ho sám nic nepřinese.",
  ['table = 4\nlabel = "Table " + ___(table)\nprint(label)       # Table 4\n'] = 'table = 4\nlabel = "Table " + ___(table)\nprint(label)       # Table 4\n',
  ["thiserror derives Display + Error; #[from] even writes the From impl. Ticket two closed."] = "thiserror derivuje Display + Error; #[from] dokonce napíše impl From. Ticket dva uzavřen.",
  ["thread::scope(|s| ...) joins every s.spawn before returning, so the closures may borrow without move. Three cooks, one menu."] = "thread::scope(|s| ...) před návratem spojí každý s.spawn, takže closure si smí půjčovat bez move. Tři kuchaři, jedno menu.",
  ["thread::sleep(Duration) takes a Duration, never a bare number. Duration::from_secs and from_millis build one."] = "thread::sleep(Duration) bere Duration, nikdy holé číslo. Duration::from_secs a from_millis ho postaví.",
  ["thread::spawn returns JoinHandle<T>. Keep them in a Vec, or the threads are detached and main may exit first."] = "thread::spawn vrací JoinHandle<T>. Drž je ve Vec, jinak jsou vlákna odpojená a main může skončit dřív.",
  ["thread::spawn starts a thread; move gives it its data; join waits. thread::scope may borrow."] = "thread::spawn spustí vlákno; move mu dá jeho data; join čeká. thread::scope si smí půjčovat.",
  ["thread::spawn(closure) returns a JoinHandle and runs at once on an OS thread. Rust has no green threads built in."] = "thread::spawn(closure) vrátí JoinHandle a hned běží na vlákně OS. Rust nemá vestavěná zelená vlákna.",
  ["threading.Thread(target=f).start() runs f beside the main thread; join waits. Lock guards shared state. ThreadPoolExecutor manages a pool. The GIL lets one thread run bytecode at a time."] = "threading.Thread(target=f).start() spustí f vedle hlavního vlákna; join čeká. Lock hlídá sdílený stav. ThreadPoolExecutor spravuje pool. GIL nechá běžet bytecode jen jednomu vláknu naráz.",
  ["tidy walks every import in the module, adds what is missing to go.mod and go.sum and drops what nothing uses. Run it before every commit."] = "tidy projde každý import v modulu, doplní chybějící do go.mod a go.sum a vyhodí, co nic nepoužívá. Spouštěj ho před každým commitem.",
  ["time.After in a select is the classic timeout. In a loop prefer a time.Timer."] = "time.After v select je klasický timeout. V cyklu raději time.Timer.",
  ["tokio::spawn needs a 'static + Send future. handle.await gives Result<T, JoinError>."] = "tokio::spawn potřebuje future, který je 'static + Send. handle.await dá Result<T, JoinError>.",
  ["top = prices[0]\nfor p in prices[1:]:    # ___ comparisons\n    if p > top:\n        top = p\n"] = "top = prices[0]\nfor p in prices[1:]:    # ___ porovnání\n    if p > top:\n        top = p\n",
  ["total = 0\n\ndef add(rows):\n    global total\n    total += sum(rows)\n# the child changed its own ___ of total\n"] = "total = 0\n\ndef add(rows):\n    global total\n    total += sum(rows)\n# potomek změnil vlastní ___ proměnné total\n",
  ["total = sum(prices)    # ___ : n items, n adds, inside C\n"] = "total = sum(prices)    # ___ : n položek, n součtů, uvnitř C\n",
  ["total = sum(prices)    # n steps\ntop = max(prices)      # n more\n# 2n steps, written O(___)\n"] = "total = sum(prices)    # n kroků\ntop = max(prices)      # n dalších\n# 2n kroků, zapsáno O(___)\n",
  ["total only reads the order. Which receiver borrows it without change?"] = "total objednávku jen čte. Který receiver si ji půjčí beze změny?",
  ["total(3, 5) and total(3, 5, 8) should both work. How is the parameter written to take any number of items?"] = "total(3, 5) i total(3, 5, 8) musí fungovat. Jak se zapíše parametr, aby přijal libovolný počet položek?",
  ["trait Cook lists methods. One with a body is a default; implementors may keep it or override it."] = "trait Cook vyjmenovává metody. Ta s tělem je výchozí; implementace si ji mohou nechat, nebo přepsat.",
  ['tray := []string{"muffin", "hash", "coffee", "tea"}\ntwo := tray[___]         // {"hash", "coffee"}\n'] = 'tray := []string{"muffin", "hash", "coffee", "tea"}\ntwo := tray[___]         // {"hash", "coffee"}\n',
  ['tray := []string{"muffin", "hashbrown"}\nn := ___(tray)         // 2\n'] = 'tray := []string{"muffin", "hashbrown"}\nn := ___(tray)         // 2\n',
  ['tray := []string{"muffin"}\ntray = ___(tray, "hashbrown")\n'] = 'tray := []string{"muffin"}\ntray = ___(tray, "hashbrown")\n',
  ['tray := ___([]string, 0, 8)   // len 0, cap 8\ntray = append(tray, "muffin")\n'] = 'tray := ___([]string, 0, 8)   // len 0, cap 8\ntray = append(tray, "muffin")\n',
  ["tray := make([]string, 2, 8)\nfmt.Println(len(tray), ___(tray))   // 2 8\n"] = "tray := make([]string, 2, 8)\nfmt.Println(len(tray), ___(tray))   // 2 8\n",
  ["tray = append(tray, x). Never ignore the return."] = "tray = append(tray, x). Návratovou hodnotu nikdy neignoruj.",
  ["trays = [\"egg\", \"tea\", \"toast\", \"rice\"]\nprint(trays[___])     # ['tea', 'toast']\n"] = "trays = [\"egg\", \"tea\", \"toast\", \"rice\"]\nprint(trays[___])     # ['tea', 'toast']\n",
  ['trays = ["egg", "tea", "toast", "rice"]\nprint(trays[___])     # rice\n'] = 'trays = ["egg", "tea", "toast", "rice"]\nprint(trays[___])     # rice\n',
  ['trays = ["egg", "tea", "toast"]\nit = ___(trays)\nprint(next(it))     # egg\nprint(next(it))     # tea\n'] = 'trays = ["egg", "tea", "toast"]\nit = ___(trays)\nprint(next(it))     # egg\nprint(next(it))     # tea\n',
  ['trays = ["egg", "tea", "toast"]\nprint(___(trays))     # 3\n'] = 'trays = ["egg", "tea", "toast"]\nprint(___(trays))     # 3\n',
  ["trays = [\"egg\", \"tea\"]\ntrays.___(\"toast\")\nprint(trays)     # ['egg', 'tea', 'toast']\n"] = "trays = [\"egg\", \"tea\"]\ntrays.___(\"toast\")\nprint(trays)     # ['egg', 'tea', 'toast']\n",
  ["trays.append(x) is amortized O(1). trays = trays.append(x) is the classic bug: it sets trays to None."] = "trays.append(x) je amortizovaně O(1). trays = trays.append(x) je klasický bug: nastaví trays na None.",
  ["tree.as_ref() turns &Option<T> into Option<&T>. Without it, map would try to move out of the borrow."] = "tree.as_ref() změní &Option<T> na Option<&T>. Bez toho by se map pokusil přesunout hodnotu z výpůjčky.",
  ["try, except, raise"] = "try, except, raise",
  ["try, underscore, then the blocking method's name."] = "try, podtržítko, pak jméno blokující metody.",
  ['try:\n    price = menu[dish]\nexcept KeyError ___ e:\n    print("unknown dish", e)\n'] = 'try:\n    price = menu[dish]\nexcept KeyError ___ e:\n    print("unknown dish", e)\n',
  ['try:\n    qty = int(raw)\n___ ValueError:\n    print("not a number:", raw)\n    qty = 0\n'] = 'try:\n    qty = int(raw)\n___ ValueError:\n    print("not a number:", raw)\n    qty = 0\n',
  ['try:\n    refund(receipt)\nexcept KeyError:\n    print("no such receipt")\n___:\n    printer.close()\n'] = 'try:\n    refund(receipt)\nexcept KeyError:\n    print("no such receipt")\n___:\n    printer.close()\n',
  ["try: guards the risky lines. Rust has Result and ?; Python unwinds the stack to the nearest except."] = "try: chrání riskantní řádky. Rust má Result a ?; Python odvíjí zásobník k nejbližšímu except.",
  ["try_recv() returns at once: Ok(v), Err(Empty) or Err(Disconnected). Good for polling loops; recv_timeout is the middle road."] = "try_recv() se vrátí okamžitě: Ok(v), Err(Empty) nebo Err(Disconnected). Dobré pro dotazovací cykly; recv_timeout je střední cesta.",
  ["two-sum with a HashMap, palindrome with chars().rev(), anagram with a [0; 26] counter, word count with entry().or_insert(0)."] = "two-sum přes HashMap, palindrom přes chars().rev(), přesmyčka přes čítač [0; 26], počítání slov přes entry().or_insert(0).",
  ["type Floor int             // new type, underlying int\n\nf := ___(3)                // int -> Floor\n"] = "type Floor int             // nový typ, základ int\n\nf := ___(3)                // int -> Floor\n",
  ["type Floor int is a new type: its own methods, no accidental mixing with int."] = "type Floor int je nový typ: vlastní metody, žádné náhodné míchání s int.",
  ["type Future[T any] struct{ ch chan T }\n\nfunc (f Future[T]) Await() T {\n    return ___f.ch\n}\n"] = "type Future[T any] struct{ ch chan T }\n\nfunc (f Future[T]) Await() T {\n    return ___f.ch\n}\n",
  ["type IntHeap []int\n\nfunc (h IntHeap) Len() int { return len(h) }\nfunc (h IntHeap) Less(i, j int) bool {\n    return h[i] ___ h[j]    // the smallest rises to the top\n}\nfunc (h IntHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }\n"] = "type IntHeap []int\n\nfunc (h IntHeap) Len() int { return len(h) }\nfunc (h IntHeap) Less(i, j int) bool {\n    return h[i] ___ h[j]    // nejmenší stoupá na vrchol\n}\nfunc (h IntHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }\n",
  ["type Kitchen struct {\n    ___                  // promoted methods\n}\n"] = "type Kitchen struct {\n    ___                  // povýšené metody\n}\n",
  ["type Kitchen struct { Grill }. k.Toast() calls Grill.Toast."] = "type Kitchen struct { Grill }. k.Toast() volá Grill.Toast.",
  ["type LRU struct {\n    cap int\n    m   map[int]___         // key -> its node in l\n    l   *list.List          // front = most recent\n}\n"] = "type LRU struct {\n    cap int\n    m   map[int]___         // klíč -> jeho uzel v l\n    l   *list.List          // front = nejčerstvější\n}\n",
  ["type Link = Option<Box<ListNode>>;\nfn pop(head: &mut Link) -> Option<i32> {\n    // move the first node out, leave None in its place\n    let node = head.___()?;\n    *head = node.next;\n    Some(node.val)\n}\n"] = "type Link = Option<Box<ListNode>>;\nfn pop(head: &mut Link) -> Option<i32> {\n    // přesuň první uzel ven a nech tam None\n    let node = head.___()?;\n    *head = node.next;\n    Some(node.val)\n}\n",
  ["type ListNode struct {\n    Val  int\n    Next ___             // nil at the tail\n}\n"] = "type ListNode struct {\n    Val  int\n    Next ___             // na konci nil\n}\n",
  ["type Name ___, then curly braces with fields."] = "type Name ___, pak složené závorky s poli.",
  ["type Node struct {\n    Val         int\n    Left, Right ___      // nil at the leaves\n}\n"] = "type Node struct {\n    Val         int\n    Left, Right ___      // v listech nil\n}\n",
  ["type Number interface {\n    ___int | ___float64      // underlying types\n}\nfunc Sum[T Number](xs []T) T\n"] = "type Number interface {\n    ___int | ___float64      // podkladové typy\n}\nfunc Sum[T Number](xs []T) T\n",
  ["type Order ___ {\n    Item  string\n    Price int\n}\n"] = "type Order ___ {\n    Item  string\n    Price int\n}\n",
  ['type Order struct {\n    Item string `json:"___"`\n}\n'] = 'type Order struct {\n    Item string `json:"___"`\n}\n',
  ['type Order struct {\n    Item string `json:"dish"`\n    Note string `json:"note,___"`   // skip when empty\n}\n'] = 'type Order struct {\n    Item string `json:"dish"`\n    Note string `json:"note,___"`   // přeskoč, když je prázdné\n}\n',
  ["type Order struct {\n    ___  string           // json needs a capital\n    Price int\n}\n"] = "type Order struct {\n    ___  string           // json chce velké písmeno\n    Price int\n}\n",
  ["type Order struct { Item string; Price int }. A value type."] = "type Order struct { Item string; Price int }. Hodnotový typ.",
  ["type Payer ___ {\n    Pay(int) error\n}\n"] = "type Payer ___ {\n    Pay(int) error\n}\n",
  ['type RefundError struct{ Amount int }\n\nfunc (e *RefundError) ___() string {\n    return "refund " + strconv.Itoa(e.Amount)\n}\n'] = 'type RefundError struct{ Amount int }\n\nfunc (e *RefundError) ___() string {\n    return "refund " + strconv.Itoa(e.Amount)\n}\n',
  ["type names a type. v.(T) asserts, switch v.(type) branches. Sprintf formats."] = "type pojmenuje typ. v.(T) asertuje, switch v.(type) větví. Sprintf formátuje.",
  ["type orderKey struct{}\n\nctx = context.___(ctx, orderKey{}, id)\n// five calls deeper:\nid, ok := ctx.Value(orderKey{}).(int)\n"] = "type orderKey struct{}\n\nctx = context.___(ctx, orderKey{}, id)\n// o pět volání hlouběji:\nid, ok := ctx.Value(orderKey{}).(int)\n",
  ["type the answer"] = "napiš odpověď",
  ["type(price) is float. Python is dynamically typed: the value carries the type, the name does not."] = "type(price) je float. Python je dynamicky typovaný: typ nese hodnota, ne jméno.",
  ["u for unsigned, then the word for pointer size. Same type as len() returns."] = "u jako unsigned, pak anglické slovo pro velikost ukazatele. Stejný typ, jaký vrací len().",
  ["u for unsigned, then the word size. It is also the type used to index a Vec."] = "u jako unsigned, pak velikost slova. Je to také typ, kterým se indexuje Vec.",
  ["unwrap, then an underscore, then a two-letter word."] = "unwrap, pak podtržítko, pak dvoupísmenné slovo.",
  ["unwrap_or(default) returns the Ok value or your default. Sibling: unwrap_or_else(|e| ...). Zero coins, but no crash."] = "unwrap_or(default) vrátí hodnotu z Ok nebo tvou výchozí. Sourozenec: unwrap_or_else(|e| ...). Nula mincí, ale žádný pád.",
  ['use serde::{Deserialize, ___};\n// Cargo.toml: serde = {version="1", features=["derive"]}\n#[derive(Debug, ___, Deserialize)]\nstruct Order {\n    name: String,\n    qty: u32,\n}\n'] = 'use serde::{Deserialize, ___};\n// Cargo.toml: serde = {version="1", features=["derive"]}\n#[derive(Debug, ___, Deserialize)]\nstruct Order {\n    name: String,\n    qty: u32,\n}\n',
  ["use std::collections::HashMap;\n// station id -> the ids one hop away (an adjacency list)\ntype Graph = HashMap<u32, ___<u32>>;\nfn degree(g: &Graph, n: u32) -> usize {\n    g[&n].len()          // how many exits this station has\n}\n"] = "use std::collections::HashMap;\n// id stanice -> id na jeden skok daleko (seznam sousednosti)\ntype Graph = HashMap<u32, ___<u32>>;\nfn degree(g: &Graph, n: u32) -> usize {\n    g[&n].len()          // kolik má tahle stanice východů\n}\n",
  ['use std::collections::HashMap;\nfn main() {\n    let mut count = HashMap::new();\n    count.insert("t7", 2);\n    *count.___("t4").or_insert(0) += 1;   // t4 is 1\n    println!("{:?}", count.get("t9"));    // None\n}\n'] = 'use std::collections::HashMap;\nfn main() {\n    let mut count = HashMap::new();\n    count.insert("t7", 2);\n    *count.___("t4").or_insert(0) += 1;   // t4 je 1\n    println!("{:?}", count.get("t9"));    // None\n}\n',
  ["use std::collections::HashMap; The :: walks the path. std is always there, no Cargo.toml line needed."] = "use std::collections::HashMap; Dvojtečky :: procházejí cestu. std je vždy k dispozici, žádný řádek v Cargo.toml není třeba.",
  ['use std::collections::___;\n\nlet mut menu = ___::new();\nmenu.insert("tea", 12);\nlet price = menu["tea"];    // hash, bucket, compare\n'] = 'use std::collections::___;\n\nlet mut menu = ___::new();\nmenu.insert("tea", 12);\nlet price = menu["tea"];    // hash, bucket, porovnání\n',
  ['use std::error::Error;\nfn main() -> Result<(), ___<dyn Error>> {\n    let qty: i32 = "18".parse()?;   // ParseIntError fits\n    let text = std::fs::read_to_string("menu.txt")?;\n    println!("{qty} sets, {} bytes of menu", text.len());\n    Ok(())\n}\n'] = 'use std::error::Error;\nfn main() -> Result<(), ___<dyn Error>> {\n    let qty: i32 = "18".parse()?;   // ParseIntError se vejde\n    let text = std::fs::read_to_string("menu.txt")?;\n    println!("{qty} sets, {} bytes of menu", text.len());\n    Ok(())\n}\n',
  ['use std::fmt;\n// Receipt carries a lifetime; fmt does not need its name.\nimpl fmt::Display for Receipt<___> {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} paid {}", self.name, self.total)\n    }\n}\n'] = 'use std::fmt;\n// Receipt nese lifetime; fmt jeho jméno nepotřebuje.\nimpl fmt::Display for Receipt<___> {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} paid {}", self.name, self.total)\n    }\n}\n',
  ['use std::fmt;\n// Teach println!("{}") how to print an Order.\nimpl fmt::___ for Order {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} x{}", self.bun, self.qty)\n    }\n}\n'] = 'use std::fmt;\n// Nauč println!("{}"), jak vypsat Order.\nimpl fmt::___ for Order {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} x{}", self.bun, self.qty)\n    }\n}\n',
  ['use std::fmt;\nimpl fmt::___ for OrderError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "order failed")\n    }\n}\n'] = 'use std::fmt;\nimpl fmt::___ for OrderError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "order failed")\n    }\n}\n',
  ['use std::fs;\n// A missing menu file is a bug: stop with a message.\nlet menu = fs::read_to_string("menu.txt")\n    .___("menu.txt must exist");\n'] = 'use std::fs;\n// Chybějící soubor s menu je bug: zastav se se zprávou.\nlet menu = fs::read_to_string("menu.txt")\n    .___("menu.txt must exist");\n',
  ["use std::num::ParseIntError;\n\n#[derive(Debug)]\n___ OrderError {\n    Empty,\n    BadQty(ParseIntError),\n}\n"] = "use std::num::ParseIntError;\n\n#[derive(Debug)]\n___ OrderError {\n    Empty,\n    BadQty(ParseIntError),\n}\n",
  ["use std::num::ParseIntError;\n// Hand any parse error straight back to the caller.\nfn cents(s: &str) -> Result<u32, ParseIntError> {\n    let n: u32 = s.parse()___;\n    Ok(n * 100)\n}\n"] = "use std::num::ParseIntError;\n// Každou chybu parsování předej rovnou zpět volajícímu.\nfn cents(s: &str) -> Result<u32, ParseIntError> {\n    let n: u32 = s.parse()___;\n    Ok(n * 100)\n}\n",
  ["use std::sync::Arc;\n// Arc: one receiver, many owners across threads.\n// The lock: only one cook holds the rail at a time.\nlet rx = Arc::new(___::new(rx));\nlet rx2 = Arc::clone(&rx);       // one clone per cook\n"] = "use std::sync::Arc;\n// Arc: jeden příjemce, mnoho vlastníků napříč vlákny.\n// Zámek: lištu drží vždycky jen jeden kuchař.\nlet rx = Arc::new(___::new(rx));\nlet rx2 = Arc::clone(&rx);       // jeden klon na kuchaře\n",
  ['use std::sync::RwLock;\nlet menu = RwLock::new(vec!["bun", "egg tart"]);\n// Many may look at once; only .write() has to wait.\nlet first = menu.___().unwrap()[0];\n'] = 'use std::sync::RwLock;\nlet menu = RwLock::new(vec!["bun", "egg tart"]);\n// Mnozí se mohou dívat najednou; čekat musí jen .write().\nlet first = menu.___().unwrap()[0];\n',
  ["use std::sync::atomic::{AtomicUsize, Ordering};\nstatic SERVED: AtomicUsize = AtomicUsize::new(0);\n// No lock needed: add one in a single hardware step.\nSERVED.___(1, Ordering::SeqCst);\n"] = "use std::sync::atomic::{AtomicUsize, Ordering};\nstatic SERVED: AtomicUsize = AtomicUsize::new(0);\n// Žádný zámek není třeba: přičti jedničku v jediném hardwarovém kroku.\nSERVED.___(1, Ordering::SeqCst);\n",
  ['use std::sync::mpsc;\n// One pipe from till to kitchen: a sender and a receiver.\nlet (tx, rx) = mpsc::___();\ntx.send("egg tart").unwrap();\n'] = 'use std::sync::mpsc;\n// Jedna trubka z pokladny do kuchyně: odesílatel a příjemce.\nlet (tx, rx) = mpsc::___();\ntx.send("egg tart").unwrap();\n',
  ["use std::sync::mpsc;\ntype Job = Box<dyn FnOnce() + Send>;\n// one rail: many senders allowed, exactly one receiver\nlet (tx, rx) = mpsc::___::<Job>();\n"] = "use std::sync::mpsc;\ntype Job = Box<dyn FnOnce() + Send>;\n// jedna lišta: mnoho odesílatelů, přesně jeden příjemce\nlet (tx, rx) = mpsc::___::<Job>();\n",
  ['use std::thread;\n// The grill gets its own thread; the till keeps serving.\nlet grill = thread::___(|| {\n    println!("bun is toasting");\n});\ngrill.join().unwrap();\n'] = 'use std::thread;\n// Gril dostane vlastní vlákno; pokladna dál obsluhuje.\nlet grill = thread::___(|| {\n    println!("bun is toasting");\n});\ngrill.join().unwrap();\n',
  ['use std::time::Duration;\n// Steep the tea for 300 ms before pouring.\nthread::___(Duration::from_millis(300));\nprintln!("pour");\n'] = 'use std::time::Duration;\n// Louhuj čaj 300 ms, než ho naliješ.\nthread::___(Duration::from_millis(300));\nprintln!("pour");\n',
  ["utf8.RuneCountInString counts code points. []rune(s) makes them indexable."] = "utf8.RuneCountInString počítá kódové body. []rune(s) je zpřístupní indexem.",
  ["v is an any that holds a string. Take it out: s := v.(___)"] = "v je any, které drží string. Vytáhni ho: s := v.(___)",
  ["v is smaller than the node's value. Which side does the insert recurse into?"] = "v je menší než hodnota uzlu. Do které strany vkládání rekurzivně jde?",
  ["v, ___ := <-orders\nif !___ {\n    return\n}\n"] = "v, ___ := <-orders\nif !___ {\n    return\n}\n",
  ["v, ok := <-ch tells a closed channel from a zero value. Receiving from a closed channel returns the zero value at once; sending on one panics. A nil channel blocks for ever, which is how a select case is switched off. len and cap look inside a buffer, and the sender closes, never the receiver."] = "v, ok := <-ch odliší zavřený kanál od nulové hodnoty. Příjem ze zavřeného kanálu okamžitě vrátí nulovou hodnotu; odeslání do něj způsobí panic. Kanál nil blokuje navždy, a přesně tak se vypíná větev selectu. len a cap koukají dovnitř bufferu a zavírá vždycky odesílatel, nikdy příjemce.",
  ["v, ok := m[k]. If ok is false, v is the zero value and the key was missing."] = "v, ok := m[k]. Když je ok false, v je nulová hodnota a klíč chyběl.",
  ["v.(T) is a type assertion. s, ok := v.(T) never panics."] = "v.(T) je typová aserce. s, ok := v.(T) nikdy nepanikaří.",
  ["v.sort() on n receipts: what does it cost, in Big O?"] = "v.sort() na n účtenkách: co to stojí, v Big O?",
  ["v1.0.1 shipped with a wrong price. Warn everyone off it without deleting the tag."] = "v1.0.1 vyšlo se špatnou cenou. Varuj všechny, aniž bys tag smazal.",
  ["value += 1 is not atomic across processes either. Which method hands you its own lock?"] = "value += 1 není atomické ani mezi procesy. Která metoda ti podá jeho vlastní zámek?",
  ["var bufs = sync.Pool{\n    New: func() any { return new(bytes.Buffer) },\n}\nb := bufs.___().(*bytes.Buffer)\ndefer bufs.Put(b)\n"] = "var bufs = sync.Pool{\n    New: func() any { return new(bytes.Buffer) },\n}\nb := bufs.___().(*bytes.Buffer)\ndefer bufs.Put(b)\n",
  ["var count [26]int\nfor _, c := range a {\n    count[c-'a']___          // add\n}\nfor _, c := range b {\n    count[c-'a']--           // remove\n}\n"] = "var count [26]int\nfor _, c := range a {\n    count[c-'a']___          // přičti\n}\nfor _, c := range b {\n    count[c-'a']--           // odečti\n}\n",
  ['var counts sync.___\ncounts.Store("wonton", 3)\nv, ok := counts.Load("wonton")\n'] = 'var counts sync.___\ncounts.Store("wonton", 3)\nv, ok := counts.Load("wonton")\n',
  ["var err error\nif err != ___ {\n    return err\n}\n"] = "var err error\nif err != ___ {\n    return err\n}\n",
  ['var floors map[string]int      // nil: read ok, write panics\nfloors = ___(map[string]int)\nfloors["Sogo"] = 1\n'] = 'var floors map[string]int      // nil: čtení ok, zápis panikaří\nfloors = ___(map[string]int)\nfloors["Sogo"] = 1\n',
  ['var frames ___          // length is part of the type\nframes[0] = "muffin"\n'] = 'var frames ___          // délka je součástí typu\nframes[0] = "muffin"\n',
  ["var live atomic.___[Menu]\nlive.Store(&fresh)\nm := live.Load()\n"] = "var live atomic.___[Menu]\nlive.Store(&fresh)\nm := live.Load()\n",
  ["var memo = map[int]int{}\n\nfunc fib(n int) int {\n    if v, ok := memo[n]; ___ {\n        return v            // seen before\n    }\n"] = "var memo = map[int]int{}\n\nfunc fib(n int) int {\n    if v, ok := memo[n]; ___ {\n        return v            // už viděno\n    }\n",
  ["var memo = map[int]int{}\nfunc fib(n int) int {\n    if v, ok := memo[n]; ___ { return v }\n    if n < 2 { return n }\n    memo[n] = fib(n-1) + fib(n-2)\n    return memo[n]\n}\n"] = "var memo = map[int]int{}\nfunc fib(n int) int {\n    if v, ok := memo[n]; ___ { return v }\n    if n < 2 { return n }\n    memo[n] = fib(n-1) + fib(n-2)\n    return memo[n]\n}\n",
  ['var menu = sync.___(loadMenu)\n\nfmt.Println(menu()["set"])\n'] = 'var menu = sync.___(loadMenu)\n\nfmt.Println(menu()["set"])\n',
  ['var menu ___[string]int\nprice := menu["tea"]    // hash the key, jump to the bucket\n'] = 'var menu ___[string]int\nprice := menu["tea"]    // zahashuj klíč, skoč do bucketu\n',
  ["var mu ___\nmu.Lock()\nsold++\nmu.Unlock()\n"] = "var mu ___\nmu.Lock()\nsold++\nmu.Unlock()\n",
  ["var mu sync.Mutex is a working lock. No New, no init: the zero value is unlocked and ready."] = "var mu sync.Mutex je funkční zámek. Žádné New, žádný init: nulová hodnota je odemčená a připravená.",
  ["var mu sync.RWMutex\nmu.___()                // readers share\nn := count\nmu.RUnlock()\n"] = "var mu sync.RWMutex\nmu.___()                // čtenáři sdílejí\nn := count\nmu.RUnlock()\n",
  ["var mu sync.___\nmu.Lock()\ncount++\nmu.Unlock()\n"] = "var mu sync.___\nmu.Lock()\ncount++\nmu.Unlock()\n",
  ['var mu sync.___\nmu.RLock()\nprice := menu["set"]\nmu.RUnlock()\n'] = 'var mu sync.___\nmu.RLock()\nprice := menu["set"]\nmu.RUnlock()\n',
  ["var n int              // zero value\nfmt.Println(n)         // prints ___\n"] = "var n int              // nulová hodnota\nfmt.Println(n)         // vytiskne ___\n",
  ["var n int with no assignment. What is n?"] = "var n int bez přiřazení. Co je n?",
  ["var name type = value. Outside a function := is a compile error."] = "var name type = value. Mimo funkci je := chyba překladu.",
  ["var once sync.Once\n\nonce.___(func() {\n    menu = loadMenu()\n})\n"] = "var once sync.Once\n\nonce.___(func() {\n    menu = loadMenu()\n})\n",
  ["var once sync.___\nfunc grill() {\n    once.Do(warm)      // warm runs one time\n}\n"] = "var once sync.___\nfunc grill() {\n    once.Do(warm)      // warm běží jen jednou\n}\n",
  ["var order Order\nerr := json.___(b, &order)   // pointer!\n"] = "var order Order\nerr := json.___(b, &order)   // ukazatel!\n",
  ["var p *Order = nil\nvar i any = p\nfmt.Println(i == nil)   // prints ___\n"] = "var p *Order = nil\nvar i any = p\nfmt.Println(i == nil)   // vytiskne ___\n",
  ['var p ___Order         // address of an Order\np = &Order{Item: "set"}\n'] = 'var p ___Order         // adresa nějakého Order\np = &Order{Item: "set"}\n',
  ["var prev *ListNode\ncur := head\nfor cur != nil {\n    next := cur.Next      // save before we cut it\n    cur.Next = ___\n    prev, cur = cur, next\n}\n"] = "var prev *ListNode\ncur := head\nfor cur != nil {\n    next := cur.Next      // ulož, než to přerušíme\n    cur.Next = ___\n    prev, cur = cur, next\n}\n",
  ["var r ___ = '灣'        // one code point\nfmt.Println(r)          // 28771\n"] = "var r ___ = '灣'        // jeden kódový bod\nfmt.Println(r)          // 28771\n",
  ["var re *RefundError\nif errors.___(err, &re) {      // typed match\n    pay(re.Amount)\n}\n"] = "var re *RefundError\nif errors.___(err, &re) {      // shoda podle typu\n    pay(re.Amount)\n}\n",
  ["var sold atomic.Int64\nsold.Add(1)\nn := sold.___()\n"] = "var sold atomic.Int64\nsold.Add(1)\nn := sold.___()\n",
  ["var sold atomic.___\nsold.Add(1)\nfmt.Println(sold.Load())\n"] = "var sold atomic.___\nsold.Add(1)\nfmt.Println(sold.Load())\n",
  ['var v any = "muffin"\ns := v.(___)              // panics if v is not one\ns2, ok := v.(string)      // safe form\n'] = 'var v any = "muffin"\ns := v.(___)              // panic, když v není string\ns2, ok := v.(string)      // bezpečná forma\n',
  ["var wg sync.___\nwg.Add(2)\ngo cook(&wg)\nwg.Wait()\n"] = "var wg sync.___\nwg.Add(2)\ngo cook(&wg)\nwg.Wait()\n",
  ["vec![18, 22, 25] is the literal form. Vec::new() makes an empty one. Index with [0] like Go."] = "vec![18, 22, 25] je literální tvar. Vec::new() vytvoří prázdný. Indexuj přes [0] jako v Go.",
  ['visited := map[string]___{}\nqueue := []string{"Causeway Bay"}\nvisited["Causeway Bay"] = true\n'] = 'visited := map[string]___{}\nqueue := []string{"Causeway Bay"}\nvisited["Causeway Bay"] = true\n',
  ["wg.Add(1)\ngo func() {\n    defer wg.___()\n    cook(o)\n}()\nwg.Wait()\n"] = "wg.Add(1)\ngo func() {\n    defer wg.___()\n    cook(o)\n}()\nwg.Wait()\n",
  ["wg.Add(1) per worker, or wg.Add(3) once. Pass &wg: a WaitGroup must not be copied."] = "wg.Add(1) na každého workera, nebo jednou wg.Add(3). Předej &wg: WaitGroup se nesmí kopírovat.",
  ["where T: Display, reads the same as <T: Display> but stays legible with many bounds."] = "where T: Display, se čte stejně jako <T: Display>, ale zůstává čitelné i s mnoha omezeními.",
  ["while True:\n    item = q.___()\n    if item is None:\n        break\n    save(item)\n"] = "while True:\n    item = q.___()\n    if item is None:\n        break\n    save(item)\n",
  ["while True:\n    item = q.get()\n    save(item)\n    q.___()\n# parent: q.join() returns at zero\n"] = "while True:\n    item = q.get()\n    save(item)\n    q.___()\n# rodič: q.join() se vrátí na nule\n",
  ["while left > 0 { } Prints 2 then 0. continue jumps to the next check, break leaves."] = "while left > 0 { } Vypíše 2 a pak 0. continue skočí na další kontrolu, break odejde.",
  ['while queue: runs while the list is truthy, i.e. not empty. An empty list, 0, None and "" are all False.'] = 'while queue: běží, dokud je seznam pravdivý, tedy neprázdný. Prázdný seznam, 0, None a "" jsou všechny False.',
  ["who returns a borrow of self. Write the return type with no lifetime at all."] = "who vrací výpůjčku ze self. Napiš návratový typ úplně bez lifetimu.",
  ['with ProcessPoolExecutor(8) as ex:\n    fut = ex.___(total, rows)\n    log("still free to work")\n'] = 'with ProcessPoolExecutor(8) as ex:\n    fut = ex.___(total, rows)\n    log("still free to work")\n',
  ["with calls __enter__ on the way in and __exit__ on the way out, exception or not. Go's defer, scoped to a block."] = "with volá __enter__ na cestě dovnitř a __exit__ na cestě ven, s výjimkou i bez ní. defer z Go, omezený na blok.",
  ["with lock: is acquire and release, even on error. served += 1 is not atomic, GIL or no GIL."] = "with lock: je acquire a release, i při chybě. served += 1 není atomické, s GIL nebo bez.",
  ["with lock: is the same thing with the finally written for you, which is why nobody writes acquire by hand any more."] = "with lock: je totéž s finally už napsaným za tebe, a proto už acquire nikdo nepíše ručně.",
  ["with mp.Pool(8) as pool:\n    for size in pool.___(resize, photos):\n        log(size)\n"] = "with mp.Pool(8) as pool:\n    for size in pool.___(resize, photos):\n        log(size)\n",
  ["with mp.Pool(8) as pool:\n    r = pool.apply_async(total, (rows,))\n    do_other_work()\n    print(r.___(timeout=60))\n"] = "with mp.Pool(8) as pool:\n    r = pool.apply_async(total, (rows,))\n    do_other_work()\n    print(r.___(timeout=60))\n",
  ["with mp.Pool(8) as pool:\n    sizes = pool.___(resize, photos)\n# sizes[0] belongs to photos[0]\n"] = "with mp.Pool(8) as pool:\n    sizes = pool.___(resize, photos)\n# sizes[0] patří k photos[0]\n",
  ["with mp.___() as m:\n    totals = m.dict()\n    pool.map(add_to, [(totals, r) for r in rows])\n    print(dict(totals))\n"] = "with mp.___() as m:\n    totals = m.dict()\n    pool.map(add_to, [(totals, r) for r in rows])\n    print(dict(totals))\n",
  ['with open("stock.csv") ___ f:\n    data = f.read()\n'] = 'with open("stock.csv") ___ f:\n    data = f.read()\n',
  ["with opens a resource and guarantees it is closed, even on error. __enter__ and __exit__ make a class a context manager; @contextmanager makes one from a generator."] = "with otevře zdroj a zaručí, že se zavře, i při chybě. __enter__ a __exit__ dělají ze třídy kontextový manažer; @contextmanager ho vytvoří z generátoru.",
  ["words = [\"noodles\", \"tea\", \"toast\"]\nwords.sort(key=___)\nprint(words)     # ['tea', 'toast', 'noodles']\n"] = "words = [\"noodles\", \"tea\", \"toast\"]\nwords.sort(key=___)\nprint(words)     # ['tea', 'toast', 'noodles']\n",
  ["wrapping, underscore, the operation. Its cousins are checked_sub (Option) and saturating_sub (stops at 0)."] = "wrapping, podtržítko, operace. Její příbuzní jsou checked_sub (Option) a saturating_sub (zastaví se na 0).",
  ["x := 1\ndefer fmt.Println(x)    // prints ___ at the end\nx = 2\n"] = "x := 1\ndefer fmt.Println(x)    // na konci vypíše ___\nx = 2\n",
  ['x in list is O(n); x in set or dict is O(1). not in is the negative. Works on strings too: "eg" in "egg".'] = 'x in list je O(n); x in set nebo dict je O(1). not in je negace. Funguje i na řetězcích: "eg" in "egg".',
  ["x in list walks every element; x in set hashes once. One keyword, two costs. Know which one you are paying."] = "x in list projde každý prvek; x in set hashuje jednou. Jedno klíčové slovo, dvě ceny. Věz, kterou platíš.",
  ["yield suspends the function; the loop resumes it. Nothing is built ahead: one bowl in memory at a time."] = "yield pozastaví funkci; cyklus ji obnoví. Nic se nestaví dopředu: v paměti je jedna miska.",
  ["yield turns a function into a generator: it hands out one value at a time and remembers where it was. next pulls one. iter, enumerate and zip are the everyday iterator tools."] = "yield mění funkci v generátor: vydává jednu hodnotu po druhé a pamatuje si, kde byl. next jednu vytáhne. iter, enumerate a zip jsou každodenní iterátorové nástroje.",
  ["zip stops at the shorter list; zip(a, b, strict=True) raises on a mismatch (3.10). zip(*pairs) unzips."] = "zip se zastaví na kratším seznamu; zip(a, b, strict=True) vyhodí výjimku při neshodě (3.10). zip(*pairs) rozbalí.",
  ["zip(xs, xs[1:]) walks neighbouring pairs. Since 3.10 itertools.pairwise does the same. Round five to Bo."] = "zip(xs, xs[1:]) prochází sousední dvojice. Od 3.10 dělá totéž itertools.pairwise. Páté kolo pro Boa.",
  ['{} or dict(). {"tea": 12} with items. Keys must be hashable: strings, numbers, tuples, not lists.'] = '{} nebo dict(). {"tea": 12} s položkami. Klíče musí být hashovatelné: řetězce, čísla, tuple, ne seznamy.',
  ["{} uses Display. {:?} uses Debug. {n} reads a variable by name. Three muffins, printed."] = "{} používá Display. {:?} používá Debug. {n} čte proměnnou podle jména. Tři muffiny, vypsáno.",
  ["|x| x * 2 is a closure. It captures nothing here; map calls it for every &i32."] = "|x| x * 2 je closure. Tady nic nezachytává; map ji volá pro každé &i32.",
  ["~T means 'underlying type T'. | joins the choices. See constraints.Ordered."] = "~T znamená „podkladový typ T“. | spojuje možnosti. Viz constraints.Ordered.",
